window.H=window.H||{};H[30]={"30회-2차-052":{"한줄":"용도지구는 용도지역의 제한을 강화하거나 완화해 용도지역의 기능을 증진하는 지역이다(법 제2조제16호).","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제2조제16호","원문":"16. \"용도지구\"란 토지의 이용 및 건축물의 용도ㆍ건폐율ㆍ용적률ㆍ높이 등에 대한 용도지역의 제한을 강화하거나 완화하여 적용함으로써 용도지역의 기능을 증진시키고 경관ㆍ안전 등을 도모하기 위하여 도시ㆍ군관리계획으로 결정하는 지역을 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제2조제15호","원문":"15. \"용도지역\"이란 토지의 이용 및 건축물의 용도, 건폐율(「건축법」 제55조의 건폐율을 말한다. 이하 같다), 용적률(「건축법」 제56조의 용적률을 말한다. 이하 같다), 높이 등을 제한함으로써 토지를 경제적ㆍ효율적으로 이용하고 공공복리의 증진을 도모하기 위하여 서로 중복되지 아니하게 도시ㆍ군관리계획으로 결정하는 지역을 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ은 용도지구, ㄴ은 용도지역이다(법 제2조제16호)."},{"번호":2,"판정":"틀림","설명":"ㄴ이 용도구역이 아니라 용도지역이다. 용도구역은 용도지역·용도지구의 제한을 강화·완화한다(법 제2조제17호)."},{"번호":3,"판정":"틀림","설명":"ㄱ이 용도지역이 아니다. 용도지역은 서로 중복되지 않게 정하며 제한을 강화·완화하는 지역이 아니다(법 제2조제15호)."},{"번호":4,"판정":"틀림","설명":"ㄴ이 용도지역 및 용도구역이 아니라 용도지역이다(법 제2조제16호)."},{"번호":5,"판정":"틀림","설명":"ㄱ이 용도지역이 아니라 용도지구다(법 제2조제16호)."}],"개념":[{"종류":"표","제목":"용도지역·용도지구·용도구역·개발밀도관리구역","머리":["구분","핵심","조문"],"행":[["용도지역","토지 이용, 건축물 용도, 건폐율, 용적률, 높이 등을 제한. 서로 중복되지 않게 도시·군관리계획으로 결정","법 제2조제15호"],["용도지구","용도지역의 제한을 강화하거나 완화해 용도지역의 기능 증진, 경관·안전 도모","법 제2조제16호"],["용도구역","용도지역·용도지구의 제한을 강화하거나 완화해 따로 정함. 시가화 확산 방지 등","법 제2조제17호"],["개발밀도관리구역","기반시설 설치가 곤란한 지역에 건폐율·용적률을 강화해 적용","법 제2조제18호, 제66조"]]}],"함정":"세 용어의 기준이 되는 대상을 바꿔 외우기 쉽다. 용도지구는 용도지역, 용도구역은 용도지역과 용도지구의 제한을 손본다. 괄호 ㄴ에 용도구역이나 '용도지역 및 용도구역'을 넣은 선지가 오답으로 깔려 있다."},"30회-2차-042":{"한줄":"산업·유통개발진흥지구의 지정·변경은 입안 제안 대상이다(법 제26조제1항제3호가목, 시행령 제19조의2제1항).","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제26조제1항제3호","원문":"3. 다음 각 목의 어느 하나에 해당하는 용도지구의 지정 및 변경에 관한 사항 가. 개발진흥지구 중 공업기능 또는 유통물류기능 등을 집중적으로 개발ㆍ정비하기 위한 개발진흥지구로서 대통령령으로 정하는 개발진흥지구 나. 제37조에 따라 지정된 용도지구 중 해당 용도지구에 따른 건축물이나 그 밖의 시설의 용도ㆍ종류 및 규모 등의 제한을 지구단위계획으로 대체하기 위한 용도지구"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"시행령 제19조의2제1항","원문":"① 법 제26조제1항제3호가목에서 \"대통령령으로 정하는 개발진흥지구\"란 제31조제2항제8호나목에 따른 산업ㆍ유통개발진흥지구를 말한다. <개정 2017.12.29>"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"시행령 제20조제1항","원문":"①법 제26조제1항에 따라 도시ㆍ군관리계획입안의 제안을 받은 국토교통부장관, 시ㆍ도지사, 시장 또는 군수는 제안일부터 45일 이내에 도시ㆍ군관리계획입안에의 반영여부를 제안자에게 통보하여야 한다. 다만, 부득이한 사정이 있는 경우에는 1회에 한하여 30일을 연장할 수 있다. <개정 2004.1.20, 2008.2.29, 2011.7.1, 2012.4.10, 2013.3.23>"}],"선지":[{"번호":1,"판정":"옳음","설명":"제안을 받은 자는 제안자와 협의해 입안·결정에 필요한 비용의 전부 또는 일부를 제안자에게 부담시킬 수 있다(법 제26조제3항)."},{"번호":2,"판정":"옳음","설명":"제안서에는 도시·군관리계획도서와 계획설명서를 첨부한다(법 제26조제1항 후단)."},{"번호":3,"판정":"옳음","설명":"제안을 받은 자는 그 처리 결과를 제안자에게 알린다(법 제26조제2항)."},{"번호":4,"판정":"틀림","설명":"산업·유통개발진흥지구의 지정·변경은 제안 대상이다(법 제26조제1항제3호가목, 시행령 제19조의2제1항)."},{"번호":5,"판정":"옳음","설명":"동의 대상 토지 면적에서 국·공유지는 제외한다(시행령 제19조의2제2항 후단)."}],"개념":[{"종류":"흐름","제목":"도시·군관리계획 입안 제안 절차","단계":[{"이름":"제안","설명":"주민(이해관계자 포함)이 입안권자에게 제안. 제안서에 도시·군관리계획도서와 계획설명서 첨부(법 제26조제1항)"},{"이름":"동의","설명":"토지소유자 동의. 기반시설 등은 5분의 4, 지구단위계획 등은 3분의 2. 국·공유지 제외(시행령 제19조의2제2항)"},{"이름":"반영 여부 통보","설명":"제안일부터 45일 이내 통보. 부득이한 사정이 있으면 1회에 한해 30일 연장(시행령 제20조제1항)"},{"이름":"자문","설명":"필요하면 중앙도시계획위원회 또는 지방도시계획위원회 자문(시행령 제20조제2항)"},{"이름":"비용","설명":"제안자와 협의해 입안·결정 비용 일부 또는 전부를 제안자에게 부담시킬 수 있음(법 제26조제3항)"}]}],"함정":"개발진흥지구 전부가 제안 대상인 것은 아니고, 공업기능이나 유통물류기능을 집중 개발하는 산업·유통개발진흥지구로 한정된다. 이 지구는 제안 대상이라는 점을 놓치면 선지 4를 맞는 문장으로 읽게 된다."},"30회-2차-044":{"한줄":"도시·군계획 수립 대상지역의 일부에 대해 토지 이용 합리화, 미관 개선, 환경 확보를 위해 수립하는 도시·군관리계획은 지구단위계획이다(법 제2조제5호).","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제2조제5호","원문":"5. \"지구단위계획\"이란 도시ㆍ군계획 수립 대상지역의 일부에 대하여 토지 이용을 합리화하고 그 기능을 증진시키며 미관을 개선하고 양호한 환경을 확보하며, 그 지역을 체계적ㆍ계획적으로 관리하기 위하여 수립하는 도시ㆍ군관리계획을 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제2조제5호의5","원문":"5의5. \"도시혁신계획\"이란 창의적이고 혁신적인 도시공간의 개발을 목적으로 도시혁신구역에서의 토지의 이용 및 건축물의 용도ㆍ건폐율ㆍ용적률ㆍ높이 등의 제한에 관한 사항을 따로 정하기 위하여 공간재구조화계획으로 결정하는 도시ㆍ군관리계획을 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"일부관리계획이라는 용어는 법에 정의되어 있지 않다."},{"번호":2,"판정":"옳음","설명":"제시문은 지구단위계획의 정의 그대로다(법 제2조제5호)."},{"번호":3,"판정":"틀림","설명":"도시·군기본계획은 관할 구역과 생활권의 기본적 공간구조와 장기발전방향을 제시하는 종합계획이다(법 제2조제3호)."},{"번호":4,"판정":"틀림","설명":"시가화조정구역계획이라는 용어는 법에 없다. 시가화조정구역의 지정은 도시·군관리계획의 한 내용이다(법 제2조제4호나목)."},{"번호":5,"판정":"틀림","설명":"도시혁신계획은 도시혁신구역에서의 제한을 따로 정하기 위해 공간재구조화계획으로 결정하는 도시·군관리계획이다(법 제2조제5호의5)."}],"개념":[{"종류":"표","제목":"도시·군계획 관련 계획의 종류","머리":["계획","핵심","조문"],"행":[["광역도시계획","지정된 광역계획권의 장기발전방향 제시","법 제2조제1호"],["도시·군기본계획","관할 구역과 생활권의 공간구조·장기발전방향을 제시하는 종합계획. 관리계획 수립의 지침","법 제2조제3호"],["도시·군관리계획","용도지역·지구 지정, 시설 설치, 지구단위계획 등 개발·정비·보전 계획","법 제2조제4호"],["지구단위계획","대상지역의 일부를 체계적·계획적으로 관리하기 위한 도시·군관리계획","법 제2조제5호"],["성장관리계획","성장관리계획구역의 난개발 방지와 계획적 개발 유도","법 제2조제5호의3"],["공간재구조화계획","제한을 완화하는 용도구역의 효율적·계획적 관리","법 제2조제5호의4"],["도시혁신계획","도시혁신구역에서 토지 이용·건축물 용도·건폐율·용적률·높이 등 제한을 따로 정함","법 제2조제5호의5"],["복합용도계획","복합용도구역에서 건축물 용도별 구성비율 등을 따로 정함","법 제2조제5호의6"]]}],"함정":"지구단위계획의 '일부' 요소에 이끌려 일부관리계획을 고르기 쉽다. 법에 없는 용어가 선지 1, 4에 섞여 있다.","개정":"입지규제최소구역계획은 법 제2조제5호의2가 삭제되면서(2024.2.6) 없어졌고, 후속 제도로 도시혁신계획이 제2조제5호의5에 규정되어 있다. 이 문항 선지 5는 도시혁신계획으로 고쳐 실었다. 정답은 달라지지 않는다."},"30회-2차-046":{"한줄":"영 제107조제1호가 자연취락지구 주민을 위해 정한 지원사업에 ㄱ~ㄹ이 모두 들어 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제105조","원문":"국가나 지방자치단체는 대통령령으로 정하는 바에 따라 취락지구 주민의 생활 편익과 복지 증진 등을 위한 사업을 시행하거나 그 사업을 지원할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제107조제1호","원문":"1. 자연취락지구 가. 자연취락지구안에 있거나 자연취락지구에 연결되는 도로ㆍ수도공급설비ㆍ하수도 등의 정비 나. 어린이놀이터ㆍ공원ㆍ녹지ㆍ주차장ㆍ학교ㆍ마을회관 등의 설치ㆍ정비 다. 쓰레기처리장ㆍ하수처리시설 등의 설치ㆍ개량 라. 하천정비 등 재해방지를 위한 시설의 설치ㆍ개량 마. 주택의 신축ㆍ개량"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄹ 주택의 개량도 지원사업이라 ㄱ, ㄴ, ㄷ만 고르면 부족하다(영 제107조제1호마목)."},{"번호":2,"판정":"틀림","설명":"ㄷ 하천정비 등 재해방지시설의 설치도 지원사업이라 부족하다(영 제107조제1호라목)."},{"번호":3,"판정":"틀림","설명":"ㄴ 쓰레기처리장·하수처리시설의 개량도 지원사업이라 부족하다(영 제107조제1호다목)."},{"번호":4,"판정":"틀림","설명":"ㄱ 어린이놀이터·마을회관의 설치도 지원사업이라 부족하다(영 제107조제1호나목)."},{"번호":5,"판정":"옳음","설명":"네 보기가 모두 영 제107조제1호 각 목에 있어 이 조합이 맞다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"어린이놀이터·마을회관 등의 설치·정비는 지원사업이다(영 제107조제1호나목)."},{"기호":"ㄴ","판정":"옳음","설명":"쓰레기처리장·하수처리시설 등의 설치·개량은 지원사업이다(영 제107조제1호다목)."},{"기호":"ㄷ","판정":"옳음","설명":"하천정비 등 재해방지를 위한 시설의 설치·개량은 지원사업이다(영 제107조제1호라목)."},{"기호":"ㄹ","판정":"옳음","설명":"주택의 신축·개량은 지원사업이다(영 제107조제1호마목)."}],"개념":[{"종류":"표","제목":"취락지구에 대한 지원(영 제107조)","머리":["취락지구","지원 근거","지원사업"],"행":[["자연취락지구","영 제107조제1호","도로·수도공급설비·하수도 정비, 어린이놀이터·공원·녹지·주차장·학교·마을회관 설치·정비, 쓰레기처리장·하수처리시설 설치·개량, 하천정비 등 재해방지시설 설치·개량, 주택 신축·개량"],["보호취락지구","영 제107조제2호","농촌공간 재구조화 및 재생지원에 관한 법령에서 정하는 바에 따른다"],["집단취락지구","영 제107조제3호","개발제한구역의 지정 및 관리에 관한 특별조치법령에서 정하는 바에 따른다"]]},{"종류":"표","제목":"취락지구의 세분","머리":["세분","정비 대상","조문"],"행":[["자연취락지구","녹지지역·관리지역·농림지역·자연환경보전지역 안의 취락","영 제31조제2항제7호가목"],["보호취락지구","같은 지역 안의 취락을 농촌의 주거환경 보호와 주거기능 강화를 목적으로 정비","영 제31조제2항제7호나목"],["집단취락지구","개발제한구역 안의 취락","영 제31조제2항제7호다목"]]}],"함정":"ㄴ은 개량이어서, ㄹ은 신축이 아닌 개량이어서 빠진다고 생각하기 쉽다. 영 제107조제1호다목은 ‘설치ㆍ개량’, 마목은 ‘신축ㆍ개량’이라 둘 다 포함된다.","개정":"영 제107조는 <개정 2025.7.1>로 취락지구별 호가 나뉘어 보호취락지구(제2호)가 들어갔다. 자연취락지구의 지원사업 다섯 가지는 이 문항의 ㄱ~ㄹ과 겹친다."},"30회-2차-050":{"한줄":"ㄱ만 영 제31조제2항의 세분과 일치하고 ㄴ, ㄷ, ㄹ은 조문에 없는 지구가 섞여 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제31조제2항제5호","원문":"5. 보호지구 가. 역사문화환경보호지구 … 나. 중요시설물보호지구 … 다. 생태계보호지구 …"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제31조제2항제4호","원문":"4. 방재지구 가. 시가지방재지구 … 나. 자연방재지구 …"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제31조제2항제1호","원문":"1. 경관지구 가. 자연경관지구 … 나. 시가지경관지구 … 다. 특화경관지구 …"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제31조제2항제7호","원문":"7. 취락지구 가. 자연취락지구 … 나. 보호취락지구 … 다. 집단취락지구 …"}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ만 조문의 세분과 일치한다."},{"번호":2,"판정":"틀림","설명":"ㄹ 취락지구에는 농어촌취락지구가 없고, ㄱ은 옳은 보기라 ㄹ만으로는 맞지 않는다."},{"번호":3,"판정":"틀림","설명":"ㄷ 경관지구에는 주거경관지구가 없다(자연·시가지·특화경관지구)."},{"번호":4,"판정":"틀림","설명":"ㄴ은 특정개발방재지구가 없고 ㄹ은 농어촌취락지구가 없다."},{"번호":5,"판정":"틀림","설명":"ㄷ과 ㄹ 모두 조문에 없는 세분이 섞여 있다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"보호지구는 역사문화환경보호지구, 중요시설물보호지구, 생태계보호지구로 세분한다(영 제31조제2항제5호)."},{"기호":"ㄴ","판정":"틀림","설명":"방재지구 세분은 시가지방재지구와 자연방재지구 둘이다. 특정개발방재지구는 없다(영 제31조제2항제4호)."},{"기호":"ㄷ","판정":"틀림","설명":"경관지구 세분은 자연경관지구, 시가지경관지구, 특화경관지구다. 주거경관지구는 없다(영 제31조제2항제1호)."},{"기호":"ㄹ","판정":"틀림","설명":"취락지구 세분은 자연취락지구, 보호취락지구, 집단취락지구다. 농어촌취락지구는 없다(영 제31조제2항제7호)."}],"개념":[{"종류":"표","제목":"용도지구의 세분(영 제31조제2항)","머리":["용도지구","세분","비고"],"행":[["경관지구","자연경관지구, 시가지경관지구, 특화경관지구","조례로 추가 세분 가능(제3항)"],["방재지구","시가지방재지구, 자연방재지구","건축물·인구 밀집 지역은 시가지, 토지이용도가 낮은 해안변·하천변·급경사지 주변은 자연"],["보호지구","역사문화환경보호지구, 중요시설물보호지구, 생태계보호지구","중요시설물보호지구는 조례로 추가 세분 가능"],["취락지구","자연취락지구, 보호취락지구, 집단취락지구","집단취락지구는 개발제한구역 안"],["개발진흥지구","주거개발진흥지구, 산업·유통개발진흥지구, 관광·휴양개발진흥지구, 복합개발진흥지구, 특정개발진흥지구","다목은 삭제 <2012.4.10>"]]}],"함정":"ㄴ의 ‘특정개발’은 개발진흥지구의 세분 이름이라 방재지구에 붙어 있어도 그럴듯하게 읽힌다. ㄹ의 ‘농어촌취락지구’, ㄷ의 ‘주거경관지구’도 이름만 보면 자연스럽지만 영 제31조제2항에 없다.","개정":"취락지구에 보호취락지구가 있고, 이를 위한 영 제78조제2항이 2025.7.1 신설됐다. ㄹ 보기에 쓰인 농어촌취락지구는 현행 조문에 없다."},"30회-2차-047":{"한줄":"준주거지역의 용적률 최대한도는 500퍼센트로, 제1종전용주거(100)·제3종일반주거(300)·일반공업(350)·준공업(400)보다 크다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제85조제1항","원문":"1. 제1종전용주거지역 : 50퍼센트 이상 100퍼센트 이하 / 5. 제3종일반주거지역 : 100퍼센트 이상 300퍼센트 이하 / 6. 준주거지역 : 200퍼센트 이상 500퍼센트 이하 / 12. 일반공업지역 : 150퍼센트 이상 350퍼센트 이하 / 13. 준공업지역 : 150퍼센트 이상 400퍼센트 이하"}],"선지":[{"번호":1,"판정":"틀림","설명":"제1종전용주거지역은 100퍼센트 이하다."},{"번호":2,"판정":"틀림","설명":"제3종일반주거지역은 300퍼센트 이하다."},{"번호":3,"판정":"옳음","설명":"준주거지역은 500퍼센트 이하로 보기 중 가장 크다(영 제85조제1항제6호)."},{"번호":4,"판정":"틀림","설명":"일반공업지역은 350퍼센트 이하다."},{"번호":5,"판정":"틀림","설명":"준공업지역은 400퍼센트 이하다. 공업지역 중에서는 가장 크지만 준주거지역에는 못 미친다."}],"개념":[{"종류":"표","제목":"용도지역별 용적률 범위(영 제85조제1항)","머리":["용도지역","하한","상한"],"행":[["제1종전용주거","50","100"],["제2종전용주거","50","150"],["제1종일반주거","100","200"],["제2종일반주거","100","250"],["제3종일반주거","100","300"],["준주거","200","500"],["중심상업","200","1500"],["일반상업","200","1300"],["근린상업","200","900"],["유통상업","200","1100"],["전용공업","150","300"],["일반공업","150","350"],["준공업","150","400"],["보전녹지","50","80"],["생산녹지","50","100"],["자연녹지","50","100"],["보전관리ㆍ생산관리","50","80"],["계획관리","50","100"],["농림ㆍ자연환경보전","50","80"]]}],"함정":"공업지역 안에서는 준공업(400)이 가장 크지만 준주거(500)에는 못 미친다. 주거지역도 제3종일반주거는 300이어서 준주거와 200 차이가 난다."},"30회-2차-049":{"한줄":"제3종일반주거지역에서 위험물저장 및 처리시설 중 액화가스 취급소ㆍ판매소는 도시ㆍ군계획조례로 정하는 바에 따라 건축할 수 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제71조제1항제5호","원문":"제3종일반주거지역안에서 건축할 수 있는 건축물 : 별표 6에 규정된 건축물"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"별표 6 제2호","원문":"도시ㆍ군계획조례가 정하는 바에 의하여 건축할 수 있는 건축물 / 가. 「건축법 시행령」 별표 1 제4호의 제2종 근린생활시설(단란주점 및 안마시술소를 제외한다) / 나. 「건축법 시행령」 별표 1 제5호의 문화 및 집회시설(관람장을 제외한다) / 라. 「건축법 시행령」 별표 1 제9호의 의료시설(격리병원을 제외한다) / 아. 「건축법 시행령」 별표 1 제14호의 업무시설로서 그 용도에 쓰이는 바닥면적의 합계가 3천제곱미터 이하인 것 / 카. 「건축법 시행령」 별표 1 제19호의 위험물저장 및 처리시설 중 주유소, 석유판매소, 액화가스 취급소"}],"선지":[{"번호":1,"판정":"틀림","설명":"제2종 근린생활시설은 허용되지만 단란주점과 안마시술소는 제외된다(별표 6 제2호가목)."},{"번호":2,"판정":"틀림","설명":"의료시설은 허용되지만 격리병원은 제외된다(별표 6 제2호라목)."},{"번호":3,"판정":"틀림","설명":"문화 및 집회시설은 허용되지만 관람장은 제외된다(별표 6 제2호나목)."},{"번호":4,"판정":"옳음","설명":"위험물저장 및 처리시설 중 주유소, 석유판매소, 액화가스 취급소ㆍ판매소 등은 조례로 허용되는 건축물이다(별표 6 제2호카목)."},{"번호":5,"판정":"틀림","설명":"업무시설은 바닥면적 합계가 3천제곱미터 이하여야 한다. 4천제곱미터는 초과한다(별표 6 제2호아목)."}],"개념":[{"종류":"표","제목":"제3종일반주거지역 조례 허용 건축물의 제외 항목과 한도(영 별표 6 제2호)","머리":["용도","조례로 허용되는 범위"],"행":[["제2종 근린생활시설","단란주점ㆍ안마시술소 제외"],["문화 및 집회시설","관람장 제외"],["의료시설","격리병원 제외"],["업무시설","바닥면적 합계 3천제곱미터 이하"],["위험물저장 및 처리시설","주유소ㆍ석유판매소ㆍ액화가스 취급소ㆍ판매소 등 열거된 시설만"],["판매시설","바닥면적 합계 2천제곱미터 미만(너비 15미터 이상 도로에 접한 대지 등 요건)"]]}],"함정":"조례 허용 용도는 괄호의 제외 항목과 면적 한도에서 갈린다. 단란주점ㆍ격리병원ㆍ관람장은 빠지고, 업무시설은 3천제곱미터 이하여야 한다. 위험물저장 및 처리시설은 전부가 아니라 열거된 주유소ㆍ액화가스 취급소 등만 허용된다."},"30회-2차-048":{"한줄":"고시일부터 20년이 지나도록 시행되지 않으면 20년이 되는 날의 다음날에 효력을 잃는다. ㄱ은 20, ㄴ은 되는 날의 다음날이다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제48조제1항","원문":"도시ㆍ군계획시설결정이 고시된 도시ㆍ군계획시설에 대하여 그 고시일부터 20년이 지날 때까지 그 시설의 설치에 관한 도시ㆍ군계획시설사업이 시행되지 아니하는 경우 그 도시ㆍ군계획시설결정은 그 고시일부터 20년이 되는 날의 다음날에 그 효력을 잃는다."}],"선지":[{"번호":1,"판정":"-","설명":"10년이 아니라 20년이고, 효력상실 시점은 되는 날이 아니라 다음날이다."},{"번호":2,"판정":"-","설명":"20년은 맞으나 효력상실 시점이 20년이 되는 날이 아니라 그 다음날이다."},{"번호":3,"판정":"-","설명":"10년이 아니라 20년이다."},{"번호":4,"판정":"-","설명":"15년이라는 기간은 법에 없다. 20년이다."},{"번호":5,"판정":"-","설명":"20년, 되는 날의 다음날이 모두 맞다."}],"개념":[{"종류":"표","제목":"시설결정 고시일 이후 기간 비교","머리":["기간","내용","근거"],"행":[["10년","매수청구 요건, 해제 입안 신청 요건, 지방의회 보고 대상","법 제47조제1항, 제48조의2제1항, 제48조제3항"],["20년","미시행 시 시설결정 효력상실(20년이 되는 날의 다음날)","법 제48조제1항"],["실효 후","시ㆍ도지사 또는 대도시 시장이 지체 없이 그 사실을 고시","법 제48조제2항"]]}],"함정":"10년과 20년을 혼동하기 쉽고, '되는 날'과 '그 다음날'의 차이도 문제로 나온다. 효력은 20년이 되는 날의 다음날에 잃는다."},"30회-2차-043":{"한줄":"개발행위허가에 조건을 붙이려면 미리 허가를 신청한 자의 의견을 들어야 한다(령 제54조제2항).","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제54조제2항","원문":"②특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 법 제57조제4항에 따라 개발행위허가에 조건을 붙이려는 때에는 미리 개발행위허가를 신청한 자의 의견을 들어야 한다. <개정 2006.8.17, 2012.4.10>"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제56조제4항","원문":"④ 다음 각 호의 어느 하나에 해당하는 행위는 제1항에도 불구하고 개발행위허가를 받지 아니하고 할 수 있다. 다만, 제1호의 응급조치를 한 경우에는 1개월 이내에 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수에게 신고하여야 한다. <개정 2011.4.14> 1. 재해복구나 재난수습을 위한 응급조치"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제60조제1항","원문":"① 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 기반시설의 설치나 그에 필요한 용지의 확보, 위해 방지, 환경오염 방지, 경관, 조경 등을 위하여 필요하다고 인정되는 경우로서 대통령령으로 정하는 경우에는 이의 이행을 보증하기 위하여 개발행위허가(다른 법률에 따라 개발행위허가가 의제되는 협의를 거친 인가ㆍ허가ㆍ승인 등을 포함한다. 이하 이 조에서 같다)를 받는 자로 하여금 이행보증금을 예치하게 할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다. <개정 2011.4.14, 2013.7.16> 1. 국가나 지방자치단체가 시행하는 개발행위"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제65조제1항","원문":"① 개발행위허가(다른 법률에 따라 개발행위허가가 의제되는 협의를 거친 인가ㆍ허가ㆍ승인 등을 포함한다. 이하 이 조에서 같다)를 받은 자가 행정청인 경우 개발행위허가를 받은 자가 새로 공공시설을 설치하거나 기존의 공공시설에 대체되는 공공시설을 설치한 경우에는 「국유재산법」과 「공유재산 및 물품 관리법」에도 불구하고 새로 설치된 공공시설은 그 시설을 관리할 관리청에 무상으로 귀속되고, 종래의 공공시설은 개발행위허가를 받은 자에게 무상으로 귀속된다. <개정 2013.7.16>"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제65조제2항","원문":"② 개발행위허가를 받은 자가 행정청이 아닌 경우 개발행위허가를 받은 자가 새로 설치한 공공시설은 그 시설을 관리할 관리청에 무상으로 귀속되고, 개발행위로 용도가 폐지되는 공공시설은 「국유재산법」과 「공유재산 및 물품 관리법」에도 불구하고 새로 설치한 공공시설의 설치비용에 상당하는 범위에서 개발행위허가를 받은 자에게 무상으로 양도할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"재해복구나 재난수습을 위한 응급조치는 허가 없이 할 수 있다. 1개월 이내에 신고한다(법 제56조제4항제1호)."},{"번호":2,"판정":"틀림","설명":"국가나 지방자치단체가 시행하는 개발행위는 이행보증금 예치 대상에서 빠진다(법 제60조제1항제1호)."},{"번호":3,"판정":"옳음","설명":"조건을 붙이려는 때에는 미리 개발행위허가를 신청한 자의 의견을 들어야 한다(령 제54조제2항)."},{"번호":4,"판정":"틀림","설명":"행정청이 대체 공공시설을 설치하면 종래의 공공시설은 설치비용에 상당하는 범위에서 양도되는 것이 아니라 허가를 받은 자에게 무상으로 귀속된다(법 제65조제1항)."},{"번호":5,"판정":"틀림","설명":"행정청이 아닌 경우 용도가 폐지되는 공공시설은 새로 설치한 공공시설의 설치비용에 상당하는 범위에서 무상으로 양도할 수 있다. 전부 귀속되는 것이 아니다(법 제65조제2항)."}],"개념":[{"종류":"표","제목":"개발행위허가 절차","머리":["단계","내용","조문"],"행":[["신청","기반시설 설치·용지 확보, 위해 방지, 환경오염 방지, 경관, 조경 등에 관한 계획서를 첨부한 신청서 제출","법 제57조제1항"],["처리기간","15일 이내 허가 또는 불허가(도시계획위원회 심의·관계 행정기관 협의 기간은 제외)","법 제57조제2항, 령 제54조제1항"],["조건 부여","조건을 붙이려면 미리 신청한 자의 의견을 들어야 함","법 제57조제4항, 령 제54조제2항"],["이행보증금","허가를 받는 자에게 예치하게 할 수 있음. 국가·지방자치단체 시행은 제외","법 제60조제1항"],["준공검사","토지분할·물건 쌓기를 제외한 건축·공작물 설치·형질변경·토석채취 허가를 받은 자는 개발행위를 마치면 준공검사","법 제62조제1항"],["허가 없이 가능","재해복구·재난수습 응급조치(1개월 이내 신고), 경미한 행위","법 제56조제4항"]]},{"종류":"비교","제목":"개발행위에 따른 공공시설의 귀속","왼쪽":{"이름":"허가를 받은 자가 행정청","항목":["새로 설치한 공공시설은 관리청에 무상 귀속","종래의 공공시설은 허가받은 자에게 무상 귀속","준공검사를 마치고 관리청에 통지한 날 각각 귀속된 것으로 봄","귀속된 공공시설의 처분 수익금은 도시·군계획사업 외의 목적에 사용 불가"]},"오른쪽":{"이름":"허가를 받은 자가 행정청이 아님","항목":["새로 설치한 공공시설은 관리청에 무상 귀속","용도가 폐지되는 공공시설은 새 시설의 설치비용에 상당하는 범위에서 무상 양도 가능","개발행위가 끝나기 전에 관리청에 종류와 토지의 세목 통지","준공검사를 받음으로써 각각 귀속·양도된 것으로 봄"]}}],"함정":"선지 4와 5는 행정청과 행정청이 아닌 자의 귀속 규정을 서로 바꿔 놓은 구조다. 행정청은 종래 시설 전부가 허가받은 자에게 무상 귀속되고, 행정청이 아니면 설치비용 범위에서만 양도한다."},"30회-2차-041":{"한줄":"행위 제한이 완화되거나 해제되는 지역은 기반시설부담구역으로 지정할 수 없는 곳이 아니라 지정하여야 하는 곳이다(법 제67조제1항제1호).","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제67조제1항","원문":"① 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 다음 각 호의 어느 하나에 해당하는 지역에 대하여는 기반시설부담구역으로 지정하여야 한다. 다만, 개발행위가 집중되어 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수가 해당 지역의 계획적 관리를 위하여 필요하다고 인정하면 다음 각 호에 해당하지 아니하는 경우라도 기반시설부담구역으로 지정할 수 있다. <개정 2011.4.14> 1. 이 법 또는 다른 법령의 제정ㆍ개정으로 인하여 행위 제한이 완화되거나 해제되는 지역"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제67조제2항","원문":"② 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 기반시설부담구역을 지정 또는 변경하려면 주민의 의견을 들어야 하며, 해당 지방자치단체에 설치된 지방도시계획위원회의 심의를 거쳐 대통령령으로 정하는 바에 따라 이를 고시하여야 한다. <개정 2011.4.14>"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제67조제4항","원문":"④ 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 제2항에 따라 기반시설부담구역이 지정되면 대통령령으로 정하는 바에 따라 기반시설설치계획을 수립하여야 하며, 이를 도시ㆍ군관리계획에 반영하여야 한다. <개정 2011.4.14>"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제65조제3항","원문":"③ 제1항 및 제2항에도 불구하고 법 제52조제1항에 따라 지구단위계획을 수립한 경우에는 기반시설설치계획을 수립한 것으로 본다. <개정 2012.4.10>"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제65조제4항","원문":"④ 기반시설부담구역의 지정고시일부터 1년이 되는 날까지 기반시설설치계획을 수립하지 아니하면 그 1년이 되는 날의 다음날에 기반시설부담구역의 지정은 해제된 것으로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지정되면 기반시설설치계획을 수립하고 도시·군관리계획에 반영해야 한다(법 제67조제4항)."},{"번호":2,"판정":"옳음","설명":"지정·변경은 해당 지방자치단체에 설치된 지방도시계획위원회의 심의를 거친다. 광역시장이 지정하면 광역시의 지방도시계획위원회가 심의한다(법 제67조제2항)."},{"번호":3,"판정":"틀림","설명":"법령의 제정·개정으로 행위 제한이 완화되거나 해제되는 지역은 기반시설부담구역으로 지정하여야 하는 지역이다(법 제67조제1항제1호)."},{"번호":4,"판정":"옳음","설명":"지구단위계획을 수립한 경우 기반시설설치계획을 수립한 것으로 본다(영 제65조제3항)."},{"번호":5,"판정":"옳음","설명":"지정고시일부터 1년이 되는 날까지 기반시설설치계획을 수립하지 않으면 그 다음 날 지정이 해제된 것으로 본다(영 제65조제4항)."}],"개념":[{"종류":"표","제목":"기반시설부담구역 지정과 후속 절차","머리":["단계","내용","조문"],"행":[["지정 대상(의무)","행위 제한이 완화·해제되는 지역, 용도지역 변경·해제로 행위 제한이 완화되는 지역, 대통령령으로 정하는 지역","법 제67조제1항"],["대통령령 지역","전년도 개발행위허가 건수가 전전년도보다 20퍼센트 이상 증가한 지역, 전년도 인구증가율이 소속 지방자치단체 인구증가율보다 20퍼센트 이상 높은 지역","영 제64조제1항"],["지정 절차","주민 의견 청취, 지방도시계획위원회 심의, 명칭·위치·면적·지정일자 고시","법 제67조제2항, 영 제64조제2항"],["기반시설설치계획","지정 후 수립하고 도시·군관리계획에 반영. 지구단위계획을 수립했으면 수립한 것으로 봄","법 제67조제4항, 영 제65조제3항"],["해제의제","지정고시일부터 1년이 되는 날까지 계획 미수립 시 다음 날 해제","영 제65조제4항"],["지정기준","기반시설이 적절히 배치될 수 있는 규모로 최소 10만 제곱미터 이상","영 제66조제1항제1호"]]},{"종류":"표","제목":"개발밀도관리구역과 기반시설부담구역","머리":["구분","개발밀도관리구역","기반시설부담구역","조문"],"행":[["대상 지역","주거·상업·공업지역 중 기반시설 설치가 곤란한 지역","개발밀도관리구역 외의 지역으로서 개발로 기반시설 설치가 필요한 지역","법 제66조제1항, 제2조제19호"],["지정권자","특별시장·광역시장·특별자치시장·특별자치도지사·시장·군수","특별시장·광역시장·특별자치시장·특별자치도지사·시장·군수","법 제66조제1항, 제67조제1항"],["지정 절차","지방도시계획위원회 심의 후 고시","주민 의견 청취, 지방도시계획위원회 심의 후 고시","법 제66조제3항·제4항, 제67조제2항"],["효과","건폐율·용적률 강화(용적률 최대한도의 50퍼센트 범위)","기반시설설치계획 수립, 설치비용 부과","영 제62조제1항, 법 제67조제4항, 법 제68조"],["부과·관리","-","부과대상 200제곱미터 초과 신·증축, 구역별 특별회계","법 제68조제1항, 제70조제1항"]]}],"함정":"선지 3은 '지정할 수 없다'가 반대다. 행위 제한이 완화되는 지역은 지정 의무 대상이다. 선지 4의 지구단위계획 간주 규정은 시행령에 있어서 법 조문만 찾으면 놓치기 쉽다."},"30회-2차-045":{"한줄":"개발밀도관리구역의 지정·변경은 지방도시계획위원회 심의만 규정하고 주민 의견 청취는 규정하지 않는다(법 제66조제3항).","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제14조제1항","원문":"① 국토교통부장관, 시ㆍ도지사, 시장 또는 군수는 광역도시계획을 수립하거나 변경하려면 미리 공청회를 열어 주민과 관계 전문가 등으로부터 의견을 들어야 하며, 공청회에서 제시된 의견이 타당하다고 인정하면 광역도시계획에 반영하여야 한다. <개정 2013.3.23>"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제75조의2제2항","원문":"② 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 성장관리계획구역을 지정하거나 이를 변경하려면 대통령령으로 정하는 바에 따라 미리 주민과 해당 지방의회의 의견을 들어야 하며, 관계 행정기관과의 협의 및 지방도시계획위원회의 심의를 거쳐야 한다. 다만, 대통령령으로 정하는 경미한 사항을 변경하는 경우에는 그러하지 아니하다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제75조의3제4항","원문":"④ 성장관리계획의 수립 및 변경에 관한 절차는 제75조의2제2항부터 제5항까지의 규정을 준용한다. 이 경우 \"성장관리계획구역\"은 \"성장관리계획\"으로 본다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제128조제3항","원문":"③특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장ㆍ군수 또는 구청장은 제1항의 규정에 의하여 시범도시사업계획을 수립하고자 하는 때에는 미리 설문조사ㆍ열람 등을 통하여 주민의 의견을 들어야 한다. <개정 2012.4.10>"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제67조제2항","원문":"② 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 기반시설부담구역을 지정 또는 변경하려면 주민의 의견을 들어야 하며, 해당 지방자치단체에 설치된 지방도시계획위원회의 심의를 거쳐 대통령령으로 정하는 바에 따라 이를 고시하여야 한다. <개정 2011.4.14>"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제66조제3항","원문":"③ 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 제1항에 따라 개발밀도관리구역을 지정하거나 변경하려면 다음 각 호의 사항을 포함하여 해당 지방자치단체에 설치된 지방도시계획위원회의 심의를 거쳐야 한다. <개정 2011.4.14>"}],"선지":[{"번호":1,"판정":"옳음","설명":"광역도시계획을 수립·변경하려면 미리 공청회를 열어 주민과 관계 전문가의 의견을 듣는다(법 제14조제1항)."},{"번호":2,"판정":"옳음","설명":"성장관리계획의 수립·변경은 성장관리계획구역 지정 절차를 준용하므로 미리 주민과 지방의회의 의견을 듣는다(법 제75조의3제4항, 제75조의2제2항)."},{"번호":3,"판정":"옳음","설명":"시범도시사업계획을 수립하려면 미리 설문조사·열람 등으로 주민 의견을 듣는다(영 제128조제3항)."},{"번호":4,"판정":"옳음","설명":"기반시설부담구역을 지정·변경하려면 주민 의견을 듣는다(법 제67조제2항)."},{"번호":5,"판정":"틀림","설명":"개발밀도관리구역은 지방도시계획위원회 심의와 고시만 규정한다. 주민 의견 청취는 명시되어 있지 않다(법 제66조제3항·제4항)."}],"개념":[{"종류":"표","제목":"지정·수립 시 의견 청취 규정","머리":["대상","주민 등 의견 청취","조문"],"행":[["광역도시계획","공청회를 열어 주민·관계 전문가 의견 청취","법 제14조제1항"],["성장관리계획구역·성장관리계획","주민과 지방의회 의견 청취. 지방의회는 60일 이내 의견 제시, 미제시는 의견 없음으로 봄","법 제75조의2제2항·제3항, 제75조의3제4항"],["시범도시사업계획","설문조사·열람 등으로 주민 의견 청취","영 제128조제3항"],["기반시설부담구역","주민 의견 청취 후 지방도시계획위원회 심의","법 제67조제2항"],["개발밀도관리구역","지방도시계획위원회 심의만 규정(주민 의견 규정 없음)","법 제66조제3항"]]}],"함정":"선지 5가 정답이다. 개발밀도관리구역과 기반시설부담구역은 절차가 비슷해 보이지만 주민 의견 청취는 기반시설부담구역에만 있다. 선지 2의 '성장관리방안'은 옛 용어이고 현행은 성장관리계획이다.","개정":"이 문항의 선지 2는 '성장관리방안'을 '성장관리계획'으로 고친 문장이다. 성장관리계획구역·성장관리계획 규정은 법 제3절(제75조의2~제75조의3)에 있고 이 절은 <신설 2021.1.12>이다."},"30회-2차-051":{"한줄":"선지 중 기반시설유발계수가 가장 큰 것은 관광휴게시설 1.9다(영 별표 1의3 제27호).","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"별표 1의3","원문":"1. 단독주택: 0.7 … 4. 제2종 근린생활시설: 1.6 … 다. 비금속 광물제품 제조공장: 1.3 … 27. 관광휴게시설: 1.9 28. 장례시설: 0.7"}],"선지":[{"번호":1,"판정":"-","설명":"단독주택 0.7(별표 1의3 제1호)."},{"번호":2,"판정":"-","설명":"장례시설 0.7(별표 1의3 제28호)."},{"번호":3,"판정":"-","설명":"관광휴게시설 1.9로 선지 중 가장 크다(별표 1의3 제27호)."},{"번호":4,"판정":"-","설명":"제2종 근린생활시설 1.6(별표 1의3 제4호)."},{"번호":5,"판정":"-","설명":"비금속 광물제품 제조공장 1.3(별표 1의3 제17호다목)."}],"개념":[{"종류":"표","제목":"건축물별 기반시설유발계수 주요 값","머리":["유발계수","건축물"],"행":[["2.1","위락시설, 목재 및 나무제품 제조공장(공장 중 펄프·종이 제조공장은 2.5)"],["1.9","관광휴게시설"],["1.6","제2종 근린생활시설"],["1.4","문화 및 집회시설, 종교시설, 운수시설, 자원순환 관련 시설"],["1.3","제1종 근린생활시설, 판매시설, 비금속 광물제품 제조공장"],["0.7","단독주택, 공동주택, 교육연구시설, 업무시설, 장례시설 등"]]},{"종류":"표","제목":"기반시설설치비용 산정 요소","머리":["요소","내용","조문"],"행":[["산식","(기반시설 표준시설비용 + 용지비용) × 부과대상 건축연면적 × 민간 개발사업자 부담률","법 제68조제2항"],["용지비용","용지환산계수(0.4 범위에서 조례) × 개별공시지가 평균 × 건축물별 기반시설유발계수","법 제68조제4항"],["부담률","100분의 20, 100분의 25 범위에서 가감 가능","법 제68조제5항"],["표준시설비용 고시","매년 1월 1일 기준, 매년 6월 10일까지 국토교통부장관 고시","영 제68조"]]}],"함정":"선지 2의 장례시설은 0.7이다. 계수가 큰 쪽은 위락시설 2.1, 관광휴게시설 1.9, 제2종 근린생활시설 1.6 순이다."},"30회-2차-053":{"한줄":"천재지변, 그 밖의 사유로 도시개발사업을 긴급하게 할 필요가 있으면 국토교통부장관이 도시개발구역을 지정할 수 있다(법 제3조제3항제5호, 영 제4조제2항).","근거":[{"법령":"도시개발법","조문":"제3조제1항","원문":"① 다음 각 호의 어느 하나에 해당하는 자는 계획적인 도시개발이 필요하다고 인정되는 때에는 도시개발구역을 지정할 수 있다. <개정 2008.3.28, 2009.12.29, 2021.1.12, 2026.3.5> 1. 특별시장ㆍ통합특별시장ㆍ광역시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다) 2. 「지방자치법」 제198조제1항에 따른 인구 50만 이상 대도시의 시장(이하 \"대도시 시장\"이라 한다)"},{"법령":"도시개발법","조문":"제3조제2항","원문":"② 도시개발사업이 필요하다고 인정되는 지역이 둘 이상의 특별시ㆍ광역시ㆍ도ㆍ특별자치도(이하 \"시ㆍ도\"라 한다) 또는 「지방자치법」 제198조에 따른 서울특별시와 광역시를 제외한 인구 50만 이상의 대도시(이하 이 조, 제8조 및 제10조의2에서 \"대도시\"라 한다)의 행정구역에 걸치는 경우에는 관계 시ㆍ도지사 또는 대도시 시장이 협의하여 도시개발구역을 지정할 자를 정한다. <개정 2008.3.28, 2009.12.29, 2021.1.12, 2021.4.1>"},{"법령":"도시개발법","조문":"제3조제3항","원문":"③ 국토교통부장관은 다음 각 호의 어느 하나에 해당하면 제1항과 제2항에도 불구하고 도시개발구역을 지정할 수 있다. <개정 2009.12.29, 2013.3.23> … 4. 제2항에 따른 협의가 성립되지 아니하는 경우 5. 그 밖에 대통령령으로 정하는 경우"},{"법령":"도시개발법 시행령","조문":"제4조제2항","원문":"② 법 제3조제3항제5호에서 \"대통령령으로 정하는 경우\"란 천재지변, 그 밖의 사유로 인하여 도시개발사업을 긴급하게 할 필요가 있는 경우를 말한다."},{"법령":"도시개발법 시행령","조문":"제5조의2제1항","원문":"① 법 제3조의2제1항에 따라 도시개발구역을 둘 이상의 사업시행지구로 분할할 수 있는 경우는 지정권자가 도시개발사업의 효율적인 추진을 위하여 필요하다고 인정하는 경우로서 분할 후 각 사업시행지구의 면적이 각각 1만제곱미터 이상인 경우로 한다."},{"법령":"도시개발법","조문":"제4조제1항","원문":"① 지정권자는 도시개발구역을 지정하려면 해당 도시개발구역에 대한 도시개발사업의 계획(이하 \"개발계획\"이라 한다)을 수립하여야 한다. 다만, 제2항에 따라 개발계획을 공모하거나 대통령령으로 정하는 지역에 도시개발구역을 지정할 때에는 도시개발구역을 지정한 후에 개발계획을 수립할 수 있다. <개정 2011.9.30, 2012.1.17>"},{"법령":"도시개발법 시행령","조문":"제6조제1항","원문":"① 법 제4조제1항 단서에서 \"대통령령으로 정하는 지역\"이란 다음 각 호의 어느 하나에 해당하는 지역을 말한다. 1. 자연녹지지역"}],"선지":[{"번호":1,"판정":"틀림","설명":"인구 50만 이상 대도시의 시장도 도시개발구역을 지정할 수 있다(법 제3조제1항제2호)."},{"번호":2,"판정":"틀림","설명":"둘 이상의 시·도에 걸치면 관계 시·도지사가 협의하여 지정할 자를 정한다. 면적이 더 넓은 쪽으로 정하는 규정은 없다(법 제3조제2항)."},{"번호":3,"판정":"옳음","설명":"긴급한 필요가 있는 경우 국토교통부장관이 지정할 수 있다(법 제3조제3항제5호, 영 제4조제2항)."},{"번호":4,"판정":"틀림","설명":"분할은 분할 후 각 사업시행지구가 1만 제곱미터 이상일 때 가능하다. 총 면적이 1만 제곱미터 미만이면 둘로 나눌 수 없다(영 제5조의2제1항)."},{"번호":5,"판정":"틀림","설명":"자연녹지지역은 구역을 먼저 지정하고 개발계획을 나중에 수립할 수 있는 지역이다(법 제4조제1항 단서, 영 제6조제1항제1호)."}],"개념":[{"종류":"표","제목":"도시개발구역 지정권자","머리":["구분","내용","조문"],"행":[["원칙","시·도지사, 인구 50만 이상 대도시의 시장","법 제3조제1항"],["둘 이상의 시·도·대도시에 걸침","관계 시·도지사 또는 대도시 시장이 협의해 지정할 자를 정함","법 제3조제2항"],["국토교통부장관","국가 사업 필요, 관계 중앙행정기관의 장 요청, 공공기관·정부출연기관의 장이 30만 제곱미터 이상으로 국가계획과 밀접한 구역 지정 제안, 협의 불성립, 천재지변 등 긴급 필요","법 제3조제3항, 영 제4조"],["시장(대도시 제외)·군수·구청장","직접 지정하지 못하고 시·도지사에게 지정을 요청","법 제3조제4항"]]},{"종류":"표","제목":"구역 지정 후 개발계획을 수립할 수 있는 지역(영 제6조제1항)","머리":["구분","내용"],"행":[["용도지역","자연녹지지역, 지정면적 100분의 30 이하의 생산녹지지역"],["도시지역 외","도시지역 외의 지역"],["예외 지역","영 제2조제3항제3호 지역(국토교통부장관이 지역균형발전을 위해 협의해 지정하려는 지역)"],["혼합 구역","주거·상업·공업지역 면적 합계가 구역 지정면적의 100분의 30 이하인 지역"]]}],"함정":"선지 1은 대도시 시장이 도지사에게 요청해야 한다고 했다. 요청 절차는 군수·구청장·대도시 아닌 시장에게 적용된다. 선지 4의 1만 제곱미터는 분할 후 사업시행지구 기준이다.","개정":"법 제3조제1항은 <개정 2026.3.5>로 시·도지사에 통합특별시장이 포함된다."},"30회-2차-057":{"한줄":"분할 혼용방식은 수용 또는 사용 방식 지역과 환지 방식 지역을 사업시행지구별로 분할하여 시행하는 방식이다(영 제43조제2항제1호).","근거":[{"법령":"도시개발법 시행령","조문":"제43조제2항","원문":"② 시행자가 도시개발사업을 제1항제3호에 따른 혼용방식으로 시행하려는 경우에는 다음 각 호의 방식으로 도시개발사업을 시행할 수 있다. <개정 2012.3.26> 1. 분할 혼용방식: 수용 또는 사용 방식이 적용되는 지역과 환지 방식이 적용되는 지역을 사업시행지구별로 분할하여 시행하는 방식"},{"법령":"도시개발법 시행령","조문":"제43조제1항","원문":"① 시행자는 도시개발구역으로 지정하려는 지역에 대하여 다음 각 호에서 정하는 바에 따라 도시개발사업의 시행방식을 정함을 원칙으로 하되, 사업의 용이성ㆍ규모 등을 고려하여 필요하면 국토교통부장관이 정하는 기준에 따라 도시개발사업의 시행방식을 정할 수 있다. <개정 2013.3.23, 2021.1.5> … 2. 수용 또는 사용방식: 계획적이고 체계적인 도시개발 등 집단적인 조성과 공급이 필요한 경우"},{"법령":"도시개발법","조문":"제21조제2항","원문":"② 지정권자는 도시개발구역지정 이후 다음 각 호의 어느 하나에 해당하는 경우에는 도시개발사업의 시행방식을 변경할 수 있다."},{"법령":"도시개발법","조문":"제5조제1항제5호","원문":"① 개발계획에는 다음 각 호의 사항이 포함되어야 한다. 다만, 제13호부터 제16호까지의 규정에 해당하는 사항은 도시개발구역을 지정한 후에 개발계획에 포함시킬 수 있다. <개정 2011.9.30, 2015.8.28, 2019.8.27, 2021.12.21> … 5. 도시개발사업의 시행방식"},{"법령":"도시개발법","조문":"제11조제4항","원문":"④ 제2항에 따라 지방자치단체등이 도시개발사업의 전부를 환지 방식으로 시행하려고 할 때와 제1항제1호부터 제4호까지 또는 제11호(제1항제1호부터 제4호까지의 규정에 해당하는 자가 대통령령으로 정하는 비율을 초과하여 출자한 경우로 한정한다)에 해당하는 자가 도시개발사업의 일부를 환지 방식으로 시행하려고 할 때에는 대통령령으로 정하는 바에 따라 시행규정을 작성하여야 한다. 이 경우 제1항제2호부터 제4호까지의 시행자는 대통령령으로 정하는 기준에 따라 사업관리에 필요한 비용의 책정에 관한 사항을 시행규정에 포함할 수 있다. <개정 2011.9.30>"},{"법령":"도시개발법","조문":"제11조제3항","원문":"③ 지정권자는 제1항제5호에 따른 토지 소유자 2인 이상이 도시개발사업을 시행하려고 할 때 또는 같은 호에 따른 토지 소유자가 같은 항 제7호부터 제10호까지의 규정에 해당하는 자와 공동으로 도시개발사업을 시행하려고 할 때에는 대통령령으로 정하는 바에 따라 도시개발사업에 관한 규약을 정하게 할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"분할 혼용방식은 사업시행지구를 분할해 수용·사용 방식 지역과 환지 방식 지역을 각각 시행한다(영 제43조제2항제1호)."},{"번호":2,"판정":"틀림","설명":"계획적이고 체계적인 도시개발 등 집단적인 조성과 공급이 필요한 경우의 방식은 수용 또는 사용 방식이다(영 제43조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"지정권자는 구역 지정 이후에도 법 제21조제2항 각 호의 경우에는 시행방식을 변경할 수 있다(법 제21조제2항)."},{"번호":4,"판정":"틀림","설명":"시행방식은 개발계획에 포함되는 사항이며(법 제5조제1항제5호), 시행자가 국토교통부장관의 허가를 받는다는 규정은 없다."},{"번호":5,"판정":"틀림","설명":"지방자치단체등이 사업 전부를 환지 방식으로 시행하려면 시행규정을 작성한다. 규약은 토지 소유자가 2인 이상이거나 공동 시행할 때 정한다(법 제11조제3항·제4항)."}],"개념":[{"종류":"표","제목":"도시개발사업 시행방식","머리":["방식","적용","조문"],"행":[["환지 방식","토지의 교환·분할·합병·구획변경이나 공공시설 정비가 필요한 경우, 지가가 인근보다 현저히 높아 수용·사용이 어려운 경우","영 제43조제1항제1호"],["수용 또는 사용 방식","계획적이고 체계적인 도시개발 등 집단적인 조성과 공급이 필요한 경우","영 제43조제1항제2호"],["혼용 방식","구역이 부분적으로 환지 방식 또는 수용·사용 방식 요건에 해당하는 경우","영 제43조제1항제3호"],["분할 혼용","수용·사용 지역과 환지 지역을 사업시행지구별로 분할 시행","영 제43조제2항제1호"],["미분할 혼용","사업시행지구를 분할하지 않고 두 방식을 혼용. 환지에는 환지 규정, 그 밖에는 수용·사용 규정 적용","영 제43조제2항제2호"]]}],"함정":"선지 2는 집단적 조성·공급이 필요한 경우를 환지 방식으로 바꿨다. 수용 또는 사용 방식이 이 경우에 해당한다. 선지 3은 구역 지정 이후 변경이 불가능하다고 했지만 법 제21조제2항에 변경 사유가 있다."},"30회-2차-054":{"한줄":"전부 환지 방식 사업에서 공공시설 사업과 병행할 필요가 있어 지정되는 지방자치단체등은 지방자치단체, 한국토지주택공사, 지방공사, 외부감사 대상 신탁업자이며 국가는 포함되지 않는다(법 제11조제2항, 영 제20조제1항).","근거":[{"법령":"도시개발법","조문":"제11조제2항제2호","원문":"② 지정권자는 제1항 단서에도 불구하고 다음 각 호의 어느 하나에 해당하는 사유가 있으면 지방자치단체나 대통령령으로 정하는 자(이하 \"지방자치단체등\"이라 한다)를 시행자로 지정할 수 있다. 이 경우 도시개발사업을 시행하는 자가 시ㆍ도지사 또는 대도시 시장인 경우 국토교통부장관이 지정한다. <개정 2008.3.28, 2013.3.23> 2. 지방자치단체의 장이 집행하는 공공시설에 관한 사업과 병행하여 시행할 필요가 있다고 인정한 경우"},{"법령":"도시개발법 시행령","조문":"영 제20조제1항","원문":"① 법 제11조제2항 각 호 외의 부분 전단에서 \"대통령령으로 정하는 자\"란 한국토지주택공사, 「지방공기업법」에 따른 지방공사(이하 \"지방공사\"라 한다)와 제18조제5항제2호에 해당하는 자를 말한다. <개정 2009.9.21, 2017.12.5>"},{"법령":"도시개발법 시행령","조문":"영 제18조제5항제2호","원문":"⑤ 법 제11조제1항제9호에서 \"대통령령으로 정하는 요건에 해당하는 자\"란 다음 각 호의 어느 하나에 해당하는 자로서 경영의 건전성이 국토교통부령으로 정하여 고시하는 기준 이상인 자를 말한다. 다만, 「채무자 회생 및 파산에 관한 법률」에 따른 회생절차가 진행 중인 법인은 제외한다. <개정 2013.3.23, 2018.10.30> 2. 「자본시장과 금융투자업에 관한 법률」에 따른 신탁업자 중 「주식회사 등의 외부감사에 관한 법률」 제4조에 따른 외부감사의 대상이 되는 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"국가는 법 제11조제2항 및 영 제20조제1항의 지방자치단체등에 들어 있지 않아 이 경우 시행자로 지정될 수 없다."},{"번호":2,"판정":"옳음","설명":"지방자치단체는 지방자치단체등에 해당한다(법 제11조제2항)."},{"번호":3,"판정":"옳음","설명":"지방공사는 영 제20조제1항에 열거된 자다."},{"번호":4,"판정":"옳음","설명":"한국토지주택공사는 영 제20조제1항에 열거된 자다."},{"번호":5,"판정":"옳음","설명":"외부감사 대상 신탁업자는 영 제20조제1항이 가리키는 영 제18조제5항제2호에 해당한다."}],"개념":[{"종류":"표","제목":"환지 방식 시행자 지정의 원칙과 예외","머리":["구분","내용","조문"],"행":[["원칙","구역 전부를 환지 방식으로 시행하면 토지 소유자(제5호) 또는 조합(제6호)을 시행자로 지정","법 제11조제1항 단서"],["예외 사유 1","토지 소유자나 조합이 정해진 기간에 시행자 지정을 신청하지 않았거나 신청 내용이 위법·부당한 경우","법 제11조제2항제1호"],["예외 사유 2","지방자치단체의 장이 집행하는 공공시설 사업과 병행하여 시행할 필요가 있는 경우","법 제11조제2항제2호"],["예외 사유 3","국공유지 제외 토지면적 2분의 1 이상 소유자와 소유자 총수 2분의 1 이상이 지방자치단체등의 시행에 동의한 경우","법 제11조제2항제3호"],["지정 대상","지방자치단체, 한국토지주택공사, 지방공사, 외부감사 대상 신탁업자","영 제20조제1항, 제18조제5항제2호"],["신청 기간(사유 1)","개발계획 수립·고시일부터 1년(6개월 범위 연장 가능)","영 제20조제2항"]]}],"함정":"국가도 공공 성격의 시행자라서 당연히 지정될 것으로 보기 쉽다. 이 경우의 지정 대상은 영 제20조제1항에 열거된 자뿐이며 국가가 없다. 선지 5의 신탁업자는 영 제18조제5항제2호를 거쳐 포함된다."},"30회-2차-056":{"한줄":"국가 또는 지방자치단체가 주택건설사업자 등에게 대행시킬 수 있는 범위는 실시설계, 부지조성공사, 기반시설공사, 조성된 토지의 분양 네 가지 모두다(영 제25조의2제1항).","근거":[{"법령":"도시개발법","조문":"제11조제11항","원문":"⑪ 제1항제1호부터 제4호까지의 규정에 해당하는 자는 도시개발사업을 효율적으로 시행하기 위하여 필요한 경우에는 대통령령으로 정하는 바에 따라 설계ㆍ분양 등 도시개발사업의 일부를 「주택법」 제4조에 따른 주택건설사업자 등으로 하여금 대행하게 할 수 있다. <신설 2015.8.11, 2016.1.19>"},{"법령":"도시개발법 시행령","조문":"영 제25조의2제1항","원문":"① 법 제11조제11항에 따라 주택건설사업자 등에게 대행하게 할 수 있는 도시개발사업의 범위는 다음 각 호와 같다. 1. 실시설계 2. 부지조성공사 3. 기반시설공사 4. 조성된 토지의 분양"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄹ(조성된 토지의 분양)이 빠졌다(영 제25조의2제1항제4호)."},{"번호":2,"판정":"틀림","설명":"ㄷ(부지조성공사)이 빠졌다(영 제25조의2제1항제2호)."},{"번호":3,"판정":"틀림","설명":"ㄴ(기반시설공사)이 빠졌다(영 제25조의2제1항제3호)."},{"번호":4,"판정":"틀림","설명":"ㄱ(실시설계)이 빠졌다(영 제25조의2제1항제1호)."},{"번호":5,"판정":"옳음","설명":"ㄱ~ㄹ 모두 대행 범위에 속한다(영 제25조의2제1항)."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"실시설계는 대행 범위다(영 제25조의2제1항제1호)."},{"기호":"ㄴ","판정":"옳음","설명":"기반시설공사는 대행 범위다(영 제25조의2제1항제3호)."},{"기호":"ㄷ","판정":"옳음","설명":"부지조성공사는 대행 범위다(영 제25조의2제1항제2호)."},{"기호":"ㄹ","판정":"옳음","설명":"조성된 토지의 분양은 대행 범위다(영 제25조의2제1항제4호)."}],"개념":[{"종류":"흐름","제목":"시행자의 사업 대행 절차","단계":[{"이름":"대행 결정","설명":"공공시행자(국가·지방자치단체·공공기관·정부출연기관·지방공사)가 필요하다고 판단해 설계·분양 등 일부를 대행하게 함(법 제11조제11항)"},{"이름":"공고","설명":"개발사업의 목적·종류와 개요·시행기간·대행개발사업자의 자격요건과 제출서류·선정기준과 방식을 공고(영 제25조의2제2항)"},{"이름":"선정","설명":"경쟁입찰 방식으로 대행개발사업자 선정(영 제25조의2제2항)"},{"이름":"계약","설명":"대행에 관한 계약 체결(영 제25조의2제3항)"}]},{"종류":"표","제목":"대행 범위(영 제25조의2제1항)","머리":["호","사업","주의"],"행":[["제1호","실시설계","-"],["제2호","부지조성공사","-"],["제3호","기반시설공사","-"],["제4호","조성된 토지의 분양","분양까지 포함"]]}],"함정":"대행 범위에서 조성된 토지의 분양을 빼고 외우기 쉽다. 설계·공사 위주로만 기억하면 선지 1~3 중 하나를 고르게 된다. 네 가지 모두 대행 범위다."},"30회-2차-058":{"한줄":"토지상환채권의 지급보증 요건은 제5호부터 제11호까지의 시행자에게만 붙어 있어 제1호의 지방자치단체는 지급보증 없이 발행할 수 있다(법 제23조제1항).","근거":[{"법령":"도시개발법","조문":"제23조제1항","원문":"① 시행자는 토지 소유자가 원하면 토지등의 매수 대금의 일부를 지급하기 위하여 대통령령으로 정하는 바에 따라 사업 시행으로 조성된 토지ㆍ건축물로 상환하는 채권(이하 \"토지상환채권\"이라 한다)을 발행할 수 있다. 다만, 제11조제1항제5호부터 제11호까지의 규정에 해당하는 자는 대통령령으로 정하는 금융기관 등으로부터 지급보증을 받은 경우에만 이를 발행할 수 있다."},{"법령":"도시개발법","조문":"제22조제1항","원문":"① 시행자는 도시개발사업에 필요한 토지등을 수용하거나 사용할 수 있다. 다만, 제11조제1항제5호 및 제7호부터 제11호까지의 규정(같은 항 제1호부터 제4호까지의 규정에 해당하는 자가 100분의 50 비율을 초과하여 출자한 경우는 제외한다)에 해당하는 시행자는 사업대상 토지면적의 3분의 2 이상에 해당하는 토지를 소유하고 토지 소유자 총수의 2분의 1 이상에 해당하는 자의 동의를 받아야 한다. 이 경우 토지 소유자의 동의요건 산정기준일은 도시개발구역지정 고시일을 기준으로 하며, 그 기준일 이후 시행자가 취득한 토지에 대하여는 동의 요건에 필요한 토지 소유자의 총수에 포함하고 이를 동의한 자의 수로 산정한다."},{"법령":"도시개발법","조문":"제25조제2항","원문":"② 시행자(지정권자가 시행자인 경우는 제외한다)는 제1항에 따라 해당 대금의 전부 또는 일부를 미리 받으려면 지정권자의 승인을 받아야 한다."},{"법령":"도시개발법","조문":"제25조의2제1항","원문":"① 시행자는 도시를 자연친화적으로 개발하거나 복합적ㆍ입체적으로 개발하기 위하여 필요한 경우에는 대통령령으로 정하는 절차에 따라 미리 지정권자의 승인을 받아 다음 각 호의 어느 하나에 해당하는 자에게 원형지를 공급하여 개발하게 할 수 있다. 이 경우 공급될 수 있는 원형지의 면적은 도시개발구역 전체 토지 면적의 3분의 1 이내로 한정한다. <개정 2015.8.11> 1. 국가 또는 지방자치단체 2. 「공공기관의 운영에 관한 법률」 제4조에 따른 공공기관 3. 「지방공기업법」에 따라 설립된 지방공사 4. 제11조제1항제1호 또는 제2호에 따른 시행자가 복합개발 등을 위하여 실시한 공모에서 선정된 자 5. 원형지를 학교나 공장 등의 부지로 직접 사용하는 자"},{"법령":"도시개발법 시행령","조문":"영 제57조제2항","원문":"② 조성토지등의 공급은 경쟁입찰의 방법에 따른다. <개정 2017.12.5>"},{"법령":"도시개발법 시행령","조문":"영 제57조제3항","원문":"③ 제2항에도 불구하고 제1호부터 제3호까지의 어느 하나에 해당하는 토지는 추첨의 방법으로 분양할 수 있다. 다만, 법 제11조제1항제1호부터 제4호까지의 규정에 따른 시행자가 제1호의 토지 중 임대주택 건설용지를 공급하는 경우에는 추첨의 방법으로 분양하여야 한다. <신설 2017.12.5> 1. 「주택법」 제2조제6호에 따른 국민주택규모 이하의 주택건설용지 2. 「주택법」 제2조제24호에 따른 공공택지 3. 국토교통부령으로 정하는 면적 이하의 단독주택용지 및 공장용지"}],"선지":[{"번호":1,"판정":"틀림","설명":"동의 요건이 붙는 시행자는 제5호와 제7호~제11호 시행자다. 지방공사(제4호)는 토지 소유자 전원의 동의 없이도 수용·사용할 수 있다(법 제22조제1항)."},{"번호":2,"판정":"옳음","설명":"지급보증은 제5호부터 제11호까지의 시행자만 받아야 한다. 지방자치단체는 제1호라서 필요 없다(법 제23조제1항)."},{"번호":3,"판정":"틀림","설명":"지정권자가 아닌 시행자는 선수금을 받으려면 지정권자의 승인을 받아야 한다(법 제25조제2항)."},{"번호":4,"판정":"틀림","설명":"원형지 면적은 구역 전체 토지 면적의 3분의 1 이내로 한정된다(법 제25조의2제1항). 3분의 1을 넘을 수 없다."},{"번호":5,"판정":"틀림","설명":"조성토지등의 공급은 경쟁입찰이 원칙이다. 일정한 용지는 추첨으로, 법정 사유가 있으면 수의계약으로 공급한다(영 제57조제2항·제3항·제5항)."}],"개념":[{"종류":"표","제목":"조성토지등의 공급방법(영 제57조)","머리":["방법","대상","조문"],"행":[["경쟁입찰(원칙)","조성토지등. 최고가격 입찰자가 낙찰","제2항, 제7항"],["추첨","국민주택규모 이하 주택건설용지, 공공택지, 국토교통부령이 정한 면적 이하의 단독주택용지·공장용지. 공공시행자가 임대주택 건설용지를 공급할 때는 추첨 의무","제3항"],["수의계약","학교용지·공공청사용지 등 공공용지를 공급받을 수 있는 자에게 공급, 토지상환채권으로 상환, 2회 이상 유찰 등","제5항"],["가격","감정가격","제6항"]]},{"종류":"표","제목":"토지상환채권 발행 요건","머리":["항목","내용","조문"],"행":[["발행 가능 시행자","시행자(토지 소유자가 원하면 매수대금 일부를 사업으로 조성된 토지·건축물로 상환)","법 제23조제1항"],["지급보증","제5호~제11호 시행자는 금융기관 등의 지급보증을 받은 경우에만 발행","법 제23조제1항 단서"],["발행계획 승인","지정권자가 아닌 시행자는 미리 지정권자의 승인","법 제23조제2항"],["발행 규모","분양토지·분양건축물 면적의 2분의 1 이하","영 제45조"]]}],"함정":"지급보증은 민간 시행자에게 요구되는 요건이다. 공공 시행자(제1~4호)는 지급보증 없이 발행할 수 있다. 수용·사용 동의 요건도 지방공사(제4호)에는 적용되지 않는다."},"30회-2차-055":{"한줄":"환지 계획에는 필지별로 된 환지 명세와, 필지별·권리별로 된 청산 대상 토지 명세가 들어간다(법 제28조제1항제2호·제3호).","근거":[{"법령":"도시개발법","조문":"제28조제1항","원문":"① 시행자는 도시개발사업의 전부 또는 일부를 환지 방식으로 시행하려면 다음 각 호의 사항이 포함된 환지 계획을 작성하여야 한다. <개정 2011.9.30, 2013.3.23> / 2. 필지별로 된 환지 명세 / 3. 필지별과 권리별로 된 청산 대상 토지 명세"},{"법령":"도시개발법 시행규칙","조문":"제28조제1항","원문":"① 법 제28조제5항에 따른 보류지는 법 제17조에 따른 실시계획인가에 따라 정하되, 도시개발구역이 2 이상의 환지계획구역으로 구분되는 경우에는 환지계획구역별로 사업비 및 보류지를 책정하여야 한다."},{"법령":"도시개발법","조문":"제36조제1항","원문":"① 환지 예정지가 지정되면 종전의 토지의 소유자와 임차권자등은 환지 예정지 지정의 효력발생일부터 환지처분이 공고되는 날까지 환지 예정지나 해당 부분에 대하여 종전과 같은 내용의 권리를 행사할 수 있으며 종전의 토지는 사용하거나 수익할 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"환지처분은 시행자가 한다. 지정권자의 준공검사를 받은 날(지정권자가 시행자이면 공사 완료 공고 때)부터 60일 이내에 하며, 지정권자에게 환지처분을 신청하는 절차는 없다(법 제40조제4항, 영 제65조)."},{"번호":2,"판정":"틀림","설명":"도시개발구역이 둘 이상의 환지계획구역으로 나뉘면 환지계획구역별로 사업비와 보류지를 책정한다(규칙 제28조제1항)."},{"번호":3,"판정":"틀림","설명":"조성토지등의 가격은 감정평가법인등이 평가한 뒤 토지평가협의회 심의로 결정한다. 개별공시지가로 정하지 않는다(법 제28조제3항, 영 제59조)."},{"번호":4,"판정":"틀림","설명":"환지 예정지가 지정되면 임차권자등은 종전 토지를 사용·수익할 수 없고 환지 예정지에서 권리를 행사한다(법 제36조제1항)."},{"번호":5,"판정":"옳음","설명":"환지 계획에는 필지별 환지 명세와 필지별·권리별 청산 대상 토지 명세가 포함된다(법 제28조제1항제2호·제3호)."}],"개념":[{"종류":"표","제목":"환지 계획에 들어가는 내용","머리":["구분","내용","조문"],"행":[["환지 설계","환지예정지도, 환지전후대비도, 과부족면적표시도, 환지전후 평가단가 표시도 첨부","법 제28조제1항제1호, 규칙 제26조제1항"],["필지별 환지 명세","필지별로 작성","법 제28조제1항제2호"],["청산 대상 토지 명세","필지별과 권리별로 작성","법 제28조제1항제3호"],["체비지·보류지 명세","법 제34조의 체비지·보류지","법 제28조제1항제4호"],["입체 환지","입체 환지용 건축물 명세, 공급 방법·규모","법 제28조제1항제5호"],["국토교통부령 사항","수입·지출 계획서, 평균부담률·비례율과 계산서(평가식), 건축 계획(입체 환지), 토지평가협의회 심의 결과","규칙 제26조제3항"]]},{"종류":"비교","제목":"환지설계 방식(규칙 제27조제3항)","왼쪽":{"이름":"평가식(원칙)","항목":["도시개발사업 시행 전후 토지의 평가가액에 비례해 환지를 결정","환지 계획에 평균부담률·비례율과 계산서가 들어감"]},"오른쪽":{"이름":"면적식","항목":["시행 전 토지와 위치를 기준으로 환지를 결정","환지지정으로 토지의 이동이 경미하거나 기반시설의 단순한 정비 등의 경우에 적용","한 환지계획구역에서는 같은 방식을 적용"]}}],"함정":"사업비와 보류지를 구역 전체로 책정하는 것으로 오해하기 쉽다. 환지계획구역이 둘 이상이면 구역별로 책정한다. 조성토지등 가격은 공시지가가 아니라 감정평가와 토지평가협의회 심의로 정한다."},"30회-2차-062":{"한줄":"정비예정구역 면적은 20퍼센트 미만으로 변경할 때만 경미한 변경이라 25퍼센트 변경은 지방의회 의견청취를 생략할 수 없다(령 제6조제4항제5호).","근거":[{"법령":"도시 및 주거환경정비법","조문":"제6조제3항","원문":"③ 제1항 및 제2항에도 불구하고 대통령령으로 정하는 경미한 사항을 변경하는 경우에는 주민공람과 지방의회의 의견청취 절차를 거치지 아니할 수 있다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제6조제4항","원문":"④ 법 제6조제3항 및 제7조제1항 단서에서 \"대통령령으로 정하는 경미한 사항을 변경하는 경우\"란 각각 다음 각 호의 경우를 말한다. / 2. 정비사업의 계획기간을 단축하는 경우 / 3. 공동이용시설에 대한 설치계획을 변경하는 경우 / 4. 사회복지시설 및 주민문화시설 등에 대한 설치계획을 변경하는 경우 / 5. 구체적으로 면적이 명시된 법 제5조제1항제9호에 따른 정비예정구역(이하 \"정비예정구역\"이라 한다)의 면적을 20퍼센트 미만의 범위에서 변경하는 경우 / 8. 정비사업의 시행을 위하여 필요한 재원조달에 관한 사항을 변경하는 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"공동이용시설 설치계획 변경은 경미한 변경이다(령 제6조제4항제3호)."},{"번호":2,"판정":"옳음","설명":"정비사업의 계획기간을 단축하는 경우는 경미한 변경이다(령 제6조제4항제2호)."},{"번호":3,"판정":"옳음","설명":"사회복지시설 및 주민문화시설 등의 설치계획 변경은 경미한 변경이다(령 제6조제4항제4호)."},{"번호":4,"판정":"틀림","설명":"정비예정구역 면적은 20퍼센트 미만 범위의 변경만 경미하다. 25퍼센트는 의견청취를 생략할 수 없다(령 제6조제4항제5호)."},{"번호":5,"판정":"옳음","설명":"재원조달에 관한 사항 변경은 경미한 변경이다(령 제6조제4항제8호)."}],"개념":[{"종류":"표","제목":"기본계획 경미한 변경(령 제6조제4항)","머리":["항목","경미한 변경 범위"],"행":[["정비기반시설","규모 확대, 또는 면적을 10퍼센트 미만 범위에서 축소"],["정비사업 계획기간","단축"],["공동이용시설·사회복지시설·주민문화시설 설치계획","변경"],["정비예정구역 면적(면적이 명시된 경우)","20퍼센트 미만 범위에서 변경"],["단계별 정비사업 추진계획","변경"],["건폐율·용적률","각 20퍼센트 미만 범위에서 변경"],["재원조달에 관한 사항","변경"],["효과","주민공람·지방의회 의견청취 생략(법 제6조제3항), 협의·지방도시계획위원회 심의 생략(법 제7조제1항 단서)"]]}],"함정":"정비예정구역 면적은 20퍼센트 미만, 정비기반시설 축소는 10퍼센트 미만이다. 기준 숫자를 서로 바꿔 25퍼센트를 경미하다고 보면 틀린다. 계획기간은 단축만 경미하고 연장은 아니다."},"30회-2차-064":{"한줄":"이동이 쉽지 않은 물건을 쌓아놓는 행위는 1개월 이상일 때 허가 대상이라 14일 동안 쌓아두는 데는 허가가 필요 없다(령 제15조제1항제6호).","근거":[{"법령":"도시 및 주거환경정비법","조문":"제19조제1항제6호","원문":"① 정비구역에서 다음 각 호의 어느 하나에 해당하는 행위를 하려는 자는 시장ㆍ군수등의 허가를 받아야 한다. 허가받은 사항을 변경하려는 때에도 또한 같다. / 6. 물건을 쌓아 놓는 행위"},{"법령":"도시 및 주거환경정비법 시행령","조문":"제15조제1항제6호","원문":"① 법 제19조제1항에 따라 시장ㆍ군수등의 허가를 받아야 하는 행위는 다음 각 호와 같다. <개정 2021.1.5> / 6. 물건을 쌓아놓는 행위 : 이동이 쉽지 아니한 물건을 1개월 이상 쌓아놓는 행위"},{"법령":"도시 및 주거환경정비법","조문":"제19조제8항","원문":"⑧ 정비예정구역 또는 정비구역(이하 \"정비구역등\"이라 한다)에서는 「주택법」 제2조제11호가목에 따른 지역주택조합의 조합원을 모집해서는 아니 된다. <신설 2018.6.12>"},{"법령":"도시 및 주거환경정비법","조문":"제8조제3항","원문":"③ 정비구역의 지정권자는 정비구역의 진입로 설치를 위하여 필요한 경우에는 진입로 지역과 그 인접지역을 포함하여 정비구역을 지정할 수 있다."},{"법령":"도시 및 주거환경정비법","조문":"제7조제3항","원문":"③ 기본계획의 수립권자는 기본계획을 수립하거나 변경한 때에는 지체 없이 이를 해당 지방자치단체의 공보에 고시하고 일반인이 열람할 수 있도록 하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제6조제1항","원문":"① 기본계획의 수립권자는 기본계획을 수립하거나 변경하려는 경우에는 14일 이상 주민에게 공람하여 의견을 들어야 하며, 제시된 의견이 타당하다고 인정되면 이를 기본계획에 반영하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"기본계획을 수립하려면 14일 이상 주민에게 공람해 의견을 듣는다(법 제6조제1항)."},{"번호":2,"판정":"옳음","설명":"수립한 때에는 지체 없이 공보에 고시하고 일반인이 열람하게 한다(법 제7조제3항)."},{"번호":3,"판정":"옳음","설명":"진입로 설치에 필요하면 진입로 지역과 인접지역을 포함해 정비구역을 지정할 수 있다(법 제8조제3항)."},{"번호":4,"판정":"옳음","설명":"정비예정구역과 정비구역에서는 지역주택조합 조합원을 모집할 수 없다(법 제19조제8항)."},{"번호":5,"판정":"틀림","설명":"허가 대상은 1개월 이상 쌓아놓는 행위다. 14일은 기준에 미치지 못한다(령 제15조제1항제6호)."}],"개념":[{"종류":"표","제목":"정비구역 행위허가(법 제19조, 령 제15조)","머리":["구분","내용"],"행":[["건축물의 건축 등","가설건축물 포함 건축, 용도변경"],["공작물의 설치","건축물이 아닌 인공 시설물의 설치"],["토지의 형질변경","절토·성토·정지·포장 등, 굴착, 공유수면 매립"],["토석의 채취","흙·모래·자갈·바위 채취(형질변경 목적이면 형질변경으로 본다)"],["토지분할","허가 대상"],["물건을 쌓아놓는 행위","이동이 쉽지 아니한 물건을 1개월 이상 쌓아놓는 행위"],["죽목의 벌채 및 식재","허가 대상"],["허가 불요","재해복구·재난수습 응급조치, 붕괴 우려 건축물의 안전조치 등(법 제19조제2항)"]]}],"함정":"14일은 기본계획 주민공람 기간(법 제6조제1항)이다. 물건 쌓아놓기의 허가 기준은 1개월이다. 지역주택조합 조합원 모집 금지는 정비구역뿐 아니라 정비예정구역에도 적용된다."},"30회-2차-059":{"한줄":"조합 정관에는 정비구역의 위치 및 면적이 포함되어야 한다(법 제40조제1항제4호).","근거":[{"법령":"도시 및 주거환경정비법","조문":"제40조제1항제4호","원문":"① 조합의 정관에는 다음 각 호의 사항이 포함되어야 한다. <개정 2023.12.26> / 4. 정비구역의 위치 및 면적"},{"법령":"도시 및 주거환경정비법","조문":"제26조제3항","원문":"③ 제2항에 따라 시장ㆍ군수등이 직접 정비사업을 시행하거나 토지주택공사등을 사업시행자로 지정ㆍ고시한 때에는 그 고시일 다음 날에 추진위원회의 구성승인 또는 조합설립인가가 취소된 것으로 본다. 이 경우 시장ㆍ군수등은 해당 지방자치단체의 공보에 해당 내용을 고시하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제38조제3항","원문":"③ 조합은 명칭에 \"정비사업조합\"이라는 문자를 사용하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제42조제3항","원문":"③ 조합장 또는 이사가 자기를 위하여 조합과 계약이나 소송을 할 때에는 감사가 조합을 대표한다."},{"법령":"도시 및 주거환경정비법","조문":"제23조제4항","원문":"④ 제3항에 따라 건축물을 건설하여 공급하는 경우 주택, 부대시설 및 복리시설을 제외한 건축물(이하 이 항에서 \"공동주택 외 건축물\"이라 한다)은 「국토의 계획 및 이용에 관한 법률」에 따른 준주거지역 및 상업지역에서만 건설할 수 있다. 이 경우 공동주택 외 건축물의 연면적은 전체 건축물 연면적의 100분의 30 이하이어야 한다. <개정 2025.1.31>"}],"선지":[{"번호":1,"판정":"옳음","설명":"정비구역의 위치 및 면적은 정관의 필수 기재사항이다(법 제40조제1항제4호)."},{"번호":2,"판정":"틀림","설명":"토지주택공사등을 사업시행자로 지정·고시한 때에는 고시일 다음 날에 조합설립인가가 취소된 것으로 본다(법 제26조제3항). 고시일이 아니다."},{"번호":3,"판정":"틀림","설명":"조합은 명칭에 '정비사업조합'이라는 문자를 사용해야 한다(법 제38조제3항)."},{"번호":4,"판정":"틀림","설명":"조합장 또는 이사가 자기를 위해 조합과 소송할 때는 감사가 조합을 대표한다(법 제42조제3항)."},{"번호":5,"판정":"틀림","설명":"공동주택 외 건축물은 준주거지역 및 상업지역에서만 건설할 수 있다. 그 밖의 지역에서는 건설할 수 없다(법 제23조제4항)."}],"개념":[{"종류":"표","제목":"조합의 성립·명칭·대표","머리":["항목","내용","조문"],"행":[["법인격","조합은 법인","법 제38조제1항"],["성립","조합설립인가일부터 30일 이내에 주된 사무소 소재지에서 등기하는 때","법 제38조제2항"],["명칭","'정비사업조합'이라는 문자를 사용","법 제38조제3항"],["조합장의 직무","조합 대표, 사무 총괄, 총회·대의원회 의장","법 제42조제1항"],["자기 거래·소송","조합장 또는 이사가 자기를 위해 조합과 계약·소송을 할 때 감사가 조합을 대표","법 제42조제3항"],["겸직 금지","같은 목적의 정비사업을 하는 다른 조합의 임원·직원 겸직 불가","법 제42조제4항"]]},{"종류":"표","제목":"공공시행자 지정 사유(재개발·재건축)","머리":["사유","내용","조문"],"행":[["긴급 시행","천재지변, 사용제한·사용금지 등 불가피한 사유로 긴급히 시행 필요","법 제26조제1항제1호"],["인가 미신청","정비계획상 시행 예정일부터 2년 내 사업시행계획인가 미신청(재건축 제외), 추진위원회 승인 후 3년 내 조합설립인가 미신청, 조합설립인가 후 3년 내 사업시행계획인가 미신청","법 제26조제1항제2·3호"],["도시계획사업 병행·순환정비","지방자치단체장이 시행하는 도시·군계획사업과 병행, 순환정비방식 시행 필요","법 제26조제1항제4·5호"],["사업시행계획인가 취소","인가가 취소된 때","법 제26조제1항제6호"],["동의 기준","국·공유지 면적(토지주택공사등 소유 합산)이 2분의 1 이상이고 토지등소유자 과반수 동의, 또는 토지면적 2분의 1 이상 소유자와 토지등소유자 3분의 2 이상이 요청","법 제26조제1항제7·8호"],["효과","지정·고시일 다음 날 추진위원회 구성승인·조합설립인가 취소로 봄","법 제26조제3항"]]}],"함정":"취소 간주 시점은 고시일이 아니라 고시일 다음 날이다. 자기를 위한 소송에서 조합을 대표하는 자는 이사가 아니라 감사다. 오피스텔 등 공동주택 외 건축물은 준주거·상업지역으로 한정된다."},"30회-2차-060":{"한줄":"국가 또는 지방자치단체는 시장·군수등이 아닌 사업시행자가 시행하는 정비사업에 드는 비용의 일부를 보조 또는 융자하거나 융자를 알선할 수 있다(법 제95조제3항).","근거":[{"법령":"도시 및 주거환경정비법","조문":"제92조제1항","원문":"① 정비사업비는 이 법 또는 다른 법령에 특별한 규정이 있는 경우를 제외하고는 사업시행자가 부담한다."},{"법령":"도시 및 주거환경정비법","조문":"제95조제3항","원문":"③ 국가 또는 지방자치단체는 시장ㆍ군수등이 아닌 사업시행자가 시행하는 정비사업에 드는 비용의 일부를 보조 또는 융자하거나 융자를 알선할 수 있다."},{"법령":"도시 및 주거환경정비법","조문":"제98조제4항","원문":"④ 정비구역의 국유ㆍ공유재산은 「국유재산법」 제9조 또는 「공유재산 및 물품 관리법」 제10조에 따른 국유재산종합계획 또는 공유재산관리계획과 「국유재산법」 제43조 및 「공유재산 및 물품 관리법」 제29조에 따른 계약의 방법에도 불구하고 사업시행자 또는 점유자 및 사용자에게 다른 사람에 우선하여 수의계약으로 매각 또는 임대될 수 있다."},{"법령":"도시 및 주거환경정비법","조문":"제93조제4항","원문":"④ 시장ㆍ군수등이 아닌 사업시행자는 부과금 또는 연체료를 체납하는 자가 있는 때에는 시장ㆍ군수등에게 그 부과ㆍ징수를 위탁할 수 있다."},{"법령":"도시 및 주거환경정비법","조문":"제94조제2항","원문":"② 사업시행자는 정비사업을 시행하는 지역에 전기ㆍ가스 등의 공급시설을 설치하기 위하여 공동구를 설치하는 경우에는 다른 법령에 따라 그 공동구에 수용될 시설을 설치할 의무가 있는 자에게 공동구의 설치에 드는 비용을 부담시킬 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"정비사업비는 특별한 규정이 없으면 사업시행자가 부담한다(법 제92조제1항)."},{"번호":2,"판정":"틀림","설명":"시장·군수등이 아닌 사업시행자의 사업에도 비용의 일부를 보조 또는 융자할 수 있다. 융자 알선에 그치지 않는다(법 제95조제3항)."},{"번호":3,"판정":"옳음","설명":"정비구역의 국유·공유재산은 사업시행자 또는 점유자·사용자에게 다른 사람에 우선하여 수의계약으로 매각 또는 임대될 수 있다(법 제98조제4항)."},{"번호":4,"판정":"옳음","설명":"시장·군수등이 아닌 사업시행자는 체납자의 부과·징수를 시장·군수등에게 위탁할 수 있다(법 제93조제4항)."},{"번호":5,"판정":"옳음","설명":"공동구에 수용될 시설을 설치할 의무가 있는 자에게 설치비용을 부담시킬 수 있다(법 제94조제2항)."}],"개념":[{"종류":"표","제목":"정비사업 비용 부담","머리":["항목","내용","조문"],"행":[["원칙","정비사업비는 사업시행자가 부담","법 제92조제1항"],["시장·군수등 부담","시장·군수등이 아닌 사업시행자의 정비계획상 주요 정비기반시설·공동이용시설, 임시거주시설 건설비의 전부 또는 일부 부담 가능","법 제92조제2항"],["부과금·연체료","토지등소유자에게 비용과 수입의 차액을 부과·징수. 체납 시 시장·군수등에게 위탁 가능(징수액의 100분의 4 교부)","법 제93조"],["정비기반시설 관리자","시장·군수등이 시행하는 사업으로 현저한 이익을 받는 관리자에게 협의 후 일부 부담","법 제94조제1항"],["공동구","수용 시설 설치 의무자에게 설치비용 부담","법 제94조제2항"],["보조·융자","시장·군수등이 아닌 사업시행자 사업은 비용 일부 보조·융자 또는 융자 알선","법 제95조제3항"],["국·공유재산","사업시행자·점유자·사용자에게 우선 수의계약 매각·임대","법 제98조제4항"]]}],"함정":"'융자를 알선할 수는 있으나 직접 보조할 수는 없다'는 부분이 틀렸다. 법 제95조제3항은 보조, 융자, 융자 알선을 모두 열어 둔다. 법 제95조제1항의 국가·시·도 보조는 시장·군수·구청장 또는 토지주택공사등이 시행하는 사업에 대한 별도 규정이다."},"30회-2차-063":{"한줄":"임원 보수·선임방법·변경·해임에 관한 정관 변경 총회는 조합원 10분의 1 이상의 요구로 소집하고, 총회 소집 통지는 개최 7일 전까지 한다(법 제44조제2항·제4항).","근거":[{"법령":"도시 및 주거환경정비법","조문":"제44조제2항","원문":"② 총회는 조합장이 직권으로 소집하거나 조합원 5분의 1 이상(정관의 기재사항 중 제40조제1항제6호에 따른 조합임원의 권리ㆍ의무ㆍ보수ㆍ선임방법ㆍ변경 및 해임에 관한 사항을 변경하기 위한 총회의 경우는 10분의 1 이상으로 한다) 또는 대의원 3분의 2 이상의 요구로 조합장이 소집하며, 조합원 또는 대의원의 요구로 총회를 소집하는 경우 조합은 소집을 요구하는 자가 본인인지 여부를 대통령령으로 정하는 기준에 따라 정관으로 정하는 방법으로 확인하여야 한다. <개정 2019.4.23, 2023.7.18>"},{"법령":"도시 및 주거환경정비법","조문":"제44조제4항","원문":"④ 제2항 및 제3항에 따라 총회를 소집하려는 자는 총회가 개최되기 7일 전까지 회의 목적ㆍ안건ㆍ일시 및 장소와 제45조제5항, 제6항 및 제8항에 따른 의결권의 행사기간 및 장소 등 의결권 행사에 필요한 사항을 정하여 조합원에게 통지하여야 한다. <개정 2021.8.10, 2024.12.3>"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ은 10분의 1이다. 3분의 1은 아니다. ㄴ 7일은 맞다."},{"번호":2,"판정":"틀림","설명":"5분의 1은 일반 총회 소집 요구 기준이다. 이 문항의 ㄱ은 10분의 1이다."},{"번호":3,"판정":"틀림","설명":"ㄱ은 10분의 1, ㄴ은 7일이다."},{"번호":4,"판정":"옳음","설명":"ㄱ 10, ㄴ 7이다."},{"번호":5,"판정":"틀림","설명":"ㄴ은 10일이 아니라 7일이다."}],"개념":[{"종류":"표","제목":"총회 소집과 의결","머리":["구분","내용","조문"],"행":[["소집권자","조합장 직권, 또는 조합원 5분의 1 이상·대의원 3분의 2 이상 요구로 조합장 소집","법 제44조제2항"],["임원 보수 등 변경 총회","조합원 10분의 1 이상 요구","법 제44조제2항"],["임원 미선임","사임·해임·임기만료 후 6개월 이상 임원 미선임 시 시장·군수등이 임원 선출 총회 소집 가능","법 제44조제3항"],["소집 통지","개최 7일 전까지 회의 목적·안건·일시·장소와 의결권 행사 사항 통지","법 제44조제4항"],["의결 정족수","조합원 과반수 출석 + 출석 조합원 과반수 찬성(다른 규정 없을 때)","법 제45조제3항"],["직접 출석","원칙 조합원의 100분의 10 이상, 시공자 선정은 과반수, 창립총회·사업시행계획서·관리처분계획 등은 100분의 20 이상","법 제45조제10항"]]}],"함정":"총회 소집 요구는 원칙 5분의 1이지만 임원 보수·선임방법·변경·해임 정관 변경 총회는 10분의 1이다. 통지 기한 7일은 대의원회 소집 통지(령 제44조제7항)와 같고, 창립총회는 14일 전(령 제27조제2항)으로 다르다."},"30회-2차-061":{"한줄":"분양대상자별 분담금의 추산액은 분양통지 사항이고 분양공고 사항에는 명시되어 있지 않다(법 제72조제1항제2호, 영 제59조제2항).","근거":[{"법령":"도시 및 주거환경정비법","조문":"법 제72조제1항제2호","원문":"2. 분양대상자별 분담금의 추산액"},{"법령":"도시 및 주거환경정비법 시행령","조문":"영 제59조제2항제3호~제6호","원문":"② 법 제72조제1항 각 호 외의 부분 본문에서 \"분양의 대상이 되는 대지 또는 건축물의 내역 등 대통령령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. <개정 2025.4.29> / 3. 분양신청기간 및 장소 / 4. 분양대상 대지 또는 건축물의 내역 / 5. 분양신청자격 / 6. 분양신청방법"}],"선지":[{"번호":1,"판정":"옳음","설명":"분양신청자격은 분양공고 사항이다(영 제59조제2항제5호)."},{"번호":2,"판정":"옳음","설명":"분양신청방법은 분양공고 사항이다(영 제59조제2항제6호)."},{"번호":3,"판정":"옳음","설명":"분양신청기간 및 장소는 분양공고 사항이다(영 제59조제2항제3호)."},{"번호":4,"판정":"틀림","설명":"분양대상자별 분담금의 추산액은 토지등소유자에게 하는 통지 사항이다(법 제72조제1항제2호). 영 제59조제2항의 공고 사항에는 없다."},{"번호":5,"판정":"옳음","설명":"분양대상 대지 또는 건축물의 내역은 분양공고 사항이다(영 제59조제2항제4호)."}],"개념":[{"종류":"비교","제목":"분양통지와 분양공고","왼쪽":{"이름":"분양통지(토지등소유자에게)","항목":["분양대상자별 종전 토지·건축물의 명세와 사업시행계획인가 고시일 기준 가격(법 제72조제1항제1호)","분양대상자별 분담금의 추산액(제2호)","분양신청기간(제3호)","사업시행인가 내용, 사업 종류·명칭·구역 위치·면적, 신청기간·장소, 대상 내역, 신청자격, 신청방법, 미신청자 조치(영 제59조제3항제1호)","분양신청서(영 제59조제3항제2호)"]},"오른쪽":{"이름":"분양공고(일간신문)","항목":["사업시행인가의 내용","정비사업의 종류·명칭 및 정비구역의 위치·면적","분양신청기간 및 장소","분양대상 대지 또는 건축물의 내역","분양신청자격","분양신청방법","토지등소유자 외의 권리자의 권리신고방법","분양을 신청하지 아니한 자에 대한 조치(이상 영 제59조제2항제1호~제8호)"]}},{"종류":"표","제목":"분양공고·분양신청 기간(법 제72조)","머리":["항목","내용","조문"],"행":[["통지·공고 시기","사업시행계획인가 고시일(인가 후 시공자를 선정한 경우 계약 체결일)부터 90일 이내","제1항"],["예외","토지등소유자 1인이 시행하는 재개발사업은 통지·공고하지 않음","제1항 단서"],["분양신청기간","통지한 날부터 30일 이상 60일 이내. 관리처분계획 수립에 지장이 없으면 20일 범위에서 한 차례 연장","제2항"],["재공고","신청기간 종료 후 사업시행계획인가 변경으로 세대수·주택규모가 달라지면 분양공고 등을 다시 할 수 있음","제4항"],["투기과열지구","관리처분계획상 분양대상자와 그 세대원은 선정일부터 5년 이내 투기과열지구에서 분양신청 불가. 상속·결혼·이혼으로 조합원 자격을 취득한 경우는 가능","제6항"]]}],"함정":"분담금 추산액이 분양공고에도 들어간다고 보기 쉽다. 분담금 추산액과 종전 자산의 가격은 개별 통지에만 있고, 공고에는 사업과 분양 조건 위주의 항목만 있다."},"30회-2차-076":{"한줄":"철도 선로 부지의 운전보안시설, 선로 위·아래를 가로지르는 보행시설, 플랫폼, 해당 사업용 급수·급탄·급유시설은 모두 건축법 적용 제외다(법 제3조제1항제2호). ㄱ~ㄹ 전부 해당한다.","근거":[{"법령":"건축법","조문":"제3조제1항제2호","원문":"① 다음 각 호의 어느 하나에 해당하는 건축물에는 이 법을 적용하지 아니한다. <개정 2016.1.19, 2019.11.26, 2023.3.21, 2023.8.8, 2024.2.6> / 2. 철도나 궤도의 선로 부지(敷地)에 있는 다음 각 목의 시설 / 가. 운전보안시설 / 나. 철도 선로의 위나 아래를 가로지르는 보행시설 / 다. 플랫폼 / 라. 해당 철도 또는 궤도사업용 급수(給水)ㆍ급탄(給炭) 및 급유(給油) 시설"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄹ(급수·급탄·급유시설)도 적용 제외다(법 제3조제1항제2호라목)."},{"번호":2,"판정":"틀림","설명":"ㄷ(선로를 가로지르는 보행시설)도 적용 제외다(법 제3조제1항제2호나목)."},{"번호":3,"판정":"틀림","설명":"ㄴ(운전보안시설)도 적용 제외다(법 제3조제1항제2호가목)."},{"번호":4,"판정":"틀림","설명":"ㄱ(플랫폼)도 적용 제외다(법 제3조제1항제2호다목)."},{"번호":5,"판정":"옳음","설명":"ㄱ~ㄹ 모두 법 제3조제1항제2호 각 목에 있다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"플랫폼은 다목이다."},{"기호":"ㄴ","판정":"옳음","설명":"운전보안시설은 가목이다."},{"기호":"ㄷ","판정":"옳음","설명":"선로의 위나 아래를 가로지르는 보행시설은 나목이다. 아래만이 아니라 위도 포함한다."},{"기호":"ㄹ","판정":"옳음","설명":"해당 철도 또는 궤도사업용 급수·급탄·급유 시설은 라목이다."}],"개념":[{"종류":"표","제목":"건축법 적용 제외·일부 규정 제외 구분(법 제3조)","머리":["구분","적용하지 않는 규정","조문"],"행":[["철도·궤도 선로 부지 시설, 지정문화유산 등, 고속도로 통행료 징수시설, 하천구역 내 수문조작실","건축법 전부","제3조제1항"],["컨테이너를 이용한 간이창고(공장 용도 대지, 이동이 쉬운 것)","건축법 전부","제3조제1항제4호"],["도시지역·지구단위계획구역 밖이면서 동·읍이 아닌 지역(섬은 인구 500명 이상 동·읍 제외)","제44조부터 제47조까지, 제51조, 제57조","제3조제2항"],["도시·군계획시설로 결정된 도로 예정지에 건축하는 건축물·공작물","제45조부터 제47조까지","제3조제3항"]]}],"함정":"선지 구성이 하나씩 빠진 조합이라 각 목을 정확히 알아야 한다. 선로 '위'를 가로지르는 보행시설도 제외 대상이고, 급수·급탄·급유시설은 해당 철도 또는 궤도사업용일 때만 제외된다."},"30회-2차-072":{"한줄":"사전결정 통지로 개발행위허가, 산지전용허가·신고와 산지일시사용허가·신고(보전산지는 도시지역만), 농지전용허가·신고 및 협의, 하천점용허가를 받은 것으로 본다(법 제10조제6항). ㄱ, ㄴ, ㄹ이 해당한다.","근거":[{"법령":"건축법","조문":"제10조제6항","원문":"⑥ 제4항에 따른 사전결정 통지를 받은 경우에는 다음 각 호의 허가를 받거나 신고 또는 협의를 한 것으로 본다. <개정 2010.5.31> / 1. 「국토의 계획 및 이용에 관한 법률」 제56조에 따른 개발행위허가 / 2. 「산지관리법」 제14조와 제15조에 따른 산지전용허가와 산지전용신고, 같은 법 제15조의2에 따른 산지일시사용허가ㆍ신고. 다만, 보전산지인 경우에는 도시지역만 해당된다. / 3. 「농지법」 제34조, 제35조 및 제43조에 따른 농지전용허가ㆍ신고 및 협의 / 4. 「하천법」 제33조에 따른 하천점용허가"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄹ(농지법상 농지전용허가)도 사전결정 통지로 받은 것으로 본다(법 제10조제6항제3호)."},{"번호":2,"판정":"옳음","설명":"ㄱ, ㄴ, ㄹ이 해당한다(법 제10조제6항제1호~제3호)."},{"번호":3,"판정":"틀림","설명":"ㄷ은 농림지역 안의 보전산지라 해당하지 않고, ㄴ도 빠졌다(법 제10조제6항제2호 단서)."},{"번호":4,"판정":"틀림","설명":"ㄱ이 빠졌고 ㄷ이 들어 있다(법 제10조제6항제1호·제2호)."},{"번호":5,"판정":"틀림","설명":"ㄷ(농림지역 안의 보전산지 전용허가)은 해당하지 않는다(법 제10조제6항제2호 단서)."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"국토계획법 제56조 개발행위허가는 제1호에 있다."},{"기호":"ㄴ","판정":"옳음","설명":"산지일시사용허가·신고는 제2호에 있고, 보전산지는 도시지역만 해당하는데 ㄴ은 도시지역 안의 보전산지다."},{"기호":"ㄷ","판정":"틀림","설명":"산지전용허가는 제2호에 있으나 보전산지는 도시지역만 해당한다. 농림지역은 도시지역이 아니다."},{"기호":"ㄹ","판정":"옳음","설명":"농지법 제34조의 농지전용허가는 제3호에 있다."}],"개념":[{"종류":"표","제목":"허가·신고 의제 비교(법 제10조제6항, 제11조제5항)","머리":["의제되는 허가·신고","사전결정 통지","건축허가"],"행":[["국토계획법상 개발행위허가","의제","의제"],["산지전용허가·신고, 산지일시사용허가·신고","의제(보전산지는 도시지역만)","의제(보전산지는 도시지역만)"],["농지법상 농지전용허가·신고 및 협의","의제","의제"],["하천법상 하천점용 등의 허가","의제","의제"],["도로법상 도로점용 허가","의제 아님","의제"],["사도법상 사도개설허가","의제 아님","의제"],["공작물 축조신고, 공사용 가설건축물 축조신고","의제 아님","의제"]]}],"함정":"ㄴ과 ㄷ은 둘 다 산지관리법상 허가인데 지역이 다르다. 보전산지는 도시지역에서만 의제되므로 농림지역 안의 보전산지 전용허가(ㄷ)는 빠진다. 사전결정에서 의제되는 것은 네 가지뿐이고 건축허가에서 의제되는 범위보다 좁다."},"30회-2차-074":{"한줄":"허가권자는 연면적 1천제곱미터 이상인 건축물로서 조례로 정하는 건축물에 대해 착공신고 시 건축공사비의 1퍼센트 범위에서 예치금을 예치하게 할 수 있다(법 제13조제2항).","근거":[{"법령":"건축법","조문":"제13조제2항","원문":"② 허가권자는 연면적이 1천제곱미터 이상인 건축물(「주택도시기금법」에 따른 주택도시보증공사가 분양보증을 한 건축물, 「건축물의 분양에 관한 법률」 제4조제1항제1호에 따른 분양보증이나 신탁계약을 체결한 건축물은 제외한다)로서 해당 지방자치단체의 조례로 정하는 건축물에 대하여는 제21조에 따른 착공신고를 하는 건축주(「한국토지주택공사법」에 따른 한국토지주택공사 또는 「지방공기업법」에 따라 건축사업을 수행하기 위하여 설립된 지방공사는 제외한다)에게 장기간 건축물의 공사현장이 방치되는 것에 대비하여 미리 미관 개선과 안전관리에 필요한 비용(대통령령으로 정하는 보증서를 포함하며, 이하 \"예치금\"이라 한다)을 건축공사비의 1퍼센트의 범위에서 예치하게 할 수 있다. <개정 2012.12.18, 2014.5.28, 2015.1.6>"},{"법령":"건축법","조문":"제13조제5항","원문":"⑤ 허가권자는 공사현장이 방치되어 도시미관을 저해하고 안전을 위해한다고 판단되면 건축허가를 받은 자에게 건축물 공사현장의 미관과 안전관리를 위한 다음 각 호의 개선을 명할 수 있다. <개정 2014.5.28, 2019.4.30, 2020.6.9> / 1. 안전울타리 설치 등 안전조치 / 2. 공사재개 또는 해체 등 정비"}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ 1천제곱미터, ㄴ 1퍼센트다(법 제13조제2항)."},{"번호":2,"판정":"틀림","설명":"ㄴ은 3퍼센트가 아니라 1퍼센트다(법 제13조제2항)."},{"번호":3,"판정":"틀림","설명":"ㄴ은 5퍼센트가 아니라 1퍼센트다(법 제13조제2항)."},{"번호":4,"판정":"틀림","설명":"ㄱ은 3천이 아니라 1천이고, ㄴ은 3퍼센트가 아니라 1퍼센트다(법 제13조제2항)."},{"번호":5,"판정":"틀림","설명":"ㄱ은 3천이 아니라 1천이고, ㄴ은 5퍼센트가 아니라 1퍼센트다(법 제13조제2항)."}],"개념":[{"종류":"표","제목":"건축 공사현장 안전관리 예치금(법 제13조)","머리":["항목","내용","항"],"행":[["대상","연면적 1천제곱미터 이상으로서 지방자치단체 조례가 정하는 건축물","제2항"],["제외","주택도시보증공사 분양보증·분양보증이나 신탁계약을 체결한 건축물, 한국토지주택공사·지방공사가 건축주인 경우","제2항"],["예치 시기","착공신고를 하는 건축주에게","제2항"],["한도","건축공사비의 1퍼센트 범위","제2항"],["반환","대통령령이 정하는 이율의 이자를 포함해 반환(보증서 예치는 제외)","제3항"],["방치 시 조치","안전울타리 설치 등 안전조치, 공사재개 또는 해체 등 정비를 명하고, 불이행하면 대집행","제5항·제6항"]]}],"함정":"숫자 선지는 1천·3천제곱미터와 1·3·5퍼센트를 섞어 놓았다. 면적은 1천제곱미터, 비율은 건축공사비의 1퍼센트 범위 하나뿐이다."},"30회-2차-075":{"한줄":"국가·지방자치단체 소유 대지의 여유공간에 구분지상권을 설정해 설치할 수 있는 시설에 문화 및 집회시설은 공연장과 전시장만 들어간다. 공연장이 해당한다(법 제29조제4항, 영 제22조제4항제3호).","근거":[{"법령":"건축법","조문":"제29조제4항","원문":"④ 국가나 지방자치단체가 소유한 대지의 지상 또는 지하 여유공간에 구분지상권을 설정하여 주민편의시설 등 대통령령으로 정하는 시설을 설치하고자 하는 경우 허가권자는 구분지상권자를 건축주로 보고 구분지상권이 설정된 부분을 제2조제1항제1호의 대지로 보아 건축허가를 할 수 있다. 이 경우 구분지상권 설정의 대상 및 범위, 기간 등은 「국유재산법」 및 「공유재산 및 물품 관리법」에 적합하여야 한다. <신설 2016.1.19>"},{"법령":"건축법 시행령","조문":"제22조제4항","원문":"④ 법 제29조제4항 전단에서 \"주민편의시설 등 대통령령으로 정하는 시설\"이란 다음 각 호의 시설을 말한다. <신설 2016.7.19> / 1. 제1종 근린생활시설 / 2. 제2종 근린생활시설(총포판매소, 장의사, 다중생활시설, 제조업소, 단란주점, 안마시술소 및 노래연습장은 제외한다) / 3. 문화 및 집회시설(공연장 및 전시장으로 한정한다) / 8. 업무시설(오피스텔은 제외한다)"}],"선지":[{"번호":1,"판정":"틀림","설명":"수련시설은 열거된 시설에 없다(영 제22조제4항)."},{"번호":2,"판정":"틀림","설명":"제2종 근린생활시설 중 다중생활시설은 제외된다(영 제22조제4항제2호)."},{"번호":3,"판정":"틀림","설명":"제2종 근린생활시설 중 노래연습장은 제외된다(영 제22조제4항제2호)."},{"번호":4,"판정":"옳음","설명":"문화 및 집회시설은 공연장 및 전시장으로 한정해 인정된다(영 제22조제4항제3호)."},{"번호":5,"판정":"틀림","설명":"업무시설 중 오피스텔은 제외된다(영 제22조제4항제8호)."}],"개념":[{"종류":"표","제목":"구분지상권 설정 대상 시설(영 제22조제4항)","머리":["호","용도","범위"],"행":[["제1호","제1종 근린생활시설","전부"],["제2호","제2종 근린생활시설","총포판매소·장의사·다중생활시설·제조업소·단란주점·안마시술소·노래연습장 제외"],["제3호","문화 및 집회시설","공연장, 전시장만"],["제4호","의료시설","전부"],["제5호","교육연구시설","전부"],["제6호","노유자시설","전부"],["제7호","운동시설","전부"],["제8호","업무시설","오피스텔 제외"]]}],"함정":"열거된 용도에도 괄호 제외가 붙는다. 제2종 근린생활시설의 다중생활시설·노래연습장, 업무시설의 오피스텔이 대표적이고, 문화 및 집회시설은 공연장과 전시장만 된다. 수련시설은 아예 열거에 없다."},"30회-2차-081":{"한줄":"물이 고이거나 상시 물을 저장하는 저수지·호수 등의 토지와 연·왕골 등이 자생하는 배수가 잘 되지 않는 토지는 유지(溜池)다(영 제58조제19호).","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제19호","원문":"유지(溜池): 물이 고이거나 상시적으로 물을 저장하고 있는 댐ㆍ저수지ㆍ소류지(沼溜地)ㆍ호수ㆍ연못 등의 토지와 연ㆍ왕골 등이 자생하는 배수가 잘 되지 아니하는 토지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제20호","원문":"양어장: 육상에 인공으로 조성된 수산생물의 번식 또는 양식을 위한 시설을 갖춘 부지와 이에 접속된 부속시설물의 부지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제18호","원문":"구거: 용수(用水) 또는 배수(排水)를 위하여 일정한 형태를 갖춘 인공적인 수로ㆍ둑 및 그 부속시설물의 부지와 자연의 유수(流水)가 있거나 있을 것으로 예상되는 소규모 수로부지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제2호","원문":"답: 물을 상시적으로 직접 이용하여 벼ㆍ연(蓮)ㆍ미나리ㆍ왕골 등의 식물을 주로 재배하는 토지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제24호","원문":"유원지: 일반 공중의 위락ㆍ휴양 등에 적합한 시설물을 종합적으로 갖춘 수영장ㆍ유선장(遊船場)ㆍ낚시터ㆍ어린이놀이터ㆍ동물원ㆍ식물원ㆍ민속촌ㆍ경마장ㆍ야영장 등의 토지와 이에 접속된 부속시설물의 부지. 다만, 이들 시설과의 거리 등으로 보아 독립적인 것으로 인정되는 숙식시설 및 유기장(遊技場)의 부지와 하천ㆍ구거 또는 유지[공유(公有)인 것으로 한정한다]로 분류되는 것은 제외한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"발문의 토지는 유지(溜池)다(영 제58조제19호)."},{"번호":2,"판정":"틀림","설명":"양어장은 육상에 인공으로 조성된 수산생물의 번식·양식 시설을 갖춘 부지다(영 제58조제20호)."},{"번호":3,"판정":"틀림","설명":"구거는 용수·배수를 위한 인공 수로·둑·부속시설물의 부지와 소규모 수로부지다(영 제58조제18호)."},{"번호":4,"판정":"틀림","설명":"답은 물을 상시적으로 직접 이용하여 벼·연·미나리·왕골 등을 주로 재배하는 토지다(영 제58조제2호)."},{"번호":5,"판정":"틀림","설명":"유원지는 수영장·유선장·낚시터·동물원 등 위락·휴양 시설을 종합적으로 갖춘 토지다(영 제58조제24호)."}],"개념":[{"종류":"표","제목":"물·시설 부지 지목 구분(영 제58조)","머리":["지목","포함","제외·주의"],"행":[["광천지","온수·약수·석유류 등이 용출되는 용출구와 그 유지에 사용되는 부지","송수관·송유관·저장시설의 부지는 제외"],["수도용지","물을 정수하여 공급하기 위한 취수·저수·도수·정수·송수 및 배수 시설의 부지와 접속 부속시설물의 부지","-"],["유지","물이 고이거나 상시 물을 저장하는 댐·저수지·소류지·호수·연못 등과 연·왕골 등이 자생하는 배수가 잘 되지 않는 토지","연·왕골 등을 상시 직접 이용하여 재배하면 답"],["답","물을 상시적으로 직접 이용하여 벼·연·미나리·왕골 등을 주로 재배하는 토지","-"],["구거","용수·배수를 위한 인공 수로·둑·부속시설물의 부지, 유수가 있거나 있을 것으로 예상되는 소규모 수로부지","-"],["하천","자연의 유수가 있거나 있을 것으로 예상되는 토지","-"],["양어장","육상에 인공으로 조성된 수산생물의 번식·양식 시설을 갖춘 부지와 접속 부속시설물의 부지","-"]]}],"함정":"연·왕골이 나오는 지목은 둘이다. 상시 직접 이용해 재배하면 답이고, 자생하는 배수 불량 토지면 유지다."},"30회-2차-091":{"한줄":"제방의 부호는 \"제\"이므로(규칙 제64조) ④가 옳다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제64조","원문":"지목을 지적도 및 임야도(이하 \"지적도면\"이라 한다)에 등록하는 때에는 다음의 부호로 표기하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"광천지의 부호는 \"광\"이다(규칙 제64조)."},{"번호":2,"판정":"틀림","설명":"공장용지의 부호는 \"장\"이다(규칙 제64조)."},{"번호":3,"판정":"틀림","설명":"유원지의 부호는 \"원\"이다(규칙 제64조)."},{"번호":4,"판정":"옳음","설명":"제방의 부호는 \"제\"다(규칙 제64조)."},{"번호":5,"판정":"틀림","설명":"도로의 부호는 \"도\"다(규칙 제64조)."}],"개념":[{"종류":"표","제목":"지목 28종과 지적도면 부호(규칙 제64조)","머리":["지목","부호","지목","부호"],"행":[["전","전","철도용지","철"],["답","답","제방","제"],["과수원","과","하천","천"],["목장용지","목","구거","구"],["임야","임","유지","유"],["광천지","광","양어장","양"],["염전","염","수도용지","수"],["대","대","공원","공"],["공장용지","장","체육용지","체"],["학교용지","학","유원지","원"],["주차장","차","종교용지","종"],["주유소용지","주","사적지","사"],["창고용지","창","묘지","묘"],["도로","도","잡종지","잡"]]}],"함정":"공장용지(장)와 유원지(원)는 이름의 두 번째 글자를, 광천지(광)와 도로(도)는 첫 글자를 쓴다. 하천은 두 번째 글자 천이지만 제방(제)·구거(구)·유지(유)는 첫 글자다."},"30회-2차-083":{"한줄":"지상경계를 새로 정한 경우 경계점 위치 설명도와 경계점표지의 종류 등을 등록하여 관리하는 장부는 지상경계점등록부다(법 제65조제2항, 규칙 제60조제2항).","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제65조제2항","원문":"지적소관청은 토지의 이동에 따라 지상경계를 새로 정한 경우에는 다음 각 호의 사항을 등록한 지상경계점등록부를 작성ㆍ관리하여야 한다. 1. 토지의 소재 2. 지번 3. 경계점 좌표(경계점좌표등록부 시행지역에 한정한다) 4. 경계점 위치 설명도 5. 그 밖에 국토교통부령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제60조제2항","원문":"법 제65조제2항제5호에서 \"그 밖에 국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 1. 공부상 지목과 실제 토지이용 지목 2. 경계점의 사진 파일 3. 경계점표지의 종류 및 경계점 위치"}],"선지":[{"번호":1,"판정":"틀림","설명":"토지이동조사부는 토지이동현황을 직권으로 조사한 때 이동현황을 적는 장부다(규칙 제59조제2항)."},{"번호":2,"판정":"틀림","설명":"부동산종합공부는 토지·건축물·토지이용·가격·권리 정보를 등록하는 공부다(법 제76조의3, 영 제62조의2)."},{"번호":3,"판정":"틀림","설명":"경계점좌표등록부는 토지의 소재, 지번, 좌표 등을 등록하는 지적공부다(법 제73조)."},{"번호":4,"판정":"옳음","설명":"경계점 위치 설명도, 경계점표지의 종류 및 경계점 위치 등은 지상경계점등록부에 등록한다(법 제65조제2항, 규칙 제60조제2항)."},{"번호":5,"판정":"틀림","설명":"토지이동정리 결의서는 지적공부를 정리할 때 토지이동 조서를 첨부하는 서식이다(규칙 제59조제4항)."}],"개념":[{"종류":"표","제목":"지상경계점등록부(법 제65조제2항, 규칙 제60조제2항)","머리":["구분","등록사항"],"행":[["토지의 소재","법 제65조제2항제1호"],["지번","법 제65조제2항제2호"],["경계점 좌표","경계점좌표등록부 시행지역에 한정(제3호)"],["경계점 위치 설명도","법 제65조제2항제4호"],["공부상 지목과 실제 토지이용 지목","규칙 제60조제2항제1호"],["경계점의 사진 파일","규칙 제60조제2항제2호"],["경계점표지의 종류 및 경계점 위치","규칙 제60조제2항제3호"]]},{"종류":"표","제목":"지적공부별 등록사항(법 제71조~제73조, 규칙 제68조·제69조·제71조)","머리":["공부","등록사항"],"행":[["토지대장·임야대장","토지의 소재, 지번, 지목, 면적, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 지적도 또는 임야도의 번호와 필지별 장번호 및 축척, 토지의 이동사유, 토지소유자가 변경된 날과 그 원인, 토지등급 또는 기준수확량등급과 설정·수정 연월일, 개별공시지가와 그 기준일"],["공유지연명부","토지의 소재, 지번, 소유권 지분, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 필지별 공유지연명부의 장번호, 토지소유자가 변경된 날과 그 원인"],["대지권등록부","토지의 소재, 지번, 대지권 비율, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 전유부분의 건물표시, 건물의 명칭, 집합건물별 대지권등록부의 장번호, 토지소유자가 변경된 날과 그 원인, 소유권 지분"],["경계점좌표등록부","토지의 소재, 지번, 좌표, 토지의 고유번호, 지적도면의 번호, 필지별 경계점좌표등록부의 장번호, 부호 및 부호도"],["지적도·임야도","토지의 소재, 지번, 지목, 경계, 지적도면의 색인도, 지적도면의 제명 및 축척, 도곽선과 그 수치, 좌표에 의하여 계산된 경계점 간의 거리(경계점좌표등록부 시행지역), 삼각점 및 지적기준점의 위치, 건축물 및 구조물 등의 위치"]]}],"함정":"경계점 위치 설명도와 경계점표지의 종류는 지상경계점등록부의 항목이다. 경계점좌표등록부에는 좌표가 들어가고, 토지이동조사부와 토지이동정리 결의서는 직권 조사·정리에 쓰는 서식이다."},"30회-2차-086":{"한줄":"정보처리시스템으로 기록·저장된 지적공부의 열람·등본 발급은 특별자치시장, 시장·군수 또는 구청장이나 읍·면·동의 장에게 신청하므로(법 제75조제1항) 시·도지사를 든 ①이 틀리다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제75조제1항","원문":"지적공부를 열람하거나 그 등본을 발급받으려는 자는 해당 지적소관청에 그 열람 또는 발급을 신청하여야 한다. 다만, 정보처리시스템을 통하여 기록ㆍ저장된 지적공부(지적도 및 임야도는 제외한다)를 열람하거나 그 등본을 발급받으려는 경우에는 특별자치시장, 시장ㆍ군수 또는 구청장이나 읍ㆍ면ㆍ동의 장에게 신청할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제76조의3","원문":"지적소관청은 부동산종합공부에 다음 각 호의 사항을 등록하여야 한다. 1. 토지의 표시와 소유자에 관한 사항: 이 법에 따른 지적공부의 내용 2. 건축물의 표시와 소유자에 관한 사항(토지에 건축물이 있는 경우만 해당한다): 「건축법」 제38조에 따른 건축물대장의 내용 3. 토지의 이용 및 규제에 관한 사항: 「토지이용규제 기본법」 제10조에 따른 토지이용계획확인서의 내용 4. 부동산의 가격에 관한 사항: 「부동산 가격공시에 관한 법률」 제10조에 따른 개별공시지가, 같은 법 제16조, 제17조 및 제18조에 따른 개별주택가격 및 공동주택가격 공시내용 5. 그 밖에 부동산의 효율적 이용과 부동산과 관련된 정보의 종합적 관리ㆍ운영을 위하여 필요한 사항으로서 대통령령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제74조제2항","원문":"법 제76조의4에 따라 부동산종합공부를 열람하거나 부동산종합공부 기록사항의 전부 또는 일부에 관한 증명서(이하 \"부동산종합증명서\"라 한다)를 발급받으려는 자는 별지 제71호서식의 지적공부ㆍ부동산종합공부 열람ㆍ발급 신청서(전자문서로 된 신청서를 포함한다)를 지적소관청 또는 읍ㆍ면ㆍ동장에게 제출하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"신청 상대는 특별자치시장, 시장·군수 또는 구청장이나 읍·면·동의 장이다. 시·도지사는 포함되지 않는다(법 제75조제1항 단서)."},{"번호":2,"판정":"옳음","설명":"부동산종합공부에는 지적공부의 내용 중 토지의 표시와 소유자에 관한 사항을 등록한다(법 제76조의3제1호)."},{"번호":3,"판정":"옳음","설명":"부동산종합공부의 열람과 증명서 발급은 열람·발급 신청서(전자문서 포함)를 지적소관청 또는 읍·면·동장에게 제출한다(규칙 제74조제2항)."},{"번호":4,"판정":"옳음","설명":"토지이용계획확인서의 내용 중 토지의 이용 및 규제에 관한 사항을 등록한다(법 제76조의3제3호)."},{"번호":5,"판정":"옳음","설명":"건축물대장의 내용 중 건축물의 표시와 소유자에 관한 사항을 등록한다. 토지에 건축물이 있는 경우만 해당한다(법 제76조의3제2호)."}],"개념":[{"종류":"표","제목":"부동산종합공부의 등록사항(법 제76조의3, 영 제62조의2)","머리":["호","등록사항","내용 출처"],"행":[["1","토지의 표시와 소유자에 관한 사항","공간정보법에 따른 지적공부의 내용"],["2","건축물의 표시와 소유자에 관한 사항(토지에 건축물이 있는 경우만)","건축법 제38조에 따른 건축물대장의 내용"],["3","토지의 이용 및 규제에 관한 사항","토지이용규제 기본법 제10조에 따른 토지이용계획확인서의 내용"],["4","부동산의 가격에 관한 사항","부동산 가격공시에 관한 법률 제10조에 따른 개별공시지가, 같은 법 제16조·제17조·제18조에 따른 개별주택가격 및 공동주택가격 공시내용"],["5","부동산의 효율적 이용과 정보의 종합적 관리·운영을 위하여 필요한 사항","부동산등기법 제48조에 따른 부동산의 권리에 관한 사항(영 제62조의2)"]]},{"종류":"표","제목":"지적공부 열람·등본 발급 신청(법 제75조제1항, 규칙 제74조)","머리":["구분","신청 상대"],"행":[["원칙","해당 지적소관청"],["정보처리시스템으로 기록·저장된 지적공부(지적도·임야도 제외)","특별자치시장, 시장·군수 또는 구청장이나 읍·면·동의 장"],["지적도·임야도","해당 지적소관청"],["신청서","지적공부·부동산종합공부 열람·발급 신청서(전자문서 포함)"]]}],"함정":"정보처리시스템 기록분은 지적소관청 외에 읍·면·동의 장에게도 신청할 수 있지만 지적도·임야도는 제외되고, 시·도지사는 신청 상대가 아니다."},"30회-2차-084":{"한줄":"바다로 된 토지의 등록말소 신청 통지를 받은 토지소유자가 통지를 받은 날부터 90일 이내에 신청하지 않으면 지적소관청이 등록을 말소하므로(법 제82조제2항) 60일이라고 한 ④가 틀리다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제82조제1항","원문":"지적소관청은 지적공부에 등록된 토지가 지형의 변화 등으로 바다로 된 경우로서 원상(原狀)으로 회복될 수 없거나 다른 지목의 토지로 될 가능성이 없는 경우에는 지적공부에 등록된 토지소유자에게 지적공부의 등록말소 신청을 하도록 통지하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제82조제2항","원문":"지적소관청은 제1항에 따른 토지소유자가 통지를 받은 날부터 90일 이내에 등록말소 신청을 하지 아니하면 대통령령으로 정하는 바에 따라 등록을 말소한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제82조제3항","원문":"지적소관청은 제2항에 따라 말소한 토지가 지형의 변화 등으로 다시 토지가 된 경우에는 대통령령으로 정하는 바에 따라 토지로 회복등록을 할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제68조","원문":"법 제82조제2항에 따라 토지소유자가 등록말소 신청을 하지 아니하면 지적소관청이 직권으로 그 지적공부의 등록사항을 말소하여야 한다. ② 지적소관청은 법 제82조제3항에 따라 회복등록을 하려면 그 지적측량성과 및 등록말소 당시의 지적공부 등 관계 자료에 따라야 한다. ③ 제1항 및 제2항에 따라 지적공부의 등록사항을 말소하거나 회복등록하였을 때에는 그 정리 결과를 토지소유자 및 해당 공유수면의 관리청에 통지하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제89조제1항","원문":"지적소관청은 제64조제2항(신규등록은 제외한다), 제66조제2항, 제82조, 제83조제2항, 제84조제2항 또는 제85조제2항에 따른 사유로 토지의 표시 변경에 관한 등기를 할 필요가 있는 경우에는 지체 없이 관할 등기관서에 그 등기를 촉탁하여야 한다. 이 경우 등기촉탁은 국가가 국가를 위하여 하는 등기로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"원상 회복될 수 없는 경우 지적소관청은 토지소유자에게 등록말소 신청을 하도록 통지한다(법 제82조제1항)."},{"번호":2,"판정":"옳음","설명":"등록말소로 토지의 표시 변경에 관한 등기가 필요하면 지체 없이 관할 등기관서에 촉탁한다(법 제89조제1항)."},{"번호":3,"판정":"옳음","설명":"회복등록은 지적측량성과 및 등록말소 당시의 지적공부 등 관계 자료에 따른다(영 제68조제2항)."},{"번호":4,"판정":"틀림","설명":"신청 기한은 통지를 받은 날부터 90일 이내다. 60일이 아니다. 신청이 없으면 지적소관청이 직권으로 말소한다(법 제82조제2항, 영 제68조제1항)."},{"번호":5,"판정":"옳음","설명":"말소하거나 회복등록하였을 때에는 정리 결과를 토지소유자 및 해당 공유수면의 관리청에 통지한다(영 제68조제3항)."}],"개념":[{"종류":"흐름","제목":"바다로 된 토지의 등록말소와 회복(법 제82조, 영 제68조)","단계":[{"이름":"통지","설명":"지형의 변화 등으로 바다로 된 토지가 원상으로 회복될 수 없거나 다른 지목의 토지로 될 가능성이 없으면 소유자에게 등록말소 신청을 하도록 통지(법 제82조제1항)"},{"이름":"신청","설명":"통지를 받은 날부터 90일 이내에 등록말소 신청(법 제82조제2항)"},{"이름":"직권 말소","설명":"신청이 없으면 지적소관청이 직권으로 등록사항을 말소(영 제68조제1항)"},{"이름":"등기촉탁","설명":"토지의 표시 변경에 관한 등기가 필요하면 지체 없이 관할 등기관서에 촉탁(법 제89조제1항)"},{"이름":"정리 결과 통지","설명":"토지소유자 및 해당 공유수면의 관리청에 통지(영 제68조제3항)"},{"이름":"회복등록","설명":"말소한 토지가 다시 토지가 된 경우 지적측량성과 및 등록말소 당시의 지적공부 등 관계 자료에 따라 회복등록(법 제82조제3항, 영 제68조제2항)"}]}],"함정":"④는 직권 말소라는 후단은 맞고 전단의 기한만 60일로 바꿨다. 신청 기한은 통지를 받은 날부터 90일이다."},"30회-2차-085":{"한줄":"축척변경위원회의 회의는 재적위원 과반수의 출석과 출석위원 과반수의 찬성으로 열고 의결하며(ㄱ), 위원은 토지소유자 중 지역 사정에 정통한 사람과 지적 전문가 중에서 지적소관청이 위촉한다(ㄷ).","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제81조제2항","원문":"축척변경위원회의 회의는 위원장을 포함한 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제79조제1항","원문":"축척변경위원회는 5명 이상 10명 이하의 위원으로 구성하되, 위원의 2분의 1 이상을 토지소유자로 하여야 한다. 이 경우 그 축척변경 시행지역의 토지소유자가 5명 이하일 때에는 토지소유자 전원을 위원으로 위촉하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제79조제3항","원문":"위원은 다음 각 호의 사람 중에서 지적소관청이 위촉한다. 1. 해당 축척변경 시행지역의 토지소유자로서 지역 사정에 정통한 사람 2. 지적에 관하여 전문지식을 가진 사람"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ은 옳은 보기이나 옳은 ㄷ이 빠졌다."},{"번호":2,"판정":"틀림","설명":"ㄴ은 틀린 보기이고 옳은 ㄱ, ㄷ이 빠졌다. 위원 수와 토지소유자 비율이 영 제79조제1항과 다르다."},{"번호":3,"판정":"옳음","설명":"회의 정족수(ㄱ)와 위원의 위촉(ㄷ)이 영 제81조제2항과 제79조제3항에 맞아 이 조합이 맞다."},{"번호":4,"판정":"틀림","설명":"ㄴ은 틀린 보기다. 5명 이상 15명 이하, 3분의 2 이상이 아니라 5명 이상 10명 이하, 2분의 1 이상이다."},{"번호":5,"판정":"틀림","설명":"ㄴ은 틀린 보기이므로 세 보기를 모두 고르면 맞지 않다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"회의는 위원장을 포함한 재적위원 과반수의 출석으로 개의하고 출석위원 과반수의 찬성으로 의결한다(영 제81조제2항)."},{"기호":"ㄴ","판정":"틀림","설명":"축척변경위원회는 5명 이상 10명 이하의 위원으로 구성하고 위원의 2분의 1 이상을 토지소유자로 한다. 토지소유자가 5명 이하이면 전원을 위촉한다(영 제79조제1항)."},{"기호":"ㄷ","판정":"옳음","설명":"위원은 해당 축척변경 시행지역의 토지소유자로서 지역 사정에 정통한 사람과 지적에 관하여 전문지식을 가진 사람 중에서 지적소관청이 위촉한다(영 제79조제3항)."}],"개념":[{"종류":"표","제목":"축척변경위원회(영 제79조~제81조)","머리":["구분","내용"],"행":[["구성","5명 이상 10명 이하의 위원. 위원의 2분의 1 이상은 토지소유자(제79조제1항)"],["토지소유자가 5명 이하","토지소유자 전원을 위원으로 위촉(제79조제1항)"],["위원장","위원 중에서 지적소관청이 지명(제79조제2항)"],["위원","해당 지역 토지소유자로서 지역 사정에 정통한 사람, 지적에 관하여 전문지식을 가진 사람 중에서 지적소관청이 위촉(제79조제3항)"],["기능","축척변경 시행계획, 지번별 제곱미터당 금액과 청산금 산정, 청산금 이의신청 등을 심의·의결(제80조)"],["회의","재적위원 과반수 출석으로 개의, 출석위원 과반수 찬성으로 의결. 소집 통지는 회의 5일 전까지 서면(제81조)"]]},{"종류":"흐름","제목":"축척변경의 절차","단계":[{"이름":"신청 또는 직권","설명":"지적도가 일정한 사유에 해당하면 토지소유자의 신청 또는 지적소관청의 직권으로 일정 지역의 축척을 변경한다(법 제83조제2항)."},{"이름":"동의·의결·승인","설명":"축척변경 시행지역 토지소유자 3분의 2 이상의 동의, 축척변경위원회의 의결, 시·도지사 또는 대도시 시장의 승인(법 제83조제3항)."},{"이름":"시행공고","설명":"승인을 받으면 지체 없이 20일 이상 공고(영 제71조제1항). 토지소유자·점유자는 공고일부터 30일 이내에 경계점표지를 설치(영 제71조제3항)."},{"이름":"측량과 조서","설명":"새 축척으로 측량하고 시행공고일 현재의 면적과 측량 후 면적을 비교한 축척변경 지번별 조서를 작성(영 제72조, 제73조)."},{"이름":"청산금 산정·공고","설명":"지번별 제곱미터당 금액은 위원회 의결로 정하고, 청산금 결정을 15일 이상 공고(영 제75조)."},{"이름":"납부고지·이의신청","설명":"공고일부터 20일 이내에 납부고지·수령통지(영 제76조제1항). 이의신청은 통지를 받은 날부터 1개월 이내, 지적소관청은 1개월 이내에 위원회 의결을 거쳐 결정(영 제77조)."},{"이름":"확정공고","설명":"청산금의 납부 및 지급이 완료되면 지체 없이 확정공고하고 확정된 사항을 지적공부에 등록한다. 확정공고일에 토지의 이동이 있는 것으로 본다(영 제78조)."}]}],"함정":"ㄴ은 위원 수 상한(10명), 토지소유자 비율(2분의 1 이상), 전원 위촉 기준(5명 이하)을 하나씩 바꿔 놓은 보기다. 숫자 세 개를 정확히 외워 둔다."},"30회-2차-087":{"한줄":"지적공부의 작성 또는 재작성 당시 잘못 정리된 경우(ㄱ)와 등록사항이 잘못 입력된 경우(ㄹ)가 영 제82조제1항이 정한 직권정정 사유다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제84조제2항","원문":"지적소관청은 지적공부의 등록사항에 잘못이 있음을 발견하면 대통령령으로 정하는 바에 따라 직권으로 조사ㆍ측량하여 정정할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제82조제1항제2호","원문":"지적소관청이 법 제84조제2항에 따라 지적공부의 등록사항에 잘못이 있는지를 직권으로 조사ㆍ측량하여 정정할 수 있는 경우는 다음 각 호와 같다. 2. 지적도 및 임야도에 등록된 필지가 면적의 증감 없이 경계의 위치만 잘못된 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제82조제1항제4호","원문":"지적소관청이 법 제84조제2항에 따라 지적공부의 등록사항에 잘못이 있는지를 직권으로 조사ㆍ측량하여 정정할 수 있는 경우는 다음 각 호와 같다. 4. 지적공부의 작성 또는 재작성 당시 잘못 정리된 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제82조제1항제5호","원문":"지적소관청이 법 제84조제2항에 따라 지적공부의 등록사항에 잘못이 있는지를 직권으로 조사ㆍ측량하여 정정할 수 있는 경우는 다음 각 호와 같다. 5. 지적측량성과와 다르게 정리된 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제82조제1항제7호","원문":"지적소관청이 법 제84조제2항에 따라 지적공부의 등록사항에 잘못이 있는지를 직권으로 조사ㆍ측량하여 정정할 수 있는 경우는 다음 각 호와 같다. 7. 지적공부의 등록사항이 잘못 입력된 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ은 직권정정 사유가 아니다. 영 제82조제1항제5호는 측량 준비 파일이 아니라 지적측량성과와 다르게 정리된 경우다."},{"번호":2,"판정":"틀림","설명":"ㄹ은 직권정정 사유이나 옳은 ㄱ이 빠졌다."},{"번호":3,"판정":"옳음","설명":"ㄱ(제4호)과 ㄹ(제7호)이 직권정정 사유이므로 이 조합이 맞다."},{"번호":4,"판정":"틀림","설명":"ㄴ은 경계가 지상 경계와 맞지 않아 면적이 증감하는 경우라 직권정정 사유가 아니다(제2호는 면적 증감 없이 경계 위치만 잘못된 경우). ㄷ도 사유가 아니다."},{"번호":5,"판정":"틀림","설명":"ㄷ은 사유가 아니라서 ㄱ, ㄷ, ㄹ 조합은 맞지 않다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"지적공부의 작성 또는 재작성 당시 잘못 정리된 경우다(영 제82조제1항제4호)."},{"기호":"ㄴ","판정":"틀림","설명":"직권정정 사유는 면적의 증감 없이 경계의 위치만 잘못된 경우다(영 제82조제1항제2호). 면적이 증감하는 경우는 해당하지 않는다."},{"기호":"ㄷ","판정":"틀림","설명":"지적측량성과와 다르게 정리된 경우가 사유다(영 제82조제1항제5호). 측량 준비 파일과의 불일치는 사유가 아니다."},{"기호":"ㄹ","판정":"옳음","설명":"지적공부의 등록사항이 잘못 입력된 경우다(영 제82조제1항제7호)."}],"개념":[{"종류":"표","제목":"직권으로 조사·측량하여 정정할 수 있는 경우(영 제82조제1항)","머리":["호","사유"],"행":[["1","토지이동정리 결의서의 내용과 다르게 정리된 경우"],["2","지적도·임야도에 등록된 필지가 면적의 증감 없이 경계의 위치만 잘못된 경우"],["3","1필지가 각각 다른 지적도·임야도에 등록된 경우로서 면적은 일치하지만 경계가 접합되지 않아 지상 경계에 맞추어 정정해야 하는 토지가 발견된 경우"],["4","지적공부의 작성 또는 재작성 당시 잘못 정리된 경우"],["5","지적측량성과와 다르게 정리된 경우"],["6","법 제29조제10항에 따라 지적공부의 등록사항을 정정해야 하는 경우"],["7","지적공부의 등록사항이 잘못 입력된 경우"],["8","「부동산등기법」 제37조제2항에 따른 통지가 있는 경우(지적소관청의 착오로 잘못 합병한 경우만 해당)"],["9","법률 제2801호 지적법개정법률 부칙 제3조에 따른 면적 환산이 잘못된 경우"]]},{"종류":"비교","제목":"등록사항 정정의 두 경로(법 제84조)","왼쪽":{"이름":"토지소유자의 신청(제1항)","항목":["지적공부의 등록사항에 잘못이 있음을 발견한 토지소유자가 신청","정정으로 인접 토지의 경계가 변경되면 인접 토지소유자의 승낙서 또는 이에 대항할 수 있는 확정판결서 정본 제출(제3항)"]},"오른쪽":{"이름":"지적소관청의 직권(제2항)","항목":["잘못을 발견하면 대통령령이 정하는 바에 따라 직권으로 조사·측량하여 정정","대통령령이 정하는 경우는 영 제82조제1항의 9가지","정정 사유에 해당하는 토지가 있으면 지체 없이 정정(영 제82조제2항)"]}}],"함정":"ㄴ은 경계가 지상과 달라 면적이 변하는 경우다. 직권정정은 면적의 증감 없이 경계의 위치만 잘못된 경우에 한한다. ㄷ은 '지적측량성과'를 '측량 준비 파일'로 바꿔 놓은 보기다."},"30회-2차-089":{"한줄":"도시개발사업 등의 시행으로 인한 토지의 이동은 토지의 형질변경 등의 공사가 준공된 때 이루어진 것으로 보므로(법 제86조제3항) 공사 착수 때라는 ②가 틀린 설명이다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제86조제3항","원문":"제2항에 따른 토지의 이동은 토지의 형질변경 등의 공사가 준공된 때에 이루어진 것으로 본다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제95조제1항","원문":"법 제86조제1항 및 영 제83조제2항에 따른 도시개발사업 등의 착수 또는 변경의 신고를 하려는 자는 별지 제81호서식의 도시개발사업 등의 착수(시행)ㆍ변경ㆍ완료 신고서에 다음 각 호의 서류를 첨부하여야 한다. 다만, 변경신고의 경우에는 변경된 부분으로 한정한다. 1. 사업인가서 2. 지번별 조서 3. 사업계획도"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제83조제2항","원문":"법 제86조제1항에 따른 도시개발사업 등의 착수ㆍ변경 또는 완료 사실의 신고는 그 사유가 발생한 날부터 15일 이내에 하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제83조제3항","원문":"법 제86조제2항에 따른 토지의 이동 신청은 그 신청대상지역이 환지(換地)를 수반하는 경우에는 법 제86조제1항에 따른 사업완료 신고로써 이를 갈음할 수 있다. 이 경우 사업완료 신고서에 법 제86조제2항에 따른 토지의 이동 신청을 갈음한다는 뜻을 적어야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제83조제4항","원문":"「주택법」에 따른 주택건설사업의 시행자가 파산 등의 이유로 토지의 이동 신청을 할 수 없을 때에는 그 주택의 시공을 보증한 자 또는 입주예정자 등이 신청할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"착수 신고서에는 사업인가서, 지번별 조서, 사업계획도를 첨부한다(규칙 제95조제1항)."},{"번호":2,"판정":"틀림","설명":"토지의 이동은 토지의 형질변경 등의 공사가 준공된 때 이루어진 것으로 본다(법 제86조제3항). 착수된 때가 아니다."},{"번호":3,"판정":"옳음","설명":"착수·변경·완료 신고는 그 사유가 발생한 날부터 15일 이내에 한다(영 제83조제2항)."},{"번호":4,"판정":"옳음","설명":"주택건설사업의 시행자가 파산 등으로 신청할 수 없으면 주택의 시공을 보증한 자 또는 입주예정자 등이 신청할 수 있다(영 제83조제4항)."},{"번호":5,"판정":"옳음","설명":"환지를 수반하는 경우 사업완료 신고로 토지의 이동 신청을 갈음할 수 있고, 신고서에 그 뜻을 적어야 한다(영 제83조제3항)."}],"개념":[{"종류":"표","제목":"도시개발사업 등 시행지역의 토지이동 특례(법 제86조)","머리":["구분","내용","근거"],"행":[["신고 대상","도시개발사업, 농어촌정비사업, 그 밖에 대통령령이 정하는 토지개발사업의 착수·변경·완료","법 제86조제1항"],["신고 상대방·기한","지적소관청에, 사유가 발생한 날부터 15일 이내","법 제86조제1항, 영 제83조제2항"],["토지이동 신청","해당 사업의 시행자가 지적소관청에 신청","법 제86조제2항"],["토지이동 시기","공사가 준공된 때 이루어진 것으로 봄","법 제86조제3항"],["토지소유자의 요청","착수·변경 신고가 된 토지의 소유자가 이동을 원하면 시행자에게 신청하도록 요청","법 제86조제4항"],["신고서 첨부서류(착수·변경)","사업인가서, 지번별 조서, 사업계획도","규칙 제95조제1항"],["신고서 첨부서류(완료)","확정될 토지·종전 토지의 지번별 조서, 환지계획서(환지를 수반하지 않으면 사업 완료 증명 서류)","규칙 제95조제2항"]]},{"종류":"표","제목":"대통령령이 정하는 토지개발사업의 범위(영 제83조제1항)","머리":["호","사업"],"행":[["1","「주택법」에 따른 주택건설사업"],["2","「택지개발촉진법」에 따른 택지개발사업"],["3","「산업입지 및 개발에 관한 법률」에 따른 산업단지개발사업"],["4","「도시 및 주거환경정비법」에 따른 정비사업"],["5","「지역 개발 및 지원에 관한 법률」에 따른 지역개발사업"],["10","「공공주택 특별법」에 따른 공공주택지구조성사업"]]}],"함정":"②는 착수 시기와 준공 시기를 바꿔 놓았다. 토지이동은 준공 때 이뤄진 것으로 본다. ⑤는 환지를 수반하는 경우 완료 신고로 이동 신청을 갈음한다는 점을 알아야 옳은 선지로 읽힌다."},"30회-2차-092":{"한줄":"공동주택 부지, 도로, 제방, 하천, 구거, 유지 등으로서 합병해야 할 토지가 있으면 그 사유가 발생한 날부터 60일 이내에 합병을 신청해야 하므로(법 제80조제2항) 90일이라는 ⑤가 틀린 설명이다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제26조제1항","원문":"합병에 따른 경계ㆍ좌표 또는 면적은 따로 지적측량을 하지 아니하고 다음 각 호의 구분에 따라 결정한다. 1. 합병 후 필지의 경계 또는 좌표: 합병 전 각 필지의 경계 또는 좌표 중 합병으로 필요 없게 된 부분을 말소하여 결정 2. 합병 후 필지의 면적: 합병 전 각 필지의 면적을 합산하여 결정"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제56조제3항제4호","원문":"4. 합병의 경우에는 합병 대상 지번 중 선순위의 지번을 그 지번으로 하되, 본번으로 된 지번이 있을 때에는 본번 중 선순위의 지번을 합병 후의 지번으로 할 것. 이 경우 토지소유자가 합병 전의 필지에 주거ㆍ사무실 등의 건축물이 있어서 그 건축물이 위치한 지번을 합병 후의 지번으로 신청할 때에는 그 지번을 합병 후의 지번으로 부여하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제84조제2항","원문":"지적소관청은 제1항에 따른 토지의 이동이 있는 경우에는 토지이동정리 결의서를 작성하여야 하고, 토지소유자의 변동 등에 따라 지적공부를 정리하려는 경우에는 소유자정리 결의서를 작성하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제80조제2항","원문":"토지소유자는 「주택법」에 따른 공동주택의 부지, 도로, 제방, 하천, 구거, 유지, 그 밖에 대통령령으로 정하는 토지로서 합병하여야 할 토지가 있으면 그 사유가 발생한 날부터 60일 이내에 지적소관청에 합병을 신청하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"합병 후 필지의 면적은 합병 전 각 필지의 면적을 합산하여 결정한다(법 제26조제1항제2호)."},{"번호":2,"판정":"옳음","설명":"토지소유자가 합병 전 필지의 건축물이 위치한 지번을 합병 후의 지번으로 신청하면 그 지번을 부여한다(영 제56조제3항제4호)."},{"번호":3,"판정":"옳음","설명":"합병에 따른 경계는 합병 전 각 필지의 경계 중 합병으로 필요 없게 된 부분을 말소하여 결정한다(법 제26조제1항제1호)."},{"번호":4,"판정":"옳음","설명":"토지의 이동이 있으면 지적공부를 정리하고 토지이동정리 결의서를 작성한다(영 제84조제1항·제2항)."},{"번호":5,"판정":"틀림","설명":"합병 의무 신청 기한은 사유가 발생한 날부터 60일 이내다(법 제80조제2항). 90일이 아니다."}],"개념":[{"종류":"표","제목":"토지이동 신청 기한","머리":["신청","기한","근거"],"행":[["신규등록","사유가 발생한 날부터 60일 이내","법 제77조"],["등록전환","사유가 발생한 날부터 60일 이내","법 제78조"],["분할(1필지 일부의 용도 변경)","용도가 변경된 날부터 60일 이내","법 제79조제2항"],["합병(공동주택 부지·도로·제방·하천·구거·유지 등)","사유가 발생한 날부터 60일 이내","법 제80조제2항"],["지목변경","사유가 발생한 날부터 60일 이내","법 제81조"],["바다로 된 토지의 등록말소","통지를 받은 날부터 90일 이내","법 제82조제2항"]]},{"종류":"표","제목":"합병의 제한과 결정 방법","머리":["구분","내용","근거"],"행":[["합병 불가","지번부여지역·지목·소유자가 서로 다른 경우, 소유권·지상권·전세권·임차권 등 외의 등기가 있는 경우 등","법 제80조제3항"],["합병 후 경계·좌표","합병 전 경계·좌표 중 필요 없게 된 부분을 말소하여 결정","법 제26조제1항제1호"],["합병 후 면적","합병 전 각 필지의 면적을 합산하여 결정","법 제26조제1항제2호"],["합병 후 지번","합병 대상 지번 중 선순위 지번, 본번이 있으면 본번 중 선순위. 건축물 소재 지번을 신청하면 그 지번","영 제56조제3항제4호"]]}],"함정":"합병 신청 기한과 바다로 된 토지의 등록말소 신청 기한(90일)을 섞으면 ⑤가 옳아 보인다. 합병은 60일이다. 나머지 선지는 합병 시 면적·경계·지번 결정 방법을 그대로 서술한 옳은 문장이다."},"30회-2차-082":{"한줄":"지적측량 적부심사에 대한 재심사와 지적분야 측량기술자의 양성에 관한 사항은 법 제28조제1항제3호·제4호에 따라 중앙지적위원회가 심의·의결한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제28조제1항제3호","원문":"제29조제6항에 따른 지적측량 적부심사(適否審査)에 대한 재심사(再審査)"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제28조제1항제4호","원문":"제39조에 따른 측량기술자 중 지적분야 측량기술자(이하 \"지적기술자\"라 한다)의 양성에 관한 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제28조제2항","원문":"제29조에 따른 지적측량에 대한 적부심사 청구사항을 심의ㆍ의결하기 위하여 특별시ㆍ통합특별시ㆍ광역시ㆍ특별자치시ㆍ도 또는 특별자치도(이하 \"시ㆍ도\"라 한다)에 지방지적위원회를 둔다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제83조제1항","원문":"축척변경에 관한 사항을 심의ㆍ의결하기 위하여 지적소관청에 축척변경위원회를 둔다."}],"선지":[{"번호":1,"판정":"틀림","설명":"축척변경위원회는 축척변경에 관한 사항을 심의·의결한다(법 제83조제1항)."},{"번호":2,"판정":"옳음","설명":"재심사와 지적기술자의 양성은 중앙지적위원회의 심의·의결사항이다(법 제28조제1항제3호·제4호)."},{"번호":3,"판정":"틀림","설명":"토지수용위원회는 토지 수용 재결을 하는 기관이다. 지적측량 재심사와 기술자 양성은 심의하지 않는다."},{"번호":4,"판정":"틀림","설명":"경계결정위원회는 지적재조사에서 경계설정에 관한 결정을 의결한다(지적재조사에 관한 특별법 제31조)."},{"번호":5,"판정":"틀림","설명":"지방지적위원회는 적부심사 청구사항을 심의·의결한다(법 제28조제2항). 재심사는 하지 않는다."}],"개념":[{"종류":"표","제목":"지적 관련 위원회","머리":["위원회","소속","심의·의결 사항"],"행":[["중앙지적위원회","국토교통부","지적 관련 정책 개발 및 업무 개선, 지적측량기술의 연구·개발 및 보급, 적부심사 재심사, 지적기술자 양성, 지적기술자의 업무정지 처분 및 징계요구"],["지방지적위원회","시·도","지적측량 적부심사 청구사항"],["축척변경위원회","지적소관청","축척변경에 관한 사항"],["경계결정위원회","지적소관청","경계설정에 관한 결정, 경계설정에 따른 이의신청에 관한 결정(지적재조사에 관한 특별법 제31조)"],["중앙지적재조사위원회","국토교통부장관 소속","지적재조사 기본계획의 수립 및 변경 등"]]}],"함정":"이름이 비슷한 위원회가 많다. 적부심사는 지방, 그에 대한 재심사와 기술자 양성·징계는 중앙이다. 축척변경위원회와 경계결정위원회는 각각 축척변경과 지적재조사 경계결정을 맡는다."},"30회-2차-090":{"한줄":"신규등록, 지적공부 복구, 지적재조사사업에 따른 토지의 이동, 바다가 된 토지의 등록말소는 모두 법 제23조제1항제3호에 열거돼 측량을 할 필요가 있으면 지적측량을 해야 하므로 ㄱ~ㄹ 모두 해당한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제23조제1항제3호","원문":"다음 각 목의 어느 하나에 해당하는 경우로서 측량을 할 필요가 있는 경우 가. 제74조에 따라 지적공부를 복구하는 경우 나. 제77조에 따라 토지를 신규등록하는 경우 다. 제78조에 따라 토지를 등록전환하는 경우 라. 제79조에 따라 토지를 분할하는 경우 마. 제82조에 따라 바다가 된 토지의 등록을 말소하는 경우 바. 제83조에 따라 축척을 변경하는 경우 사. 제84조에 따라 지적공부의 등록사항을 정정하는 경우 아. 제86조에 따른 도시개발사업 등의 시행지역에서 토지의 이동이 있는 경우 자. 「지적재조사에 관한 특별법」에 따른 지적재조사사업에 따라 토지의 이동이 있는 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄹ(바다가 된 토지의 등록말소)도 지적측량 사유라 ㄱ, ㄴ, ㄷ만으로는 부족하다."},{"번호":2,"판정":"틀림","설명":"ㄷ(지적재조사사업)이 빠졌다."},{"번호":3,"판정":"틀림","설명":"ㄴ(지적공부 복구)이 빠졌다."},{"번호":4,"판정":"틀림","설명":"ㄱ(신규등록)이 빠졌다."},{"번호":5,"판정":"옳음","설명":"ㄱ(나목), ㄴ(가목), ㄷ(자목), ㄹ(마목) 모두 해당한다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"신규등록(법 제77조)은 제23조제1항제3호나목이다."},{"기호":"ㄴ","판정":"옳음","설명":"지적공부의 복구(법 제74조)는 제23조제1항제3호가목이다."},{"기호":"ㄷ","판정":"옳음","설명":"지적재조사사업에 따라 토지의 이동이 있는 경우는 제23조제1항제3호자목이다."},{"기호":"ㄹ","판정":"옳음","설명":"바다가 된 토지의 등록말소(법 제82조)는 제23조제1항제3호마목이다."}],"개념":[{"종류":"표","제목":"지적측량을 하여야 하는 경우와 의뢰(법 제23조제1항, 제24조제1항)","머리":["사유","지적측량 실시","토지소유자 등의 의뢰"],"행":[["지적기준점을 정하는 경우(제1호)","해야 함","의뢰함"],["지적측량성과를 검사하는 경우(제2호)","해야 함","의뢰하지 않음(시·도지사, 대도시 시장 또는 지적소관청이 검사)"],["지적공부 복구, 신규등록, 등록전환, 분할, 바다가 된 토지의 등록말소, 축척변경, 등록사항정정(제3호 가목~사목)","측량이 필요한 경우 해야 함","의뢰함"],["도시개발사업 등의 시행지역에서 토지의 이동이 있는 경우(제3호 아목)","측량이 필요한 경우 해야 함","의뢰함"],["지적재조사사업에 따라 토지의 이동이 있는 경우(제3호 자목)","측량이 필요한 경우 해야 함","의뢰하지 않음"],["경계점을 지상에 복원하는 경우(제4호)","해야 함","의뢰함"],["그 밖에 대통령령으로 정하는 경우(제5호)","해야 함","의뢰함"]]}],"함정":"「측량을 하여야 하는 경우」는 의뢰 대상과 달리 지적재조사사업(자목)도 포함한다. 같은 보기를 의뢰 문제(28회 등)로 물으면 ㄷ의 결론이 달라진다."},"30회-2차-093":{"한줄":"丙이 乙을 대위하여 등기를 신청해도 절차법상 등기권리자는 乙이고 丙은 대위신청인일 뿐이므로 ⑤가 틀리다.","근거":[{"법령":"부동산등기법","조문":"법 제23조제1항","원문":"등기는 법률에 다른 규정이 없는 경우에는 등기권리자(登記權利者)와 등기의무자(登記義務者)가 공동으로 신청한다."},{"법령":"부동산등기법","조문":"법 제28조제1항","원문":"채권자는 「민법」 제404조에 따라 채무자를 대위(代位)하여 등기를 신청할 수 있다."},{"법령":"부동산등기법","조문":"법 제28조제2항","원문":"등기관이 제1항 또는 다른 법령에 따른 대위신청에 의하여 등기를 할 때에는 대위자의 성명 또는 명칭, 주소 또는 사무소 소재지 및 대위원인을 기록하여야 한다."},{"이론":"실체법상·절차법상 등기권리자·등기의무자","내용":"실체법상 등기권리자는 등기의 실체적 권리를 취득하거나 등기청구권을 가진 자이고, 절차법상 등기권리자는 등기기록의 형식상 권리를 얻거나 이익을 받는 자다. 말소등기에서는 말소로 이익을 받는 자가 절차법상 등기권리자다. 판례·이론 요지다."}],"선지":[{"번호":1,"판정":"옳음","설명":"실체법상 권리관계와 등기기록상 형식이 다를 수 있어 둘이 일치하지 않는 경우가 있다."},{"번호":2,"판정":"옳음","설명":"실체법상 등기권리자는 실체법상 등기의무자에게 등기신청에 협력할 것을 요구할 권리를 가진 자다."},{"번호":3,"판정":"옳음","설명":"절차법상 등기의무자 여부는 등기기록상 형식적으로 판단하고 실체법상 권리의무는 고려하지 않는다(형식적 심사)."},{"번호":4,"판정":"옳음","설명":"甲이 설정해 준 乙 명의 저당권 말소에서는 말소로 이익을 받는 甲이 절차법상 등기권리자다."},{"번호":5,"판정":"틀림","설명":"丙이 乙을 대위해 신청해도 丙은 대위신청인이고, 절차법상 등기권리자는 乙이다(법 제28조제1항)."}],"개념":[{"종류":"비교","제목":"실체법상 등기권리자·의무자와 절차법상 등기권리자·의무자","왼쪽":{"이름":"실체법상","항목":["등기를 청구할 수 있는 권리(등기청구권)를 가진 자가 등기권리자","협력 의무를 지는 자가 등기의무자","실체적 권리관계에 따라 정해짐"]},"오른쪽":{"이름":"절차법상","항목":["등기기록의 형식상 권리를 얻거나 이익을 받는 자가 등기권리자","등기기록상 권리를 상실하거나 불이익을 받는 자가 등기의무자","등기기록상 형식으로 판단(실체법상 권리의무는 고려하지 않음)"]}},{"종류":"표","제목":"대위신청(법 제28조)","머리":["구분","내용"],"행":[["대위신청인","민법 제404조에 따라 채권자가 채무자를 대위하여 신청"],["등기권리자","채무자(피대위자)가 절차법상 등기권리자"],["등기관의 기록","대위자의 성명 또는 명칭, 주소 또는 사무소 소재지 및 대위원인"]]}],"함정":"대위 신청에서는 신청하는 사람(대위자)과 등기의 권리자(피대위자)가 다르다. 말소등기에서는 등기기록상 권리를 잃는 자가 의무자이고 말소로 이익을 받는 자가 권리자다. 사례의 당사자를 이 기준에 대입해 푼다."},"30회-2차-088":{"한줄":"축척 600분의 1 지역은 면적을 0.1제곱미터 단위로 정한다. 0.05제곱미터는 끝자리가 0이라 버려지지만 1필지 면적이 0.1제곱미터 미만이면 0.1제곱미터로 하므로 0.1m²다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제60조제1항제2호","원문":"지적도의 축척이 600분의 1인 지역과 경계점좌표등록부에 등록하는 지역의 토지 면적은 제1호에도 불구하고 제곱미터 이하 한 자리 단위로 하되, 0.1제곱미터 미만의 끝수가 있는 경우 0.05제곱미터 미만일 때에는 버리고 0.05제곱미터를 초과할 때에는 올리며, 0.05제곱미터일 때에는 구하려는 끝자리의 숫자가 0 또는 짝수이면 버리고 홀수이면 올린다. 다만, 1필지의 면적이 0.1제곱미터 미만일 때에는 0.1제곱미터로 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제60조제1항제1호","원문":"토지의 면적에 1제곱미터 미만의 끝수가 있는 경우 0.5제곱미터 미만일 때에는 버리고 0.5제곱미터를 초과하는 때에는 올리며, 0.5제곱미터일 때에는 구하려는 끝자리의 숫자가 0 또는 짝수이면 버리고 홀수이면 올린다. 다만, 1필지의 면적이 1제곱미터 미만일 때에는 1제곱미터로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"600분의 1 지역의 면적은 제곱미터 이하 한 자리 단위로 정한다. 두 자리(0.01)로 등록하지 않는다(영 제60조제1항제2호)."},{"번호":2,"판정":"틀림","설명":"0.05는 두 자리 값이다. 0.05제곱미터는 끝자리 숫자가 0이어서 버려지고 0.1 미만 단서가 적용된다(영 제60조제1항제2호)."},{"번호":3,"판정":"옳음","설명":"계산값 0.050을 0.1 단위로 처리하면 0.0이 되고 1필지가 0.1제곱미터 미만이므로 0.1로 한다(영 제60조제1항제2호 단서)."},{"번호":4,"판정":"틀림","설명":"0.5는 일반 지역의 반올림 기준값이다. 600분의 1 지역에는 쓰지 않는다(영 제60조제1항제1호·제2호)."},{"번호":5,"판정":"틀림","설명":"1.0은 일반 지역에서 1필지가 1제곱미터 미만일 때 쓰는 최소 면적이다(영 제60조제1항제1호 단서)."}],"개념":[{"종류":"계산","제목":"면적 결정 계산(600분의 1 지역)","단계":[{"설명":"적용 규정 확인: 600분의 1 지역은 제2호 적용","식":"영 제60조제1항제2호","값":"0.1제곱미터 단위(소수 한 자리)"},{"설명":"끝수 처리: 0.1 미만 끝수 0.05, 구하려는 끝자리 숫자는 0","식":"0.05제곱미터 → 끝자리가 0 또는 짝수이면 버림","값":"0.0"},{"설명":"최소 면적 단서: 1필지 면적이 0.1제곱미터 미만","식":"0.0 < 0.1","값":"0.1제곱미터"}]},{"종류":"표","제목":"면적 결정 방법 비교(영 제60조제1항)","머리":["구분","일반 지역","600분의 1 지역·경계점좌표등록부 지역"],"행":[["등록 단위","제곱미터","제곱미터 이하 한 자리(0.1)"],["끝수 기준","0.5제곱미터 미만 버림, 초과 올림","0.05제곱미터 미만 버림, 초과 올림"],["기준값과 같을 때","끝자리가 0 또는 짝수이면 버리고 홀수이면 올림","끝자리가 0 또는 짝수이면 버리고 홀수이면 올림"],["최소 면적","1필지가 1제곱미터 미만이면 1제곱미터","1필지가 0.1제곱미터 미만이면 0.1제곱미터"]]}],"함정":"0.05를 반올림해 0.1로 올리는 풀이도 답은 같지만 규정은 다르다. 끝수 규칙은 0.05를 0.0으로 버리고, 최소 면적 단서가 0.1을 만든다. ⑤의 1.0은 일반 지역의 최소 면적이다."},"30회-2차-006":{"한줄":"협회가 시·도회 또는 지회를 설치하면 시·도회는 시·도지사에게, 지회는 등록관청에 신고해야 하므로 ③이 옳다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제32조제2항","원문":"협회가 그 시ㆍ도회 또는 지회를 설치할 때에는 그 시ㆍ도회는 시ㆍ도지사에게, 지회는 등록관청에 신고하여야 한다."},{"법령":"공인중개사법","조문":"법 제41조제4항","원문":"협회는 정관으로 정하는 바에 따라 주사무소에 두는 중앙회를 설치하고, 시ㆍ도에 시ㆍ도회를, 시(구가 설치되지 아니한 시와 특별자치도의 행정시를 말한다)ㆍ군ㆍ구에 지회를 둘 수 있다."},{"법령":"공인중개사법 시행령","조문":"영 제31조제6호","원문":"법 제42조의 규정에 따른 공제사업. 이 경우 공제사업은 비영리사업으로서 회원간의 상호부조를 목적으로 한다."},{"법령":"공인중개사법 시행령","조문":"영 제32조제1항","원문":"협회는 총회의 의결내용을 지체 없이 국토교통부장관에게 보고하여야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제31조제5호","원문":"부동산 정보제공에 관한 업무"}],"선지":[{"번호":1,"판정":"틀림","설명":"공제사업은 비영리사업으로서 회원간의 상호부조를 목적으로 한다(영 제31조제6호). 영리사업이 아니다."},{"번호":2,"판정":"틀림","설명":"총회의 의결내용은 지체 없이 국토교통부장관에게 보고한다(영 제32조제1항). 등록관청에 하는 보고가 아니다."},{"번호":3,"판정":"옳음","설명":"시·도회는 시·도지사에게, 지회는 등록관청에 신고한다(영 제32조제2항)."},{"번호":4,"판정":"틀림","설명":"영 제31조의 협회 업무에는 행정제재처분의 부과·집행이 없다. 등록취소·업무정지는 등록관청이 한다(법 제38조, 제39조)."},{"번호":5,"판정":"틀림","설명":"부동산 정보제공에 관한 업무는 협회의 업무다(영 제31조제5호). 직접 수행할 수 있다."}],"개념":[{"종류":"표","제목":"협회의 업무(영 제31조)","머리":["호","업무"],"행":[["1","회원의 품위유지를 위한 업무"],["2","부동산중개제도의 연구·개선에 관한 업무"],["3","회원의 자질향상을 위한 지도 및 교육·연수에 관한 업무"],["4","회원의 윤리헌장 제정 및 그 실천에 관한 업무"],["5","부동산 정보제공에 관한 업무"],["6","공제사업(비영리사업, 회원간의 상호부조 목적)"],["7","그 밖에 협회의 설립목적 달성을 위하여 필요한 업무"]]},{"종류":"표","제목":"협회 조직과 신고(법 제41조, 영 제32조)","머리":["구분","내용"],"행":[["설립","한국공인중개사협회는 법인. 정관 제정·변경은 국토교통부장관 인가(법 제41조제1항·제2항)"],["조직","주사무소에 중앙회, 시·도에 시·도회, 시·군·구에 지회를 둘 수 있음(법 제41조제4항)"],["총회 의결내용","지체 없이 국토교통부장관에게 보고(영 제32조제1항)"],["시·도회 설치","시·도지사에게 신고(영 제32조제2항)"],["지회 설치","등록관청에 신고(영 제32조제2항)"]]}],"함정":"신고 상대방은 시·도회가 시·도지사, 지회가 등록관청이다. ②는 보고 상대방이 국토교통부장관이다. ①은 공제사업을 영리사업으로 적었고, ④는 협회 업무에 없는 행정제재처분을, ⑤는 협회 업무인 정보제공을 직접 수행할 수 없다고 적었다.","개정":"2026.2.27 법 개정으로 협회 명칭이 한국공인중개사협회로 정해지고(법 제41조제1항) 조직 명칭이 지부에서 시·도회로 바뀌었다(법 제41조제4항, 영 제32조제2항 개정 2026.8.18). 신고 상대방은 시·도회는 시·도지사, 지회는 등록관청으로 그대로다."},"30회-2차-022":{"한줄":"내용에 부합하는 동일한 거래계약서를 여러 부 작성하는 것은 위반이 아니고, 자격정지 사유는 서로 다른 둘 이상의 거래계약서를 작성한 경우이므로 ①이 자격정지 사유에 해당하지 않는다.","근거":[{"법령":"공인중개사법","조문":"법 제36조제1항제6호","원문":"제26조제3항의 규정을 위반하여 거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성한 경우"},{"법령":"공인중개사법","조문":"법 제36조제1항제1호","원문":"제12조제2항의 규정을 위반하여 둘 이상의 중개사무소에 소속된 경우"},{"법령":"공인중개사법","조문":"법 제36조제1항제3호","원문":"제25조제1항의 규정을 위반하여 성실ㆍ정확하게 중개대상물의 확인ㆍ설명을 하지 아니하거나 설명의 근거자료를 제시하지 아니한 경우"},{"법령":"공인중개사법","조문":"법 제36조제1항제4호","원문":"제25조제4항의 규정을 위반하여 중개대상물확인ㆍ설명서에 서명 및 날인을 하지 아니한 경우"},{"법령":"공인중개사법","조문":"법 제25조제4항","원문":"제3항에 따른 확인ㆍ설명서에는 개업공인중개사(법인인 경우에는 대표자를 말하며, 법인에 분사무소가 설치되어 있는 경우에는 분사무소의 책임자를 말한다)가 서명 및 날인하되, 해당 중개행위를 한 소속공인중개사가 있는 경우에는 소속공인중개사가 함께 서명 및 날인하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"거래내용에 부합하는 동일한 거래계약서는 몇 부를 작성해도 법 제26조제3항 위반이 아니다. 자격정지는 서로 다른 둘 이상의 거래계약서를 작성한 경우에 한한다(법 제36조제1항제6호)."},{"번호":2,"판정":"옳음","설명":"둘 이상의 중개사무소에 소속된 경우는 자격정지 사유다(법 제36조제1항제1호)."},{"번호":3,"판정":"옳음","설명":"거래계약서에 거래금액을 거짓으로 기재한 경우는 자격정지 사유다. 고객의 요청이 있어도 같다(법 제36조제1항제6호)."},{"번호":4,"판정":"옳음","설명":"설명의 근거자료를 제시하지 않은 경우는 자격정지 사유다(법 제36조제1항제3호)."},{"번호":5,"판정":"옳음","설명":"해당 중개행위를 한 소속공인중개사는 확인·설명서에 함께 서명 및 날인해야 하고(법 제25조제4항), 하지 않으면 자격정지 사유다(법 제36조제1항제4호). 분사무소 책임자가 서명했어도 면제되지 않는다."}],"개념":[{"종류":"표","제목":"소속공인중개사 자격정지 사유와 기준(법 제36조제1항, 시행규칙 별표 3)","머리":["호","사유","자격정지 기준"],"행":[["1","둘 이상의 중개사무소에 소속된 경우","6월"],["2","인장등록을 하지 않거나 등록하지 않은 인장을 사용한 경우","3월"],["3","중개대상물의 확인·설명을 성실·정확하게 하지 않거나 설명의 근거자료를 제시하지 않은 경우","3월"],["4","중개대상물확인·설명서에 서명 및 날인을 하지 않은 경우","3월"],["5","거래계약서에 서명 및 날인을 하지 않은 경우","3월"],["6","거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성한 경우","6월"],["7","법 제33조제1항 각 호의 금지행위를 한 경우","6월"]]},{"종류":"표","제목":"확인·설명서와 거래계약서의 서명 및 날인(법 제25조제4항, 제26조제2항)","머리":["구분","서명 및 날인할 사람"],"행":[["개업공인중개사","서명 및 날인(법인은 대표자, 분사무소가 설치된 법인은 분사무소의 책임자)"],["소속공인중개사","해당 중개행위를 한 소속공인중개사가 있으면 함께 서명 및 날인"],["거래계약서","제25조제4항을 준용(법 제26조제2항)"]]}],"함정":"⑤에서 분사무소 책임자가 서명했다는 사정은 소속공인중개사의 의무를 덜어 주지 않는다. ①은 부수가 아니라 내용이 서로 다른지가 기준이다. 거짓 기재(③)와 서로 다른 둘 이상 작성은 같은 호(제6호)에 있다."},"30회-2차-009":{"한줄":"상업용 건축물 및 주택의 분양대행, 거래 상담, 중개업의 경영기법·경영정보 제공, 주거이전에 부수되는 용역의 알선은 모두 법인인 개업공인중개사가 할 수 있는 업무이므로 ㄱ~ㄹ 모두 해당한다.","근거":[{"법령":"공인중개사법","조문":"법 제14조제1항","원문":"법인인 개업공인중개사는 다른 법률에 규정된 경우를 제외하고는 중개업 및 다음 각 호에 규정된 업무와 제2항에 규정된 업무 외에 다른 업무를 함께 할 수 없다."},{"법령":"공인중개사법","조문":"법 제14조제1항제4호","원문":"상업용 건축물 및 주택의 분양대행"},{"법령":"공인중개사법","조문":"법 제14조제1항제2호","원문":"부동산의 이용ㆍ개발 및 거래에 관한 상담"},{"법령":"공인중개사법","조문":"법 제14조제1항제3호","원문":"개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공"},{"법령":"공인중개사법","조문":"법 제14조제1항제5호","원문":"그 밖에 중개업에 부수되는 업무로서 대통령령으로 정하는 업무"},{"법령":"공인중개사법 시행령","조문":"영 제17조제2항","원문":"법 제14조제1항제5호에서 \"대통령령이 정하는 업무\"라 함은 중개의뢰인의 의뢰에 따른 도배ㆍ이사업체의 소개 등 주거이전에 부수되는 용역의 알선을 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ, ㄹ도 겸업할 수 있어 ㄱ, ㄴ만으로는 부족하다."},{"번호":2,"판정":"틀림","설명":"ㄴ, ㄹ이 빠졌다. 거래에 관한 상담(제2호)과 주거이전에 부수되는 용역의 알선(제5호)도 겸업 가능하다."},{"번호":3,"판정":"틀림","설명":"ㄴ이 빠졌다(법 제14조제1항제2호)."},{"번호":4,"판정":"틀림","설명":"ㄱ이 빠졌다. 분양대행도 겸업 가능하다(법 제14조제1항제4호)."},{"번호":5,"판정":"옳음","설명":"ㄱ(제4호), ㄴ(제2호), ㄷ(제3호), ㄹ(제5호, 영 제17조제2항) 모두 겸업 가능하다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"분양대행은 겸업 가능하다(법 제14조제1항제4호)."},{"기호":"ㄴ","판정":"옳음","설명":"부동산의 이용·개발 및 거래에 관한 상담은 겸업 가능하다(법 제14조제1항제2호)."},{"기호":"ㄷ","판정":"옳음","설명":"개업공인중개사를 대상으로 한 경영기법·경영정보 제공은 겸업 가능하다(법 제14조제1항제3호)."},{"기호":"ㄹ","판정":"옳음","설명":"주거이전에 부수되는 용역의 알선은 겸업 가능하다(법 제14조제1항제5호, 영 제17조제2항)."}],"개념":[{"종류":"표","제목":"법인인 개업공인중개사의 겸업 범위(법 제14조)","머리":["구분","업무"],"행":[["제1항제1호","상업용 건축물 및 주택의 임대관리 등 부동산의 관리대행"],["제1항제2호","부동산의 이용·개발 및 거래에 관한 상담"],["제1항제3호","개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공"],["제1항제4호","상업용 건축물 및 주택의 분양대행"],["제1항제5호","그 밖에 중개업에 부수되는 업무로서 대통령령으로 정하는 업무(영 제17조제2항: 도배·이사업체의 소개 등 주거이전에 부수되는 용역의 알선)"],["제2항","경매·공매 대상 부동산에 대한 권리분석 및 취득의 알선과 매수신청·입찰신청의 대리(개업공인중개사 전체)"],["위반 효과","겸업 제한 위반은 등록취소 사유(법 제38조제2항제4호, 임의적)"]]}],"함정":"겸업 업무는 법 제14조제1항의 다섯 가지와 제2항의 경매·공매 대리로 닫혀 있다. 제5호는 대통령령에 위임돼 있어 도배·이사업체 소개(ㄹ)처럼 영 제17조제2항을 찾아야 확인된다. 보기가 모두 허용되는 경우라 일부만 고르면 틀린다."},"30회-2차-013":{"한줄":"거래정보사업자는 개업공인중개사에 따라 정보가 차별적으로 공개되도록 해서는 안 되므로 차별 공개가 가능하다고 한 ⑤가 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제24조제1항","원문":"국토교통부장관은 개업공인중개사 상호간에 부동산매매 등에 관한 정보의 공개와 유통을 촉진하고 공정한 부동산거래질서를 확립하기 위하여 부동산거래정보망을 설치ㆍ운영할 자를 지정할 수 있다."},{"법령":"공인중개사법","조문":"법 제24조제2항","원문":"제1항에 따라 지정을 받을 수 있는 자는 「전기통신사업법」의 규정에 의한 부가통신사업자로서 국토교통부령으로 정하는 요건을 갖춘 자로 한다."},{"법령":"공인중개사법","조문":"법 제24조제3항","원문":"제1항에 따라 지정을 받은 자(이하 \"거래정보사업자\"라 한다)는 지정받은 날부터 3개월 이내에 부동산거래정보망의 이용 및 정보제공방법 등에 관한 운영규정(이하 \"운영규정\"이라 한다)을 정하여 국토교통부장관의 승인을 얻어야 한다. 이를 변경하고자 하는 때에도 또한 같다."},{"법령":"공인중개사법","조문":"법 제24조제4항","원문":"거래정보사업자는 개업공인중개사로부터 공개를 의뢰받은 중개대상물의 정보에 한정하여 이를 부동산거래정보망에 공개하여야 하며, 의뢰받은 내용과 다르게 정보를 공개하거나 어떠한 방법으로든지 개업공인중개사에 따라 정보가 차별적으로 공개되도록 하여서는 아니된다."},{"법령":"공인중개사법","조문":"법 제24조제5항제3호","원문":"제4항의 규정을 위반하여 정보를 공개한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"국토교통부장관이 부동산거래정보망을 설치·운영할 자를 지정한다(법 제24조제1항)."},{"번호":2,"판정":"옳음","설명":"지정 대상은 전기통신사업법상 부가통신사업자로서 국토교통부령의 요건을 갖춘 자다(법 제24조제2항)."},{"번호":3,"판정":"옳음","설명":"지정받은 날부터 3개월 이내에 운영규정을 정해 국토교통부장관의 승인을 얻는다(법 제24조제3항)."},{"번호":4,"판정":"옳음","설명":"운영규정을 변경할 때도 승인을 얻는다(법 제24조제3항 후문)."},{"번호":5,"판정":"틀림","설명":"개업공인중개사에 따라 정보가 차별적으로 공개되도록 해서는 안 된다(법 제24조제4항). 위반 시 지정취소 사유다(제5항제3호)."}],"개념":[{"종류":"표","제목":"부동산거래정보망과 거래정보사업자(법 제24조)","머리":["구분","내용"],"행":[["지정권자","국토교통부장관(제1항)"],["지정 대상","전기통신사업법상 부가통신사업자로서 국토교통부령의 요건을 갖춘 자(제2항)"],["운영규정","지정받은 날부터 3개월 이내에 정해 국토교통부장관의 승인. 변경도 승인(제3항)"],["정보 공개 방법","공개를 의뢰받은 정보에 한정. 의뢰 내용과 다르게 공개하거나 개업공인중개사에 따라 차별 공개 금지(제4항)"],["지정취소 사유","부정한 방법의 지정, 운영규정 미승인·위반, 제4항 위반, 지정 후 1년 이내 미운영, 사망·해산 등으로 운영 불가(제5항)"],["개업공인중개사의 의무","정보를 거짓으로 공개 금지. 거래가 완성되면 지체 없이 거래정보사업자에게 통보(제7항)"],["개업공인중개사 제재","정보를 거짓으로 공개: 업무정지 6개월, 거래완성 미통보: 업무정지 3개월(법 제39조제1항제4호, 시행규칙 별표 4)"]]}],"함정":"⑤는 제4항이 금지한 차별 공개를 허용하는 문장으로 바꿨다. ③은 승인 기한이 지정받은 날부터 3개월이라는 점, ④는 변경 때도 승인이 필요하다는 점이 쟁점이다."},"30회-2차-019":{"한줄":"주택을 매수하려는 의뢰인이 쓰는 일반중개계약서는 권리취득용 항목(희망물건의 종류, 취득 희망가격, 희망 지역, 그 밖의 희망조건)을 적으므로 희망지역(ㄴ)과 취득 희망가격(ㄷ)이 해당한다.","근거":[{"법령":"공인중개사법","조문":"법 제22조","원문":"중개의뢰인은 중개의뢰내용을 명확하게 하기 위하여 필요한 경우에는 개업공인중개사에게 다음 각 호의 사항을 기재한 일반중개계약서의 작성을 요청할 수 있다. 1. 중개대상물의 위치 및 규모 2. 거래예정가격 3. 거래예정가격에 대하여 제32조에 따라 정한 중개보수 4. 그 밖에 개업공인중개사와 중개의뢰인이 준수하여야 할 사항"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 별지 제14호서식 뒤쪽 Ⅱ. 권리취득용(매수ㆍ임차 등)","원문":"항목: 희망물건의 종류, 취득 희망가격, 희망 지역, 그 밖의 희망조건"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 별지 제14호서식 뒤쪽 Ⅰ. 권리이전용(매도ㆍ임대 등)","원문":"소유자 및 등기명의인, 중개대상물의 표시, 권리관계, 거래규제 및 공법상 제한사항, 중개의뢰 금액, 그 밖의 사항"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄴ(희망 지역)도 적는 항목이라 ㄷ만으로는 부족하다."},{"번호":2,"판정":"틀림","설명":"ㄱ(소유자 및 등기명의인)은 권리이전용 항목이다. 매수 의뢰인은 적지 않는다."},{"번호":3,"판정":"옳음","설명":"희망 지역(ㄴ)과 취득 희망가격(ㄷ)이 권리취득용 항목이다."},{"번호":4,"판정":"틀림","설명":"ㄹ(거래규제 및 공법상 제한사항)은 권리이전용 항목이다. ㄴ도 빠졌다."},{"번호":5,"판정":"틀림","설명":"ㄱ은 권리이전용 항목이라 포함하면 틀린다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"소유자 및 등기명의인은 권리이전용 항목이다."},{"기호":"ㄴ","판정":"옳음","설명":"희망 지역은 권리취득용 항목이다."},{"기호":"ㄷ","판정":"옳음","설명":"취득 희망가격은 권리취득용 항목이다."},{"기호":"ㄹ","판정":"틀림","설명":"거래규제 및 공법상 제한사항은 권리이전용 항목이다."}],"개념":[{"종류":"비교","제목":"일반중개계약서 뒤쪽 기재 항목(별지 제14호서식)","왼쪽":{"이름":"Ⅰ. 권리이전용(매도·임대 등)","항목":["소유자 및 등기명의인(성명·생년월일·주소)","중개대상물의 표시(건축물·토지)","권리관계(은행융자·권리금·제세공과금 등 또는 월임대료·보증금·관리비 등)","거래규제 및 공법상 제한사항","중개의뢰 금액","그 밖의 사항"]},"오른쪽":{"이름":"Ⅱ. 권리취득용(매수·임차 등)","항목":["희망물건의 종류","취득 희망가격","희망 지역","그 밖의 희망조건"]}}],"함정":"권리를 넘기는 쪽(매도·임대)과 얻는 쪽(매수·임차)이 적는 항목이 다르다. 甲은 주택을 사려는 사람이므로 소유자·등기명의인(ㄱ)이나 공법상 제한사항(ㄹ)이 아니라 희망 항목을 적는다."},"30회-2차-012":{"한줄":"개업공인중개사는 선량한 관리자의 주의로 중개대상물의 권리관계 등을 조사·확인해 중개의뢰인에게 설명할 의무가 있다는 판례 요지가 옳다.","근거":[{"법령":"공인중개사법","조문":"법 제25조제1항","원문":"개업공인중개사는 중개를 의뢰받은 경우에는 중개가 완성되기 전에 다음 각 호의 사항을 확인하여 이를 해당 중개대상물에 관한 권리를 취득하고자 하는 중개의뢰인에게 성실ㆍ정확하게 설명하고, 토지대장 등본 또는 부동산종합증명서, 등기사항증명서, 신탁원부, 건축물대장 등본 등 설명의 근거자료를 제시하여야 한다."},{"법령":"공인중개사법","조문":"법 제25조제4항","원문":"제3항에 따른 확인ㆍ설명서에는 개업공인중개사(법인인 경우에는 대표자를 말하며, 법인에 분사무소가 설치되어 있는 경우에는 분사무소의 책임자를 말한다)가 서명 및 날인하되, 해당 중개행위를 한 소속공인중개사가 있는 경우에는 소속공인중개사가 함께 서명 및 날인하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 별지 제20호서식 작성방법 (공동중개)","원문":"공동중개 시 참여한 개업공인중개사(소속공인중개사를 포함합니다)는 모두 서명ㆍ날인해야 하며, 2명을 넘는 경우에는 별지로 작성하여 첨부합니다."},{"법령":"공인중개사법 시행령","조문":"영 제21조제4항","원문":"법 제25조제3항 본문에서 \"대통령령이 정하는 기간\"이란 3년을 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"개업공인중개사는 선량한 관리자의 주의로 권리관계 등을 조사·확인하여 설명할 의무가 있다. 판례 요지이며 법 제25조제1항의 확인·설명의무와 같은 취지다."},{"번호":2,"판정":"틀림","설명":"공동중개에 참여한 개업공인중개사는 모두 서명·날인해야 한다(확인·설명서 작성방법). 1인만 하면 되는 것이 아니다."},{"번호":3,"판정":"틀림","설명":"확인·설명은 중개가 완성되기 전에 한다(법 제25조제1항)."},{"번호":4,"판정":"틀림","설명":"확인·설명의무를 지는 사람은 개업공인중개사다(법 제25조제1항). 중개보조원은 의무 주체가 아니다."},{"번호":5,"판정":"틀림","설명":"확인·설명서의 보존기간은 3년이다(영 제21조제4항). 5년은 거래계약서의 보존기간이다."}],"개념":[{"종류":"표","제목":"확인·설명 사항(영 제21조제1항)","머리":["호","사항"],"행":[["1","중개대상물의 종류·소재지·지번·지목·면적·용도·구조 및 건축연도 등 기본적인 사항"],["2","소유권·전세권·저당권·지상권 및 임차권 등 권리관계에 관한 사항"],["3","거래예정금액·중개보수 및 실비의 금액과 그 산출내역"],["3의2","관리비 금액과 그 산출내역(주택 임대차 중개만)"],["4","토지이용계획, 공법상의 거래규제 및 이용제한에 관한 사항"],["5","수도·전기·가스·소방·열공급·승강기 및 배수 등 시설물의 상태"],["6","벽면·바닥면 및 도배의 상태"],["7","일조·소음·진동 등 환경조건"],["8","도로 및 대중교통수단과의 연계성, 시장·학교와의 근접성 등 입지조건"],["9","권리를 취득함에 따라 부담하여야 할 조세의 종류 및 세율"],["10~12","임대인의 정보 제시 의무·보증금 중 일정액의 보호, 전입세대확인서의 열람·교부, 민간임대주택의 임대보증금 보증(주택 임대차 중개만 적용, 12호는 민간임대주택인 경우)"]]},{"종류":"표","제목":"작성·교부·보존 비교","머리":["서류","보존기간","조문"],"행":[["중개대상물 확인·설명서","3년","영 제21조제4항"],["거래계약서","5년","영 제22조제2항"]]}],"함정":"확인·설명의 의무자(개업공인중개사), 시기(중개 완성 전), 서명·날인 대상(공동중개 참여자 전원), 보존기간(3년)이 각각 선지 하나씩 틀리게 바뀌어 있다. 거래계약서 5년과 확인·설명서 3년을 바꿔 놓지 않는다."},"30회-2차-029":{"한줄":"포상금 지급 결정을 통보받은 신고인은 국토교통부령으로 정하는 지급신청서를 신고관청 또는 허가관청에 제출해야 하므로 ⑤가 옳다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제19조의3제4항","원문":"제3항에 따라 포상금 지급 결정을 통보받은 신고인 또는 고발인은 국토교통부령으로 정하는 포상금 지급신청서를 작성하여 신고관청 또는 허가관청에 제출하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제25조의2제2항","원문":"제1항에 따른 포상금의 지급에 드는 비용은 시ㆍ군이나 구의 재원으로 충당한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제19조의2제2항","원문":"제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 포상금을 지급하지 아니할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제19조의2제3항제1호","원문":"법 제25조의2제1항제1호, 제1호의2부터 제1호의4까지의 규정에 따른 포상금의 경우: 법 제28조제1항ㆍ제3항 또는 제5항에 따라 부과되는 과태료의 100분의 20에 해당하는 금액. 이 경우 법 제25조의2제1항제1호에 따른 포상금의 지급한도액은 1천만원으로 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제19조의3제5항","원문":"신고관청 또는 허가관청은 제4항에 따른 신청서가 접수된 날부터 2개월 이내에 포상금을 지급하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"포상금 지급 비용은 시·군이나 구의 재원으로 충당한다(법 제25조의2제2항). 국고가 아니다."},{"번호":2,"판정":"틀림","설명":"위반행위에 관여한 자가 신고한 경우에는 포상금을 지급하지 않을 수 있다(영 제19조의2제2항제2호). 지급해야 하는 것이 아니다."},{"번호":3,"판정":"틀림","설명":"익명이나 가명으로 신고해 신고인을 확인할 수 없으면 포상금을 지급하지 않을 수 있다(영 제19조의2제2항제3호). 국고 환수 규정이 아니다."},{"번호":4,"판정":"틀림","설명":"포상금은 과태료의 100분의 20이고 지급한도액은 1천만원이다(영 제19조의2제3항제1호). 1천5백만원은 받을 수 없다. 법 제25조의2제1항제1호의 대상도 실제 거래가격을 거짓으로 신고한 자다."},{"번호":5,"판정":"옳음","설명":"지급 결정을 통보받은 신고인은 지급신청서를 작성하여 신고관청 또는 허가관청에 제출한다(영 제19조의3제4항)."}],"개념":[{"종류":"흐름","제목":"신고포상금 지급 절차(영 제19조의3)","단계":[{"이름":"신고","설명":"신고서와 증거자료를 신고관청 또는 허가관청에 제출(제1항)"},{"이름":"결정 통지","설명":"신고관청 또는 허가관청이 포상금 지급 여부를 결정하고 신고인·고발인에게 통지(제3항)"},{"이름":"지급신청","설명":"지급 결정을 통보받은 신고인이 지급신청서를 작성하여 제출(제4항)"},{"이름":"지급","설명":"신청서가 접수된 날부터 2개월 이내에 지급(제5항). 신고자가 2명 이상이면 국토교통부령에 따라 배분(제6항)"}]},{"종류":"표","제목":"신고포상금 대상과 금액(법 제25조의2, 영 제19조의2)","머리":["구분","내용"],"행":[["대상","실제 거래가격 거짓 신고 등(제1항제1호~제1호의4), 허가 없이 토지거래계약 체결 또는 부정한 방법의 허가(제2호), 허가받은 목적대로 이용하지 않은 자(제3호)"],["금액(제1호~제1호의4)","부과되는 과태료의 100분의 20. 제1호의 지급한도액은 1천만원"],["금액(제2호·제3호)","건별 50만원. 같은 목적으로 취득한 일단의 토지에 대한 신고·고발은 1건"],["지급하지 않을 수 있는 경우","공무원이 직무와 관련하여 발견한 사실을 신고한 경우, 위반행위에 관여한 자가 신고한 경우, 익명·가명 신고로 신고인을 확인할 수 없는 경우"],["비용 부담","시·군 또는 구의 재원"]]}],"함정":"지급 비용을 국고(①)로, 관여자 신고 시 지급 의무(②)로, 익명 신고의 환수(③)로 바꾼 문장이 섞여 있다. ④는 금액이다. 포상금 지급한도는 1천만원이고 거짓 신고가 대상이다."},"30회-2차-035":{"한줄":"2001년 장사법 시행 전인 1995년에 설치된 분묘는 20년 이상 평온·공연하게 점유하면 분묘기지권을 시효취득할 수 있으므로 시효취득할 수 없다고 한 ①이 틀리다.","근거":[{"법령":"장사 등에 관한 법률","조문":"장사법 제27조제3항","원문":"제1항 각 호의 어느 하나에 해당하는 분묘의 연고자는 해당 토지 소유자, 묘지 설치자 또는 연고자에게 토지 사용권이나 그 밖에 분묘의 보존을 위한 권리를 주장할 수 없다."},{"법령":"민법","조문":"민법 제245조제1항","원문":"20년간 소유의 의사로 평온, 공연하게 부동산을 점유하는 자는 등기함으로써 그 소유권을 취득한다."},{"판례":"대법원 2021. 4. 29. 선고 2017다228007 전원합의체 판결","요지":"타인 토지에 승낙 없이 분묘를 설치하고 20년간 평온·공연하게 점유해 분묘기지권을 시효취득한 사람도, 토지소유자가 지료를 청구한 날부터의 지료를 지급할 의무가 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"장사법이 시행되기 전(2001년 이전)에 설치된 분묘는 20년 이상 평온·공연한 점유로 시효취득할 수 있다. 장사법 시행 후 설치한 분묘는 승낙 없이 설치했다면 토지사용권을 주장할 수 없다(장사법 제27조제3항). 1995년 설치 분묘에는 해당하지 않는다."},{"번호":2,"판정":"옳음","설명":"암장되어 객관적으로 인식할 수 있는 외형이 없는 묘소에는 분묘기지권이 인정되지 않는다. 판례 요지다."},{"번호":3,"판정":"옳음","설명":"아직 사망하지 않은 사람을 위한 장래의 묘소에는 분묘기지권이 인정되지 않는다. 판례 요지다."},{"번호":4,"판정":"옳음","설명":"시효취득한 분묘기지권자는 토지소유자가 지료를 청구한 날부터의 지료를 지급할 의무가 있다(대법원 2021. 4. 29. 선고 2017다228007 전원합의체 판결)."},{"번호":5,"판정":"옳음","설명":"분묘기지권의 효력이 미치는 범위 안이라도 기존 분묘 외에 새 분묘를 설치할 권능은 없다. 판례 요지다."}],"개념":[{"종류":"표","제목":"분묘기지권 정리(판례 요지)","머리":["구분","내용"],"행":[["취득 원인","시효취득(승낙 없이 설치한 분묘를 20년간 평온·공연하게 점유), 소유자의 승낙을 받아 설치, 자기 소유 토지에 설치한 분묘의 토지를 처분하면서 분묘를 이장한다는 특약이 없는 경우"],["시효취득 제한","장사법 시행 후 승낙 없이 설치한 분묘는 토지사용권 등을 주장할 수 없음(장사법 제27조제3항)"],["인정되지 않는 경우","암장된 묘소, 장래의 묘소(아직 사망하지 않은 사람을 위한 묘소)"],["효력 범위","기존 분묘의 기지와 봉분 주위의 공지. 새 분묘 신설 권능은 없음"],["지료","시효취득자는 토지소유자가 지료를 청구한 날부터 지급(2017다228007 전원합의체)"]]}],"함정":"「2001년 장사법 시행 후에는 시효취득이 안 된다」는 문장을 1995년 설치 분묘에 그대로 대입하면 틀린다. 시효취득 가능 여부는 분묘를 설치한 시점이 장사법 시행 전인지 후인지로 갈린다.","개정":"대법원 2021. 4. 29. 선고 2017다228007 전원합의체 판결로, 시효취득한 분묘기지권자도 토지소유자가 지료를 청구한 날부터 지료를 지급해야 한다는 취지로 판례가 바뀌었다. ④는 종전의 「지료를 지급할 필요가 없다」를 현행 판례에 맞게 고쳐 실었다."},"30회-2차-037":{"한줄":"丙의 근저당권(6.3. 16:00)이 乙의 대항력 발생일(6.4. 0시)보다 앞서 있어 丙 또는 丁 누구의 경매로 매각되더라도 乙의 임차권은 소멸하므로 ②가 옳다.","근거":[{"법령":"주택임대차보호법","조문":"법 제3조제1항","원문":"임대차는 그 등기(登記)가 없는 경우에도 임차인(賃借人)이 주택의 인도(引渡)와 주민등록을 마친 때에는 그 다음 날부터 제삼자에 대하여 효력이 생긴다. 이 경우 전입신고를 한 때에 주민등록이 된 것으로 본다."},{"법령":"주택임대차보호법","조문":"법 제3조의2제2항","원문":"제3조제1항ㆍ제2항 또는 제3항의 대항요건(對抗要件)과 임대차계약증서(제3조제2항 및 제3항의 경우에는 법인과 임대인 사이의 임대차계약증서를 말한다)상의 확정일자(確定日字)를 갖춘 임차인은 「민사집행법」에 따른 경매 또는 「국세징수법」에 따른 공매(公賣)를 할 때에 임차주택(대지를 포함한다)의 환가대금(換價代金)에서 후순위권리자(後順位權利者)나 그 밖의 채권자보다 우선하여 보증금을 변제(辨濟)받을 권리가 있다."},{"법령":"주택임대차보호법","조문":"법 제3조의2제3항","원문":"임차인은 임차주택을 양수인에게 인도하지 아니하면 제2항에 따른 보증금을 받을 수 없다."},{"법령":"민사집행법","조문":"민사집행법 제91조제2항","원문":"매각부동산 위의 모든 저당권은 매각으로 소멸된다."},{"법령":"민사집행법","조문":"민사집행법 제268조","원문":"부동산을 목적으로 하는 담보권 실행을 위한 경매절차에는 제79조 내지 제162조의 규정을 준용한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"丙의 근저당권이 乙의 대항력보다 앞서 있어 乙은 매수인에게 임차권으로 대항할 수 없다."},{"번호":2,"판정":"옳음","설명":"乙은 6.4. 0시에 대항력과 우선변제권을 갖추고 丙의 근저당권은 6.3. 16:00에 설정됐으므로 乙의 임차권은 丙에 대항할 수 없다. 丙 또는 丁 누구의 경매로 매각되든 소멸한다(판례 요지, 민사집행법 제91조제2항·제268조)."},{"번호":3,"판정":"틀림","설명":"乙은 丁보다 선순위지만 丙보다는 후순위다. 丙과 丁보다 우선해 전액을 배당받는 것이 아니다."},{"번호":4,"판정":"틀림","설명":"우선변제를 받으려면 임차주택을 양수인(매수인)에게 인도해야 한다(법 제3조의2제3항). 법원에 인도하는 것이 아니다."},{"번호":5,"판정":"틀림","설명":"임차인이 집행권원을 얻어 스스로 강제경매를 신청한 경우에는 별도로 배당요구를 하지 않아도 배당받을 수 있다(판례 요지)."}],"개념":[{"종류":"계산","제목":"대항력·우선변제권 발생 시점 비교","단계":[{"설명":"乙: 인도 + 주민등록(전입) + 확정일자를 2019.6.3. 10:00에 갖춤","식":"법 제3조제1항: 전입신고 다음 날부터 효력","값":"2019.6.4. 0시 대항력·우선변제권 발생"},{"설명":"丙의 근저당권설정등기","식":"2019.6.3. 16:00","값":"乙보다 선순위"},{"설명":"丁의 근저당권설정등기","식":"2019.6.4. 16:00","값":"乙보다 후순위"},{"설명":"배당 순서","식":"丙 → 乙 → 丁","값":"乙은 丁에 우선, 丙에는 후순위"}]},{"종류":"표","제목":"임차인 보호 요건 비교(주택임대차보호법)","머리":["구분","요건","시점"],"행":[["대항력(제3조제1항)","주택의 인도 + 주민등록","그 다음 날부터"],["우선변제권(제3조의2제2항)","대항요건 + 확정일자","대항요건과 확정일자를 같은 날 갖추면 대항력이 생기는 다음 날 0시"],["보증금 수령(제3조의2제3항)","임차주택을 양수인에게 인도","인도하지 않으면 우선변제로 보증금을 받을 수 없음"]]}],"함정":"乙의 순위를 丁과만 비교하면 틀린다. 근저당권자가 둘이고 乙이 둘 사이에 끼어 있다. 말소기준이 되는 최선순위 근저당권(丙)보다 乙의 대항력이 늦으면 어느 쪽 경매든 임차권은 소멸한다."},"30회-2차-033":{"한줄":"보증금액을 달리 정하지 않았다면 보증액은 최저매각가격 1억원의 10분의 1인 1천만원이므로 최고가 1억 5천만원에서 1천만원을 뺀 1억 4천만원을 넘어야 차순위매수신고를 할 수 있다.","근거":[{"법령":"민사집행규칙","조문":"민사집행규칙 제63조제1항","원문":"기일입찰에서 매수신청의 보증금액은 최저매각가격의 10분의 1로 한다."},{"법령":"민사집행법","조문":"민사집행법 제114조제2항","원문":"차순위매수신고는 그 신고액이 최고가매수신고액에서 그 보증액을 뺀 금액을 넘는 때에만 할 수 있다."},{"법령":"민사집행규칙","조문":"민사집행규칙 제66조제1항","원문":"최고가매수신고를 한 사람이 둘 이상인 때에는 집행관은 그 사람들에게 다시 입찰하게 하여 최고가매수신고인을 정한다. 이 경우 입찰자는 전의 입찰가격에 못미치는 가격으로는 입찰할 수 없다."},{"법령":"민사집행법","조문":"민사집행법 제142조제6항","원문":"차순위매수신고인은 매수인이 대금을 모두 지급한 때 매수의 책임을 벗게 되고 즉시 매수신청의 보증을 돌려 줄 것을 요구할 수 있다."},{"법령":"민사집행법","조문":"민사집행법 제268조","원문":"부동산을 목적으로 하는 담보권 실행을 위한 경매절차에는 제79조 내지 제162조의 규정을 준용한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"기일입찰의 보증금액은 매수신고액이 아니라 최저매각가격의 10분의 1이다. 1억원의 10분의 1인 1천만원이다(규칙 제63조제1항)."},{"번호":2,"판정":"틀림","설명":"최고가매수신고를 한 사람이 둘 이상이면 그 사람들에게만 다시 입찰하게 한다(규칙 제66조제1항). 모든 사람이 아니다."},{"번호":3,"판정":"틀림","설명":"다시 입찰하는 경우 전의 입찰가격에 못 미치는 가격으로는 입찰할 수 없다(규칙 제66조제1항)."},{"번호":4,"판정":"옳음","설명":"1억 5천만원 - 1천만원 = 1억 4천만원을 넘는 신고액으로 차순위매수신고를 할 수 있다(민사집행법 제114조제2항)."},{"번호":5,"판정":"틀림","설명":"차순위매수신고인은 매수인이 대금을 모두 지급한 때에 매수의 책임을 벗고 보증 반환을 요구할 수 있다(민사집행법 제142조제6항). 매각기일 종결 즉시가 아니다."}],"개념":[{"종류":"계산","제목":"보증액과 차순위매수신고 기준","단계":[{"설명":"보증액 = 최저매각가격의 10분의 1(규칙 제63조제1항)","식":"1억원 × 1/10","값":"1천만원"},{"설명":"1억 2천만원으로 매수신청할 때 제공할 보증금액","식":"보증액은 최저매각가격 기준","값":"1천만원"},{"설명":"차순위 기준 금액 = 최고가 - 보증액(민사집행법 제114조제2항)","식":"1억 5천만원 - 1천만원","값":"1억 4천만원"}]},{"종류":"표","제목":"매각기일 종결과 보증 반환","머리":["사람","보증 반환 시기","조문"],"행":[["최고가매수신고인·차순위매수신고인을 제외한 매수신고인","매각기일 종결 고지에 따라 매수의 책임을 벗고 즉시 신청 가능","민사집행법 제115조제3항"],["차순위매수신고인","매수인이 대금을 모두 지급한 때 매수의 책임을 벗고 즉시 요구 가능","민사집행법 제142조제6항"]]}],"함정":"보증금액은 매수신고액이 얼마인지와 무관하다. ①은 1억 2천만원의 10분의 1로 계산한 오답이다. 차순위매수신고인의 보증 반환은 즉시가 아니라 매수인의 대금 완납 후라는 점(⑤)을 구별한다. 담보권 실행 경매에도 같은 규정이 준용된다(민사집행법 제268조)."},"30회-1차-041":{"한줄":"대리인이 이중매매에 적극 가담하면 본인이 사정을 몰랐어도 반사회질서 법률행위가 되므로 5가 틀렸다.","근거":[{"법령":"민법","조문":"제103조","원문":"선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다."},{"법령":"민법","조문":"제116조제1항","원문":"의사표시의 효력이 의사의 흠결, 사기, 강박 또는 어느 사정을 알았거나 과실로 알지 못한 것으로 인하여 영향을 받을 경우에 그 사실의 유무는 대리인을 표준하여 결정한다."},{"법령":"민법","조문":"제746조","원문":"불법의 원인으로 인하여 재산을 급여하거나 노무를 제공한 때에는 그 이익의 반환을 청구하지 못한다. 그러나 그 불법원인이 수익자에게만 있는 때에는 그러하지 아니하다."},{"판례":"대법원 판례(대리인의 적극 가담)","요지":"대리인이 매도인의 배임행위에 적극 가담한 이중매매는 본인이 그 사정을 몰랐더라도 반사회질서 법률행위가 된다."},{"판례":"대법원 판례(반사회질서 판단의 기준)","요지":"반사회질서 여부는 법률행위가 이루어진 때를 기준으로 하고, 그 무효는 주장할 이익이 있는 자라면 누구든지 주장할 수 있다. 보험금을 부정취득할 목적으로 다수의 보험계약을 체결한 것은 반사회질서 법률행위다."}],"선지":[{"번호":1,"판정":"옳음","설명":"반사회질서 여부는 법률행위 당시의 가치관을 기준으로 판단한다."},{"번호":2,"판정":"옳음","설명":"절대적 무효이므로 주장할 이익이 있는 자는 누구든지 주장할 수 있다."},{"번호":3,"판정":"옳음","설명":"사회질서의 내용은 시대의 가치관념에 따라 변한다."},{"번호":4,"판정":"옳음","설명":"보험금 부정취득 목적의 다수 보험계약은 제103조에 해당한다."},{"번호":5,"판정":"틀림","설명":"의사의 하자 유무는 대리인을 기준으로 결정한다(제116조제1항). 대리인이 적극 가담했다면 본인이 몰랐어도 반사회질서다."}],"개념":[{"종류":"표","제목":"반사회질서 법률행위 판례 정리","머리":["쟁점","내용"],"행":[["판단 시점","법률행위 당시"],["무효 주장권자","주장할 이익이 있는 자 누구든지"],["동기","상대방에게 표시되거나 알려진 동기가 반사회적이면 무효"],["대리인의 가담","본인이 몰랐어도 반사회질서"],["선의 제3자","보호 규정 없음"],["불법원인급여","급부한 것의 반환을 청구하지 못함(제746조)"]]}],"함정":"본인이 선의라는 사정에 끌려 반사회질서가 아니라고 고르기 쉽다. 의사 하자의 유무는 대리인을 표준으로 정하는 것이 원칙이다."},"30회-1차-042":{"한줄":"증여를 매매로 가장하면 가장된 매매만 무효이고 은닉된 증여는 유효하므로 둘 다 무효라는 3이 틀렸다.","근거":[{"법령":"민법","조문":"제108조","원문":"①상대방과 통정한 허위의 의사표시는 무효로 한다. ②전항의 의사표시의 무효는 선의의 제삼자에게 대항하지 못한다."},{"판례":"대법원 판례(허위표시의 법리)","요지":"허위표시는 상대방과 진의와 표시의 불일치에 관한 합의가 있어야 성립한다. 허위표시로 무효인 법률행위도 채권자취소권의 대상이 될 수 있고, 제3자의 범위는 새로운 법률상 이해관계를 맺었는지로 실질적으로 판단한다. 파산관재인은 파산채권자 모두가 악의가 아닌 한 선의로 다룬다."}],"선지":[{"번호":1,"판정":"옳음","설명":"진의와 표시의 불일치에 관한 상대방과의 합의가 있어야 한다(제108조제1항)."},{"번호":2,"판정":"옳음","설명":"무효인 허위표시도 채권자취소권의 대상이 될 수 있다."},{"번호":3,"판정":"틀림","설명":"가장된 매매만 무효이고 은닉된 증여는 요건을 갖추면 유효다."},{"번호":4,"판정":"옳음","설명":"새로운 법률상 이해관계를 맺었는지로 실질적으로 판단한다."},{"번호":5,"판정":"옳음","설명":"파산채권자 모두가 악의가 아닌 한 파산관재인은 선의로 취급된다."}],"개념":[{"종류":"표","제목":"통정허위표시 정리","머리":["쟁점","내용"],"행":[["성립","상대방과 진의·표시 불일치에 관한 합의"],["당사자 사이","무효"],["제3자","선의의 제3자에게 무효 대항 불가(제108조제2항)"],["제3자의 범위","허위표시를 기초로 새로운 법률상 이해관계를 맺은 자"],["파산관재인","파산채권자 모두가 악의가 아닌 한 선의로 취급"],["은닉행위","별도 요건을 갖추면 유효"],["채권자취소권","허위표시 법률행위도 대상 가능"]]}],"함정":"가장행위가 무효이니 숨은 증여도 무효로 보기 쉽다. 은닉행위는 허위표시가 아니므로 증여로서 유효 여부를 따로 판단한다."},"30회-1차-044":{"한줄":"해제의 의사표시가 담긴 내용증명우편이 반송되지 않았다면 특별한 사정이 없는 한 그 무렵 상대방에게 송달된 것으로 본다.","근거":[{"법령":"민법","조문":"제111조","원문":"① 상대방이 있는 의사표시는 상대방에게 도달한 때에 그 효력이 생긴다. ② 의사표시자가 그 통지를 발송한 후 사망하거나 제한능력자가 되어도 의사표시의 효력에 영향을 미치지 아니한다."},{"법령":"민법","조문":"제543조","원문":"①계약 또는 법률의 규정에 의하여 당사자의 일방이나 쌍방이 해지 또는 해제의 권리가 있는 때에는 그 해지 또는 해제는 상대방에 대한 의사표시로 한다. ②전항의 의사표시는 철회하지 못한다."},{"판례":"대법원 판례(내용증명우편의 도달)","요지":"내용증명우편이 발송되고 반송되지 않았다면 특별한 사정이 없는 한 그 무렵 송달되었다고 보는 것이 상당하다. 도달은 상대방이 실제로 알아야 하는 것이 아니라 알 수 있는 객관적 상태에 놓이면 충분하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"발송 후 표의자가 사망해도 효력에 영향이 없다(제111조제2항)."},{"번호":2,"판정":"틀림","설명":"실제로 알 필요는 없고 도달만으로 효력이 생긴다(제111조제1항)."},{"번호":3,"판정":"틀림","설명":"해제의 의사표시는 철회하지 못한다(제543조제2항)."},{"번호":4,"판정":"옳음","설명":"반송되지 않았다면 특별한 사정이 없는 한 그 무렵 송달된 것으로 본다."},{"번호":5,"판정":"틀림","설명":"이미 도달해 효력이 생긴 뒤의 상대방 제한능력은 효력에 영향이 없다."}],"개념":[{"종류":"표","제목":"해제의 의사표시","머리":["쟁점","내용","조문"],"행":[["방식","상대방에 대한 의사표시","제543조제1항"],["철회","불가","제543조제2항"],["효력발생","도달한 때. 알 필요 없음","제111조제1항"],["발송 후 사망·제한능력","효력에 영향 없음","제111조제2항"],["내용증명우편","반송되지 않으면 그 무렵 도달한 것으로 봄","판례"]]},{"종류":"흐름","제목":"해제 통지의 효력발생","단계":[{"이름":"발송","설명":"내용증명우편 등으로 해제 통지"},{"이름":"도달","설명":"상대방이 알 수 있는 객관적 상태에 놓인 때 효력 발생"},{"이름":"도달 이후","설명":"철회 불가(제543조제2항), 상대방의 사망·제한능력과 무관"}]}],"함정":"상대방이 실제로 내용을 알아야 효력이 생긴다고 보기 쉽다. 도달이라는 객관적 상태면 충분하고, 발송 후 당사자의 사망·제한능력은 효력에 영향이 없다."},"30회-1차-045":{"한줄":"대리권 소멸사유에 한정후견 개시는 없다.","근거":[{"법령":"민법","조문":"제127조","원문":"대리권은 다음 각 호의 어느 하나에 해당하는 사유가 있으면 소멸된다. 1. 본인의 사망 2. 대리인의 사망, 성년후견의 개시 또는 파산"},{"법령":"민법","조문":"제124조","원문":"대리인은 본인의 허락이 없으면 본인을 위하여 자기와 법률행위를 하거나 동일한 법률행위에 관하여 당사자쌍방을 대리하지 못한다. 그러나 채무의 이행은 할 수 있다."},{"법령":"민법","조문":"제128조","원문":"법률행위에 의하여 수여된 대리권은 전조의 경우외에 그 원인된 법률관계의 종료에 의하여 소멸한다. 법률관계의 종료전에 본인이 수권행위를 철회한 경우에도 같다."}],"선지":[{"번호":1,"판정":"틀림","설명":"한정후견개시는 제127조에 열거되지 않아 대리권이 소멸하지 않는다. 성년후견 개시만 소멸사유다."},{"번호":2,"판정":"옳음","설명":"본인이 허락하면 자기계약을 할 수 있다(제124조)."},{"번호":3,"판정":"옳음","설명":"특별한 사정이 없으면 본인은 수권행위를 철회할 수 있다(제128조)."},{"번호":4,"판정":"옳음","설명":"수권행위는 불요식행위이고 묵시적으로도 가능하다."},{"번호":5,"판정":"옳음","설명":"매매 대리인은 잔금을 수령할 권한이 있다."}],"개념":[{"종류":"표","제목":"대리권 소멸사유(제127조)","머리":["사유","본인","대리인"],"행":[["사망","소멸","소멸"],["성년후견 개시","해당 없음(제127조에 없음)","소멸"],["파산","해당 없음(제127조에 없음)","소멸"],["한정후견 개시","소멸 아님","소멸 아님"]]},{"종류":"흐름","제목":"임의대리권의 소멸","단계":[{"이름":"제127조","설명":"본인 사망, 대리인 사망·성년후견 개시·파산"},{"이름":"제128조 전단","설명":"원인된 법률관계 종료"},{"이름":"제128조 후단","설명":"법률관계 종료 전 본인의 수권행위 철회"}]}],"함정":"성년후견과 한정후견을 같이 보고 소멸사유로 고르기 쉽다. 제127조는 성년후견만 적는다."},"30회-1차-046":{"한줄":"임의대리인이 본인의 승낙으로 복대리인을 선임해도 본인에 대한 선임·감독 책임이 있다.","근거":[{"법령":"민법","조문":"제121조제1항","원문":"전조의 규정에 의하여 대리인이 복대리인을 선임한 때에는 본인에게 대하여 그 선임감독에 관한 책임이 있다."},{"법령":"민법","조문":"제122조","원문":"법정대리인은 그 책임으로 복대리인을 선임할 수 있다. 그러나 부득이한 사유로 인한 때에는 전조제1항에 정한 책임만이 있다."},{"법령":"민법","조문":"제123조제1항","원문":"복대리인은 그 권한내에서 본인을 대리한다."},{"판례":"대법원 판례(복대리와 표현대리)","요지":"대리인이 사망하면 복대리권도 소멸한다. 복대리인의 대리행위에도 표현대리 규정이 적용될 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"복대리인은 본인의 대리인이다(제123조)."},{"번호":2,"판정":"틀림","설명":"본인의 승낙이 있어도 선임감독 책임은 면하지 않는다(제121조제1항)."},{"번호":3,"판정":"옳음","설명":"대리인이 사망하면 복대리권도 소멸한다(판례)."},{"번호":4,"판정":"옳음","설명":"복대리인의 행위에도 표현대리가 적용된다(판례)."},{"번호":5,"판정":"옳음","설명":"법정대리인은 부득이한 사유 없이도 복대리인을 선임할 수 있다(제122조 본문)."}],"개념":[{"종류":"표","제목":"복대리인 선임 책임","머리":["선임 주체","선임 요건","책임"],"행":[["임의대리인","본인 승낙 또는 부득이한 사유","선임감독 책임(제121조제1항)"],["임의대리인(본인 지명)","본인 지명","부적임·불성실을 알고 통지·해임을 게을리한 때만(제121조제2항)"],["법정대리인","자유","전반 책임, 부득이한 사유면 선임감독 책임만(제122조)"]]}],"함정":"본인이 승낙했으니 책임이 없다고 판단하기 쉽다. 책임이 줄어드는 경우는 본인이 지명한 때(제121조제2항)와 법정대리인의 부득이한 사유(제122조 단서)다."},"30회-1차-047":{"한줄":"최고권은 상대방의 선의·악의와 관계없이 인정된다.","근거":[{"법령":"민법","조문":"제131조","원문":"상대방은 상당한 기간을 정하여 본인에게 그 추인여부의 확답을 최고할 수 있다. 본인이 그 기간내에 확답을 발하지 아니한 때에는 추인을 거절한 것으로 본다."},{"법령":"민법","조문":"제130조","원문":"대리권없는 자가 타인의 대리인으로 한 계약은 본인이 이를 추인하지 아니하면 본인에 대하여 효력이 없다."},{"법령":"민법","조문":"제133조","원문":"추인은 다른 의사표시가 없는 때에는 계약시에 소급하여 그 효력이 생긴다. 그러나 제삼자의 권리를 해하지 못한다."},{"판례":"대법원 판례(묵시적 추인·변경 추인)","요지":"추인은 묵시적으로도 할 수 있다. 본인이 계약 내용을 바꾸어 추인하면 상대방의 동의가 없는 한 효력이 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"추인이 없으면 본인에게 효력이 없다(제130조)."},{"번호":2,"판정":"옳음","설명":"묵시적 추인이 가능하다(판례)."},{"번호":3,"판정":"틀림","설명":"최고권은 악의 상대방에게도 인정된다(제131조는 선의를 요구하지 않는다). 철회권은 선의여야 한다(제134조 단서)."},{"번호":4,"판정":"옳음","설명":"변경을 가한 추인은 상대방 동의가 없으면 무효다(판례)."},{"번호":5,"판정":"옳음","설명":"추인은 계약시에 소급한다(제133조)."}],"개념":[{"종류":"표","제목":"상대방의 권리 요건","머리":["권리","선의 필요","근거"],"행":[["최고권","불요","제131조"],["철회권","필요","제134조"],["무권대리인 책임 추궁","선의·무과실","제135조제2항"]]},{"종류":"흐름","제목":"추인의 효과","단계":[{"이름":"추인","설명":"본인이 상대방 또는 무권대리인에게 의사표시(제132조)"},{"이름":"효력","설명":"계약시에 소급(제133조 본문)"},{"이름":"제한","설명":"제3자의 권리를 해하지 못함(제133조 단서)"}]}],"함정":"철회권이 선의 상대방에게만 있다는 규정을 최고권에 그대로 옮기기 쉽다. 두 규정은 요건이 다르다."},"30회-1차-048":{"한줄":"ㄱ은 각자대리 원칙(제119조), ㄴ은 보존행위만이 아니라 이용·개량도 가능(제118조), ㄷ은 유권대리 주장에 표현대리 주장이 포함되지 않는다는 판례에 어긋나 셋 모두 틀리다.","근거":[{"법령":"민법","조문":"제119조","원문":"대리인이 수인인 때에는 각자가 본인을 대리한다. 그러나 법률 또는 수권행위에 다른 정한 바가 있는 때에는 그러하지 아니하다."},{"법령":"민법","조문":"제118조","원문":"권한을 정하지 아니한 대리인은 다음 각호의 행위만을 할 수 있다. 1. 보존행위 2. 대리의 목적인 물건이나 권리의 성질을 변하지 아니하는 범위에서 그 이용 또는 개량하는 행위"},{"판례":"대법원 판례(유권대리와 표현대리 주장)","요지":"유권대리의 주장 속에는 표현대리의 주장이 포함되어 있지 않다. 두 주장은 서로 별개의 요건사실이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ만으로는 부족하다. ㄴ·ㄷ도 틀리다."},{"번호":2,"판정":"틀림","설명":"ㄴ만으로는 부족하다."},{"번호":3,"판정":"틀림","설명":"ㄴ도 틀리다."},{"번호":4,"판정":"틀림","설명":"ㄱ도 틀리다."},{"번호":5,"판정":"옳음","설명":"ㄱ·ㄴ·ㄷ 모두 틀린 설명이다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"각자대리가 원칙이다."},{"기호":"ㄴ","판정":"틀림","설명":"이용·개량도 가능하다."},{"기호":"ㄷ","판정":"틀림","설명":"표현대리 주장이 유권대리 주장에 포함되지 않는다."}],"개념":[{"종류":"표","제목":"대리인 권한 정리","머리":["항목","내용","근거"],"행":[["수인의 대리인","각자대리(수권행위로 공동대리 가능)","제119조"],["권한 미정 대리인","보존·이용·개량","제118조"],["유권대리와 표현대리","주장이 별개","판례"],["복대리 선임","임의대리: 승낙 또는 부득이","제120조"]]}],"함정":"ㄴ은 '보존행위만'이라는 단서에 속기 쉽다. 권한 미정 대리인은 보존행위에 더해 물건·권리의 성질을 바꾸지 않는 이용·개량행위를 할 수 있다."},"30회-1차-049":{"한줄":"법정추인의 이행청구는 취소권자가 상대방에게 하는 경우다. 상대방이 취소권자에게 이행을 청구하는 것은 법정추인 사유가 아니다.","근거":[{"법령":"민법","조문":"제145조","원문":"제145조(법정추인) 취소할 수 있는 법률행위에 관하여 전조의 규정에 의하여 추인할 수 있는 후에 다음 각호의 사유가 있으면 추인한 것으로 본다. 그러나 이의를 보류한 때에는 그러하지 아니하다.\n1. 전부나 일부의 이행\n2. 이행의 청구\n3. 경개\n4. 담보의 제공\n5. 취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도\n6. 강제집행"}],"선지":[{"번호":1,"판정":"옳음","설명":"전부나 일부의 이행은 법정추인 사유다(제145조제1호)."},{"번호":2,"판정":"옳음","설명":"담보의 제공은 법정추인 사유다(제145조제4호)."},{"번호":3,"판정":"틀림","설명":"이행의 청구(제145조제2호)는 취소권자가 하는 청구다. 상대방이 취소권자에게 청구하는 것은 해당하지 않는다."},{"번호":4,"판정":"옳음","설명":"취소할 수 있는 행위로 취득한 권리를 양도하면 법정추인이다(제145조제5호)."},{"번호":5,"판정":"옳음","설명":"경개는 법정추인 사유다(제145조제3호)."}],"개념":[{"종류":"표","제목":"법정추인 6사유","머리":["호","사유","비고"],"행":[["1","전부나 일부의 이행","취소권자가 이행하는 경우"],["2","이행의 청구","취소권자가 청구하는 경우, 상대방의 청구는 제외"],["3","경개","-"],["4","담보의 제공","-"],["5","취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도","-"],["6","강제집행","-"]]},{"종류":"표","제목":"법정추인 성립 요건","머리":["요건","내용"],"행":[["시기","추인할 수 있는 후(취소 원인 소멸 후)"],["사유","제145조 각 호의 어느 하나"],["이의 보류","이의를 보류하지 않았을 것"]]}],"함정":"이행의 청구가 있으면 모두 법정추인이 된다고 외우기 쉽다. 청구하는 쪽이 취소권자일 때만 추인으로 본다. 상대방이 청구했다고 취소권자가 추인한 것은 아니다."},"30회-1차-050":{"한줄":"토지거래허가를 받지 않은 乙·丙 사이 전매는 효력이 없고, 丙이 甲과 직접 계약당사자로 허가를 받았다는 사정만으로 甲으로부터 곧바로 한 이전등기가 유효해지지 않는다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제11조제6항","원문":"⑥ 제1항에 따른 허가를 받지 아니하고 체결한 토지거래계약은 그 효력이 발생하지 아니한다."},{"판례":"대법원 1991. 12. 24. 선고 90다12243 전원합의체 판결","요지":"허가구역 내 토지거래계약은 허가를 받기 전에는 효력이 발생하지 않는 유동적 무효 상태이고, 허가를 받으면 소급해 유효, 불허가나 허가 배제 목적이면 확정적 무효가 된다. 유동적 무효 상태에서는 이행청구나 채무불이행을 이유로 한 해제는 할 수 없고, 허가신청에 협력할 의무는 서로 청구할 수 있다."},{"판례":"대법원 판례(허가구역 지정 해제·기간 만료)","요지":"허가구역 지정이 해제되거나 지정기간이 만료된 후 재지정이 없으면 유동적 무효였던 계약은 확정적으로 유효가 된다."},{"판례":"대법원 판례(전매와 중간생략등기)","요지":"허가구역 내 토지의 전매에서 최초 매도인과 최종 매수인 사이에 중간생략등기 합의가 없으면 허가 없는 전매계약은 효력이 없고, 최종 매수인이 최초 매도인과 직접 허가를 받아 한 이전등기도 유효하지 않다."}],"선지":[{"번호":1,"판정":"옳음","설명":"허가 전 계약은 효력이 발생하지 않는 유동적 무효 상태다(거래신고법 제11조제6항, 판례)."},{"번호":2,"판정":"옳음","설명":"유동적 무효 상태에서는 상대방의 채무불이행을 이유로 계약을 해제할 수 없다(판례)."},{"번호":3,"판정":"옳음","설명":"허가신청 협력의무는 대금 이행제공과 동시이행 관계가 아니라 이행제공이 없다는 이유로 거절할 수 없다(판례)."},{"번호":4,"판정":"옳음","설명":"지정기간이 만료되었는데 재지정이 없으면 계약은 확정적으로 유효가 된다(판례)."},{"번호":5,"판정":"틀림","설명":"허가구역에서 최종 매수인 丙과 최초 매도인 甲을 당사자로 받은 허가는 실제 거래와 다른 허가라 무효이고, 그에 기한 이전등기도 무효다. 중간생략등기 합의가 있어도 결론은 같다(판례)."}],"개념":[{"종류":"표","제목":"유동적 무효 상태의 법률관계","머리":["쟁점","내용"],"행":[["채권적 효력","허가 전에는 이행청구 불가"],["허가신청 협력의무","서로 소로 청구할 수 있음"],["채무불이행 해제","불가"],["허가를 받은 경우","계약 시로 소급해 확정적 유효"],["불허가·허가 배제 목적","확정적 무효"],["지정 해제·기간 만료 후 재지정 없음","확정적 유효"]]},{"종류":"흐름","제목":"허가 전후 전개","단계":[{"이름":"계약 체결","설명":"허가를 받지 않고 체결하면 효력 불발생(제11조제6항)"},{"이름":"허가 신청","설명":"허가신청서 제출(제11조제3항), 처리기간 내 통지가 없으면 허가 간주(제11조제5항)"},{"이름":"결과","설명":"허가면 확정적 유효, 불허가면 확정적 무효, 지정 해제나 기간 만료 후 재지정이 없으면 확정적 유효"}]}],"함정":"허가를 받았으니 등기도 유효하다고 보기 쉽다. 허가구역에서 중간 매수인을 건너뛴 허가와 등기는 중간생략등기 합의가 있어도 무효다. 2번은 매수인이 이행하지 않아도 해제할 수 없다는 점에서 옳다."},"30회-1차-043":{"한줄":"법률행위 당시 이미 성취할 수 없는 조건이 정지조건이면 그 법률행위는 무효다(제151조제3항).","근거":[{"법령":"민법","조문":"제151조제3항","원문":"조건이 법률행위의 당시에 이미 성취할 수 없는 것인 경우에는 그 조건이 해제조건이면 조건없는 법률행위로 하고 정지조건이면 그 법률행위는 무효로 한다."},{"법령":"민법","조문":"제147조제2항","원문":"해제조건있는 법률행위는 조건이 성취한 때로부터 그 효력을 잃는다."},{"법령":"민법","조문":"제493조제1항","원문":"상계는 상대방에 대한 의사표시로 한다. 이 의사표시에는 조건 또는 기한을 붙이지 못한다."},{"판례":"대법원 판례(기한이익 상실특약)","요지":"기한이익 상실특약은 특별한 사정이 없으면 채권자의 청구 등 의사표시가 있어야 상실하는 형성권적 기한이익 상실특약으로 추정한다. 사유 발생으로 당연히 상실하는 정지조건부 특약은 그렇게 약정한 때에 한한다."},{"판례":"대법원 판례(불확정기한)","요지":"불확정한 사실이 발생한 때를 이행기한으로 정한 경우 그 사실의 발생이 불가능하게 된 때에도 이행기한은 도래한 것으로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"해제조건 있는 법률행위는 조건이 성취한 때부터 효력을 잃는다(제147조제2항)."},{"번호":2,"판정":"틀림","설명":"특별한 사정이 없으면 형성권적 기한이익 상실특약으로 추정한다. 정지조건부로 추정하지 않는다."},{"번호":3,"판정":"옳음","설명":"이미 성취할 수 없는 조건이 정지조건이면 무효다(제151조제3항)."},{"번호":4,"판정":"틀림","설명":"불확정기한은 사실 발생이 불가능하게 된 때에도 이행기한이 도래한 것으로 본다."},{"번호":5,"판정":"틀림","설명":"상계의 의사표시에는 조건·기한을 붙이지 못한다(제493조제1항)."}],"개념":[{"종류":"비교","제목":"기한이익 상실특약의 두 유형","왼쪽":{"이름":"정지조건부 특약","항목":["상실사유 발생 시 곧바로 상실","채권자의 청구 불필요","특약으로 명시해야 인정"]},"오른쪽":{"이름":"형성권적 특약","항목":["상실사유 발생 후 채권자가 청구·통지해야 상실","특별한 사정이 없으면 이쪽으로 추정","채권자가 청구하기 전에는 이행기 미도래"]}},{"종류":"표","제목":"기한의 종류와 도래","머리":["구분","도래 시기","비고"],"행":[["확정기한","정해진 날짜가 오는 때","시기·종기 모두 가능"],["불확정기한","사실이 발생한 때, 또는 발생이 불가능하게 확정된 때","판례"],["조건과 구별","사실 발생이 불가능하게 되면 조건은 불성취 확정","기한은 도래로 처리"],["기한의 이익 포기","가능하나 상대방 이익을 해하지 못함","제153조제2항"]]}],"함정":"선지 2·4는 판례 문장 앞뒤를 바꿔 놓은 것이다. 기한이익 상실특약은 형성권적으로 추정하고, 불확정기한은 발생 불능이 확정돼도 도래한 것으로 본다. 조건과 기한에서 불능 확정의 처리가 정반대라는 점이 쟁점이다."},"30회-1차-051":{"한줄":"임차인은 임대차 보전을 위해 채권자대위권으로 임대인의 소유권에 기한 물권적 청구권을 대위행사할 수 있다.","근거":[{"법령":"민법","조문":"제404조제1항","원문":"채권자는 자기의 채권을 보전하기 위하여 채무자의 권리를 행사할 수 있다. 그러나 일신에 전속한 권리는 그러하지 아니하다."},{"법령":"민법","조문":"제162조제2항","원문":"채권 및 소유권 이외의 재산권은 20년간 행사하지 아니하면 소멸시효가 완성한다."},{"법령":"민법","조문":"제192조제1항","원문":"물건을 사실상 지배하는 자는 점유권이 있다."},{"법령":"민법","조문":"제320조제1항","원문":"타인의 물건 또는 유가증권을 점유한 자는 그 물건이나 유가증권에 관하여 생긴 채권이 변제기에 있는 경우에는 변제를 받을 때까지 그 물건 또는 유가증권을 유치할 권리가 있다."},{"판례":"대법원 판례(소유권 기한 청구권과 소멸시효)","요지":"소유권은 소멸시효에 걸리지 않으므로 소유권에 기한 물권적 청구권도 소멸시효로 소멸하지 않는다."},{"판례":"대법원 판례(임차인의 대위행사)","요지":"임차인은 임대인의 소유권에 기한 방해배제청구권을 채권자대위권(제404조)에 의해 대위행사할 수 있다."},{"판례":"대법원 판례(방해와 손해)","요지":"방해는 현재 계속되는 침해 상태이고, 손해는 이미 입은 불이익이다. 개념상 구별된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"소멸시효 대상은 채권과 소유권 이외의 재산권이다(제162조). 소유권은 시효로 소멸하지 않고 그에 기한 청구권도 같다."},{"번호":2,"판정":"옳음","설명":"상대방의 귀책사유는 요건이 아니다."},{"번호":3,"판정":"옳음","설명":"방해는 현재 계속되는 침해 상태이고 손해와 구별된다."},{"번호":4,"판정":"틀림","설명":"임차인은 채권자대위권으로 임대인의 소유권에 기한 청구권을 행사할 수 있다(제404조제1항). 이 선지가 정답이다."},{"번호":5,"판정":"옳음","설명":"유치권자는 유치물을 점유하므로 점유권에 기한 청구권을 행사할 수 있다(제192조제1항, 제204조~제206조)."}],"개념":[{"종류":"비교","제목":"소유권에 기한 청구권과 점유보호청구권","왼쪽":{"이름":"소유권에 기한 물권적 청구권(제213조·제214조)","항목":["소유자가 행사","귀책사유 불요","행사기간 제한 없음, 시효 소멸 안 함","임차인이 대위행사 가능"]},"오른쪽":{"이름":"점유보호청구권(제204조~제206조)","항목":["점유자가 행사(유치권자 포함)","점유회수는 침탈일부터 1년","점유보유는 방해 종료일부터 1년","점유 물건에 대한 사실상 지배가 근거"]}},{"종류":"표","제목":"물권적 청구권을 행사하는 사람","머리":["행사자","근거","비고"],"행":[["소유자","제213조·제214조","본래 청구권자"],["지상권자·전세권자","제290조·제319조(제213조·제214조 준용)","용익물권자"],["저당권자","제370조(제214조 준용)","방해제거·예방만, 반환청구는 준용 안 함"],["점유자(유치권자 포함)","제204조~제206조","점유권에 기한 청구"],["임차인","제404조 채권자대위","임대인의 청구권 대위행사"]]}],"함정":"대위행사는 채권자가 자기 채권을 보전하기 위해 채무자의 권리를 행사하는 제도이므로 임차인에게도 열려 있다. 임차인은 물권자가 아니니 대위행사도 안 된다고 보는 오답이 선지 4다. 선지 5는 유치권이 물권이어서 점유권과 무관하다고 보면 틀린 판단이 된다."},"30회-1차-052":{"한줄":"제187조의 판결은 형성판결만 뜻하고 이행판결은 포함하지 않으므로 2번이 틀렸다.","근거":[{"법령":"민법","조문":"제187조","원문":"상속, 공용징수, 판결, 경매 기타 법률의 규정에 의한 부동산에 관한 물권의 취득은 등기를 요하지 아니한다. 그러나 등기를 하지 아니하면 이를 처분하지 못한다."},{"법령":"민법","조문":"제186조","원문":"부동산에 관한 법률행위로 인한 물권의 득실변경은 등기하여야 그 효력이 생긴다."},{"판례":"대법원 판례","요지":"제187조의 판결은 형성판결을 가리키며 이행판결·확인판결은 포함하지 않는다."},{"판례":"대법원 판례","요지":"가등기에 기한 본등기가 되면 물권변동의 효력은 본등기를 한 때 생긴다."}],"선지":[{"번호":1,"판정":"옳음","설명":"물권변동 후 등기가 원인 없이 말소돼도 물권변동의 효력은 그대로다."},{"번호":2,"판정":"틀림","설명":"제187조의 판결은 공유물분할 판결 같은 형성판결이다. 이행판결이면 등기해야 물권이 변동한다(제186조)."},{"번호":3,"판정":"옳음","설명":"가등기는 순위보전 효력만 있고 물권변동은 본등기 때 생긴다는 판례다."},{"번호":4,"판정":"옳음","설명":"미등기 매수인의 매수인은 중간생략 합의가 없는 한 최초 매도인에게 직접 등기를 청구할 수 없다."},{"번호":5,"판정":"옳음","설명":"경매로 성립한 관습상 법정지상권도 법률행위로 양도하려면 등기가 필요하다(제187조 단서)."}],"개념":[{"종류":"표","제목":"등기 없이 물권을 취득하는 경우와 처분 요건","머리":["원인","등기 없이 취득","시기"],"행":[["상속","○","상속 개시 때"],["공용징수","○","수용 시기"],["판결(형성판결)","○","판결 확정 때"],["경매","○","매각대금 완납 때(민사집행법 제135조)"],["이행판결·화해조서","×","등기 때"]]},{"종류":"비교","제목":"제186조와 제187조","왼쪽":{"이름":"법률행위(제186조)","항목":["등기해야 효력","매매·증여·설정"]},"오른쪽":{"이름":"법률 규정(제187조)","항목":["등기 없이 취득","처분하려면 등기 필요"]}}],"함정":"판결이면 모두 등기가 필요 없다고 넓게 읽기 쉽다. 이행판결은 등기를 해야 효력이 생긴다."},"30회-1차-053":{"한줄":"ㄱ(사망자 명의 신청 등기)과 ㄴ(대리권 존재)만 옳아서 정답은 1번이다.","근거":[{"판례":"대법원 판례","요지":"사망자 명의로 신청해 이루어진 이전등기는 특별한 사정이 없는 한 추정력이 인정되지 않는다."},{"판례":"대법원 판례","요지":"대리인에 의한 매매를 원인으로 이전등기가 된 경우 대리권의 존재가 추정된다."},{"판례":"대법원 판례","요지":"보존등기 명의자가 전 소유자에게서 양수했다고 주장하는데 전 소유자가 양도를 부인하면 보존등기의 추정력은 깨진다."}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ·ㄴ이 옳은 조합이다."},{"번호":2,"판정":"틀림","설명":"ㄷ이 틀려서 맞는 조합이 아니다."},{"번호":3,"판정":"틀림","설명":"ㄷ이 틀렸다."},{"번호":4,"판정":"틀림","설명":"ㄹ이 틀렸다."},{"번호":5,"판정":"틀림","설명":"ㄷ·ㄹ이 모두 틀렸다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"사망자 명의로 신청한 등기는 특별한 사정이 없는 한 추정력이 없다."},{"기호":"ㄴ","판정":"옳음","설명":"대리에 의한 매매로 이전등기가 된 경우 대리권 존재가 추정된다."},{"기호":"ㄷ","판정":"틀림","설명":"근저당권등기는 피담보채권의 존재를 추정할 뿐, 그 채권을 성립시킨 기본계약까지 추정하지 않는다."},{"기호":"ㄹ","판정":"틀림","설명":"전 소유자가 양도 사실을 부인하면 보존등기의 추정력은 깨진다."}],"개념":[{"종류":"표","제목":"등기 추정력 정리","머리":["사례","추정력"],"행":[["사망자 명의 신청 이전등기","없음"],["대리 매매 이전등기","대리권 존재 추정"],["원인 없는 말소","권리소멸 추정 없음"],["보존등기 명의자의 양수 주장, 전 소유자 부인","추정 깨짐"],["계약서가 진정하지 않다고 증명","적법 추정 깨짐"]]}],"함정":"추정력을 넓게 보아 ㄷ(기본계약 존재까지)이나 ㄹ(전 소유자 부인에도 유지)을 옳게 읽기 쉽다."},"30회-1차-056":{"한줄":"점유취득시효 완성으로 생긴 소유권이전등기청구권은 채권이므로 통상의 채권양도 법리로 양도할 수 있다.","근거":[{"법령":"민법","조문":"제449조제1항","원문":"채권은 양도할 수 있다. 그러나 채권의 성질이 양도를 허용하지 아니하는 때에는 그러하지 아니하다."},{"판례":"대법원 판례","요지":"점유취득시효 완성에 따른 소유권이전등기청구권은 채권양도의 법리에 따라 양도할 수 있고, 양도에 소유자의 동의나 승낙은 필요하지 않다."},{"판례":"대법원 판례","요지":"부동산 매수인이 목적물을 인도받아 사용·수익하는 동안에는 소유권이전등기청구권의 소멸시효가 진행하지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"시효취득에 따른 이전등기청구권은 채권적 청구권이고 통상의 채권양도 법리로 양도된다(제449조제1항)."},{"번호":2,"판정":"틀림","설명":"인도받아 사용·수익하는 매수인의 등기청구권은 소멸시효에 걸리지 않는다."},{"번호":3,"판정":"틀림","설명":"매수인의 이전등기청구권은 매매계약에 기한 채권적 청구권이다."},{"번호":4,"판정":"틀림","설명":"가등기 청구권이 시효로 소멸한 뒤 제3취득자가 가등기권자에게 갖는 말소청구권은 소유권에 기한 물권적 청구권이다."},{"번호":5,"판정":"틀림","설명":"등기청구권은 사법상 권리이고, 등기신청권은 국가에 대한 공법상 권리다. 내용이 다르다."}],"개념":[{"종류":"비교","제목":"등기청구권과 등기신청권","왼쪽":{"이름":"등기청구권","항목":["사법상 권리","상대방(등기의무자)에게 등기 협력 요구","채권적(매매)·물권적(소유권 기초) 구분"]},"오른쪽":{"이름":"등기신청권","항목":["공법상 권리","국가(등기소)에 등기를 신청하는 권리","당사자 공동신청이 원칙"]}},{"종류":"표","제목":"등기청구권 유형","머리":["유형","성격","소멸시효"],"행":[["매매에 기한","채권적","인도받아 사용·수익 중이면 진행 안 함"],["점유취득시효 완성","채권적","양도 가능(동의 불요)"],["소유권에 기한 말소청구","물권적","소유권과 별개로 소멸하지 않음"],["중간생략 합의에 기한","채권적","3자 합의 필요"]]}],"함정":"등기청구권은 모두 물권적 청구권으로 오해하기 쉽다. 매매·시효취득에 기한 이전등기청구권은 채권적이다."},"30회-1차-054":{"한줄":"간접점유자도 점유보호청구권을 행사할 수 있으므로 4번이 틀렸다.","근거":[{"법령":"민법","조문":"제207조제1항","원문":"전3조의 청구권은 제194조의 규정에 의한 간접점유자도 이를 행사할 수 있다."},{"법령":"민법","조문":"제194조","원문":"지상권, 전세권, 질권, 사용대차, 임대차, 임치 기타의 관계로 타인으로 하여금 물건을 점유하게 한 자는 간접으로 점유권이 있다."},{"판례":"대법원 판례","요지":"취득시효의 기초가 되는 점유에는 간접점유도 포함된다. 점유매개관계의 기초 법률행위가 무효여도 간접점유는 인정될 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"주택임대차보호법상 인도는 임차인의 간접점유 취득으로도 충족될 수 있다는 판례다."},{"번호":2,"판정":"옳음","설명":"시효취득의 점유에는 간접점유도 포함된다."},{"번호":3,"판정":"옳음","설명":"직접점유자가 임의로 점유를 넘기면 간접점유자 의사에 반해도 침탈이 아니다."},{"번호":4,"판정":"틀림","설명":"간접점유자도 점유회수·보유·보전 청구를 할 수 있다(제207조제1항)."},{"번호":5,"판정":"옳음","설명":"점유매개관계를 만든 법률행위가 무효여도 간접점유는 인정될 수 있다."}],"개념":[{"종류":"표","제목":"간접점유자의 점유보호","머리":["상황","청구 내용","근거"],"행":[["일반 방해·침탈","점유회수·보유·보전 청구","제207조제1항"],["직접점유자가 침탈당함","물건을 점유자에게 반환 청구","제207조제2항"],["점유자가 반환 불가·거부","자기에게 반환 청구","제207조제2항"],["직접점유자가 임의 양도","침탈 아님","판례"]]}],"함정":"점유보호청구권은 직접 점유하는 사람의 권리라고 읽기 쉽다. 간접점유자도 행사할 수 있다."},"30회-1차-055":{"한줄":"집합건물의 공용부분은 전유부분과 떨어져 따로 처분할 수 없으므로 별도로 시효취득할 수 없다.","근거":[{"법령":"민법","조문":"제197조제1항","원문":"①점유자는 소유의 의사로 선의, 평온 및 공연하게 점유한 것으로 추정한다."},{"법령":"민법","조문":"제245조제1항","원문":"①20년간 소유의 의사로 평온, 공연하게 부동산을 점유하는 자는 등기함으로써 그 소유권을 취득한다."},{"법령":"민법","조문":"제247조제2항","원문":"②소멸시효의 중단에 관한 규정은 전2조의 소유권취득기간에 준용한다."},{"판례":"대법원 1997. 8. 21. 선고 95다28625 전원합의체","요지":"점유자가 소유자의 승낙 없이 남의 부동산임을 알면서 점유한 사실(악의의 무단점유)이 증명되면 자주점유의 추정은 깨진다."},{"판례":"대법원 판례(공용부분)","요지":"집합건물의 공용부분은 전유부분과 분리해 처분할 수 없어 공용부분만 따로 취득시효로 소유권을 얻을 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"악의의 무단점유가 증명되면 소유의 의사가 없는 점유로 보아 자주점유 추정이 깨진다(제197조제1항, 95다28625 전원합의체)."},{"번호":2,"판정":"옳음","설명":"공용부분은 전유부분의 처분에 따르고 따로 처분할 수 없어 별도의 시효취득 대상이 아니다(판례, 집합건물법 제13조)."},{"번호":3,"판정":"틀림","설명":"1필 토지의 일부라도 다른 부분과 구분되는 경계 표지가 계속 있고 그 부분을 점유했다면 시효취득할 수 있다(판례)."},{"번호":4,"판정":"틀림","설명":"시효완성 전에 설정된 가등기에 기해 완성 후 본등기를 마치면 본등기 순위가 가등기 때로 올라가므로, 그 본등기 명의자에게 시효완성을 주장할 수 없다(판례)."},{"번호":5,"판정":"틀림","설명":"압류·가압류는 점유를 빼앗거나 점유 상태를 바꾸지 않으므로 점유취득시효를 중단시키지 못한다(판례). 제247조제2항의 준용은 시효 진행을 실제로 막는 사유에 한한다."}],"개념":[{"종류":"표","제목":"점유취득시효 판례 정리","머리":["쟁점","판례 결론"],"행":[["악의의 무단점유","자주점유 추정 깨짐"],["1필 토지 일부","경계 표지가 있으면 가능"],["집합건물 공용부분","별도 시효취득 불가"],["완성 전 가등기 → 완성 후 본등기","본등기자에게 대항 못함"],["압류·가압류","점유취득시효 중단사유 아님"],["완성 후 소유자 변경(새 등기)","새 소유자에게 대항 못함, 그때부터 다시 20년이면 가능"]]}],"함정":"제197조의 자주점유 추정만 떠올려 1번을 고르기 쉽다. 추정은 반증으로 깨지고, 악의의 무단점유 증명이 그 반증이다. 5번은 제168조 압류·가압류를 그대로 옮겨 오기 쉬운 자리다."},"30회-1차-057":{"한줄":"건축 자재처럼 건물에 사용되어 분리가 어려운 물건은 소유권유보 약정이나 제3자의 악의와 관계없이 건물에 부합한다.","근거":[{"법령":"민법","조문":"제256조","원문":"부동산의 소유자는 그 부동산에 부합한 물건의 소유권을 취득한다. 그러나 타인의 권원에 의하여 부속된 것은 그러하지 아니하다."},{"법령":"민법","조문":"제261조","원문":"전5조의 경우에 손해를 받은 자는 부당이득에 관한 규정에 의하여 보상을 청구할 수 있다."},{"판례":"대법원 판례(소유권유보 자재의 부합)","요지":"매도인이 소유권을 유보한 자재라도 건물에 사용되어 훼손 없이 분리할 수 없게 되면 건물에 부합한다. 소유권을 잃은 사람은 부당이득 규정으로 보상을 구한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"부동산 사이에도 부합이 인정될 수 있다(판례)."},{"번호":2,"판정":"옳음","설명":"부합물의 가격이 부동산 가격을 넘어도 부합물의 소유권은 부동산 소유자에게 귀속된다(제256조 본문, 판례)."},{"번호":3,"판정":"옳음","설명":"부합으로 소유권을 잃은 사람은 부당이득 규정에 따라 보상을 청구한다(제261조)."},{"번호":4,"판정":"옳음","설명":"사용차주가 사용대차에 의한 권원으로 식재한 수목은 부합하지 않고 차주 소유다(제256조 단서)."},{"번호":5,"판정":"틀림","설명":"시멘트를 건물 공사에 사용해 분리가 불가능하게 되면 제3자가 소유권유보를 알았더라도 건물에 부합한다. 악의는 부합 성립이 아니라 보상 문제에서 따진다(제256조, 제261조)."}],"개념":[{"종류":"표","제목":"부합의 요건과 효과","머리":["구분","내용","근거"],"행":[["부동산에의 부합","부동산 소유자가 부합물의 소유권 취득","제256조 본문"],["권원에 의한 부속","부속시킨 사람이 소유권 유지","제256조 단서"],["동산 간 부합","주된 동산의 소유자가 합성물 소유","제257조"],["부합물 가격이 더 큰 경우","부동산 소유자에게 귀속","판례"],["소유권을 잃은 사람","부당이득 규정에 따라 보상 청구","제261조"]]}],"함정":"5번은 제3자의 악의를 이유로 부합을 부정하는 판례가 있는 것처럼 읽히기 쉽다. 부합은 객관적 분리 가능성으로 판단한다. 4번의 사용차주 식재는 권원에 의한 부속이어서 부합이 일어나지 않는다."},"30회-1차-058":{"한줄":"개별 채권자들이 같은 기회에 하나의 근저당권을 설정받으면 그 근저당권은 준공유가 된다.","근거":[{"법령":"민법","조문":"제278조","원문":"본절의 규정은 소유권 이외의 재산권에 준용한다. 그러나 다른 법률에 특별한 규정이 있으면 그에 의한다."},{"법령":"민법","조문":"제265조","원문":"공유물의 관리에 관한 사항은 공유자의 지분의 과반수로써 결정한다. 그러나 보존행위는 각자가 할 수 있다."},{"법령":"민법","조문":"제267조","원문":"공유자가 그 지분을 포기하거나 상속인없이 사망한 때에는 그 지분은 다른 공유자에게 각 지분의 비율로 귀속한다."},{"법령":"민법","조문":"제186조","원문":"부동산에 관한 법률행위로 인한 물권의 득실변경은 등기하여야 그 효력이 생긴다."}],"선지":[{"번호":1,"판정":"틀림","설명":"임대차계약의 해지는 관리행위이므로 지분 과반수로 결정한다(제265조 본문). 보존행위가 아니다."},{"번호":2,"판정":"옳음","설명":"소유권 이외의 재산권인 근저당권은 공유 규정을 준용해 준공유한다(제278조)."},{"번호":3,"판정":"틀림","설명":"다른 공유자는 등기명의인인 공유자 지분을 제외한 나머지 지분에 대해서만 말소를 청구할 수 있다(판례)."},{"번호":4,"판정":"틀림","설명":"과반수 지분권자가 단독으로 임대한 경우 소수지분권자는 과반수 지분권자에게 자기 지분에 상응하는 부당이득의 반환을 청구할 수 있다(판례)."},{"번호":5,"판정":"틀림","설명":"부동산 공유지분의 포기는 등기해야 효력이 생긴다(제186조). 포기된 지분은 다른 공유자에게 귀속한다(제267조)."}],"개념":[{"종류":"표","제목":"공유관계에서 단독으로 할 수 있는 청구","머리":["상황","단독 가능 여부","근거"],"행":[["제3자의 불법점유 배제","각 공유자가 보존행위로 청구 가능","제265조 단서, 판례"],["제3자 명의 원인무효 등기 말소","각 공유자가 보존행위로 청구 가능","제265조 단서, 판례"],["공유자 1인 명의 원인무효 등기","그 공유자 지분을 뺀 나머지만 말소 청구","판례"],["임대차 해지","관리행위, 지분 과반수 필요","제265조 본문, 판례"],["공유지분 포기","등기해야 효력","제186조, 제267조"]]}],"함정":"1번에서 해지를 보존행위로 읽기 쉽다. 해지는 관리행위다. 3번은 원인무효 등기이니 전부 말소할 수 있을 것 같지만, 등기명의인 자신의 지분은 유효하다."},"30회-1차-059":{"한줄":"담보가치를 떨어뜨리는 건축으로 교환가치가 피담보채권액 미만이 되면 저당권자는 손해배상을 청구할 수 있다.","근거":[{"판례":"대법원 판례(담보지상권의 부종성)","요지":"저당권과 함께 설정한 담보지상권은 피담보채권이 시효 등으로 소멸하면 함께 소멸한다."},{"판례":"대법원 판례(담보지상권 침해)","요지":"저당권자는 담보가치를 해하는 행위를 한 자에게 저당권 침해를 이유로 손해배상을 청구할 수 있다."},{"판례":"대법원 판례(담보지상권의 성질)","요지":"담보 목적의 지상권은 용익권이 아닌 지상권이므로 사용·수익을 이유로 한 부당이득반환을 청구할 수 없고, 담보물권이 아니므로 피담보채무 범위확인을 구할 이익이 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"피담보채권이 소멸하면 담보지상권도 소멸한다."},{"번호":2,"판정":"틀림","설명":"지상권 침해를 이유로 한 乙의 철거 청구에 대해 丙은 乙과 甲 사이의 채권 사정을 들어 대항하지 못한다."},{"번호":3,"판정":"틀림","설명":"담보가치 유지만을 위한 지상권은 사용·수익을 목적으로 하지 않아 乙은 부당이득반환을 청구할 수 없다."},{"번호":4,"판정":"옳음","설명":"담보가치 하락은 저당권 침해여서 乙은 손해배상을 청구할 수 있다."},{"번호":5,"판정":"틀림","설명":"담보지상권은 담보물권이 아니라 지상권이고, 피담보채무 범위확인 청구는 부적법하다."}],"개념":[{"종류":"표","제목":"담보지상권","머리":["쟁점","결론"],"행":[["피담보채권 소멸","담보지상권도 소멸"],["제3자의 불법점유","무상 담보지상권자는 임료 상당 손해배상 청구 불가(특별한 사정 없으면)"],["제3자의 담보가치 훼손","저당권 침해로 손해배상 가능"],["피담보채무 범위확인","청구 부적법(담보물권 아님)"],["사용·수익을 이유로 한 부당이득","청구 불가"]]}],"함정":"지상권을 설정했으니 용익권자로서 부당이득도 구할 수 있다고 생각하기 쉽다. 담보 목적일 때에는 사용·수익권이 없다. 동시에 담보물권이라고 보아 범위확인을 구하는 것도 틀리다."},"30회-1차-060":{"한줄":"통행지역권을 시효취득하면 요역지 소유자는 승역지 소유자의 손해를 보상해야 한다.","근거":[{"법령":"민법","조문":"제295조제1항","원문":"공유자의 1인이 지역권을 취득한 때에는 다른 공유자도 이를 취득한다."},{"법령":"민법","조문":"제219조제2항","원문":"전항의 통행권자는 통행지소유자의 손해를 보상하여야 한다."},{"판례":"대법원 판례(통행지역권 시효취득의 보상)","요지":"통행지역권을 시효취득한 경우 요역지 소유자는 주위토지통행권의 경우처럼 승역지 소유자의 손해를 보상해야 한다."},{"판례":"대법원 판례(불법점유자와 시효취득)","요지":"요역지를 불법점유하는 자는 통행지역권을 시효취득할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"요역지는 1필의 토지여야 한다(통설)."},{"번호":2,"판정":"옳음","설명":"요역지 지상권자는 자기 용익권 범위 안에서 지역권을 행사할 수 있다."},{"번호":3,"판정":"옳음","설명":"공유자 1인의 취득은 다른 공유자도 취득한다(제295조제1항)."},{"번호":4,"판정":"옳음","설명":"불법점유자는 통행지역권을 시효취득할 수 없다."},{"번호":5,"판정":"틀림","설명":"시효취득한 통행지역권도 요역지 소유자가 승역지 소유자의 손해를 보상해야 한다(제219조제2항 유추)."}],"개념":[{"종류":"표","제목":"지역권 정리","머리":["쟁점","내용","근거"],"행":[["요역지·승역지","요역지는 1필, 승역지는 일부도 가능","통설"],["취득시효","계속·표현된 지역권","제294조"],["공유자 1인의 취득·시효중단","다른 공유자에게도 효력","제295조, 제296조"],["부종성","요역지 소유권 이전 시 따라 이전","제292조제1항"],["통행지역권 시효취득","승역지 손해 보상 필요","제219조제2항 유추"]]}],"함정":"시효취득이면 권리가 확정되었으니 보상이 없다고 생각하기 쉽다. 보상 의무가 따른다."},"30회-1차-061":{"한줄":"건물 전세권이 법정갱신되면 존속기간은 1년이 아니라 정함이 없는 것으로 본다(제312조제4항).","근거":[{"법령":"민법","조문":"제312조제4항","원문":"건물의 전세권설정자가 전세권의 존속기간 만료전 6월부터 1월까지 사이에 전세권자에 대하여 갱신거절의 통지 또는 조건을 변경하지 아니하면 갱신하지 아니한다는 뜻의 통지를 하지 아니한 경우에는 그 기간이 만료된 때에 전전세권과 동일한 조건으로 다시 전세권을 설정한 것으로 본다. 이 경우 전세권의 존속기간은 그 정함이 없는 것으로 본다."},{"법령":"민법","조문":"제309조","원문":"전세권자는 목적물의 현상을 유지하고 그 통상의 관리에 속한 수선을 하여야 한다."},{"법령":"민법","조문":"제317조","원문":"전세권이 소멸한 때에는 전세권설정자는 전세권자로부터 그 목적물의 인도 및 전세권설정등기의 말소등기에 필요한 서류의 교부를 받는 동시에 전세금을 반환하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"법정갱신 시 존속기간은 정함이 없는 것으로 본다(제312조제4항)."},{"번호":2,"판정":"옳음","설명":"건물 일부 전세권자는 건물 전부의 경매를 신청할 수 없다. 전세권이 미치는 부분만 경매할 수 있다(판례)."},{"번호":3,"판정":"옳음","설명":"존속기간이 만료되면 전세금반환채권은 특별한 사정이 없는 한 양도할 수 있다(판례)."},{"번호":4,"판정":"옳음","설명":"건물 소유권이 양도되면 양수인이 전세권설정자의 지위를 승계해 전세금반환의무를 진다. 乙은 甲에게 반환을 청구할 수 없다(판례)."},{"번호":5,"판정":"옳음","설명":"통상의 유지·수선은 전세권자의 의무라 통상필요비는 청구하지 못한다(제309조)."}],"개념":[{"종류":"표","제목":"전세권 존속 중과 소멸 후의 관계","머리":["쟁점","내용"],"행":[["법정갱신 후 기간","정함이 없는 것(제312조제4항)"],["전세금반환채권 양도","존속 중 확정 양도 불가, 만료 후에는 가능"],["건물 소유권 양도","양수인이 설정자 지위 승계, 전세금반환의무도 승계"],["통상필요비","전세권자 부담(제309조)"],["유익비","가액 증가가 현존할 때 소유자 선택에 따라 지출액 또는 증가액 상환(제310조)"]]}],"함정":"1번에서 법정갱신 기간을 1년으로 단정하기 쉽다. 건물 전세권의 최단기간 1년 규정(제312조제2항)과 법정갱신 후 기간을 섞어 읽으면 틀린다."},"30회-1차-062":{"한줄":"점유가 직접점유인지 간접점유인지는 유치권 성립에 영향이 없다. 단, 채무자를 직접점유자로 삼은 간접점유는 제외한다.","근거":[{"법령":"민법","조문":"제320조","원문":"①타인의 물건 또는 유가증권을 점유한 자는 그 물건이나 유가증권에 관하여 생긴 채권이 변제기에 있는 경우에는 변제를 받을 때까지 그 물건 또는 유가증권을 유치할 권리가 있다.\n②전항의 규정은 그 점유가 불법행위로 인한 경우에 적용하지 아니한다."},{"판례":"대법원 판례(간접점유)","요지":"유치권은 직접점유든 간접점유든 성립하지만 채무자를 직접점유자로 하는 간접점유로는 성립하지 않는다."},{"판례":"대법원 판례(배제 특약)","요지":"유치권 배제 특약이 있으면 유치권은 성립하지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"유치권은 타인의 물건에 성립하므로 소유자가 甲인지가 성립에 영향을 준다(제320조제1항)."},{"번호":2,"판정":"옳음","설명":"채권이 변제기에 있어야 하므로 변제기 도래 여부가 성립에 영향을 준다(제320조제1항)."},{"번호":3,"판정":"틀림","설명":"채무자를 매개로 한 간접점유가 아닌 한 직접점유인지 간접점유인지는 성립에 영향이 없다(판례)."},{"번호":4,"판정":"옳음","설명":"불법행위로 인한 점유는 유치권이 성립하지 않는다(제320조제2항)."},{"번호":5,"판정":"옳음","설명":"배제 특약이 있으면 유치권이 성립하지 않는다(판례)."}],"개념":[{"종류":"표","제목":"유치권 성립에 영향을 주는 사항","머리":["사항","영향","근거"],"행":[["물건 소유자가 유치권자 본인","영향 있음, 불성립","제320조제1항 타인의 물건"],["채권의 변제기 미도래","영향 있음, 불성립","제320조제1항"],["점유가 불법행위로 인한 것","영향 있음, 불성립","제320조제2항"],["유치권 배제 특약","영향 있음, 불성립","판례"],["직접점유·간접점유 구분","영향 없음, 채무자 매개 간접점유는 불성립","판례"]]}],"함정":"3번에서 직접점유만 인정된다고 고르기 쉽다. 간접점유도 인정되고, 채무자를 직접점유자로 삼은 경우만 제외되므로 직접·간접 구분은 성립에 영향이 없다."},"30회-1차-063":{"한줄":"일괄경매청구권은 저당권 설정 후 설정자가 건물을 축조한 경우에 생기는데, Y건물은 임차인 丙이 지었으므로 乙은 일괄경매를 청구할 수 없다.","근거":[{"법령":"민법","조문":"제365조","원문":"토지를 목적으로 저당권을 설정한 후 그 설정자가 그 토지에 건물을 축조한 때에는 저당권자는 토지와 함께 그 건물에 대하여도 경매를 청구할 수 있다. 그러나 그 건물의 경매대가에 대하여는 우선변제를 받을 권리가 없다."},{"법령":"민법","조문":"제361조","원문":"저당권은 그 담보한 채권과 분리하여 타인에게 양도하거나 다른 채권의 담보로 하지 못한다."},{"판례":"대법원 판례(제3자 축조 건물과 일괄경매)","요지":"저당권 설정 후 설정자가 아닌 제3자가 토지에 건물을 축조한 경우에는 저당권자가 그 건물에 대해 일괄경매를 청구할 수 없다."},{"판례":"대법원 판례(건물 경락과 임차권)","요지":"건물 소유를 위한 토지임차권은 건물 저당권의 효력이 미치는 종된 권리여서 건물 경락인이 임차권을 취득한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"저당권은 피담보채권과 분리해 양도하지 못한다(제361조)."},{"번호":2,"판정":"틀림","설명":"일괄경매는 설정자가 건물을 축조한 경우에 청구할 수 있다(제365조). Y는 임차인 丙이 축조해 소유한 건물이다."},{"번호":3,"판정":"옳음","설명":"건물 저당권의 효력은 건물 소유를 위한 토지임차권에도 미쳐 戊가 임차권을 취득한다."},{"번호":4,"판정":"옳음","설명":"丁의 저당권 실행은 Y에 대한 것이고, X에 설정된 乙의 저당권에는 영향이 없다."},{"번호":5,"판정":"옳음","설명":"저당권은 목적물의 가치를 지배하는 권리이므로 매매대금은 물상대위 대상이 아니다(제342조는 멸실·훼손·공용징수만 규정)."}],"개념":[{"종류":"표","제목":"일괄경매청구권(제365조) 성립 여부","머리":["경우","청구 가능","이유"],"행":[["설정 후 설정자가 건물 축조","가능","제365조 본문"],["설정 당시 이미 건물 존재","불가","법정지상권 문제로 처리"],["설정 후 제3자가 건물 축조","불가","판례"],["제3자가 축조한 뒤 설정자가 소유권 취득","가능","판례"],["건물 경매대가의 우선변제","불가","제365조 단서"]]}],"함정":"토지 위에 건물이 새로 생겼으니 일괄경매가 된다고 단정하기 쉽다. 제365조는 설정자가 지은 건물만 대상으로 하므로, 축조자가 누구인지가 갈림길이다."},"30회-1차-064":{"한줄":"ㄱ(설정 전 종물)과 ㄴ(설정 후 부합물)에는 효력이 미치고, ㄷ(압류 전 차임채권)에는 미치지 않는다.","근거":[{"법령":"민법","조문":"제358조","원문":"저당권의 효력은 저당부동산에 부합된 물건과 종물에 미친다. 그러나 법률에 특별한 규정 또는 설정행위에 다른 약정이 있으면 그러하지 아니하다."},{"법령":"민법","조문":"제359조","원문":"저당권의 효력은 저당부동산에 대한 압류가 있은 후에 저당권설정자가 그 부동산으로부터 수취한 과실 또는 수취할 수 있는 과실에 미친다. 그러나 저당권자가 그 부동산에 대한 소유권, 지상권 또는 전세권을 취득한 제삼자에 대하여는 압류한 사실을 통지한 후가 아니면 이로써 대항하지 못한다."},{"판례":"대법원 판례(설정 전 종물)","요지":"저당권 설정 당시 이미 존재하던 종물에도 제358조에 따라 저당권의 효력이 미친다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ도 효력이 미친다."},{"번호":2,"판정":"옳음","설명":"ㄱ(종물)과 ㄴ(부합물)에 효력이 미친다."},{"번호":3,"판정":"틀림","설명":"ㄷ은 압류 전의 차임채권이라 효력이 미치지 않는다."},{"번호":4,"판정":"틀림","설명":"ㄷ은 효력이 미치지 않는다."},{"번호":5,"판정":"틀림","설명":"ㄷ이 빠져야 한다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"설정 전부터 있던 종물도 제358조에 의해 효력이 미친다."},{"기호":"ㄴ","판정":"옳음","설명":"설정 후 부합된 물건에도 효력이 미친다(제358조)."},{"기호":"ㄷ","판정":"틀림","설명":"압류 이전에 발생한 차임채권에는 미치지 않는다. 압류 후 수취분부터 미친다(제359조)."}],"개념":[{"종류":"표","제목":"저당권 효력 범위","머리":["대상","효력","근거"],"행":[["설정 전 종물","미침","제358조·판례"],["설정 후 종물","미침","제358조"],["설정 후 부합물","미침","제358조"],["압류 후 과실","미침","제359조"],["압류 전 과실·차임채권","안 미침","제359조 반대해석"],["권원에 의한 부속물","안 미침","제256조 단서"]]}],"함정":"압류 전 차임채권도 저당부동산에서 나오는 수익이라 포함으로 고르기 쉽다. 과실에는 압류 후에 수취한 분만 효력이 미친다."},"30회-1차-066":{"한줄":"수익자는 요약자와 낙약자 계약의 착오취소에서 제109조제2항이 대항하지 못하게 하는 제3자에 속하지 않는다.","근거":[{"법령":"민법","조문":"제539조","원문":"① 계약에 의하여 당사자 일방이 제삼자에게 이행할 것을 약정한 때에는 그 제삼자는 채무자에게 직접 그 이행을 청구할 수 있다."},{"법령":"민법","조문":"제109조제2항","원문":"전항의 의사표시의 취소는 선의의 제삼자에게 대항하지 못한다."},{"판례":"대법원 판례(착오취소와 수익자)","요지":"제3자를 위한 계약에서 수익자는 요약자의 착오취소에 대하여 제109조제2항의 제3자에 해당하지 않는다."},{"판례":"대법원 판례(해제와 반환)","요지":"요약자와 낙약자 사이의 계약이 해제된 경우 낙약자는 이미 수익자에게 급부한 것을 수익자에게 부당이득으로 반환 청구할 수 없다."},{"판례":"대법원 판례(대가관계)","요지":"대가관계의 부존재는 요약자와 수익자 사이의 문제여서 요약자가 낙약자에게 기본관계상 채무의 이행을 거부할 사유가 되지 못한다."},{"판례":"대법원 판례(수익자의 손해배상)","요지":"수익의 의사표시 뒤 요약자가 낙약자의 채무불이행을 이유로 해제해도 수익자는 낙약자에게 그 채무불이행으로 입은 손해의 배상을 청구할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"대가관계의 부존재는 기본관계상 채무 이행 거부 사유가 아니다."},{"번호":2,"판정":"옳음","설명":"해제된 경우 낙약자는 수익자를 상대로 부당이득반환을 청구하지 못한다."},{"번호":3,"판정":"옳음","설명":"수익자는 낙약자에게 채무불이행으로 입은 손해의 배상을 청구할 수 있다."},{"번호":4,"판정":"틀림","설명":"수익자는 착오취소로 대항하지 못하는 제3자의 범위에 속하지 않는다. 요약자가 취소하면 수익자도 취소의 효과를 받는다."},{"번호":5,"판정":"옳음","설명":"수익의 의사표시를 한 수익자는 낙약자에게 직접 이행을 청구한다(제539조)."}],"개념":[{"종류":"표","제목":"제3자를 위한 계약의 법률관계","머리":["상황","결론","근거"],"행":[["수익자의 직접 이행청구","수익의 의사표시 후 가능","제539조"],["대가관계 부존재","요약자가 낙약자에 대한 채무를 거절할 수 없음","판례"],["계약 해제 뒤 낙약자가 수익자에게 한 급부","수익자에게 부당이득 반환 청구 불가","판례"],["요약자가 해제한 뒤 수익자의 손해","낙약자에게 손해배상 청구 가능","판례"],["요약자의 착오취소","수익자는 제109조제2항의 제3자 아님","판례"]]}],"함정":"수익자는 선의의 제3자 규정으로 보호받는다고 보기 쉽다. 수익자는 계약에서 생긴 권리를 얻은 사람이어서 취소의 효과가 그대로 미친다."},"30회-1차-067":{"한줄":"ㄱ(채권양수 후 처분금지가처분)과 ㄷ(채권 압류)은 해제된 계약의 목적물이 아닌 채권에 권리를 취득한 것이어서 보호되는 제3자가 아니다.","근거":[{"법령":"민법","조문":"제548조제1항","원문":"당사자 일방이 계약을 해제한 때에는 각 당사자는 그 상대방에 대하여 원상회복의 의무가 있다. 그러나 제삼자의 권리를 해하지 못한다."},{"판례":"대법원 판례(채권 양수인·압류채권자)","요지":"해제된 계약상의 채권을 양수한 자와 그 채권을 압류·가압류한 자는 제548조제1항 단서의 제3자가 아니다."},{"판례":"대법원 판례(목적물에 대한 가압류)","요지":"해제 전 매수인 명의로 이전등기된 부동산을 가압류 집행한 자는 해제의 소급효로부터 보호되는 제3자다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ만으로는 부족하다. ㄷ도 제3자에 해당하지 않는다."},{"번호":2,"판정":"틀림","설명":"ㄴ은 제3자에 해당한다."},{"번호":3,"판정":"옳음","설명":"제3자에 해당하지 않는 것은 ㄱ과 ㄷ이다."},{"번호":4,"판정":"틀림","설명":"ㄴ은 제3자에 해당한다."},{"번호":5,"판정":"틀림","설명":"ㄴ은 제3자에 해당한다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"채권양수인은 보호되는 제3자가 아니다. 가처분을 받았어도 같다."},{"기호":"ㄴ","판정":"틀림","설명":"해제 전 목적 부동산에 가압류를 집행한 자는 제3자에 해당한다."},{"기호":"ㄷ","판정":"옳음","설명":"계약상 채권을 압류한 자는 보호되는 제3자가 아니다."}],"개념":[{"종류":"비교","제목":"해제의 제3자 판단 기준","왼쪽":{"이름":"제3자 해당 (목적물에 권리)","항목":["해제 전 목적물을 취득하고 등기·인도를 마친 자","목적물에 가압류를 집행한 자","가등기를 마친 자","대항력 있는 임차인"]},"오른쪽":{"이름":"제3자 비해당 (계약상 채권에 권리)","항목":["해제된 계약상 채권의 양수인","채권양수 후 처분금지가처분을 받은 채권자","계약상 채권의 압류·가압류채권자"]}}],"함정":"처분금지가처분이나 압류는 권리를 보전하는 강한 조치라서 제3자로 보호된다고 보기 쉽다. 해제의 제3자는 목적물 자체에 권리를 취득한 자이고 채권을 대상으로 한 권리자는 빠진다. 목적물을 가압류한 ㄴ만 포함된다."},"30회-1차-068":{"한줄":"합의해지로 반환할 금전에는 특약이 없으면 이자를 가산하지 않는다. 이자 가산은 법정해제에 관한 제548조제2항의 효과다.","근거":[{"법령":"민법","조문":"제548조제2항","원문":"전항의 경우에 반환할 금전에는 그 받은 날로부터 이자를 가하여야 한다."},{"법령":"민법","조문":"제534조","원문":"승낙자가 청약에 대하여 조건을 붙이거나 변경을 가하여 승낙한 때에는 그 청약의 거절과 동시에 새로 청약한 것으로 본다."},{"판례":"대법원 판례(합의해제의 효과)","요지":"합의해제는 해제계약의 내용에 따라 효과가 정해지고, 원상회복에 관해 반드시 약정해야 하는 것은 아니다. 약정이 없으면 다른 사정이 없는 한 채무불이행에 따른 손해배상을 청구하지 못하고 반환할 금전에 이자를 가산할 의무도 없다."},{"판례":"대법원 판례(합의해제와 제3자)","요지":"합의해제에도 법정해제와 마찬가지로 제3자의 권리를 해하지 못한다."},{"판례":"대법원 판례(변경 승낙)","요지":"합의해제의 청약에 상대방이 변경을 가하여 승낙하면 제534조에 따라 그 청약은 효력을 잃는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"합의해제 때 원상회복을 반드시 약정해야 하는 것은 아니다."},{"번호":2,"판정":"옳음","설명":"합의해제 후에는 다른 사정이 없으면 채무불이행에 따른 손해배상을 청구하지 못한다."},{"번호":3,"판정":"틀림","설명":"특약이 없으면 반환할 금전에 이자를 가산하지 않는다. 제548조제2항은 법정해제의 규정이다."},{"번호":4,"판정":"옳음","설명":"변경을 가한 승낙은 청약의 거절이므로 청약은 효력을 잃는다(제534조)."},{"번호":5,"판정":"옳음","설명":"합의해제도 제3자의 권리를 해하지 못한다."}],"개념":[{"종류":"표","제목":"합의해제의 법률관계","머리":["쟁점","결론","근거"],"행":[["성립","청약과 승낙으로 이루어지는 해제계약","판례"],["변경을 가한 승낙","청약 거절 + 새 청약","제534조"],["원상회복","약정 없어도 무방, 약정 내용에 따름","판례"],["반환 금전의 이자","특약이 없으면 가산 없음","판례"],["손해배상","특약이 없으면 청구 불가","판례"],["제3자 보호","권리를 해하지 못함","판례"]]}],"함정":"합의해제도 법정해제와 같은 효과가 따른다고 보면 이자 가산을 맞는 것으로 고른다. 합의해제는 계약 내용이 효과를 정한다. 제3자 보호만 법정해제와 같다."},"30회-1차-071":{"한줄":"쌍방 책임 없는 이행불능으로 매매가 종료되면 매도인은 받은 계약금을 부당이득으로 반환해야 한다.","근거":[{"법령":"민법","조문":"제537조","원문":"쌍무계약의 당사자 일방의 채무가 당사자쌍방의 책임없는 사유로 이행할 수 없게 된 때에는 채무자는 상대방의 이행을 청구하지 못한다."},{"법령":"민법","조문":"제538조제1항","원문":"쌍무계약의 당사자 일방의 채무가 채권자의 책임있는 사유로 이행할 수 없게 된 때에는 채무자는 상대방의 이행을 청구할 수 있다. 채권자의 수령지체 중에 당사자쌍방의 책임없는 사유로 이행할 수 없게 된 때에도 같다."},{"법령":"민법","조문":"제741조","원문":"법률상 원인없이 타인의 재산 또는 노무로 인하여 이익을 얻고 이로 인하여 타인에게 손해를 가한 자는 그 이익을 반환하여야 한다."},{"판례":"대법원 판례(대상청구권)","요지":"대상청구권을 행사한 채권자는 상대방에게 반대급부를 이행할 의무가 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"쌍방 책임 없는 후발적 불능은 위험부담이 문제 되는 경우다."},{"번호":2,"판정":"옳음","설명":"위험부담은 쌍무계약의 법리여서 한쪽만 채무를 지는 편무계약에는 적용되지 않는다."},{"번호":3,"판정":"옳음","설명":"대상청구권을 행사하는 쪽은 상대방에 대한 반대급부 이행의무를 진다."},{"번호":4,"판정":"틀림","설명":"계약이 종료되면 매도인은 받은 계약금을 반환해야 한다. 법률상 원인이 없어졌기 때문이다(제741조)."},{"번호":5,"판정":"옳음","설명":"민법은 채무자위험부담주의를 원칙으로 한다(제537조)."}],"개념":[{"종류":"표","제목":"후발적 불능과 위험부담","머리":["유형","효과","근거"],"행":[["채무자 책임 사유","손해배상·해제(위험부담 아님)","제390조, 제546조"],["쌍방 책임 없음","채무 소멸, 채무자는 대금 청구 불가","제537조"],["채권자 책임 사유","채무자는 반대급부 청구 가능","제538조제1항"],["채권자 수령지체 중 쌍방 무책","채무자는 반대급부 청구 가능","제538조제1항 후단"],["채무자가 면하고 얻은 이익","채권자에게 상환","제538조제2항"],["이미 이행한 급부","부당이득으로 반환","제741조"]]},{"종류":"흐름","제목":"쌍방 책임 없는 이행불능의 처리","단계":[{"이름":"이행불능","설명":"계약 후 쌍방 책임 없이 매도인 채무가 불능"},{"이름":"채무 소멸","설명":"매도인은 대금을 청구하지 못함(채무자위험부담)"},{"이름":"기지급 대금 정산","설명":"계약금·중도금은 부당이득으로 반환"},{"이름":"대상청구권","설명":"대상이익이 생기면 매수인이 양도를 청구, 이때 반대급부 의무"}]}],"함정":"계약이 불능으로 끝나도 계약금은 위약금처럼 매도인에게 남는다고 보기 쉽다. 책임 있는 당사자가 없으면 받은 금전은 돌려주어야 한다."},"30회-1차-065":{"한줄":"ㄱ, ㄴ, ㄷ 모두 계약금에 관한 판례·조문과 일치하여 옳다.","근거":[{"법령":"민법","조문":"제565조","원문":"① 매매의 당사자 일방이 계약당시에 금전 기타 물건을 계약금, 보증금등의 명목으로 상대방에게 교부한 때에는 당사자간에 다른 약정이 없는 한 당사자의 일방이 이행에 착수할 때까지 교부자는 이를 포기하고 수령자는 그 배액을 상환하여 매매계약을 해제할 수 있다. ② 제551조의 규정은 전항의 경우에 이를 적용하지 아니한다."},{"판례":"대법원 판례(이행기 전 중도금 지급)","요지":"이행기 전에 중도금을 지급했어도 이행에 착수한 것이므로 매도인은 더 이상 계약금의 배액을 상환하고 해제할 수 없다."},{"판례":"대법원 판례(배액상환의 방법)","요지":"매도인이 배액을 상환하며 해제하는 경우 이행의 제공만으로 족하고, 매수인이 수령을 거절해도 공탁까지 할 필요는 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ만이 아니라 ㄴ, ㄷ도 옳다."},{"번호":2,"판정":"틀림","설명":"ㄱ, ㄴ 외에 ㄷ도 옳다."},{"번호":3,"판정":"틀림","설명":"ㄱ, ㄷ 외에 ㄴ도 옳다."},{"번호":4,"판정":"틀림","설명":"ㄴ, ㄷ 외에 ㄱ도 옳다."},{"번호":5,"판정":"옳음","설명":"ㄱ, ㄴ, ㄷ 모두 옳다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"별도 약정이 없으면 계약금은 해약금으로 추정된다(제565조제1항)."},{"기호":"ㄴ","판정":"옳음","설명":"약정 중도금 지급기일 전이라도 중도금을 지급받으면 이행에 착수한 것이어서 배액상환 해제가 막힌다."},{"기호":"ㄷ","판정":"옳음","설명":"배액을 이행제공하면 해제 의사표시가 효력을 가지고, 수령이 거절되어도 공탁은 불필요하다."}],"개념":[{"종류":"흐름","제목":"해약금 해제의 과정","단계":[{"이름":"계약금 교부","설명":"계약 당시 금전 기타 물건을 계약금 명목으로 교부"},{"이름":"해제 가능 시기","설명":"당사자 일방이 이행에 착수할 때까지"},{"이름":"교부자 해제","설명":"계약금을 포기하고 해제"},{"이름":"수령자 해제","설명":"계약금의 배액을 상환(이행의 제공)하고 해제, 공탁 불요"},{"이름":"해제 후","설명":"손해배상 청구 불가(제565조제2항)"}]}],"함정":"ㄴ을 약정 지급기일 전이라서 이행에 착수한 것이 아니라고 읽으면 틀린다. ㄷ에서 수령 거절 시 공탁이 필요하다고 보는 것도 오답이다."},"30회-1차-069":{"한줄":"매매는 당사자의 합의만으로 성립하는 낙성계약이고, 물건 인도 같은 급부가 있어야 성립하는 요물계약이 아니다.","근거":[{"법령":"민법","조문":"제563조","원문":"매매는 당사자 일방이 재산권을 상대방에게 이전할 것을 약정하고 상대방이 그 대금을 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제569조","원문":"매매의 목적이 된 권리가 타인에게 속한 경우에는 매도인은 그 권리를 취득하여 매수인에게 이전하여야 한다."},{"법령":"민법","조문":"제566조","원문":"매매계약에 관한 비용은 당사자 쌍방이 균분하여 부담한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"매매는 약정만으로 효력이 생기는 낙성계약이다(제563조)."},{"번호":2,"판정":"옳음","설명":"매도인의 재산권 이전의무와 매수인의 대금지급의무가 서로 대가관계에 있는 유상·쌍무계약이다."},{"번호":3,"판정":"옳음","설명":"담보책임은 매도인의 귀책사유를 요건으로 하지 않는 법정 무과실책임이다."},{"번호":4,"판정":"옳음","설명":"타인의 권리도 매매의 목적이 되고, 매도인은 이를 취득해 이전할 의무를 진다(제569조)."},{"번호":5,"판정":"옳음","설명":"매매 비용은 특별한 사정이 없으면 쌍방이 균분 부담한다(제566조)."}],"개념":[{"종류":"표","제목":"매매계약의 법적 성질","머리":["구분","내용","근거"],"행":[["낙성계약","합의만으로 성립","제563조"],["쌍무·유상계약","재산권 이전과 대금지급이 대가관계","제563조·제568조"],["불요식계약","서면·방식 불요","제563조"],["타인 권리 매매","유효, 매도인이 취득·이전할 의무","제569조"],["계약 비용","당사자 쌍방 균분","제566조"],["담보책임","매도인의 무과실책임","제570조 이하"]]}],"함정":"요물계약은 계약금계약, 현상광고 같은 계약에서 나오는 말이다. 매매 자체는 요물계약이 아니다."},"30회-1차-070":{"한줄":"매수인이 대금을 완제하면 목적물이 인도되지 않았어도 그 이후 생기는 과실은 매수인에게 귀속한다.","근거":[{"법령":"민법","조문":"제587조","원문":"매매계약있은 후에도 인도하지 아니한 목적물로부터 생긴 과실은 매도인에게 속한다. 매수인은 목적물의 인도를 받은 날로부터 대금의 이자를 지급하여야 한다. 그러나 대금의 지급에 대하여 기한이 있는 때에는 그러하지 아니하다."},{"판례":"대법원 판례(대금 완제와 과실 귀속)","요지":"매수인이 목적물을 인도받지 못했어도 대금을 완제한 때에는 그 이후의 과실은 매수인에게 귀속한다. 대금 완제 전에는 소유권이전등기를 먼저 받았더라도 과실은 매도인에게 속한다."},{"판례":"대법원 판례(미인도 상태의 지체 손해)","요지":"목적물이 인도되지 않고 대금도 완제되지 않았으면 과실과 이자가 균형을 이루는 것으로 보아, 매수인의 인도의무 지체 손해배상청구와 매도인의 대금 이자 상당 손해배상청구가 모두 인정되지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"목적물 인도와 대금 완제가 모두 안 된 상태에서는 과실과 이자를 같게 취급해 인도지체 손해배상을 구할 수 없다."},{"번호":2,"판정":"옳음","설명":"대금지급을 거절할 정당한 사유가 있으면 인도를 먼저 받았더라도 이자 지급의무가 없다."},{"번호":3,"판정":"옳음","설명":"인도 전에는 과실이 매도인에게 속하므로 잔대금 지체에 따른 이자 상당 손해배상은 구할 수 없다(제587조)."},{"번호":4,"판정":"옳음","설명":"등기를 받았더라도 대금을 완제하지 않았다면 과실은 매도인에게 귀속한다."},{"번호":5,"판정":"틀림","설명":"대금을 완제하면 인도 전이라도 이후 과실은 매수인에게 귀속한다."}],"개념":[{"종류":"표","제목":"매매 목적물 과실과 대금 이자","머리":["상황","과실","대금 이자","근거"],"행":[["인도 전 + 대금 미완제","매도인","지급 불요","제587조"],["인도 후","매수인","인도일부터 지급(기한 있으면 제외)","제587조"],["인도 전 + 대금 완제","매수인","-","판례"],["등기만 먼저 이전, 대금 미완제","매도인","-","판례"],["대금지급 거절 정당사유 있는 인도","-","지급 불요","판례"]]}],"함정":"제587조의 '인도하지 아니한 목적물'이라는 문구만 보고 인도가 없으면 언제나 매도인이 과실을 갖는다고 단정하면 틀린다. 대금을 완제하면 매수인 쪽으로 넘어간다."},"30회-1차-072":{"한줄":"환매권을 행사해도 환매에 의한 이전등기를 마치기 전에는 목적물을 가압류한 제3자에게 권리취득을 주장하지 못한다.","근거":[{"법령":"민법","조문":"제591조제2·3항","원문":"② 환매기간을 정한 때에는 다시 이를 연장하지 못한다. ③ 환매기간을 정하지 아니한 때에는 그 기간은 부동산은 5년, 동산은 3년으로 한다."},{"법령":"민법","조문":"제590조제1항","원문":"매도인이 매매계약과 동시에 환매할 권리를 보류한 때에는 그 영수한 대금 및 매수인이 부담한 매매비용을 반환하고 그 목적물을 환매할 수 있다."},{"법령":"민법","조문":"제186조","원문":"부동산에 관한 법률행위로 인한 물권의 득실변경은 등기하여야 그 효력이 생긴다."},{"판례":"대법원 판례(환매권 행사와 등기)","요지":"환매의 의사표시만으로는 소유권이 환매권자에게 복귀하지 않고 환매에 의한 이전등기를 마쳐야 물권변동이 생긴다. 등기 전에 목적물을 가압류한 제3자에게는 권리취득을 주장할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"환매특약등기는 환매권자의 권리를 제3자에게 대항하게 할 뿐 매수인의 처분권을 막지 않는다. 매수인은 재매수인에게 환매특약 등기를 이유로 이전등기를 거절할 수 없다."},{"번호":2,"판정":"옳음","설명":"정한 환매기간은 연장할 수 없다(제591조제2항)."},{"번호":3,"판정":"틀림","설명":"환매 의사표시만으로는 권리를 취득하지 못한다. 환매에 의한 이전등기를 하지 않으면 가압류권자에게 대항할 수 없다(제186조)."},{"번호":4,"판정":"옳음","설명":"기간 약정이 없으면 부동산 5년이다(제591조제3항)."},{"번호":5,"판정":"옳음","설명":"환매권은 매매계약과 동시에 보류해야 한다(제590조제1항)."}],"개념":[{"종류":"흐름","제목":"부동산 환매의 진행","단계":[{"이름":"환매권 보류","설명":"매매계약과 동시에 약정(제590조제1항)"},{"이름":"환매등기","설명":"매매등기와 동시에 환매권 보류를 등기해야 제3자에게 대항(제592조)"},{"이름":"환매 실행","설명":"환매기간(부동산 5년 한도) 내에 대금과 매매비용을 제공(제594조제1항)"},{"이름":"소유권 복귀","설명":"환매에 의한 이전등기를 마쳐야 물권변동(제186조)"},{"이름":"기간 도과","설명":"기간 내에 제공하지 못하면 환매권 상실"}]}],"함정":"환매 의사표시를 하면 소유권이 곧바로 돌아온다고 생각하면 틀린다. 의사표시 이후 이전등기를 해야 물권변동이 생기고, 그 전에 들어온 가압류권자에게는 대항하지 못한다."},"30회-1차-073":{"한줄":"유익비상환청구권, 부속물매수청구권, 차임·전세금 증감청구권은 전세권자와 임차인 모두에게 인정된다.","근거":[{"법령":"민법","조문":"제310조제1항","원문":"전세권자가 목적물을 개량하기 위하여 지출한 금액 기타 유익비에 관하여는 그 가액의 증가가 현존한 경우에 한하여 소유자의 선택에 좇아 그 지출액이나 증가액의 상환을 청구할 수 있다."},{"법령":"민법","조문":"제316조제2항","원문":"전항의 경우에 그 부속물건이 전세권설정자의 동의를 얻어 부속시킨 것인 때에는 전세권자는 전세권설정자에 대하여 그 부속물건의 매수를 청구할 수 있다. 그 부속물건이 전세권설정자로부터 매수한 것인 때에도 같다."},{"법령":"민법","조문":"제312조의2","원문":"전세금이 목적 부동산에 관한 조세ㆍ공과금 기타 부담의 증감이나 경제사정의 변동으로 인하여 상당하지 아니하게 된 때에는 당사자는 장래에 대하여 그 증감을 청구할 수 있다."},{"법령":"민법","조문":"제626조제2항","원문":"임차인이 유익비를 지출한 경우에는 임대인은 임대차종료시에 그 가액의 증가가 현존한 때에 한하여 임차인의 지출한 금액이나 그 증가액을 상환하여야 한다."},{"법령":"민법","조문":"제628조","원문":"임대물에 대한 공과부담의 증감 기타 경제사정의 변동으로 인하여 약정한 차임이 상당하지 아니하게 된 때에는 당사자는 장래에 대한 차임의 증감을 청구할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ뿐 아니라 ㄱ·ㄴ도 두 권리자 모두에게 인정된다."},{"번호":2,"판정":"틀림","설명":"ㄱ·ㄴ뿐 아니라 ㄷ도 인정된다."},{"번호":3,"판정":"틀림","설명":"ㄱ·ㄷ뿐 아니라 ㄴ도 인정된다."},{"번호":4,"판정":"틀림","설명":"ㄴ·ㄷ뿐 아니라 ㄱ도 인정된다."},{"번호":5,"판정":"옳음","설명":"ㄱ·ㄴ·ㄷ 모두 전세권자(제310조, 제316조, 제312조의2)와 임차인(제626조제2항, 제646조, 제628조) 모두에게 인정된다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"전세권자는 제310조, 임차인은 제626조제2항으로 인정된다."},{"기호":"ㄴ","판정":"옳음","설명":"전세권자는 제316조제2항, 임차인은 제646조로 인정된다."},{"기호":"ㄷ","판정":"옳음","설명":"전세금은 제312조의2, 차임은 제628조로 증감을 청구할 수 있다."}],"개념":[{"종류":"표","제목":"전세권과 건물임차권 비교","머리":["구분","전세권","건물임차권"],"행":[["유익비상환청구","제310조","제626조제2항"],["필요비","상환청구 없음, 유지·수선의무 부담(제309조)","상환청구(제626조제1항)"],["부속물매수청구","제316조제2항","제646조"],["보증금·차임 증감","전세금 증감청구(제312조의2)","차임증감청구(제628조)"],["양도·전대","설정행위로 금지하지 않으면 동의 없이 가능(제306조)","임대인 동의 필요(제629조)"]]}],"함정":"전세권은 물권이고 임차권은 채권이라 권리 내용이 갈릴 것 같지만, 세 권리 모두 조문이 따로 있다. 필요비만 다르다. 전세권자는 오히려 유지·수선의무를 진다."},"30회-1차-074":{"한줄":"임차인의 채무불이행으로 기간 만료 전에 임대차가 해지된 경우에는 지상물매수청구권이 인정되지 않는다.","근거":[{"법령":"민법","조문":"제643조","원문":"건물 기타 공작물의 소유 또는 식목, 채염, 목축을 목적으로 한 토지임대차의 기간이 만료한 경우에 건물, 수목 기타 지상시설이 현존한 때에는 제283조의 규정을 준용한다."},{"법령":"민법","조문":"제283조","원문":"①지상권이 소멸한 경우에 건물 기타 공작물이나 수목이 현존한 때에는 지상권자는 계약의 갱신을 청구할 수 있다. ②지상권설정자가 계약의 갱신을 원하지 아니하는 때에는 지상권자는 상당한 가액으로 전항의 공작물이나 수목의 매수를 청구할 수 있다."},{"판례":"대법원 판례(지상물매수청구권의 요건)","요지":"지상물매수청구권은 형성권이라 상대방의 승낙이 필요 없고, 건축허가를 받지 않은 건물이나 미등기 건물도 대상이 된다. 임차인의 채무불이행(차임연체 등)으로 임대차가 해지된 때에는 인정되지 않는다."},{"판례":"대법원 판례(걸쳐 지은 건물)","요지":"임차지와 제3자의 토지에 걸쳐 지은 건물은 임차지 위에 있는 부분 중 구분소유의 객체가 될 수 있는 부분에 한해 매수청구를 할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"형성권이라 임대인의 승낙이 필요 없다."},{"번호":2,"판정":"틀림","설명":"건축허가를 받지 않은 건물도 매수청구의 대상이다."},{"번호":3,"판정":"틀림","설명":"임차지 위에 있는 부분에 한해 매수청구할 수 있고 건물 전체는 안 된다."},{"번호":4,"판정":"옳음","설명":"채무불이행으로 중도 해지된 경우 매수청구를 할 수 없다."},{"번호":5,"판정":"틀림","설명":"갱신을 청구할 수 있다. 임대인이 갱신을 거절해야 매수청구가 열린다(제643조, 제283조)."}],"개념":[{"종류":"표","제목":"지상물매수청구권 요건과 효과","머리":["구분","내용","근거"],"행":[["대상 임대차","건물·공작물 소유, 식목, 채염, 목축 목적의 토지임대차","제643조"],["시기","임대차 기간 만료, 지상시설 현존","제643조"],["순서","갱신청구, 임대인 거절, 매수청구","제283조"],["성질","형성권, 승낙 불요","판례"],["대상 건물","무허가·미등기도 가능","판례"],["제외","채무불이행으로 해지, 임대차 종료 전 건물 이전","판례"],["배제 약정","임차인에게 불리하면 무효","제652조"]]}],"함정":"3은 걸쳐 지은 건물 전체를 청구할 수 있다고 보기 쉬운데, 임차지 위 부분에 한정된다. 5는 갱신청구와 매수청구가 차례로 이어지는 구조라서 갱신청구도 할 수 있다."},"30회-1차-075":{"한줄":"부속물매수청구권은 건물 기타 공작물의 임차인에게 인정된다. 토지임차인에게는 지상물매수청구권이 있을 뿐이다.","근거":[{"법령":"민법","조문":"제646조","원문":"①건물 기타 공작물의 임차인이 그 사용의 편익을 위하여 임대인의 동의를 얻어 이에 부속한 물건이 있는 때에는 임대차의 종료시에 임대인에 대하여 그 부속물의 매수를 청구할 수 있다. ②임대인으로부터 매수한 부속물에 대하여도 전항과 같다."},{"법령":"민법","조문":"제647조제1항","원문":"건물 기타 공작물의 임차인이 적법하게 전대한 경우에 전차인이 그 사용의 편익을 위하여 임대인의 동의를 얻어 이에 부속한 물건이 있는 때에는 전대차의 종료시에 임대인에 대하여 그 부속물의 매수를 청구할 수 있다."},{"법령":"민법","조문":"제652조","원문":"제627조, 제628조, 제631조, 제635조, 제638조, 제640조, 제641조, 제643조 내지 제647조의 규정에 위반하는 약정으로 임차인이나 전차인에게 불리한 것은 그 효력이 없다."},{"판례":"대법원 판례(특수목적 부속물)","요지":"오로지 임차인의 특수한 목적에 사용하기 위해 부속시킨 물건은 건물의 객관적 편익을 위한 것이 아니므로 매수청구의 대상이 아니다."}],"선지":[{"번호":1,"판정":"틀림","설명":"건물 기타 공작물의 임차인에게 인정된다. 토지임차인에게는 지상물매수청구권(제643조)이 인정된다."},{"번호":2,"판정":"옳음","설명":"임대인에게서 매수한 부속물에도 인정된다(제646조제2항)."},{"번호":3,"판정":"옳음","설명":"적법한 전차인에게도 인정된다(제647조)."},{"번호":4,"판정":"옳음","설명":"불리한 약정은 무효다(제652조)."},{"번호":5,"판정":"옳음","설명":"오로지 임차인의 특수목적을 위한 물건은 대상이 아니다."}],"개념":[{"종류":"비교","제목":"부속물매수청구권과 지상물매수청구권","왼쪽":{"이름":"부속물매수청구권(제646조)","항목":["건물 기타 공작물의 임차인","임대인 동의로 부속하거나 임대인에게서 매수한 물건","임대차 종료 시 부속물 매수 청구","적법한 전차인도 가능(제647조)"]},"오른쪽":{"이름":"지상물매수청구권(제643조)","항목":["건물 등을 소유할 목적의 토지임차인","임대차 기간 만료, 지상시설 현존, 임대인의 갱신 거절","지상건물 매수 청구","전차인의 임대청구·매수청구는 제644조"]}}],"함정":"1을 토지와 건물 모두에 인정되는 권리로 보기 쉽다. 부속물은 건물 기타 공작물 임차인의 권리이고, 토지임차인은 자기 소유 건물을 지상물로 매수청구한다."},"30회-1차-076":{"한줄":"경매 환가대금에서 보증금을 우선변제받으려면 임차인은 주택을 양수인에게 인도해야 한다.","근거":[{"법령":"주택임대차보호법","조문":"제3조의2제3항","원문":"임차인은 임차주택을 양수인에게 인도하지 아니하면 제2항에 따른 보증금을 받을 수 없다."},{"법령":"주택임대차보호법","조문":"제6조제3항","원문":"2기(期)의 차임액(借賃額)에 달하도록 연체하거나 그 밖에 임차인으로서의 의무를 현저히 위반한 임차인에 대하여는 제1항을 적용하지 아니한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"1년 약정이어도 2년으로 본다(제4조제1항 본문). 乙은 2년을 주장할 수 있다."},{"번호":2,"판정":"옳음","설명":"임차인은 2년 미만 약정이 유효함을 주장할 수 있다(제4조제1항 단서)."},{"번호":3,"판정":"옳음","설명":"2기의 차임액에 달하도록 연체한 임차인에게는 묵시적 갱신이 적용되지 않는다(제6조제3항)."},{"번호":4,"판정":"옳음","설명":"묵시적 갱신 후 임차인은 언제든지 해지를 통지할 수 있다(제6조의2제1항)."},{"번호":5,"판정":"틀림","설명":"주택을 양수인에게 인도하지 않으면 우선변제 보증금을 받을 수 없다(제3조의2제3항)."}],"개념":[{"종류":"표","제목":"대항력·우선변제권 요건","머리":["구분","요건","효력 시점"],"행":[["대항력","주택 인도와 주민등록(전입신고)","다음 날부터"],["우선변제권","대항요건과 임대차계약증서상 확정일자","둘 다 갖춘 때(나중 것 기준)"],["보증금 수령","주택을 양수인에게 인도","제3조의2제3항"],["임차권등기명령","임대차 종료 후 보증금 미반환","등기를 마친 때"],["최우선변제","경매신청등기 전 대항요건","제8조"]]}],"함정":"우선변제권이 확정일자로 생기니 인도는 필요 없다고 생각하기 쉽다. 우선변제로 보증금을 받는 단계에서는 주택을 인도해야 한다."},"30회-1차-077":{"한줄":"임차인이 임차건물을 중대한 과실로 전부 파손했다면 갱신요구 거절 사유가 있어 임대인은 권리금 회수기회를 보장할 필요가 없다.","근거":[{"법령":"상가건물 임대차보호법","조문":"제10조의4제1항","원문":"다만, 제10조제1항 각 호의 어느 하나에 해당하는 사유가 있는 경우에는 그러하지 아니하다."},{"법령":"상가건물 임대차보호법","조문":"제10조제1항제5호","원문":"임차인이 임차한 건물의 전부 또는 일부를 고의나 중대한 과실로 파손한 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"임대차계약을 체결하려는 자의 정보제공 요청은 임대인의 동의가 있어야 한다(제4조제4항)."},{"번호":2,"판정":"옳음","설명":"제10조제1항제5호 사유가 있으면 제10조의4제1항 본문이 적용되지 않는다."},{"번호":3,"판정":"틀림","설명":"갱신요구는 전체 임대차기간 10년까지 가능하다(제10조제2항). 7년이 아니다."},{"번호":4,"판정":"틀림","설명":"임차권등기명령은 관할 세무서가 아니라 지방법원·지원·시군법원에 신청한다(제6조제1항)."},{"번호":5,"판정":"틀림","설명":"묵시적 갱신 후 임차인이 해지를 통고하면 임대인이 통고를 받은 날부터 3개월이 지나야 효력이 생긴다(제10조제5항)."}],"개념":[{"종류":"표","제목":"상가 임대차 절차와 기간","머리":["항목","내용","근거"],"행":[["확정일자 부여","관할 세무서장","제4조제1항"],["정보제공 요청(체결하려는 자)","임대인 동의 필요","제4조제4항"],["임차권등기명령","관할 법원","제6조제1항"],["묵시적 갱신 후 해지","임차인 통고, 3개월 후 효력","제10조제5항"],["갱신요구 총기간","10년","제10조제2항"]]}],"함정":"관할 세무서가 확정일자를 부여하는 곳이라 임차권등기명령도 세무서에 신청한다고 생각하기 쉽다. 임차권등기명령은 법원 소관이다."},"30회-1차-078":{"한줄":"청산금은 통지 당시 담보목적부동산의 가액에서 채권액을 뺀 금액이고, 선순위담보권이 있으면 그 담보채권액을 채권액에 포함해 계산한다.","근거":[{"법령":"가등기담보 등에 관한 법률","조문":"제4조제1항","원문":"채권자는 제3조제1항에 따른 통지 당시의 담보목적부동산의 가액에서 그 채권액을 뺀 금액(이하 \"청산금\"이라 한다)을 채무자등에게 지급하여야 한다. 이 경우 담보목적부동산에 선순위담보권(先順位擔保權) 등의 권리가 있을 때에는 그 채권액을 계산할 때에 선순위담보 등에 의하여 담보된 채권액을 포함한다."},{"법령":"가등기담보 등에 관한 법률","조문":"제3조제1항","원문":"채권자가 담보계약에 따른 담보권을 실행하여 그 담보목적부동산의 소유권을 취득하기 위하여는 그 채권(債權)의 변제기(辨濟期) 후에 제4조의 청산금(淸算金)의 평가액을 채무자등에게 통지하고, 그 통지가 채무자등에게 도달한 날부터 2개월(이하 \"청산기간\"이라 한다)이 지나야 한다. 이 경우 청산금이 없다고 인정되는 경우에는 그 뜻을 통지하여야 한다."},{"법령":"가등기담보 등에 관한 법률","조문":"제9조","원문":"채권자는 제3조제1항에 따라 그가 통지한 청산금의 금액에 관하여 다툴 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"담보가등기인지 청구권보전 가등기인지는 등기부에 적힌 명목이 아니라 거래의 실질과 당사자 의사로 정한다. 채권담보 목적으로 마친 가등기가 담보가등기다(제2조제3호)."},{"번호":2,"판정":"틀림","설명":"청산금이 없다고 인정되는 경우에도 채권자는 청산금이 없다는 뜻을 채무자등에게 통지해야 한다(제3조제1항 후단)."},{"번호":3,"판정":"옳음","설명":"제4조제1항 그대로다. 선순위담보로 담보된 채권액도 채권액에 넣으므로 그만큼 청산금이 줄어든다."},{"번호":4,"판정":"틀림","설명":"채권자가 통지한 청산금 액수가 객관적 평가액에 못 미쳐도 통지의 효력은 그대로 있고, 채권자는 다시 통지할 의무가 없다. 정확한 청산금을 지급하면 소유권을 취득한다는 것이 판례다. 채권자는 자기가 통지한 금액을 다툴 수도 없다(제9조)."},{"번호":5,"판정":"틀림","설명":"통지 이후 과실수취권이 채권자에게 넘어간다는 규정은 가담법에 없다. 소유권이전등기를 마친 경우 채권자는 청산기간이 지나고 청산금을 지급한 때 소유권을 취득하므로(제4조제2항), 그 전에는 채권자의 소유가 아니다."}],"개념":[{"종류":"표","제목":"담보권 실행 절차와 청산금","머리":["단계","내용","조문"],"행":[["적용 요건","차용물 반환 대신 재산권 이전을 예약, 예약 당시 가액이 차용액과 이자의 합계 초과","제1조"],["통지 시기","채권의 변제기 후에 청산금 평가액을 채무자등에게 통지","제3조제1항"],["통지 내용","통지 당시 부동산 평가액과 민법 제360조의 채권액. 청산금이 없으면 그 뜻","제3조제1항·제2항"],["청산기간","통지가 채무자등에게 도달한 날부터 2개월","제3조제1항"],["청산금 계산","통지 당시 가액 - 채권액(선순위담보 채권액 포함)","제4조제1항"],["소유권 취득","이전등기를 마친 경우: 기간 경과 후 청산금 지급 때 / 가등기: 기간 경과 후 본등기 청구","제4조제2항"],["동시이행","청산금 지급 채무와 이전등기·인도 채무","제4조제3항"]]}],"함정":"선지 2를 고르기 쉽다. 청산금이 없으면 통지가 필요 없다고 보기 쉽지만, 없다는 뜻도 통지해야 한다. 선지 4와 5는 판례와 조문에 없는 결론을 붙였다."},"30회-1차-079":{"한줄":"재건축 참가 여부를 서면으로 촉구받고 2개월 안에 회답하지 않은 구분소유자는 참가하지 않겠다고 회답한 것으로 본다.","근거":[{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제48조제2항·제3항","원문":"제1항의 촉구를 받은 구분소유자는 촉구를 받은 날부터 2개월 이내에 회답하여야 한다. 제2항의 기간 내에 회답하지 아니한 경우 그 구분소유자는 재건축에 참가하지 아니하겠다는 뜻을 회답한 것으로 본다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제42조제1항","원문":"규약 및 관리단집회의 결의는 구분소유자의 특별승계인에 대하여도 효력이 있다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제24조제2항","원문":"관리인은 구분소유자일 필요가 없으며, 그 임기는 2년의 범위에서 규약으로 정한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"규약과 관리단집회 결의는 특별승계인에게도 효력이 있다(제42조제1항)."},{"번호":2,"판정":"옳음","설명":"공용부분의 물권 득실변경에는 등기가 필요 없다(제13조제3항)."},{"번호":3,"판정":"옳음","설명":"관리인은 구분소유자일 필요가 없다(제24조제2항)."},{"번호":4,"판정":"옳음","설명":"재건축 결의는 구분소유자 및 의결권 각 5분의 4 이상이다(제47조제2항)."},{"번호":5,"판정":"틀림","설명":"회답하지 않으면 재건축에 참가하지 않겠다고 회답한 것으로 본다(제48조제3항). 참가한다는 쪽으로 보는 것이 아니다."}],"개념":[{"종류":"흐름","제목":"재건축 결의 이후 절차","단계":[{"이름":"재건축 결의","설명":"구분소유자 및 의결권 각 5분의 4 이상(제47조제2항)"},{"이름":"참가 여부 촉구","설명":"집회를 소집한 자가 지체 없이 반대자에게 서면으로 촉구(제48조제1항)"},{"이름":"회답","설명":"촉구를 받은 날부터 2개월 이내. 회답이 없으면 참가하지 않겠다는 뜻으로 본다(제48조제2항·제3항)"},{"이름":"매도청구","설명":"회답기간 만료일부터 2개월 이내에 시가로 구분소유권·대지사용권 매도 청구(제48조제4항)"},{"이름":"철거공사 미착수 시 되팔기 청구","설명":"재건축 결의일부터 2년 이내에 철거공사 착수가 없으면 그 기간 만료일부터 6개월 이내에 대금 상당액을 제공하고 청구(제48조제6항)"}]}],"함정":"서면 촉구에 무반응이면 찬성으로 넘어간다고 생각하기 쉽다. 침묵은 불참 의사로 보아 매도청구 대상이 된다."},"30회-1차-080":{"한줄":"시험에서는 다섯 번호를 모두 정답으로 처리했다. 3자간 등기명의신탁에서 약정은 무효이고 신탁자는 매도인 丙을 상대로 이행을 청구하며 丙을 대위해 乙 명의 등기의 말소를 구한다.","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조","원문":"① 명의신탁약정은 무효로 한다. ② 명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다. ③ 제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"판례":"대법원 판례(3자간 등기명의신탁)","요지":"매도인이 신탁자와 매매계약을 맺고 수탁자 명의로 이전등기해 준 경우 소유권은 매도인에게 남아 있다. 신탁자는 매도인에게 매매계약상 이전등기를 청구할 수 있고, 매도인을 대위해 수탁자 명의 등기의 말소를 구할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"명의신탁약정은 무효다(제4조제1항)."},{"번호":2,"판정":"틀림","설명":"소유권은 매도인 丙에게 있어 乙이 신탁자에게 반환할 소유권이 없다. 甲이 乙에게 부당이득반환을 원인으로 소유권이전등기를 구하는 것은 허용되지 않는다."},{"번호":3,"판정":"옳음","설명":"甲은 丙과의 매매계약상 이전등기청구권을 가진다."},{"번호":4,"판정":"옳음","설명":"甲은 丙에 대한 이전등기청구권을 보전하기 위해 丙을 대위하여 乙 명의 등기의 말소를 구할 수 있다."},{"번호":5,"판정":"옳음","설명":"무효는 제3자에게 대항하지 못하므로(제4조제3항) 악의의 丁도 유효하게 소유권을 취득한다."}],"개념":[{"종류":"흐름","제목":"3자간 등기명의신탁에서 신탁자의 구제","단계":[{"이름":"약정과 매매","설명":"甲이 乙과 명의신탁 약정, 甲이 丙과 매매계약"},{"이름":"등기","설명":"丙이 甲의 부탁으로 乙 앞으로 이전등기. 물권변동은 무효(제4조제2항 본문)"},{"이름":"소유권 귀속","설명":"소유권은 매도인 丙에게 남음"},{"이름":"신탁자의 청구","설명":"丙에게 매매계약상 이전등기 청구, 丙을 대위해 乙 등기 말소 청구"},{"이름":"제3자 보호","설명":"乙에게서 매수해 등기를 마친 제3자는 선의·악의와 관계없이 소유권 취득(제4조제3항)"}]}],"함정":"신탁자가 돈을 낸 사람이니 수탁자에게 직접 이전등기를 청구할 수 있다고 보기 쉽다. 3자간 명의신탁에서는 소유권이 매도인에게 있으므로 매도인을 거쳐야 한다."},"30회-2차-001":{"한줄":"무등록 중개업자에게 중개를 의뢰한 거래당사자는 무등록 중개행위의 공동정범으로 처벌되지 않으므로 ③이 틀리다.","근거":[{"법령":"공인중개사법","조문":"제2조제5호","원문":"\"소속공인중개사\"라 함은 개업공인중개사에 소속된 공인중개사(개업공인중개사인 법인의 사원 또는 임원으로서 공인중개사인 자를 포함한다)로서 중개업무를 수행하거나 개업공인중개사의 중개업무를 보조하는 자를 말한다."},{"법령":"공인중개사법","조문":"제12조제2항","원문":"개업공인중개사등은 다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 개업공인중개사인 법인의 사원ㆍ임원이 될 수 없다."},{"법령":"공인중개사법","조문":"제2조제1호","원문":"\"중개\"라 함은 제3조에 따른 중개대상물에 대하여 거래당사자간의 매매ㆍ교환ㆍ임대차 그 밖의 권리의 득실변경에 관한 행위를 알선하는 것을 말한다."},{"법령":"공인중개사법","조문":"제48조제1호","원문":"제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 한 자"},{"법령":"공인중개사법","조문":"제33조제1항제2호","원문":"제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 영위하는 자인 사실을 알면서 그를 통하여 중개를 의뢰받거나 그에게 자기의 명의를 이용하게 하는 행위"},{"판례":"대법원 판례(무등록 중개업자에게 의뢰한 당사자)","요지":"무등록 중개업자에게 중개를 의뢰한 거래당사자는 무등록 중개업을 한 자의 공동정범으로 처벌되지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"소속공인중개사의 정의와 같다(제2조제5호)."},{"번호":2,"판정":"옳음","설명":"개업공인중개사인 법인의 사원·임원인 공인중개사는 소속공인중개사에 포함된다(제2조제5호)."},{"번호":3,"판정":"틀림","설명":"처벌 대상은 개설등록 없이 중개업을 한 자(제48조제1호)이고, 의뢰한 거래당사자는 공동정범이 되지 않는다는 것이 판례다. 개업공인중개사가 무등록 업자임을 알면서 중개를 의뢰받는 행위는 제33조제1항제2호의 금지행위다."},{"번호":4,"판정":"옳음","설명":"개업공인중개사등은 다른 개업공인중개사의 소속공인중개사·중개보조원 또는 개업공인중개사인 법인의 사원·임원이 될 수 없다(제12조제2항)."},{"번호":5,"판정":"옳음","설명":"지역권의 설정·취득도 권리의 득실변경에 관한 행위이고, 중개는 이를 알선하는 것이다(제2조제1호)."}],"개념":[{"종류":"표","제목":"중개업 관련 용어 정의","머리":["용어","정의의 핵심","조문"],"행":[["중개","중개대상물에 대한 매매·교환·임대차 등 권리 득실변경 행위의 알선","제2조제1호"],["공인중개사","공인중개사자격을 취득한 자(개설등록 여부 무관)","제2조제2호"],["중개업","다른 사람의 의뢰, 일정한 보수, 업으로 중개","제2조제3호"],["개업공인중개사","중개사무소 개설등록을 한 자(자격증 소지 여부는 요건이 아님)","제2조제4호"],["소속공인중개사","개업공인중개사 소속 공인중개사. 법인의 사원·임원인 공인중개사 포함. 중개업무 수행 또는 보조","제2조제5호"],["중개보조원","공인중개사 아닌 자로서 현장안내·일반서무 등 단순 업무 보조","제2조제6호"]]},{"종류":"표","제목":"이중등록·이중소속·사무소 설치 제한","머리":["금지 내용","조문","벌칙"],"행":[["이중으로 중개사무소 개설등록을 하여 중개업을 함","제12조제1항","제49조제1항 1년 이하 징역 또는 1천만원 이하 벌금(이중등록)"],["다른 개업공인중개사의 소속공인중개사·중개보조원 또는 법인의 사원·임원이 됨","제12조제2항","둘 이상의 중개사무소에 소속된 자는 제49조제1항 적용"],["등록관청 관할 구역 안에 중개사무소를 둘 이상 둠","제13조제1항","제49조제1항 1년 이하 징역 또는 1천만원 이하 벌금"],["천막 등 이동이 쉬운 임시 중개시설물을 설치함","제13조제2항","제49조제1항 1년 이하 징역 또는 1천만원 이하 벌금"]]}],"함정":"의뢰인도 무등록 업자와 함께 처벌받는다고 생각해 ③을 옳게 본다. 제48조제1호는 개설등록 없이 중개업을 한 자를 처벌하는 규정이고, 의뢰인은 대상이 아니다."},"30회-2차-004":{"한줄":"미채굴광물, 온천수, 금전채권, 점유는 모두 제3조와 시행령 제2조에 열거된 중개대상물이 아니어서 ㄱ, ㄴ, ㄷ, ㄹ이 정답이다.","근거":[{"법령":"공인중개사법","조문":"제3조","원문":"1. 토지 2. 건축물 그 밖의 토지의 정착물 3. 그 밖에 대통령령으로 정하는 재산권 및 물건"},{"법령":"공인중개사법 시행령","조문":"제2조","원문":"1. 「입목에 관한 법률」에 따른 입목 2. 「공장 및 광업재단 저당법」에 따른 공장재단 및 광업재단"},{"판례":"대법원 판례(중개대상물이 아닌 것)","요지":"금전채권과 영업상의 이점 같은 무형의 가치는 중개대상물이 아니다. 중개대상물은 법 제3조와 시행령 제2조로 한정된다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ, ㄹ도 중개대상물이 아니라 ㄱ, ㄴ만으로는 부족하다."},{"번호":2,"판정":"틀림","설명":"ㄱ, ㄴ도 중개대상물이 아니라 ㄷ, ㄹ만으로는 부족하다."},{"번호":3,"판정":"틀림","설명":"ㄷ(금전채권)이 빠져 있다."},{"번호":4,"판정":"틀림","설명":"ㄱ(미채굴광물)이 빠져 있다."},{"번호":5,"판정":"옳음","설명":"네 보기 모두 중개대상물에 해당하지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"미채굴광물은 중개대상물로 열거되지 않는다."},{"기호":"ㄴ","판정":"옳음","설명":"온천수는 중개대상물로 열거되지 않는다."},{"기호":"ㄷ","판정":"옳음","설명":"금전채권은 중개대상물이 아니다."},{"기호":"ㄹ","판정":"옳음","설명":"점유는 물건이나 열거된 재산권이 아니라서 중개대상물이 아니다."}],"개념":[{"종류":"표","제목":"중개대상물의 범위","머리":["대상","해당 여부","근거"],"행":[["토지(토지거래허가구역 토지, 가압류된 토지 포함)","해당","제3조제1호"],["건축물·정착물(미등기 건축물, 주벽을 갖춘 신축 중 건물)","해당","제3조제2호"],["입목법상 입목, 공장재단·광업재단","해당","시행령 제2조"],["동·호수가 특정되어 분양계약이 체결된 아파트 분양권","해당","판례"],["입주권(추첨 신청으로 분양예정자가 될 지위), 대토권","비해당","판례"],["영업시설·비품, 거래처·신용·점포 위치의 이점 등 무형의 가치","비해당","판례"],["금전채권(피담보채권 포함)","비해당","판례"]]}],"함정":"넷 모두 해당하지 않는 것을 고르는 문항이라 일부만 고르면 틀린다. 온천수와 미채굴광물은 땅에서 나오는 것이라 토지에 포함된다고 보기 쉽다."},"30회-2차-025":{"한줄":"포상금지급신청서를 받은 등록관청은 수사기관의 처분내용을 조회한 뒤 지급을 결정하고 결정일부터 1월 이내에 지급하므로 ④가 옳다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제28조제2항","원문":"제1항의 규정에 따라 포상금지급신청서를 제출받은 등록관청은 그 사건에 관한 수사기관의 처분내용을 조회한 후 포상금의 지급을 결정하고, 그 결정일부터 1월 이내에 포상금을 지급하여야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제36조의2제1항","원문":"법 제46조제1항의 규정에 따른 포상금은 1건당 50만원으로 한다."},{"법령":"공인중개사법 시행령","조문":"영 제36조의2제2항","원문":"제1항의 규정에 따른 포상금은 법 제46조제1항 각 호의 어느 하나에 해당하는 자가 행정기관에 의하여 발각되기 전에 등록관청이나 수사기관에 신고 또는 고발한 자에게 그 신고 또는 고발사건에 대하여 검사가 공소제기 또는 기소유예의 결정을 한 경우에 한하여 지급한다."},{"법령":"공인중개사법 시행령","조문":"영 제36조의2제3항","원문":"법 제46조제2항의 규정에 따라 포상금의 지급에 소요되는 비용 중 국고에서 보조할 수 있는 비율은 100분의 50이내로 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제28조제4항","원문":"등록관청은 하나의 사건에 대하여 2건 이상의 신고 또는 고발이 접수된 경우에는 최초로 신고 또는 고발한 자에게 포상금을 지급한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"포상금은 1건당 50만원이다(영 제36조의2제1항)."},{"번호":2,"판정":"틀림","설명":"검사가 공소제기 또는 기소유예의 결정을 한 경우에 포상금을 지급한다(영 제36조의2제2항). 기소유예도 지급 사유다."},{"번호":3,"판정":"틀림","설명":"포상금 지급 비용 중 보조할 수 있는 주체는 국고이고 비율은 100분의 50 이내다(영 제36조의2제3항). 시·도 보조가 아니다."},{"번호":4,"판정":"옳음","설명":"수사기관의 처분내용 조회 후 지급 결정, 결정일부터 1월 이내 지급이다(시행규칙 제28조제2항)."},{"번호":5,"판정":"틀림","설명":"하나의 사건에 2건 이상의 신고·고발이 접수되면 최초로 신고·고발한 자에게 지급한다(시행규칙 제28조제4항). 균등 배분은 2인 이상이 공동으로 신고·고발한 경우다(같은 조 제3항)."}],"개념":[{"종류":"표","제목":"포상금 지급 요건","머리":["구분","내용","조문"],"행":[["신고·고발 대상","무등록 중개업, 거짓·부정한 방법의 개설등록, 중개사무소등록증·공인중개사자격증의 양도·대여·양수·대여받음, 개업공인중개사가 아닌 자의 중개대상물 표시·광고, 제33조제1항제8호·제9호 행위, 제33조제2항의 업무방해","법 제46조제1항"],["지급 요건","행정기관에 발각되기 전에 등록관청·수사기관에 신고·고발하고, 검사가 공소제기 또는 기소유예 결정을 한 경우","영 제36조의2제2항"],["금액","1건당 50만원","영 제36조의2제1항"],["2인 이상 공동 신고·고발","균등 배분(미리 합의하여 신청하면 합의대로)","시행규칙 제28조제3항"],["2건 이상 접수","최초로 신고·고발한 자에게 지급","시행규칙 제28조제4항"],["국고 보조","지급 비용 중 100분의 50 이내","영 제36조의2제3항"]]},{"종류":"흐름","제목":"포상금 지급 절차","단계":[{"이름":"신고·고발","설명":"행정기관에 발각되기 전에 등록관청·수사기관에 신고 또는 고발"},{"이름":"신청","설명":"포상금지급신청서를 등록관청에 제출"},{"이름":"조회","설명":"등록관청이 그 사건에 관한 수사기관의 처분내용을 조회"},{"이름":"지급 결정","설명":"공소제기 또는 기소유예 결정이 있으면 지급 결정"},{"이름":"지급","설명":"결정일부터 1월 이내에 지급(1건당 50만원)"}]}],"함정":"⑤는 균등 배분 규정을 중복 신고에 잘못 붙였다. 균등 배분은 공동 신고·고발일 때이고 따로 접수된 중복 신고는 먼저 한 사람이 받는다. ③은 보조 주체가 시·도가 아니라 국고다."},"30회-2차-023":{"한줄":"공제사업 운용실적은 매 회계연도 종료 후 3개월 이내에 공시해야 하므로 6개월 이내라고 한 ⑤가 틀리다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제35조","원문":"협회는 법 제42조제5항에 따라 다음 각 호의 사항을 매 회계연도 종료 후 3개월 이내에 일간신문 또는 협회보에 공시하고 협회의 인터넷 홈페이지에 게시해야 한다."},{"법령":"공인중개사법","조문":"법 제42조제2항","원문":"협회는 제1항에 따른 공제사업을 하고자 하는 때에는 공제규정을 제정하여 국토교통부장관의 승인을 얻어야 한다. 공제규정을 변경하고자 하는 때에도 또한 같다."},{"법령":"공인중개사법","조문":"법 제42조의3","원문":"「금융위원회의 설치 등에 관한 법률」에 따른 금융감독원의 원장은 국토교통부장관의 요청이 있는 경우에는 공제사업에 관하여 조사 또는 검사를 할 수 있다."},{"법령":"공인중개사법","조문":"법 제42조제4항","원문":"협회는 공제사업을 다른 회계와 구분하여 별도의 회계로 관리하여야 하며, 책임준비금을 다른 용도로 사용하고자 하는 경우에는 국토교통부장관의 승인을 얻어야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제34조제3호","원문":"책임준비금의 적립비율 : 공제사고 발생률 및 공제금 지급액 등을 종합적으로 고려하여 정하되, 공제료 수입액의 100분의 10이상으로 정한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"공제규정을 제정하거나 변경하려면 국토교통부장관의 승인을 얻는다(법 제42조제2항)."},{"번호":2,"판정":"옳음","설명":"금융감독원장은 국토교통부장관의 요청이 있으면 공제사업을 조사하거나 검사할 수 있다(법 제42조의3)."},{"번호":3,"판정":"옳음","설명":"책임준비금을 다른 용도로 사용하려면 국토교통부장관의 승인을 얻는다(법 제42조제4항)."},{"번호":4,"판정":"옳음","설명":"책임준비금 적립비율은 공제사고 발생률과 공제금 지급액 등을 고려하되 공제료 수입액의 100분의 10 이상이다(영 제34조제3호)."},{"번호":5,"판정":"틀림","설명":"운용실적은 매 회계연도 종료 후 3개월 이내에 공시한다(영 제35조). 6개월이 아니다."}],"개념":[{"종류":"표","제목":"공제사업 규정 정리","머리":["항목","내용","조문"],"행":[["공제규정","제정·변경 시 국토교통부장관의 승인","법 제42조제2항"],["회계","다른 회계와 구분하여 별도 회계로 관리","법 제42조제4항"],["책임준비금","다른 용도로 사용하려면 국토교통부장관의 승인","법 제42조제4항"],["책임준비금 적립비율","공제료 수입액의 100분의 10 이상","영 제34조제3호"],["운용실적 공시","매 회계연도 종료 후 3개월 이내에 일간신문 또는 협회보에 공시하고 협회 홈페이지에 게시","영 제35조"],["조사·검사","국토교통부장관의 요청이 있으면 금융감독원장이 조사·검사","법 제42조의3"],["운영위원회","위원 19명 이내, 임기 2년에 1회 연임 가능","법 제42조의2제2항, 영 제35조의2제3항"],["재무건전성","지급여력비율 100분의 100 이상 유지","영 제35조의3제1항제1호"]]},{"종류":"흐름","제목":"공제사업 운영 절차","단계":[{"이름":"공제규정 제정","설명":"협회가 공제규정을 제정하거나 변경하려면 국토교통부장관의 승인(법 제42조제2항)"},{"이름":"운영","설명":"공제사업을 별도 회계로 관리, 책임준비금을 공제료 수입액의 100분의 10 이상 적립(법 제42조제4항, 영 제34조제3호)"},{"이름":"감독","설명":"운영위원회가 심의·감독하고, 국토교통부장관의 요청으로 금융감독원장이 조사·검사(법 제42조의2, 제42조의3)"},{"이름":"공시","설명":"매 회계연도 종료 후 3개월 이내에 일간신문 또는 협회보에 공시하고 홈페이지에 게시(영 제35조)"}]}],"함정":"⑤는 공시 기한을 6개월로 늘려 놓았다. 기한은 3개월이다. ④의 100분의 10은 하한이고 책임준비금 적립비율은 그 이상으로 정한다.","개정":"협회 명칭이 한국공인중개사협회로 정비되었다(법 제41조제1항, 개정 2026.2.27). ①, ③, ⑤는 이 명칭으로 고쳐 실었고 판단은 달라지지 않는다."},"30회-2차-020":{"한줄":"둘 이상의 중개사무소를 둔 경우는 법 제38조제2항제2호의 임의적 취소 사유라 절대적(필요적) 취소 사유가 아니므로 ⑤가 정답이다.","근거":[{"법령":"공인중개사법","조문":"법 제38조제2항제2호","원문":"제13조제1항의 규정을 위반하여 둘 이상의 중개사무소를 둔 경우"},{"법령":"공인중개사법","조문":"법 제38조제1항제1호","원문":"개인인 개업공인중개사가 사망하거나 개업공인중개사인 법인이 해산한 경우"},{"법령":"공인중개사법","조문":"법 제38조제1항제7호","원문":"업무정지기간 중에 중개업무를 하거나 자격정지처분을 받은 소속공인중개사로 하여금 자격정지기간 중에 중개업무를 하게 한 경우"},{"법령":"공인중개사법","조문":"법 제38조제1항제2호","원문":"거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 경우"},{"법령":"공인중개사법","조문":"법 제38조제1항제3호","원문":"제10조제1항제2호부터 제6호까지 또는 같은 항 제11호ㆍ제12호에 따른 결격사유에 해당하게 된 경우. 다만, 같은 항 제12호에 따른 결격사유에 해당하는 경우로서 그 사유가 발생한 날부터 2개월 이내에 그 사유를 해소한 경우에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법인이 해산하면 등록을 취소해야 한다(법 제38조제1항제1호). 절대적 취소 사유다."},{"번호":2,"판정":"옳음","설명":"자격정지 중인 소속공인중개사에게 중개업무를 하게 한 경우는 절대적 취소 사유다(법 제38조제1항제7호)."},{"번호":3,"판정":"옳음","설명":"거짓이나 그 밖의 부정한 방법으로 개설등록을 한 경우는 절대적 취소 사유다(법 제38조제1항제2호)."},{"번호":4,"판정":"옳음","설명":"법인이 아닌 개업공인중개사가 파산선고를 받고 복권되지 않은 경우는 결격사유(제10조제1항제3호)라 등록을 취소해야 한다(제38조제1항제3호)."},{"번호":5,"판정":"틀림","설명":"둘 이상의 중개사무소를 둔 경우는 임의적 취소 사유다(법 제38조제2항제2호). 이중등록(제1항제4호)과 구별한다."}],"개념":[{"종류":"표","제목":"중개사무소 개설등록 취소 사유","머리":["구분","사유","조문"],"행":[["필요적 취소","개인인 개업공인중개사의 사망, 법인의 해산","법 제38조제1항제1호"],["필요적 취소","거짓이나 그 밖의 부정한 방법으로 개설등록","제1항제2호"],["필요적 취소","결격사유 해당(제10조제1항제2호~제6호, 제11호, 제12호)","제1항제3호"],["필요적 취소","이중등록","제1항제4호"],["필요적 취소","다른 개업공인중개사의 소속공인중개사·중개보조원 또는 법인의 사원·임원이 된 경우","제1항제5호"],["필요적 취소","중개보조원 고용 상한(개업공인중개사와 소속공인중개사 합산 수의 5배) 초과","제1항제5호의2"],["필요적 취소","자기의 성명·상호를 사용하여 중개업무를 하게 하거나 등록증을 양도·대여","제1항제6호"],["필요적 취소","업무정지기간 중 중개업무, 자격정지 중인 소속공인중개사에게 중개업무를 하게 함","제1항제7호"],["필요적 취소","최근 1년 이내 2회 이상 업무정지처분을 받고 다시 업무정지 해당 행위","제1항제8호"],["임의적 취소","등록기준 미달, 둘 이상의 중개사무소, 임시 중개시설물, 겸업 위반","법 제38조제2항제1호~제4호"],["임의적 취소","6개월 초과 휴업, 정보 비공개 위반, 거래계약서 거짓 기재, 손해배상 보장조치 미이행, 금지행위","제2항제5호~제9호"],["임의적 취소","최근 1년 이내 3회 이상 업무정지 또는 과태료 처분을 받고 다시 업무정지 또는 과태료 처분 해당 행위(제1항제8호 해당 제외)","제2항제10호"],["임의적 취소","사업자단체 또는 구성원이 공정거래법 위반으로 최근 2년 이내 2회 이상 처분","제2항제11호"]]},{"종류":"표","제목":"최근 1년 이내 처분 횟수와 제재","머리":["받은 처분","다시 한 행위","제재","조문"],"행":[["업무정지 2회 이상","업무정지 해당 행위","등록취소(필요적)","법 제38조제1항제8호"],["업무정지 또는 과태료 3회 이상(위 경우 제외)","업무정지 또는 과태료 해당 행위","등록취소(임의적)","법 제38조제2항제10호"],["업무정지 또는 과태료 2회 이상","과태료 해당 행위","업무정지(임의적, 6개월)","법 제39조제1항제12호, 시행규칙 별표 4"]]}],"함정":"이중등록(제12조 위반, 필요적 취소)과 둘 이상의 중개사무소 설치(제13조 위반, 임의적 취소)는 이름이 비슷하다. 두 사무소를 두면 취소할 수 있을 뿐이다. 임시 중개시설물 설치, 겸업 위반도 같은 임의적 취소 사유다."},"30회-2차-024":{"한줄":"시·도지사는 자격취소처분을 한 때 5일 이내에 국토교통부장관과 다른 시·도지사에게 통보해야 하므로 ②가 옳다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제29조제3항","원문":"시ㆍ도지사는 공인중개사의 자격취소처분을 한 때에는 5일 이내에 이를 국토교통부장관과 다른 시ㆍ도지사에게 통보해야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제29조제1항","원문":"법 제35조의 규정에 따른 공인중개사의 자격취소처분 및 법 제36조의 규정에 따른 자격정지처분은 그 공인중개사자격증(이하 \"자격증\"이라 한다)을 교부한 시ㆍ도지사가 행한다."},{"법령":"공인중개사법","조문":"법 제35조제2항","원문":"시ㆍ도지사는 제1항에 따라 공인중개사의 자격을 취소하고자 하는 경우에는 청문을 실시하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제21조","원문":"법 제35조제3항의 규정에 따라 공인중개사자격증을 반납하고자 하는 자는 자격취소처분을 받은 날부터 7일 이내에 그 공인중개사자격증을 교부한 시ㆍ도지사에게 공인중개사자격증을 반납하여야 한다."},{"법령":"공인중개사법","조문":"법 제35조제4항","원문":"분실 등의 사유로 인하여 제3항에 따라 공인중개사자격증을 반납할 수 없는 자는 제3항에도 불구하고 자격증 반납을 대신하여 그 이유를 기재한 사유서를 시ㆍ도지사에게 제출하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"자격취소처분은 자격증을 교부한 시·도지사가 한다(영 제29조제1항). 현주소지 시장·군수·구청장이 아니다."},{"번호":2,"판정":"옳음","설명":"자격취소처분을 한 때에는 5일 이내에 국토교통부장관과 다른 시·도지사에게 통보한다(영 제29조제3항)."},{"번호":3,"판정":"틀림","설명":"자격을 취소하려면 청문을 실시해야 한다(법 제35조제2항). 생략할 수 없다."},{"번호":4,"판정":"틀림","설명":"자격증은 자격증을 교부한 시·도지사에게 처분을 받은 날부터 7일 이내에 반납한다(시행규칙 제21조). 한국산업인력공단이 아니다."},{"번호":5,"판정":"틀림","설명":"분실 등으로 반납할 수 없으면 반납을 대신하여 그 이유를 적은 사유서를 시·도지사에게 제출한다(법 제35조제4항). 재발급받아 반납하는 절차가 없다."}],"개념":[{"종류":"표","제목":"공인중개사 자격취소 사유(법 제35조제1항)","머리":["호","사유"],"행":[["1","부정한 방법으로 공인중개사의 자격을 취득한 경우"],["2","다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도·대여한 경우"],["3","자격정지처분을 받고 그 정지기간 중에 중개업무를 행한 경우(다른 개업공인중개사의 소속공인중개사·중개보조원 또는 법인인 개업공인중개사의 사원·임원이 되는 경우 포함)"],["4","이 법 또는 공인중개사의 직무와 관련하여 형법 제114조, 제231조, 제234조, 제347조, 제355조 또는 제356조를 위반하여 금고 이상의 형(집행유예 포함)을 선고받은 경우"]]},{"종류":"흐름","제목":"자격취소 절차","단계":[{"이름":"청문","설명":"시·도지사가 자격을 취소하려면 청문을 실시(법 제35조제2항)"},{"이름":"처분","설명":"자격증을 교부한 시·도지사가 처분. 사무소 소재지 시·도지사와 다르면 사무소 소재지 시·도지사가 절차를 모두 이행한 후 교부한 시·도지사에게 통보(영 제29조제1항·제2항)"},{"이름":"통보","설명":"취소처분을 한 때 5일 이내에 국토교통부장관과 다른 시·도지사에게 통보(영 제29조제3항)"},{"이름":"반납","설명":"처분을 받은 날부터 7일 이내에 자격증을 교부한 시·도지사에게 반납. 분실 등이면 사유서 제출(시행규칙 제21조, 법 제35조제4항)"},{"이름":"미반납 제재","설명":"반납·사유서 제출 의무 위반 시 100만원 이하 과태료(법 제51조제3항제6호), 시·도지사가 부과"}]}],"함정":"③은 청문이 필수라는 점을, ④는 반납 상대(교부한 시·도지사)를 놓치면 옳게 보인다. ⑤는 분실한 경우 사유서 제출로 반납을 갈음한다.","개정":"시·도지사의 자격취소 통보는 5일 이내에 국토교통부장관과 다른 시·도지사에게 통보하는 것으로 정해져 있다(영 제29조제3항, 개정 2023.11.16). ②는 문구를 현행 통보로 맞춰 실었고 판단은 달라지지 않는다."},"30회-2차-026":{"한줄":"공제업무 개선명령 불이행의 과태료는 400만원으로 휴업 재개 미신고(20만원), 이전신고 미이행(30만원), 등록증 미게시(30만원), 휴업기간 변경 미신고(20만원)보다 크다.","근거":[{"법령":"공인중개사법","조문":"법 제51조제2항제8호","원문":"제42조의4에 따른 공제업무의 개선명령을 이행하지 아니한 자"},{"법령":"공인중개사법 시행령","조문":"영 별표 2 차목","원문":"법 제42조의4에 따른 공제업무의 개선명령을 이행하지 않은 경우: 과태료 400만원"},{"법령":"공인중개사법 시행령","조문":"영 별표 2 더목","원문":"법 제21조제1항을 위반하여 휴업, 폐업, 휴업한 중개업의 재개 또는 휴업기간의 변경 신고를 하지 않은 경우: 과태료 20만원"},{"법령":"공인중개사법 시행령","조문":"영 별표 2 너목","원문":"법 제20조제1항을 위반하여 중개사무소의 이전신고를 하지 않은 경우: 과태료 30만원"},{"법령":"공인중개사법 시행령","조문":"영 별표 2 파목","원문":"법 제17조를 위반하여 중개사무소등록증 등을 게시하지 않은 경우: 과태료 30만원"}],"선지":[{"번호":1,"판정":"-","설명":"400만원. 다섯 가운데 가장 큰 금액이다."},{"번호":2,"판정":"-","설명":"20만원. 휴업한 중개업의 재개 신고를 하지 않은 경우다."},{"번호":3,"판정":"-","설명":"30만원. 중개사무소 이전신고를 하지 않은 경우다."},{"번호":4,"판정":"-","설명":"30만원. 중개사무소등록증을 게시하지 않은 경우다."},{"번호":5,"판정":"-","설명":"20만원. 휴업기간의 변경 신고를 하지 않은 경우다. 재개 신고 위반과 금액이 같다."}],"개념":[{"종류":"표","제목":"과태료 금액(영 별표 2)","머리":["위반행위","과태료"],"행":[["공제업무 개선명령 불이행","400만원"],["임원 징계·해임 요구·시정명령 불이행","400만원"],["부동산거래정보망 운영규정 위반","400만원"],["공제사업 운용실적 미공시","300만원"],["확인·설명 불성실 또는 근거자료 미제시","250만원 또는 500만원"],["연수교육 미이수","위반 기간별 20만원~100만원"],["사무소 명칭 위반, 등록증 미반납","50만원"],["등록증 미게시, 이전신고, 손해배상 설명 위반, 자격증 미반납","30만원"],["휴업·폐업·재개·휴업기간 변경 미신고","20만원"]]},{"종류":"표","제목":"과태료 부과·징수권자(법 제51조제5항)","머리":["부과권자","과태료 사유","조문"],"행":[["국토교통부장관","인터넷 광고 모니터링 자료 제출·조치 요구 불이행, 부동산거래정보망 운영규정 위반, 거래정보사업자의 보고·검사 거부, 공제사업 운용실적 미공시, 공제 개선명령 불이행, 임원 징계·해임 요구 불이행, 협회 조사·검사 거부","제2항제1호의2·제1호의3·제1호의5·제6호~제8호·제8호의2·제9호"],["시·도지사","연수교육 미이수, 공인중개사자격증 미반납·사유서 미제출","제2항제5호의2, 제3항제6호"],["등록관청","부당 표시·광고, 중개보조원 신분 미고지, 확인·설명 불성실, 등록증 미게시, 사무소 명칭 위반, 표시·광고 위반, 이전신고·휴업·폐업·재개·휴업기간 변경 미신고, 손해배상책임 설명·증서 교부 위반, 등록증 미반납","제2항제1호·제1호의4·제1호의6, 제3항제1호~제5호·제7호"]]}],"함정":"금액이 큰 쪽은 국토교통부장관이 부과하는 협회·공제 관련 과태료(300만원~400만원)이고, 중개사무소 관련 신고·게시 의무는 20만원~50만원 수준이다. 신고 위반 중에서도 이전신고(30만원)는 휴업·폐업·재개·변경 신고(20만원)보다 크다.","개정":"협회 명칭이 한국공인중개사협회로 정비되었다(법 제41조제1항, 개정 2026.2.27). 금액은 달라지지 않았다."},"30회-2차-003":{"한줄":"시험시행기관장은 시험에서 부정한 행위를 한 응시자의 시험을 무효로 하고 처분일부터 5년간 응시자격을 정지하므로 ④가 옳다.","근거":[{"법령":"공인중개사법","조문":"법 제4조의3","원문":"제4조제1항 및 제2항에 따라 시험을 시행하는 시ㆍ도지사 또는 국토교통부장관(이하 \"시험시행기관장\"이라 한다)은 시험에서 부정한 행위를 한 응시자에 대하여는 그 시험을 무효로 하고, 그 처분이 있은 날부터 5년간 시험응시자격을 정지한다. 이 경우 시험시행기관장은 지체 없이 이를 다른 시험시행기관장에게 통보하여야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제3조","원문":"국토교통부장관이 법 제4조제2항에 따라 직접 시험문제를 출제하거나 시험을 시행하려는 경우에는 심의위원회의 의결을 미리 거쳐야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제3조제2항","원문":"법 제5조제3항의 규정에 따라 공인중개사자격증의 재교부를 신청하는 자는 별지 제4호서식의 재교부신청서를 자격증을 교부한 시ㆍ도지사에게 제출하여야 한다."},{"법령":"공인중개사법","조문":"법 제5조제2항","원문":"시ㆍ도지사는 제1항에 따른 합격자에게 국토교통부령으로 정하는 바에 따라 공인중개사자격증을 교부하여야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제7조제2항","원문":"시험시행기관장은 법 제4조에 따라 시험을 시행하려는 때에는 예정 시험일시ㆍ시험방법 등 시험시행에 관한 개략적인 사항을 매년 2월 말일까지 「신문 등의 진흥에 관한 법률」 제2조제1호가목에 따른 일반일간신문(이하 \"일간신문\"이라 한다), 관보, 방송 중 하나 이상에 공고하고, 인터넷 홈페이지 등에도 이를 공고해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"국토교통부장관이 직접 시험문제를 출제하거나 시험을 시행하려면 심의위원회의 의결을 미리 거쳐야 한다(영 제3조)."},{"번호":2,"판정":"틀림","설명":"재교부신청서는 자격증을 교부한 시·도지사에게 제출한다(시행규칙 제3조제2항). 국토교통부장관이 아니다."},{"번호":3,"판정":"틀림","설명":"자격증은 시·도지사가 합격자에게 교부한다(법 제5조제2항). 국토교통부장관이 교부하지 않는다."},{"번호":4,"판정":"옳음","설명":"부정한 행위를 한 응시자는 시험이 무효가 되고 그 처분일부터 5년간 응시자격이 정지된다(법 제4조의3)."},{"번호":5,"판정":"틀림","설명":"시험 개략 공고는 매년 2월 말일까지 일간신문, 관보, 방송 중 하나 이상에 하고 인터넷 홈페이지에도 공고한다(영 제7조제2항). 전년도 12월 31일, 관보 및 일간신문 모두가 아니다."}],"개념":[{"종류":"표","제목":"자격시험·자격증 규정","머리":["항목","내용","조문"],"행":[["시험 시행","시·도지사가 시행. 국토교통부장관이 직접 출제·시행하려면 심의위원회 의결을 미리 거침","법 제4조, 영 제3조"],["시험 미시행","부득이한 사정이 있으면 심의위원회 의결을 거쳐 당해연도 시험을 시행하지 않을 수 있음","영 제7조제1항"],["시행 공고","예정 시험일시·방법 등 개략적 사항을 매년 2월 말일까지 일간신문·관보·방송 중 하나 이상에 공고하고 인터넷 홈페이지에도 공고","영 제7조제2항"],["세부 공고","시험일시·장소·방법 등을 시험시행일 90일 전까지 공고","영 제7조제3항"],["부정행위자","시험 무효, 처분일부터 5년간 응시자격 정지","법 제4조의3"],["자격증 교부","시·도지사가 합격자 결정 공고일부터 1개월 이내에 자격증교부대장 기재 후 교부","법 제5조제2항, 시행규칙 제3조제1항"],["자격증 재교부","자격증을 교부한 시·도지사에게 신청","법 제5조제3항, 시행규칙 제3조제2항"],["자격 결격","자격취소 후 3년이 지나지 않은 자는 공인중개사가 될 수 없음","법 제6조"],["자격증 대여 등 금지","성명 사용 허락, 자격증 양도·대여, 양수·대여받음, 알선 금지","법 제7조"]]},{"종류":"표","제목":"공인중개사 정책심의위원회","머리":["항목","내용","조문"],"행":[["설치","국토교통부에 둘 수 있음","법 제2조의2제1항"],["심의사항","① 공인중개사의 시험 등 자격취득, ② 부동산 중개업의 육성, ③ 중개보수 변경, ④ 손해배상책임의 보장 등","법 제2조의2제1항제1호~제4호"],["시·도지사 구속력","심의사항 중 제1호(시험 등 자격취득)에 한해 시·도지사가 따라야 함","법 제2조의2제3항"],["구성","위원장 1명 포함 7명 이상 11명 이내","영 제1조의2제1항"],["위원장","국토교통부 제1차관","영 제1조의2제2항"],["위원 임기","위원장 제외 위원 2년(보궐위원은 전임자 잔여기간)","영 제1조의2제3항"],["제척","위원이 안건에 증언·진술·자문·조사·연구·용역·감정을 한 경우 등","영 제1조의3제1항"],["기피","당사자가 신청하고 심의위원회가 의결로 결정(대상 위원은 참여 불가)","영 제1조의3제2항"],["위원장 직무대행","위원장이 미리 지명한 위원","영 제1조의4제2항"],["회의","재적위원 과반수 출석으로 개의, 출석위원 과반수 찬성으로 의결","영 제1조의5제2항"]]}],"함정":"⑤의 공고 시한과 매체가 함정이다. 시한은 매년 2월 말일이고 매체는 일간신문·관보·방송 중 하나 이상이다(홈페이지 공고도 함께). 자격증 교부와 재교부는 모두 시·도지사 사무다(②, ③)."},"30회-2차-008":{"한줄":"위원장이 부득이한 사유로 직무를 수행할 수 없을 때는 위원장이 미리 지명한 위원이 대행하며 부위원장 제도가 없으므로 ④가 틀리다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제1조의4제2항","원문":"위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다."},{"법령":"공인중개사법","조문":"법 제2조의2제1항","원문":"공인중개사의 업무에 관한 다음 각 호의 사항을 심의하기 위하여 국토교통부에 공인중개사 정책심의위원회를 둘 수 있다."},{"법령":"공인중개사법 시행령","조문":"영 제1조의2제1항","원문":"「공인중개사법」(이하 \"법\"이라 한다) 제2조의2제1항에 따른 공인중개사 정책심의위원회(이하 \"심의위원회\"라 한다)는 위원장 1명을 포함하여 7명 이상 11명 이내의 위원으로 구성한다."},{"법령":"공인중개사법 시행령","조문":"영 제1조의3제1항제3호","원문":"위원이 해당 안건에 대하여 증언, 진술, 자문, 조사, 연구, 용역 또는 감정을 한 경우"},{"법령":"공인중개사법 시행령","조문":"영 제1조의5제2항","원문":"심의위원회의 회의는 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"국토교통부에 심의위원회를 둘 수 있다(법 제2조의2제1항)."},{"번호":2,"판정":"옳음","설명":"심의위원회는 위원장 1명을 포함하여 7명 이상 11명 이내의 위원으로 구성한다(영 제1조의2제1항)."},{"번호":3,"판정":"옳음","설명":"위원이 해당 안건에 대하여 자문을 한 경우 심의·의결에서 제척된다(영 제1조의3제1항제3호)."},{"번호":4,"판정":"틀림","설명":"위원장이 직무를 수행할 수 없을 때는 위원장이 미리 지명한 위원이 대행한다(영 제1조의4제2항). 부위원장이 대행하는 것이 아니다."},{"번호":5,"판정":"옳음","설명":"재적위원 과반수의 출석으로 개의하고 출석위원 과반수의 찬성으로 의결한다(영 제1조의5제2항)."}],"개념":[{"종류":"표","제목":"공인중개사 정책심의위원회","머리":["항목","내용","조문"],"행":[["설치","국토교통부에 둘 수 있음","법 제2조의2제1항"],["심의사항","① 공인중개사의 시험 등 자격취득, ② 부동산 중개업의 육성, ③ 중개보수 변경, ④ 손해배상책임의 보장 등","법 제2조의2제1항제1호~제4호"],["시·도지사 구속력","심의사항 중 제1호(시험 등 자격취득)에 한해 시·도지사가 따라야 함","법 제2조의2제3항"],["구성","위원장 1명 포함 7명 이상 11명 이내","영 제1조의2제1항"],["위원장","국토교통부 제1차관","영 제1조의2제2항"],["위원 임기","위원장 제외 위원 2년(보궐위원은 전임자 잔여기간)","영 제1조의2제3항"],["제척","위원이 안건에 증언·진술·자문·조사·연구·용역·감정을 한 경우 등","영 제1조의3제1항"],["기피","당사자가 신청하고 심의위원회가 의결로 결정(대상 위원은 참여 불가)","영 제1조의3제2항"],["위원장 직무대행","위원장이 미리 지명한 위원","영 제1조의4제2항"],["회의","재적위원 과반수 출석으로 개의, 출석위원 과반수 찬성으로 의결","영 제1조의5제2항"]]}],"함정":"직무 대행자를 부위원장으로 쓰는 것은 다른 위원회의 일반적인 구조에서 온 착각이다. 이 위원회는 부위원장을 두지 않고 위원장이 미리 지명한 위원이 대행한다. 공제사업 운영위원회는 반대로 위원장·부위원장을 호선하고 부위원장이 대행한다(영 제35조의2제6항)."},"30회-2차-002":{"한줄":"이 법 위반 벌금형이 결격이 되는 금액은 300만원 이상이라서 200만원 벌금형은 결격사유에 해당하지 않는다.","근거":[{"법령":"공인중개사법","조문":"법 제10조제1항제11호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 이 법을 위반하여 300만원 이상의 벌금형의 선고를 받고 3년이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"법 제10조제1항제4호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 금고 이상의 실형의 선고를 받고 그 집행이 종료(집행이 종료된 것으로 보는 경우를 포함한다)되거나 집행이 면제된 날부터 3년이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"법 제10조제1항제6호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 제35조제1항에 따라 공인중개사의 자격이 취소된 후 3년이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"법 제10조제1항제10호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 제39조에 따라 업무정지처분을 받은 개업공인중개사인 법인의 업무정지의 사유가 발생한 당시의 사원 또는 임원이었던 자로서 해당 개업공인중개사에 대한 업무정지기간이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"법 제10조제1항제7호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 제36조제1항에 따라 공인중개사의 자격이 정지된 자로서 자격정지기간중에 있는 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"이 법 위반 벌금형은 300만원 이상이어야 결격이다. 200만원은 해당하지 않는다(법 제10조제1항제11호)."},{"번호":2,"판정":"옳음","설명":"금고 이상의 실형은 집행 종료·면제일부터 3년이 지나지 않으면 결격이다(법 제10조제1항제4호)."},{"번호":3,"판정":"옳음","설명":"자격이 취소된 후 3년이 지나지 않으면 결격이다(법 제10조제1항제6호)."},{"번호":4,"판정":"옳음","설명":"업무정지처분을 받은 법인의 정지 사유 발생 당시 사원·임원이었던 자는 법인의 업무정지기간이 지나기 전까지 결격이다(법 제10조제1항제10호)."},{"번호":5,"판정":"옳음","설명":"자격정지기간 중에 있는 자는 결격이다(법 제10조제1항제7호)."}],"개념":[{"종류":"표","제목":"결격 기간 비교(법 제10조제1항)","머리":["사유","기산 시점","기간"],"행":[["금고 이상의 실형(제4호)","집행 종료·집행 면제일","3년"],["금고 이상의 집행유예(제5호)","유예기간 만료일","2년(유예기간 중 포함)"],["이 법 위반 300만원 이상 벌금형(제11호)","선고일","3년"],["공인중개사 자격취소(제6호)","취소일","3년"],["개설등록 취소(제8호)","취소일","3년(법 제40조제3항 취소는 폐업기간 공제)"],["자격정지(제7호)","-","자격정지기간 중"],["업무정지 후 폐업(제9호)","-","업무정지기간이 지나기 전"]]},{"종류":"표","제목":"결격자의 범위와 제재(법 제10조, 제38조, 제39조)","머리":["구분","내용","근거"],"행":[["개설등록 불가","제10조제1항 제1호~제12호","법 제10조제1항"],["소속공인중개사·중개보조원 불가","제10조제1항 제1호~제11호(법인에 관한 제12호 제외)","법 제10조제2항"],["결격자를 고용한 개업공인중개사","업무정지 가능. 사유 발생일부터 2개월 이내 해소하면 제외","법 제39조제1항제1호"],["등록 후 결격 발생","등록 취소. 제12호(법인)는 사유 발생일부터 2개월 이내 해소하면 제외","법 제38조제1항제3호"]]}],"함정":"이 법 위반 벌금형은 300만원 이상이 기준이다(①의 200만원은 미달). 나머지는 실형·자격취소 후 3년, 법인의 업무정지 당시 사원·임원, 자격정지기간 중이라는 열거 사유 그대로다."},"30회-2차-018":{"한줄":"분사무소설치신고확인서 재교부 신청, 개설등록 신청, 분사무소 설치 신고는 조례 수수료 대상이고, 국토교통부장관이 시행하는 시험은 아니다.","근거":[{"법령":"공인중개사법","조문":"법 제47조제1항","원문":"다음 각 호의 어느 하나에 해당하는 자는 해당 지방자치단체의 조례로 정하는 바에 따라 수수료를 납부하여야 한다. 다만, 공인중개사자격시험을 제4조제2항의 규정에 따라 국토교통부장관이 시행하는 경우 제1호에 해당하는 자는 국토교통부장관이 결정ㆍ공고하는 수수료를 납부하여야 한다. 1. 제4조에 따른 공인중개사자격시험에 응시하는 자 2. 제5조제3항에 따라 공인중개사자격증의 재교부를 신청하는 자 3. 제9조제1항에 따라 중개사무소의 개설등록을 신청하는 자 4. 제11조제2항에 따라 중개사무소등록증의 재교부를 신청하는 자 5. 제13조제3항에 따라 분사무소설치의 신고를 하는 자 6. 제13조제5항에 따라 분사무소설치신고확인서의 재교부를 신청하는 자"},{"법령":"공인중개사법","조문":"법 제47조제2항","원문":"제4조에 따른 공인중개사자격시험 또는 제5조제3항에 따른 공인중개사자격증 재교부업무를 제45조의 규정에 따라 위탁한 경우에는 해당 업무를 위탁받은 자가 위탁한 자의 승인을 얻어 결정ㆍ공고하는 수수료를 각각 납부하여야 한다."},{"법령":"공인중개사법","조문":"법 제13조제5항","원문":"제5조제3항은 제4항에 따른 신고확인서의 재교부에 관하여 이를 준용한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄴ은 조례 수수료 대상이 아니고 ㄷ, ㄹ이 빠졌다."},{"번호":2,"판정":"틀림","설명":"ㄴ은 조례 수수료 대상이 아니고 ㄷ이 빠졌다."},{"번호":3,"판정":"옳음","설명":"ㄱ, ㄷ, ㄹ이 조례로 정한 수수료를 내는 경우다."},{"번호":4,"판정":"틀림","설명":"ㄴ은 조례 수수료 대상이 아니고 ㄱ이 빠졌다."},{"번호":5,"판정":"틀림","설명":"ㄴ은 조례 수수료 대상이 아니다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"분사무소설치신고확인서의 재교부를 신청하는 자는 수수료를 낸다(법 제47조제1항제6호)."},{"기호":"ㄴ","판정":"틀림","설명":"국토교통부장관이 시행하는 시험의 응시자는 조례가 아니라 장관이 결정·공고하는 수수료를 낸다(법 제47조제1항 단서)."},{"기호":"ㄷ","판정":"옳음","설명":"개설등록을 신청하는 자는 수수료를 낸다(법 제47조제1항제3호)."},{"기호":"ㄹ","판정":"옳음","설명":"분사무소 설치 신고를 하는 자는 수수료를 낸다(법 제47조제1항제5호)."}],"개념":[{"종류":"표","제목":"수수료 납부 대상(법 제47조제1항)","머리":["호","납부 대상","수수료 결정"],"행":[["1","공인중개사자격시험 응시","지방자치단체 조례(국토교통부장관이 시행하는 시험은 장관이 결정·공고)"],["2","공인중개사자격증 재교부 신청","조례"],["3","중개사무소 개설등록 신청","조례"],["4","중개사무소등록증 재교부 신청","조례"],["5","분사무소 설치 신고","조례"],["6","분사무소설치신고확인서 재교부 신청","조례"]]},{"종류":"표","제목":"응시수수료의 반환(영 제8조제2항, 시행규칙 제2조제2항)","머리":["사유","반환액"],"행":[["수수료를 과오납한 경우","과오납한 금액 전부"],["시험시행기관의 귀책사유로 응시하지 못한 경우","납입 수수료 전부"],["응시원서 접수기간 내 접수 취소","납입 수수료 전부"],["접수마감일 다음 날부터 7일 이내 접수 취소","납입 수수료의 100분의 60"],["그 이후 시험시행일 10일 전까지 접수 취소","납입 수수료의 100분의 50"]]}],"함정":"자격시험 응시수수료는 시험을 국토교통부장관이 시행하면 장관이 결정·공고하는 수수료를 낸다. 이 경우는 조례 수수료가 아니다(ㄴ).","개정":"보기 ㄱ의 \"분사무소설치신고필증\"은 현행 법령의 용어인 \"분사무소설치신고확인서\"로 고쳐 실었다(법 제13조제4항·제5항, 제47조제1항제6호)."},"30회-2차-005":{"한줄":"법 제13조는 중개사무소를 두는 지역만 정할 뿐이고 관할구역 밖에 있는 중개대상물의 중개를 막는 조문은 없어 ④가 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제13조제1항","원문":"개업공인중개사는 그 등록관청의 관할 구역안에 중개사무소를 두되, 1개의 중개사무소만을 둘 수 있다."},{"법령":"공인중개사법","조문":"법 제13조제2항","원문":"개업공인중개사는 천막 그 밖에 이동이 용이한 임시 중개시설물을 설치하여서는 아니된다."},{"법령":"공인중개사법","조문":"법 제13조제3항","원문":"제1항에도 불구하고 법인인 개업공인중개사는 대통령령으로 정하는 기준과 절차에 따라 등록관청에 신고하고 그 관할 구역 외의 지역에 분사무소를 둘 수 있다."},{"법령":"공인중개사법","조문":"법 제9조제1항","원문":"중개업을 영위하려는 자는 국토교통부령으로 정하는 바에 따라 중개사무소(법인의 경우에는 주된 중개사무소를 말한다)를 두려는 지역을 관할하는 시장(구가 설치되지 아니한 시의 시장과 특별자치도 행정시의 시장을 말한다. 이하 같다)ㆍ군수 또는 구청장(이하 \"등록관청\"이라 한다)에게 중개사무소의 개설등록을 하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"개업공인중개사는 등록관청의 관할구역 안에 1개의 중개사무소만 둘 수 있다(법 제13조제1항)."},{"번호":2,"판정":"옳음","설명":"천막 그 밖에 이동이 용이한 임시 중개시설물은 설치할 수 없다(법 제13조제2항)."},{"번호":3,"판정":"옳음","설명":"분사무소는 법인인 개업공인중개사만 둘 수 있다(법 제13조제3항)."},{"번호":4,"판정":"틀림","설명":"사무소의 설치 지역을 정한 조문(법 제13조제1항)과 달리 중개대상물의 소재지를 관할구역으로 제한하는 조문은 없다."},{"번호":5,"판정":"옳음","설명":"법인은 신고하고 관할 구역 외의 지역에 분사무소를 둘 수 있다(법 제13조제3항)."}],"개념":[{"종류":"표","제목":"중개사무소의 설치(법 제13조)","머리":["항목","내용","위반 시"],"행":[["개수","등록관청 관할구역 안에 1개만","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제4호), 등록취소 가능"],["임시 시설물","천막 등 이동이 용이한 임시 중개시설물 설치 금지","제49조제1항제5호, 등록취소 가능(제38조제2항제3호)"],["분사무소","법인인 개업공인중개사만 신고하고 관할 구역 밖에 설치","-"],["공동 사용","다른 개업공인중개사와 공동 사용 가능. 업무정지기간 중 일정한 경우 제한","-"],["중개 지역","사무소를 두는 지역만 정하고 중개대상물의 소재지는 제한하지 않음","-"]]},{"종류":"표","제목":"분사무소 설치(법 제13조제3항, 영 제15조)","머리":["항목","내용","근거"],"행":[["설치 주체","법인인 개업공인중개사","법 제13조제3항"],["설치 지역","주된 사무소 소재지가 속한 시·군·구를 제외한 시·군·구, 시·군·구별 1개소","영 제15조제1항"],["책임자","공인중개사. 다른 법률에 따라 중개업을 하는 법인의 분사무소는 예외","영 제15조제2항"],["신고처","주된 사무소 소재지 관할 등록관청","영 제15조제3항"],["첨부서류","책임자 실무교육 수료확인증 사본, 보증 설정 증명서류, 사용권 확보 증명서류","영 제15조제3항제3호~제5호"],["신고확인서","적합하면 신고확인서를 교부하고 설치예정지역 관할 시장·군수·구청장에게 통보","법 제13조제4항"],["보증","분사무소마다 2억원 이상 추가 설정","영 제24조제1항제1호"]]}],"함정":"제한되는 것은 사무소를 두는 장소다. 중개 대상 부동산의 소재지는 등록관청 관할과 무관하다."},"30회-2차-007":{"한줄":"소속공인중개사의 미등록 인장 사용은 시·도지사의 자격정지 사유이고, 업무정지는 개업공인중개사 대상이며 범위도 6개월이므로 ②가 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제36조제1항제2호","원문":"시ㆍ도지사는 공인중개사가 소속공인중개사로서 업무를 수행하는 기간 중에 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위 안에서 기간을 정하여 그 자격을 정지할 수 있다. 제16조의 규정을 위반하여 인장등록을 하지 아니하거나 등록하지 아니한 인장을 사용한 경우"},{"법령":"공인중개사법","조문":"법 제39조제1항제2호","원문":"등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위 안에서 기간을 정하여 업무의 정지를 명할 수 있다. 이 경우 법인인 개업공인중개사에 대하여는 법인 또는 분사무소별로 업무의 정지를 명할 수 있다. 제16조의 규정을 위반하여 인장등록을 하지 아니하거나 등록하지 아니한 인장을 사용한 경우"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제9조제2항","원문":"제1항의 규정에 따라 등록한 인장을 변경한 경우에는 개업공인중개사 및 소속공인중개사는 변경일부터 7일 이내에 그 변경된 인장을 등록관청에 등록(전자문서에 의한 등록을 포함한다)하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제9조제4항","원문":"법인인 개업공인중개사의 제1항 및 제2항에 따른 인장 등록은 「상업등기규칙」에 따른 인감증명서의 제출로 갈음한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제9조제6항","원문":"제1항에 따른 인장의 등록은 다음 각 호의 신청이나 신고와 같이 할 수 있다. 1. 제4조에 따른 중개사무소 개설등록신청 2. 제8조에 따른 소속공인중개사ㆍ중개보조원에 대한 고용 신고"}],"선지":[{"번호":1,"판정":"옳음","설명":"법인인 개업공인중개사의 인장 등록은 인감증명서 제출로 갈음한다(시행규칙 제9조제4항)."},{"번호":2,"판정":"틀림","설명":"소속공인중개사가 등록하지 않은 인장을 사용하면 시·도지사가 6개월의 범위에서 자격을 정지할 수 있다(법 제36조제1항제2호). 업무정지는 개업공인중개사에 대한 처분이고 기간도 6개월의 범위다(법 제39조제1항)."},{"번호":3,"판정":"옳음","설명":"인장 등록은 개설등록 신청과 같이 할 수 있다(시행규칙 제9조제6항제1호)."},{"번호":4,"판정":"옳음","설명":"소속공인중개사 고용 신고와 같이 인장을 등록할 수 있다(시행규칙 제9조제6항제2호)."},{"번호":5,"판정":"옳음","설명":"등록한 인장을 변경하면 변경일부터 7일 이내에 등록한다(시행규칙 제9조제2항)."}],"개념":[{"종류":"표","제목":"인장등록(법 제16조, 시행규칙 제9조)","머리":["항목","내용","근거"],"행":[["등록 대상자","개업공인중개사, 소속공인중개사","법 제16조제1항"],["등록 시기","업무를 개시하기 전","시행규칙 제9조제1항"],["변경 등록","변경일부터 7일 이내","시행규칙 제9조제2항"],["사용 의무","중개행위를 할 때 등록한 인장 사용","법 제16조제2항"],["함께 할 수 있는 신청","개설등록 신청, 소속공인중개사·중개보조원 고용 신고와 같이 등록 가능","시행규칙 제9조제6항"],["위반 제재","개업공인중개사는 업무정지, 소속공인중개사는 자격정지","법 제39조제1항제2호, 제36조제1항제2호"]]},{"종류":"비교","제목":"자격정지와 업무정지","왼쪽":{"이름":"자격정지(소속공인중개사)","항목":["처분권자: 시·도지사(법 제36조제1항)","대상: 소속공인중개사로 업무를 수행하는 공인중개사","기간: 6개월의 범위","인장등록 위반도 사유(제1항제2호)"]},"오른쪽":{"이름":"업무정지(개업공인중개사)","항목":["처분권자: 등록관청(법 제39조제1항)","대상: 개업공인중개사(법인은 법인 또는 분사무소별)","기간: 6개월의 범위","사유 발생일부터 3년이 지나면 처분 불가(제3항)","인장등록 위반도 사유(제1항제2호)"]}}],"함정":"소속공인중개사의 인장 위반에는 업무정지가 아니라 자격정지가 붙는다. 처분권자도 등록관청이 아니라 시·도지사다. 기간의 상한은 어느 쪽이나 6개월이다."},"30회-2차-011":{"한줄":"표시·광고에는 중개사무소의 명칭·연락처와 개업공인중개사의 성명을 명시하고, 소속공인중개사의 성명은 명시 사항이 아니다.","근거":[{"법령":"공인중개사법","조문":"법 제18조의2제1항","원문":"개업공인중개사가 의뢰받은 중개대상물에 대하여 표시ㆍ광고(「표시ㆍ광고의 공정화에 관한 법률」 제2조에 따른 표시ㆍ광고를 말한다. 이하 같다)를 하려면 중개사무소, 개업공인중개사에 관한 사항으로서 대통령령으로 정하는 사항을 명시하여야 하며, 중개보조원에 관한 사항은 명시해서는 아니 된다."},{"법령":"공인중개사법 시행령","조문":"영 제17조의2제1항","원문":"법 제18조의2제1항에서 \"대통령령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 1. 중개사무소의 명칭, 소재지, 연락처 및 등록번호 2. 개업공인중개사의 성명(법인인 경우에는 대표자의 성명)"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄹ도 명시 사항이라 ㄱ, ㄴ만으로는 모자란다."},{"번호":2,"판정":"틀림","설명":"ㄷ은 명시 사항이 아니다."},{"번호":3,"판정":"틀림","설명":"ㄷ은 명시 사항이 아니고 ㄱ, ㄴ이 빠졌다."},{"번호":4,"판정":"옳음","설명":"연락처(ㄱ), 명칭(ㄴ), 개업공인중개사의 성명(ㄹ)이 명시 사항이다."},{"번호":5,"판정":"틀림","설명":"ㄷ은 명시 사항이 아니고 ㄴ이 빠졌다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"중개사무소의 연락처는 명시 사항이다(영 제17조의2제1항제1호)."},{"기호":"ㄴ","판정":"옳음","설명":"중개사무소의 명칭은 명시 사항이다(영 제17조의2제1항제1호)."},{"기호":"ㄷ","판정":"틀림","설명":"소속공인중개사의 성명은 영 제17조의2제1항에 열거되어 있지 않다."},{"기호":"ㄹ","판정":"옳음","설명":"개업공인중개사의 성명(법인은 대표자)은 명시 사항이다(영 제17조의2제1항제2호)."}],"개념":[{"종류":"표","제목":"중개대상물 표시·광고 명시 사항(법 제18조의2제1항·제2항, 영 제17조의2)","머리":["구분","명시 사항"],"행":[["모든 표시·광고","중개사무소의 명칭, 소재지, 연락처, 등록번호, 개업공인중개사의 성명(법인은 대표자)"],["금지","중개보조원에 관한 사항은 명시 금지"],["인터넷 표시·광고 추가","소재지, 면적, 가격, 중개대상물 종류, 거래 형태"],["건축물 등 추가","총 층수, 사용승인·사용검사·준공검사 등을 받은 날"],["건축물 등 추가","방향, 방의 개수, 욕실의 개수, 입주가능일, 주차대수, 관리비"],["구체적 방법","국토교통부장관이 고시(영 제17조의2제3항)"]]},{"종류":"표","제목":"중개사무소 명칭과 표시·광고(법 제18조, 제18조의2)","머리":["항목","내용","근거"],"행":[["명칭","개업공인중개사는 사무소 명칭에 \"공인중개사사무소\" 또는 \"부동산중개\" 사용","법 제18조제1항"],["명칭 금지","개업공인중개사가 아닌 자는 \"공인중개사사무소\", \"부동산중개\" 또는 유사 명칭 사용 금지","법 제18조제2항"],["옥외광고물","설치하는 경우 등록증에 표기된 개업공인중개사 성명 표기(법인은 대표자, 분사무소는 신고확인서의 책임자). 설치 자체는 의무 아님","법 제18조제3항, 시행규칙 제10조의2"],["철거","위반 간판은 등록관청이 철거를 명하고 이행하지 않으면 행정대집행","법 제18조제5항"],["표시·광고 명시","중개사무소 명칭·소재지·연락처·등록번호, 개업공인중개사 성명(법인은 대표자). 중개보조원 사항은 명시 금지","법 제18조의2제1항, 영 제17조의2제1항"],["표시·광고 주체","개업공인중개사가 아닌 자는 중개대상물 표시·광고 금지","법 제18조의2제3항"],["제재","명칭 미사용·성명 미표기 100만원 이하 과태료, 명칭 무자격 사용 1년 이하 징역 또는 1천만원 이하 벌금","법 제51조제3항제2호, 제49조제1항제6호"]]}],"함정":"명시 사항은 사무소 명칭·소재지·연락처·등록번호와 개업공인중개사 성명이다. 중개보조원에 관한 사항은 명시하면 안 되고, 소속공인중개사의 성명은 열거되어 있지 않다."},"30회-2차-015":{"한줄":"신고서 서식의 폐업 칸은 \"폐업일\"이고 폐업기간 칸은 없으므로 ②가 틀리다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제18조제1항","원문":"개업공인중개사는 법 제21조제1항에 따라 다음 각 호의 어느 하나에 해당하는 경우에는 국토교통부령으로 정하는 신고서에 중개사무소등록증을 첨부(제1호 및 제2호의 경우만 해당한다)하여 등록관청에 미리 신고(제3호 및 제4호에 해당하여 신고하는 경우에는 전자문서에 의한 신고를 포함한다)해야 한다. 1. 3개월을 초과하여 휴업(법 제9조에 따른 중개사무소 개설등록 후 업무를 개시하지 않는 경우를 포함한다. 이하 이 조에서 같다)하려는 경우 2. 폐업하려는 경우 3. 3개월을 초과하여 휴업한 부동산중개업을 재개하려는 경우 4. 신고한 휴업기간을 변경하려는 경우"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 별지 제13호서식","원문":"개업공인중개사 종별: [ ] 법인 [ ] 공인중개사 [ ] 법 제7638호 부칙 제6조제2항에 따른 개업공인중개사 / 신고사항: 휴업(휴업기간), 폐업(폐업일), 재개(재개일), 휴업기간 변경(원래 휴업기간, 변경 휴업기간) / 첨부서류: 중개사무소등록증(휴업신고 또는 폐업신고의 경우에만 첨부하며, 법인의 분사무소인 경우에는 분사무소설치 신고확인서를 첨부합니다)"},{"법령":"공인중개사법","조문":"법 제21조의2제1항제2호","원문":"개업공인중개사는 다음 각 호의 어느 하나에 해당하는 경우에는 지체 없이 사무소의 간판을 철거하여야 한다. 제21조제1항에 따라 등록관청에 폐업사실을 신고한 경우"},{"법령":"공인중개사법 시행령","조문":"영 제18조제6항제3호","원문":"법 제21조제2항에서 \"대통령령으로 정하는 부득이한 사유\"란 다음 각 호의 어느 하나에 해당하는 사유를 말한다. 취학"}],"선지":[{"번호":1,"판정":"옳음","설명":"서식의 종별 칸은 법인, 공인중개사, 법 제7638호 부칙 제6조제2항에 따른 개업공인중개사로 나뉜다(별지 제13호서식)."},{"번호":2,"판정":"틀림","설명":"서식에는 휴업은 휴업기간, 폐업은 폐업일을 적는다(별지 제13호서식). 폐업기간을 적는 칸은 없다."},{"번호":3,"판정":"옳음","설명":"개설등록 후 업무를 개시하지 않는 경우도 3개월을 초과하면 휴업이므로 등록증을 첨부해 미리 신고한다(영 제18조제1항제1호)."},{"번호":4,"판정":"옳음","설명":"폐업사실을 신고하면 지체 없이 간판을 철거한다(법 제21조의2제1항제2호)."},{"번호":5,"판정":"옳음","설명":"취학은 6개월을 초과하여 휴업할 수 있는 사유다(영 제18조제6항제3호)."}],"개념":[{"종류":"표","제목":"휴업·폐업·재개·휴업기간 변경 신고서(시행규칙 별지 제13호서식)","머리":["항목","기재 내용"],"행":[["신고서 종류","부동산중개업 또는 분사무소의 휴업, 폐업, 재개, 휴업기간 변경"],["개업공인중개사 종별","법인, 공인중개사, 법 제7638호 부칙 제6조제2항에 따른 개업공인중개사"],["휴업","휴업기간"],["폐업","폐업일"],["재개","재개일"],["휴업기간 변경","원래 휴업기간, 변경 휴업기간"],["첨부서류","중개사무소등록증(휴업·폐업 신고만, 분사무소는 분사무소설치 신고확인서)"],["처리기간","즉시"]]},{"종류":"흐름","제목":"휴업·재개·폐업 신고","단계":[{"이름":"휴업 신고","설명":"3개월을 초과하는 휴업은 등록관청에 미리 신고하고 등록증을 첨부(영 제18조제1항제1호)"},{"이름":"휴업 기간","설명":"6개월을 초과할 수 없음. 질병 요양, 징집 입영, 취학, 임신·출산 등은 예외(법 제21조제2항, 영 제18조제6항)"},{"이름":"기간 변경","설명":"신고한 휴업기간을 바꾸려면 미리 신고. 전자문서 신고 가능(영 제18조제1항제4호)"},{"이름":"재개 신고","설명":"3개월을 초과하여 휴업한 중개업을 재개하려면 미리 신고. 등록관청은 반납받은 등록증을 즉시 반환(영 제18조제1항제3호·제5항)"},{"이름":"폐업 신고","설명":"폐업하려면 미리 신고하고 등록증 첨부. 신고 후 간판은 지체 없이 철거(영 제18조제1항제2호, 법 제21조의2제1항)"}]}],"함정":"휴업은 기간이 있고 폐업은 시점(폐업일)이다. 서식 하나로 휴업·폐업·재개·기간 변경을 모두 신고하며 등록증은 휴업·폐업 때만 붙인다."},"30회-2차-010":{"한줄":"고용관계 종료 신고는 종료일부터 10일 이내에 하므로 14일 이내라고 한 ②가 틀리다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"규칙 제8조제4항","원문":"개업공인중개사는 소속공인중개사 또는 중개보조원과의 고용관계가 종료된 때에는 법 제15조제1항에 따라 고용관계가 종료된 날부터 10일 이내에 등록관청에 신고하여야 한다."},{"법령":"공인중개사법","조문":"법 제15조제2항","원문":"소속공인중개사 또는 중개보조원의 업무상 행위는 그를 고용한 개업공인중개사의 행위로 본다."},{"법령":"공인중개사법","조문":"법 제30조제1항","원문":"개업공인중개사는 중개행위를 하는 경우 고의 또는 과실로 인하여 거래당사자에게 재산상의 손해를 발생하게 한 때에는 그 손해를 배상할 책임이 있다."},{"법령":"민법","조문":"민법 제750조","원문":"고의 또는 과실로 인한 위법행위로 타인에게 손해를 가한 자는 그 손해를 배상할 책임이 있다."},{"법령":"공인중개사법 시행규칙","조문":"규칙 제10조제3호","원문":"3. 개업공인중개사 및 소속공인중개사의 공인중개사자격증 원본(해당되는 자가 있는 경우로 한정한다)"},{"법령":"공인중개사법 시행규칙","조문":"규칙 제8조제1항","원문":"업무개시 전까지 등록관청에 신고(전자문서에 의한 신고를 포함한다)하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"중개보조원의 업무상 행위는 고용한 개업공인중개사의 행위로 본다(법 제15조제2항)."},{"번호":2,"판정":"틀림","설명":"종료 신고는 종료된 날부터 10일 이내다(규칙 제8조제4항). 14일이 아니다."},{"번호":3,"판정":"옳음","설명":"개업공인중개사는 법 제30조제1항에 따라 책임을 지고, 중개보조원 본인도 과실로 손해를 입히면 민법 제750조의 불법행위책임을 진다는 것이 판례의 입장이다."},{"번호":4,"판정":"옳음","설명":"소속공인중개사를 둔 경우 개업공인중개사와 소속공인중개사의 자격증 원본을 사무소에 게시한다(규칙 제10조제3호)."},{"번호":5,"판정":"옳음","설명":"중개보조원 고용 신고도 전자문서로 할 수 있다(규칙 제8조제1항)."}],"개념":[{"종류":"표","제목":"소속공인중개사와 중개보조원 비교","머리":["구분","소속공인중개사","중개보조원"],"행":[["정의","개업공인중개사에 소속된 공인중개사로서 중개업무를 수행하거나 개업공인중개사의 중개업무를 보조하는 자(법 제2조제5호)","공인중개사가 아닌 자로서 현장안내·일반서무 등 단순한 업무를 보조하는 자(법 제2조제6호)"],["고용 신고","업무개시 전까지 등록관청에 신고, 전자문서 신고 포함(규칙 제8조제1항)","업무개시 전까지 등록관청에 신고, 전자문서 신고 포함(규칙 제8조제1항)"],["고용 전 교육","신고일 전 1년 이내 시·도지사의 실무교육(법 제34조제2항)","신고일 전 1년 이내 시·도지사 또는 등록관청의 직무교육(법 제34조제3항)"],["자격 확인","등록관청이 자격증을 발급한 시·도지사에게 자격 확인 요청(규칙 제8조제2항)","해당 없음(공인중개사가 아님)"],["고용관계 종료 신고","종료일부터 10일 이내(규칙 제8조제4항)","종료일부터 10일 이내(규칙 제8조제4항)"],["인장등록","등록 대상(법 제16조제1항)","등록 대상 아님"],["업무상 행위","고용한 개업공인중개사의 행위로 봄(법 제15조제2항)","고용한 개업공인중개사의 행위로 봄(법 제15조제2항)"]]},{"종류":"비교","제목":"고용인의 행위에 대한 책임","왼쪽":{"이름":"개업공인중개사","항목":["중개행위로 고의·과실에 의한 재산상 손해를 입히면 배상책임(법 제30조제1항)","고용인의 업무상 행위는 자신의 행위로 봄(법 제15조제2항)","업무개시 전 보증보험·공제 가입 또는 공탁(법 제30조제3항)"]},"오른쪽":{"이름":"중개보조원","항목":["자신의 과실로 거래당사자에게 손해를 입히면 민법 제750조의 불법행위책임이 별도로 성립(판례)","인장등록 대상 아님(법 제16조제1항)","고용관계 종료 신고는 종료일부터 10일 이내(규칙 제8조제4항)"]}}],"함정":"③은 고용한 개업공인중개사만 책임진다고 알고 있으면 틀린 보기로 읽힌다. 개업공인중개사의 책임과 별개로 중개보조원 본인의 불법행위책임도 성립한다. 정답은 종료 신고 기한(10일)을 14일로 바꾼 ②다."},"30회-2차-017":{"한줄":"임대차의 전속중개계약에서 공개해야 하는 정보는 ㄹ(환경 조건)뿐이다. 권리자의 인적 사항은 공개하면 안 되고, 임대차의 공시지가는 공개하지 않을 수 있다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제20조제2항제4호","원문":"4. 도로 및 대중교통수단과의 연계성, 시장ㆍ학교 등과의 근접성, 지형 등 입지조건, 일조(日照)ㆍ소음ㆍ진동 등 환경조건"},{"법령":"공인중개사법 시행령","조문":"영 제20조제2항제5호","원문":"5. 소유권ㆍ전세권ㆍ저당권ㆍ지상권 및 임차권 등 중개대상물의 권리관계에 관한 사항. 다만, 각 권리자의 주소ㆍ성명 등 인적 사항에 관한 정보는 공개하여서는 아니 된다."},{"법령":"공인중개사법 시행령","조문":"영 제20조제2항제7호","원문":"7. 중개대상물의 거래예정금액 및 공시지가. 다만, 임대차의 경우에는 공시지가를 공개하지 아니할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄹ만 공개해야 하는 정보이므로 이 조합이 맞다."},{"번호":2,"판정":"틀림","설명":"ㄱ(임차인 성명)과 ㄴ(저당권자 주소)은 권리자의 인적 사항이라 공개하면 안 된다."},{"번호":3,"판정":"틀림","설명":"ㄷ 공시지가는 임대차이므로 공개하지 않을 수 있는 정보다."},{"번호":4,"판정":"틀림","설명":"ㄱ, ㄴ은 공개 금지 정보라 ㄱ, ㄴ, ㄹ을 고른 조합은 맞지 않는다."},{"번호":5,"판정":"틀림","설명":"ㄱ, ㄴ은 공개 금지 정보이고 ㄷ은 임대차에서 공개 의무가 없다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"기존 임차인의 성명은 권리자의 인적 사항이므로 공개하여서는 아니 된다(영 제20조제2항제5호 단서)."},{"기호":"ㄴ","판정":"틀림","설명":"저당권자의 주소는 권리자의 인적 사항이므로 공개하여서는 아니 된다(영 제20조제2항제5호 단서)."},{"기호":"ㄷ","판정":"틀림","설명":"임대차의 경우 공시지가는 공개하지 않을 수 있어 반드시 공개할 정보가 아니다(영 제20조제2항제7호 단서)."},{"기호":"ㄹ","판정":"옳음","설명":"일조·소음·진동 등 환경조건은 공개 정보다(영 제20조제2항제4호)."}],"개념":[{"종류":"표","제목":"전속중개계약 공개 정보(영 제20조제2항)","머리":["호","공개 정보","비고"],"행":[["1","중개대상물의 종류, 소재지, 지목 및 면적, 건축물의 용도·구조 및 건축연도 등 특정 사항",""],["2","벽면 및 도배의 상태",""],["3","수도·전기·가스·소방·열공급·승강기 설비, 오수·폐수·쓰레기 처리시설 등의 상태",""],["4","도로 및 대중교통수단과의 연계성, 시장·학교 등과의 근접성, 지형 등 입지조건, 일조·소음·진동 등 환경조건",""],["5","소유권·전세권·저당권·지상권 및 임차권 등 권리관계","각 권리자의 주소·성명 등 인적 사항은 공개 금지"],["6","공법상의 이용제한 및 거래규제에 관한 사항",""],["7","중개대상물의 거래예정금액 및 공시지가","임대차는 공시지가를 공개하지 않을 수 있음"]]}],"함정":"ㄷ은 공시지가가 공개 대상 목록에 있어서 고르기 쉽다. 임대차라는 조건이 붙으면 공개 의무가 없어진다. 권리관계는 공개하되 권리자의 인적 사항만 빼야 한다."},"30회-2차-014":{"한줄":"개업공인중개사가 중개의뢰인과 직접 거래를 하는 행위는 법 제33조제1항제6호가 금지하므로 ③이 옳다.","근거":[{"법령":"공인중개사법","조문":"법 제33조제1항","원문":"개업공인중개사등은 다음 각 호의 행위를 하여서는 아니된다."},{"법령":"공인중개사법","조문":"법 제33조제1항제6호","원문":"6. 중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위"},{"법령":"공인중개사법","조문":"법 제10조제3항","원문":"개업공인중개사ㆍ소속공인중개사ㆍ중개보조원 및 개업공인중개사인 법인의 사원ㆍ임원(이하 \"개업공인중개사등\"이라 한다)"},{"법령":"공인중개사법","조문":"법 제33조제1항제1호","원문":"1. 제3조에 따른 중개대상물의 매매를 업으로 하는 행위"}],"선지":[{"번호":1,"판정":"틀림","설명":"금지행위의 적용 대상인 개업공인중개사등에는 법인의 사원·임원이 들어가므로 사원의 매매업도 금지된다(법 제10조제3항, 제33조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"거래당사자 쌍방을 대리하는 행위는 금지된다(법 제33조제1항제6호)."},{"번호":3,"판정":"옳음","설명":"중개의뢰인과 직접 거래를 하는 행위는 금지된다(법 제33조제1항제6호)."},{"번호":4,"판정":"틀림","설명":"법인의 임원도 개업공인중개사등이어서 직접 거래가 금지된다(법 제10조제3항, 제33조제1항제6호)."},{"번호":5,"판정":"틀림","설명":"중개보조원도 개업공인중개사등이어서 직접 거래가 금지된다(법 제10조제3항, 제33조제1항제6호)."}],"개념":[{"종류":"표","제목":"금지행위 규정이 적용되는 사람","머리":["규정","적용 대상","비고"],"행":[["법 제33조제1항","개업공인중개사등","개업공인중개사·소속공인중개사·중개보조원·개업공인중개사인 법인의 사원·임원(법 제10조제3항)"],["법 제33조제2항","누구든지","시세에 부당한 영향을 줄 목적으로 개업공인중개사등의 업무를 방해하는 행위"],["법 제18조의2제3항","개업공인중개사가 아닌 자","중개대상물에 대한 표시·광고 금지"]]},{"종류":"표","제목":"개업공인중개사등의 금지행위(법 제33조제1항)와 벌칙","머리":["호","금지행위","벌칙"],"행":[["1","중개대상물의 매매를 업으로 하는 행위","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제10호)"],["2","중개사무소 개설등록 없이 중개업을 하는 자인 사실을 알면서 그를 통해 중개를 의뢰받거나 그에게 자기 명의를 이용하게 하는 행위","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제10호)"],["3","사례·증여 그 밖의 어떤 명목으로도 법정 보수 또는 실비를 초과하여 금품을 받는 행위","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제10호)"],["4","중개대상물의 거래상 중요사항에 관하여 거짓된 언행 그 밖의 방법으로 중개의뢰인의 판단을 그르치게 하는 행위","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제10호)"],["5","관계 법령에서 양도·알선 등이 금지된 부동산의 분양·임대 등과 관련 있는 증서 등의 매매·교환 등을 중개하거나 그 매매를 업으로 하는 행위","3년 이하 징역 또는 3천만원 이하 벌금(법 제48조제3호)"],["6","중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위","3년 이하 징역 또는 3천만원 이하 벌금(법 제48조제3호)"],["7","탈세 등 관계 법령을 위반할 목적으로 미등기·전매제한 부동산의 매매를 중개하는 등 부동산투기를 조장하는 행위","3년 이하 징역 또는 3천만원 이하 벌금(법 제48조제3호)"],["8","부당한 이익을 얻거나 얻게 할 목적으로 거짓으로 거래가 완료된 것처럼 꾸미는 등 시세에 부당한 영향을 주거나 줄 우려가 있는 행위","3년 이하 징역 또는 3천만원 이하 벌금(법 제48조제3호)"],["9","단체를 구성하여 특정 중개대상물에 대하여 중개를 제한하거나 단체 구성원 이외의 자와 공동중개를 제한하는 행위","3년 이하 징역 또는 3천만원 이하 벌금(법 제48조제3호)"]]}],"함정":"제33조제1항은 개업공인중개사만이 아니라 소속공인중개사, 중개보조원, 법인의 사원·임원까지 적용된다. 선지 ①④⑤는 이 범위를 좁혀 금지되지 않는다고 적었다."},"30회-2차-016":{"한줄":"공제사업을 하는 자도 계약금등의 예치명의자가 될 수 있으므로 그 명의로 예치하도록 권고할 수 없다고 한 ④가 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제31조제1항","원문":"개업공인중개사는 거래의 안전을 보장하기 위하여 필요하다고 인정하는 경우에는 거래계약의 이행이 완료될 때까지 계약금ㆍ중도금 또는 잔금(이하 이 조에서 \"계약금등\"이라 한다)을 개업공인중개사 또는 대통령령으로 정하는 자의 명의로 금융기관, 제42조에 따라 공제사업을 하는 자 또는 「자본시장과 금융투자업에 관한 법률」에 따른 신탁업자 등에 예치하도록 거래당사자에게 권고할 수 있다."},{"법령":"공인중개사법 시행령","조문":"영 제27조제1항제2호","원문":"2. 「보험업법」에 따른 보험회사"},{"법령":"공인중개사법 시행령","조문":"영 제27조제1항제5호","원문":"5. 법 제42조의 규정에 따라 공제사업을 하는 자"},{"법령":"공인중개사법 시행령","조문":"영 제27조제3항","원문":"개업공인중개사는 제2항의 규정에 따라 거래계약과 관련된 계약금등을 자기 명의로 금융기관 등에 예치하는 경우에는 자기 소유의 예치금과 분리하여 관리될 수 있도록 하여야 하며"}],"선지":[{"번호":1,"판정":"옳음","설명":"거래의 안전을 위해 필요하다고 인정하면 예치를 권고할 수 있다(법 제31조제1항)."},{"번호":2,"판정":"옳음","설명":"예치 대상은 계약금·중도금 또는 잔금이다(법 제31조제1항)."},{"번호":3,"판정":"옳음","설명":"보험업법에 따른 보험회사는 예치명의자가 될 수 있다(영 제27조제1항제2호)."},{"번호":4,"판정":"틀림","설명":"법 제42조에 따라 공제사업을 하는 자도 예치명의자다(영 제27조제1항제5호). 그 명의로 예치하도록 권고할 수 있다."},{"번호":5,"판정":"옳음","설명":"자기 명의로 예치하는 경우 자기 소유의 예치금과 분리하여 관리해야 한다(영 제27조제3항)."}],"개념":[{"종류":"표","제목":"계약금등 예치(법 제31조, 영 제27조)","머리":["항목","내용"],"행":[["권고","개업공인중개사는 거래의 안전을 위해 필요하다고 인정하면 예치를 권고할 수 있다(의무 아님)"],["예치 대상","계약금·중도금 또는 잔금"],["예치명의자","개업공인중개사, 은행, 보험회사, 신탁업자, 체신관서, 공제사업을 하는 자, 거래계약 이행 보장 업무를 수행하는 전문회사"],["자기 명의 예치 시","자기 소유의 예치금과 분리하여 관리, 거래당사자의 동의 없이 인출 금지, 예치 금액을 보장하는 보증보험·공제 가입 또는 공탁"],["미리 수령","예치 후 매도인 등은 계약 해제 시 반환을 보장하는 금융기관·보증보험회사 발행 보증서를 교부하고 계약금등을 미리 수령할 수 있다(법 제31조제2항)"]]}],"함정":"예치명의자 목록(개업공인중개사, 은행, 보험회사, 신탁업자, 체신관서, 공제사업자, 전문회사)에서 공제사업을 하는 자가 빠졌다고 적은 것이 ④다. 예치는 권고일 뿐 의무가 아니다."},"30회-2차-032":{"한줄":"정정신청 대상인 개업공인중개사 사항은 전화번호·상호·사무소 소재지이고, 성명·주소는 포함되지 않는다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제3조제1항","원문":"① 거래당사자 또는 개업공인중개사는 부동산 거래계약 신고 내용 중 다음 각 호의 어느 하나에 해당하는 사항이 잘못 기재된 경우에는 신고관청에 신고 내용의 정정을 신청할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제3조제1항제1호","원문":"1. 거래당사자의 주소ㆍ전화번호 또는 휴대전화번호"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제3조제1항제2호","원문":"2. 거래 지분 비율"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제3조제1항제3호","원문":"3. 개업공인중개사의 전화번호ㆍ상호 또는 사무소 소재지"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제3조제1항제4호","원문":"4. 거래대상 건축물의 종류"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제3조제1항제5호","원문":"5. 거래대상 부동산등(부동산을 취득할 수 있는 권리에 관한 계약의 경우에는 그 권리의 대상인 부동산을 말한다. 이하 같다)의 지목, 면적, 거래 지분 및 대지권비율"}],"선지":[{"번호":1,"판정":"-","설명":"거래대상 건축물의 종류는 정정신청 사항이다(규칙 제3조제1항제4호)."},{"번호":2,"판정":"-","설명":"개업공인중개사 성명·주소는 정정신청 사항이 아니다. 개업공인중개사는 전화번호·상호·사무소 소재지만 정정한다(규칙 제3조제1항제3호)."},{"번호":3,"판정":"-","설명":"거래대상 부동산등의 면적은 정정신청 사항이다(규칙 제3조제1항제5호)."},{"번호":4,"판정":"-","설명":"거래 지분 비율은 정정신청 사항이다(규칙 제3조제1항제2호). 지분 비율 변경은 변경신고 사항이기도 하다(제3항제1호)."},{"번호":5,"판정":"-","설명":"거래당사자의 전화번호는 정정신청 사항이다(규칙 제3조제1항제1호)."}],"개념":[{"종류":"표","제목":"정정신청 사항(규칙 제3조제1항)","머리":["호","정정 대상"],"행":[["1","거래당사자의 주소·전화번호 또는 휴대전화번호"],["2","거래 지분 비율"],["3","개업공인중개사의 전화번호·상호 또는 사무소 소재지"],["4","거래대상 건축물의 종류"],["5","거래대상 부동산등의 지목, 면적, 거래 지분 및 대지권비율"]]},{"종류":"비교","제목":"정정신청과 변경신고(규칙 제3조)","왼쪽":{"이름":"정정신청(제1항·제2항)","항목":["신고 내용이 잘못 기재된 경우","거래당사자 또는 개업공인중개사가 신청","신고필증에 정정사항을 표시하고 서명 또는 날인하여 제출","거래당사자 주소·전화번호 정정은 일방이 단독으로 신청 가능"]},"오른쪽":{"이름":"변경신고(제3항·제4항)","항목":["신고 후 내용이 바뀐 경우","부동산등기법에 따른 등기신청 전에 신고","별지 제3호서식 부동산거래계약 변경 신고서 제출","면적 변경 없이 거래가격만 바뀌면 거래계약서 사본 등 증명서류 첨부"]}}],"함정":"개업공인중개사 인적사항은 신고사항이다. 정정 대상은 전화번호·상호·사무소 소재지로 좁고, 성명·주소는 정정 신청 목록에 없다."},"30회-2차-039":{"한줄":"택지개발촉진법에 따라 공급된 토지의 임대차계약은 매매·공급계약·지위의 매매 어디에도 속하지 않아 신고 대상이 아니다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제3조제1항제1호","원문":"1. 부동산의 매매계약"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제3조제1항제2호","원문":"2. 「택지개발촉진법」, 「주택법」 등 대통령령으로 정하는 법률에 따른 부동산에 대한 공급계약"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제3조제1항제3호나목","원문":"나. 「도시 및 주거환경정비법」 제74조에 따른 관리처분계획의 인가 및 「빈집 및 소규모주택 정비에 관한 특례법」 제29조에 따른 사업시행계획인가로 취득한 입주자로 선정된 지위"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제3조제3항","원문":"3. 「도시개발법」 … 7. 「택지개발촉진법」"}],"선지":[{"번호":1,"판정":"-","설명":"주택법에 따라 공급된 주택을 사고파는 매매계약은 부동산의 매매계약이다(법 제3조제1항제1호)."},{"번호":2,"판정":"-","설명":"토지의 임대차계약은 신고 대상 계약이 아니다. 신고 대상은 매매계약, 공급계약, 지위의 매매계약이다(법 제3조제1항)."},{"번호":3,"판정":"-","설명":"도시개발법에 따른 부동산 공급계약은 신고 대상이다(법 제3조제1항제2호, 영 제3조제3항제3호)."},{"번호":4,"판정":"-","설명":"등록된 체육시설이 있는 건물도 건축물이므로 그 매매계약은 신고 대상이다(법 제3조제1항제1호)."},{"번호":5,"판정":"-","설명":"관리처분계획 인가로 취득한 입주자로 선정된 지위의 매매계약은 신고 대상이다(법 제3조제1항제3호나목)."}],"개념":[{"종류":"표","제목":"부동산 거래신고 대상 계약(법 제3조제1항, 영 제3조제3항)","머리":["구분","대상","근거"],"행":[["매매","부동산(토지·건축물)의 매매계약","법 제3조제1항제1호"],["공급계약","건축물의 분양에 관한 법률, 공공주택 특별법, 도시개발법, 도시 및 주거환경정비법, 빈집 및 소규모주택 정비에 관한 특례법, 산업입지 및 개발에 관한 법률, 주택법, 택지개발촉진법에 따른 공급계약","법 제3조제1항제2호, 영 제3조제3항"],["지위의 매매","공급계약으로 부동산을 공급받는 자로 선정된 지위(분양권)의 매매계약","법 제3조제1항제3호가목"],["지위의 매매","관리처분계획 인가(도시 및 주거환경정비법) 또는 사업시행계획인가(빈집 및 소규모주택 정비에 관한 특례법)로 취득한 입주자로 선정된 지위(입주권)의 매매계약","법 제3조제1항제3호나목"],["대상 아님","위 각 호에 없는 계약(증여, 임대차 등). 주택 임대차는 별도의 임대차 신고 제도(법 제6조의2)","법 제3조제1항"]]},{"종류":"표","제목":"공급계약 신고 대상 법률(영 제3조제3항)","머리":["호","법률"],"행":[["1","건축물의 분양에 관한 법률"],["2","공공주택 특별법"],["3","도시개발법"],["4","도시 및 주거환경정비법"],["4의2","빈집 및 소규모주택 정비에 관한 특례법"],["5","산업입지 및 개발에 관한 법률"],["6","주택법"],["7","택지개발촉진법"]]}],"함정":"택지개발촉진법은 공급계약의 근거 법률 목록에 들어 있어 ②도 신고 대상처럼 보인다. ②는 공급계약이 아니라 임대차계약이다."},"30회-2차-040":{"한줄":"계약의 조건이나 기한이 있으면 그 조건 또는 기한이 신고사항이다(영 별표 1 제1호바목).","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 별표 1 제1호바목","원문":"바. 계약의 조건이나 기한이 있는 경우에는 그 조건 또는 기한"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제3조제1항","원문":"① 거래당사자는 다음 각 호의 어느 하나에 해당하는 계약을 체결한 경우 그 실제 거래가격 등 대통령령으로 정하는 사항을 거래계약의 체결일부터 30일 이내에 그 권리의 대상인 부동산등(권리에 관한 계약의 경우에는 그 권리의 대상인 부동산을 말한다)의 소재지를 관할하는 시장(구가 설치되지 아니한 시의 시장 및 특별자치시장과 특별자치도 행정시의 시장을 말한다)ㆍ군수 또는 구청장(이하 \"신고관청\"이라 한다)에게 공동으로 신고하여야 한다. 다만, 거래당사자 중 일방이 국가, 지방자치단체, 대통령령으로 정하는 자의 경우(이하 \"국가등\"이라 한다)에는 국가등이 신고를 하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제3조제2항","원문":"② 법 제3조제1항 각 호 외의 부분 단서에서 \"대통령령으로 정하는 자\"란 다음 각 호의 기관을 말한다. … 2. 「지방공기업법」에 따른 지방직영기업ㆍ지방공사 또는 지방공단"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제5조제2항","원문":"② 제2조제4항, 제3조제2항ㆍ제4항 및 제4조제1항ㆍ제2항의 개업공인중개사의 위임을 받은 소속공인중개사(「공인중개사법」 제2조제5호에 따른 소속공인중개사를 말한다. 이하 같다)는 부동산거래계약 신고서 등의 제출을 대행할 수 있다. 이 경우 소속공인중개사는 신분증명서를 신고관청에 보여줘야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"거래신고 기한은 계약 체결일부터 30일이다(법 제3조제1항). 60일이 아니다."},{"번호":2,"판정":"틀림","설명":"신고 의무자는 거래당사자 또는 개업공인중개사다. 소속공인중개사는 개업공인중개사의 위임을 받아 제출을 대행할 수 있을 뿐이고, 중개보조원에 관한 규정은 없다(법 제3조, 규칙 제5조제2항)."},{"번호":3,"판정":"틀림","설명":"지방공사는 국가등이다. 국가등이 한쪽 당사자이면 국가등이 신고한다(법 제3조제1항 단서, 영 제3조제2항제2호)."},{"번호":4,"판정":"틀림","설명":"공법상의 거래규제 및 이용제한은 영 별표 1 신고사항이 아니다."},{"번호":5,"판정":"옳음","설명":"조건·기한은 신고사항이다(영 별표 1 제1호바목)."}],"개념":[{"종류":"표","제목":"신고사항 구성(영 제3조제1항, 별표 1)","머리":["구분","신고사항"],"행":[["공통(제1호)","거래당사자 인적사항, 계약 체결일·중도금 및 잔금 지급일, 소재지·지번·지목·면적, 부동산 종류, 실제 거래가격, 조건·기한, 매수인이 국내 주소·거소가 없을 때 위탁관리인, 외국인 매수인의 체류자격 등, 개업공인중개사 인적사항과 사무소 상호·전화번호·소재지"],["법인의 주택 거래(제2호)","법인 등기 현황, 거래상대방과의 관계, 취득 목적, 자금조달계획, 이용계획"],["주택 매수(제3호·제3호의2)","자금조달계획과 지급방식, 매수자 본인의 입주 여부·시기 등 이용계획"],["토지 매수(제4호·제5호)","자금조달계획, 토지 이용계획"]]},{"종류":"표","제목":"신고 주체와 방법(법 제3조)","머리":["상황","신고 주체·방법","근거"],"행":[["거래당사자 직접거래","거래당사자가 공동으로 신고. 계약 체결일부터 30일 이내","법 제3조제1항"],["일방이 국가등","국가등이 신고하고 서명 또는 날인도 국가등이 단독으로 한다","법 제3조제1항 단서, 규칙 제2조제2항"],["국가등의 범위","국가, 지방자치단체, 공공기관, 지방직영기업·지방공사·지방공단","법 제3조제1항 단서, 영 제3조제2항"],["개업공인중개사가 거래계약서를 작성·교부","개업공인중개사가 신고. 공동중개이면 공동으로 신고","법 제3조제3항"],["일방이 신고 거부","다른 일방이 단독 신고. 거래계약서 사본, 계약금 지급 확인 서류, 단독신고사유서 첨부","법 제3조제2항·제4항, 규칙 제2조제3항"],["소속공인중개사","개업공인중개사의 위임을 받아 제출을 대행하고 신분증명서를 보여준다","규칙 제5조제2항"]]}],"함정":"소속공인중개사는 제출 대행이 가능하다는 점이 신고 의무자라는 말로 옮겨지면 ②처럼 틀린다. ③의 지방공사는 국가등이어서 공동신고 대상이 아니다."},"30회-2차-027":{"한줄":"특별자치시장은 외국인등의 취득·계속보유 신고내용을 매 분기 종료일부터 1개월 이내에 국토교통부장관에게 직접 제출한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제5조제3항","원문":"③ 신고관청은 법 제8조에 따른 신고내용을 매 분기 종료일부터 1개월 이내에 특별시장ㆍ광역시장ㆍ도지사 또는 특별자치도지사에게 제출(「전자서명법」 제2조제1호에 따른 전자문서에 의한 제출을 포함한다)하여야 한다. 다만, 특별자치시장은 직접 국토교통부장관에게 제출하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제5조제2항","원문":"② 법 제8조제2항에서 \"대통령령으로 정하는 계약 외의 원인\"이란 다음 각 호의 어느 하나에 해당하는 사유를 말한다. … 2. 법원의 확정판결"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제6조제3항","원문":"③ 제1항에 따른 신청서를 받은 신고관청은 신청서를 받은 날부터 다음 각 호의 구분에 따른 기간 안에 허가 또는 불허가 처분을 해야 한다. 다만, 부득이한 사유로 제1호에 따른 기간 안에 허가 또는 불허가 처분을 할 수 없는 경우에는 30일의 범위에서 그 기간을 연장할 수 있으며, 기간을 연장하는 경우에는 연장 사유와 처리예정일을 지체 없이 신청인에게 알려야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제8조제2항","원문":"② 외국인등이 상속ㆍ경매, 그 밖에 대통령령으로 정하는 계약 외의 원인으로 대한민국 안의 부동산등을 취득한 때에는 부동산등을 취득한 날부터 6개월 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"경매로 취득하면 취득한 날부터 6개월 이내에 신고한다(법 제8조제2항). 3개월이 아니다."},{"번호":2,"판정":"틀림","설명":"임대차계약은 부동산등을 취득하는 계약이 아니어서 법 제8조의 신고 대상이 아니다."},{"번호":3,"판정":"옳음","설명":"특별자치시장은 신고내용을 국토교통부장관에게 직접 제출한다(영 제5조제3항 단서)."},{"번호":4,"판정":"틀림","설명":"생태·경관보전지역은 법 제9조제1항제1호의 구역이 아니라서 처리기간이 15일이다(영 제6조제3항제2호). 30일은 군사기지 등 구역·지역이다."},{"번호":5,"판정":"틀림","설명":"법원의 확정판결로 취득한 경우도 계약 외 원인으로서 6개월 이내에 신고한다(영 제5조제2항제2호, 법 제8조제2항)."}],"개념":[{"종류":"표","제목":"신고내용 제출 경로(영 제5조제3항·제4항, 제6조제5항·제6항)","머리":["단계","내용"],"행":[["신고관청","매 분기 종료일부터 1개월 이내 신고내용(허가내용)을 시·도지사에게 제출"],["특별시장·광역시장·도지사·특별자치도지사","제출받은 날부터 1개월 이내 국토교통부장관에게 제출"],["특별자치시장","국토교통부장관에게 직접 제출"]]},{"종류":"표","제목":"외국인등의 토지취득 허가(법 제9조, 영 제6조)","머리":["항목","내용"],"행":[["허가 지역","군사기지 및 군사시설 보호구역 등, 지정문화유산과 보호물·보호구역, 천연기념물등과 보호물·보호구역, 생태·경관보전지역, 야생생물 특별보호구역"],["허가 시기·허가권자","토지취득계약 체결 전에 신고관청의 허가"],["처리기간","군사기지 등 국방목적 구역·지역은 30일, 그 밖의 구역·지역은 15일(부득이하면 군사기지 등은 30일 범위에서 연장)"],["예외","법 제11조에 따른 토지거래계약 허가를 받은 경우"],["위반 효과","허가 없이 체결한 토지취득계약은 효력이 발생하지 않는다(법 제9조제3항)"]]}],"함정":"③은 특별자치시에만 적용되는 예외이고 나머지 시·군·구는 시·도지사를 거친다. ④는 허가 구역에 따라 처리기간이 갈린다는 점이 요점이다.","개정":"외국인등의 토지취득 허가 처리기간은 영 제6조제3항에서 군사기지 등 구역·지역 30일, 그 밖의 구역·지역 15일로 나뉜다(<개정 2023.10.4>). 선지 ④는 생태·경관보전지역으로 한정해 틀린 문장으로 유지했다. 정답 번호는 그대로다."},"30회-2차-028":{"한줄":"매수청구 토지의 매수자는 국가·지방자치단체·한국토지주택공사와 영 제11조제1항제1호~제10호 기관 중에서 지정한다. 지방자치단체·한국석유공사·한국관광공사가 이에 든다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제16조제2항","원문":"② 제1항에 따른 매수 청구를 받은 시장ㆍ군수 또는 구청장은 국가, 지방자치단체, 한국토지주택공사, 그 밖에 대통령령으로 정하는 공공기관 또는 공공단체 중에서 매수할 자를 지정하여, 매수할 자로 하여금 예산의 범위에서 공시지가를 기준으로 하여 해당 토지를 매수하게 하여야 한다. 다만, 토지거래계약 허가신청서에 적힌 가격이 공시지가보다 낮은 경우에는 허가신청서에 적힌 가격으로 매수할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제13조제2항","원문":"② 법 제16조제2항에서 \"대통령령으로 정하는 공공기관 또는 공공단체\"란 제11조제1항제1호부터 제10호까지의 기관 또는 단체를 말한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제11조제1항","원문":"4. 「한국관광공사법」에 따른 한국관광공사 … 7. 「한국석유공사법」에 따른 한국석유공사 … 15. 「한국은행법」에 따른 한국은행 … 16. 「지방공기업법」에 따른 지방공사와 지방공단 … 22. 「항만공사법」에 따른 항만공사"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄴ(한국은행), ㅁ(항만공사)은 제11호~제22호 기관이라 지정 대상이 아니고, ㄱ·ㄹ·ㅂ은 지정 대상이다."},{"번호":2,"판정":"옳음","설명":"지방자치단체(법 제16조제2항), 한국석유공사(영 제11조제1항제7호), 한국관광공사(제4호)가 지정될 수 있다."},{"번호":3,"판정":"틀림","설명":"ㄴ(한국은행), ㄷ(지방공사), ㅁ(항만공사)이 지정 대상이 아니다."},{"번호":4,"판정":"틀림","설명":"ㅁ(항만공사)은 지정 대상이 아니다."},{"번호":5,"판정":"틀림","설명":"ㄴ, ㄷ, ㅁ은 지정 대상이 아니다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"지방자치단체는 법 제16조제2항이 직접 규정한 매수자다."},{"기호":"ㄴ","판정":"틀림","설명":"한국은행은 영 제11조제1항제15호라서 영 제13조제2항의 지정 대상(제1호~제10호)이 아니다."},{"기호":"ㄷ","판정":"틀림","설명":"지방공사는 영 제11조제1항제16호라서 지정 대상이 아니다."},{"기호":"ㄹ","판정":"옳음","설명":"한국석유공사는 영 제11조제1항제7호다."},{"기호":"ㅁ","판정":"틀림","설명":"항만공사는 영 제11조제1항제22호라서 지정 대상이 아니다."},{"기호":"ㅂ","판정":"옳음","설명":"한국관광공사는 영 제11조제1항제4호다."}],"개념":[{"종류":"표","제목":"선매자·매수 지정 대상 기관(법 제15조·제16조, 영 제11조제1항·제12조·제13조)","머리":["구분","기관"],"행":[["국가·지방자치단체·한국토지주택공사","법에 직접 규정"],["영 제11조제1항제1호~제10호","한국농수산식품유통공사, 대한석탄공사, 한국토지주택공사, 한국관광공사, 한국농어촌공사, 한국도로공사, 한국석유공사, 한국수자원공사, 한국전력공사, 한국철도공사"],["영 제11조제1항제11호~제22호","산림조합·중앙회, 농협, 수협, 중소벤처기업진흥공단, 한국은행, 지방공사·지방공단, 공무원연금공단, 인천국제공항공사, 국민연금공단, 사립학교교직원연금공단, 한국자산관리공사, 항만공사(국가등 허가 협의 특례에는 해당하나 선매자·매수자 지정 대상에서는 제외)"]]},{"종류":"표","제목":"토지거래계약 허가(법 제11조~제14조)","머리":["항목","내용"],"행":[["허가 대상","허가구역 안 토지의 소유권·지상권(취득을 목적으로 하는 권리 포함)을 대가를 받고 이전·설정하는 계약(예약 포함)"],["허가 절차","당사자 공동 신청. 허가관청은 신청서를 받은 날부터 15일 이내 허가·변경허가·불허가 처분(영 제8조제3항)"],["허가 없이 체결","계약은 효력이 발생하지 않는다(법 제11조제6항)"],["이의신청","처분을 받은 날부터 1개월 이내 시장·군수·구청장에게(법 제13조제1항)"],["매수청구","불허가처분을 통지받은 날부터 1개월 이내(법 제16조제1항)"],["적용 제외","수용, 민사집행법상 경매, 영 제11조제3항의 계약"]]}],"함정":"국가등 허가 협의 특례(법 제14조제1항)는 영 제11조제1항의 22개 기관이 모두 대상이고, 선매자·매수자 지정(영 제12조·제13조)은 제1호~제10호 기관으로 좁다. 한국은행·지방공사·항만공사는 앞 특례에는 들고 뒤 지정에는 들지 않는다."},"30회-2차-030":{"한줄":"이행명령을 받은 자가 명령을 이행해도 그 전에 이미 부과된 이행강제금은 징수해야 한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제18조제3항","원문":"③ 시장ㆍ군수 또는 구청장은 최초의 이행명령이 있었던 날을 기준으로 1년에 한 번씩 그 이행명령이 이행될 때까지 반복하여 제2항에 따른 이행강제금을 부과ㆍ징수할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제18조제4항","원문":"④ 시장ㆍ군수 또는 구청장은 제17조제1항에 따른 이용 의무기간이 지난 후에는 이행강제금을 부과할 수 없다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제18조제5항","원문":"⑤ 시장ㆍ군수 또는 구청장은 제1항에 따른 이행명령을 받은 자가 그 명령을 이행하는 경우에는 새로운 이행강제금의 부과를 즉시 중지하되, 명령을 이행하기 전에 이미 부과된 이행강제금은 징수하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제16조제3항제2호","원문":"2. 토지거래계약허가를 받아 토지를 취득한 자가 직접 이용하지 아니하고 임대한 경우: 토지 취득가액의 100분의 7에 상당하는 금액"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제16조제7항","원문":"⑦ 제6항에 따른 이행강제금 부과처분을 받은 자는 법 제18조제6항에 따라 이의를 제기하려는 경우에는 부과처분을 고지받은 날부터 30일 이내에 하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"반복 부과의 기준일은 최초의 의무이행 위반이 있었던 날이 아니라 최초의 이행명령이 있었던 날이다(법 제18조제3항)."},{"번호":2,"판정":"틀림","설명":"이용 의무기간이 지난 후에는 이행강제금을 부과할 수 없다(법 제18조제4항)."},{"번호":3,"판정":"옳음","설명":"이행명령을 이행해도 이미 부과된 이행강제금은 징수한다(법 제18조제5항)."},{"번호":4,"판정":"틀림","설명":"직접 이용하지 않고 임대한 경우의 이행강제금은 취득가액의 100분의 7이다(영 제16조제3항제2호). 100분의 20이 아니다."},{"번호":5,"판정":"틀림","설명":"부과처분에 이의를 제기하려면 고지받은 날부터 30일 이내에 시장·군수·구청장에게 한다(법 제18조제6항, 영 제16조제7항). 국토교통부장관이나 14일이 아니다."}],"개념":[{"종류":"표","제목":"이행강제금 금액(법 제18조제2항, 영 제16조제3항)","머리":["위반 유형","금액(토지 취득가액 기준)"],"행":[["당초 목적대로 이용하지 않고 방치","100분의 10"],["직접 이용하지 않고 임대","100분의 7"],["허가관청의 승인 없이 이용목적 변경","100분의 5"],["위 세 가지에 해당하지 않는 경우","100분의 7"]]},{"종류":"흐름","제목":"이행명령과 이행강제금(법 제18조, 영 제16조)","단계":[{"이름":"이행명령","설명":"문서로 하고 이행기간은 3개월 이내로 정한다(영 제16조제1항)"},{"이름":"계고","설명":"이행기간 내 이행하지 않으면 이행강제금을 부과·징수한다는 뜻을 미리 문서로 계고(영 제16조제5항)"},{"이름":"부과","설명":"이행명령이 이행되지 않으면 이행강제금 부과. 최초 이행명령이 있었던 날을 기준으로 1년에 한 번씩 반복 부과(법 제18조제3항)"},{"이름":"이의제기","설명":"부과처분을 고지받은 날부터 30일 이내 시장·군수·구청장에게(영 제16조제7항, 법 제18조제6항)"},{"이름":"이행 시","설명":"새로운 이행강제금 부과는 즉시 중지, 이미 부과된 이행강제금은 징수(법 제18조제5항). 의무기간이 지나면 부과 불가(제4항)"}]}],"함정":"임대의 이행강제금 비율(100분의 7)과 방치의 비율(100분의 10)을 서로 바꾸어 놓기 쉽다. ⑤는 기한 30일, 이의제기 상대방이 시장·군수·구청장이다."},"30회-2차-031":{"한줄":"무허가건물이라도 건물의 요건을 갖추면 관습법상 법정지상권이 성립하고(ㄱ), 성립 후 증축해도 구 건물을 기준으로 인정되므로(ㄴ) ㄱ, ㄴ이 옳다.","근거":[{"판례":"대법원 판례(관습법상 법정지상권의 성립)","요지":"동일인 소유이던 토지와 건물 중 건물만 매매 등으로 소유자가 달라지고 철거 특약이 없으면 건물 소유자는 관습법상 법정지상권을 취득한다. 건물이 무허가이거나 미등기여도 성립한다."},{"판례":"대법원 판례(건물의 증축·개축)","요지":"관습법상 법정지상권이 성립한 뒤 건물을 증축·개축·신축해도 구 건물을 기준으로 지상권이 인정된다. 그 범위는 구 건물의 유지·사용에 필요한 범위로 한정된다."},{"판례":"대법원 판례(법정지상권의 포기)","요지":"건물 취득 시 건물 소유자가 대지 소유자와 대지에 대한 임대차계약을 체결했다면 관습법상 법정지상권을 포기한 것으로 본다."},{"판례":"대법원 판례(지료)","요지":"관습법상 법정지상권이 성립해도 건물 소유자는 대지 소유자에게 지료를 지급할 의무가 있다."},{"법령":"민법","조문":"민법 제366조(비교 조문)","원문":"저당물의 경매로 인하여 토지와 그 지상건물이 다른 소유자에 속한 경우에는 토지소유자는 건물소유자에 대하여 지상권을 설정한 것으로 본다. 그러나 지료는 당사자의 청구에 의하여 법원이 이를 정한다."},{"법령":"민법","조문":"민법 제287조(지료 연체와 소멸청구)","원문":"지상권자가 2년 이상의 지료를 지급하지 아니한 때에는 지상권설정자는 지상권의 소멸을 청구할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"무허가건물에도 성립하고(ㄱ) 증축 후에도 구 건물을 기준으로 인정되므로(ㄴ) 이 조합이 맞다."},{"번호":2,"판정":"틀림","설명":"ㄷ은 틀린 보기이고 옳은 ㄱ이 빠졌다. 대지 임대차계약의 체결은 법정지상권의 포기로 본다."},{"번호":3,"판정":"틀림","설명":"ㄷ은 지상권 포기로 보는 경우이고 ㄹ은 지료 지급 의무가 있는 경우라 둘 다 틀린 보기다."},{"번호":4,"판정":"틀림","설명":"ㄹ은 틀린 보기다. 법정지상권자는 지료를 지급할 의무가 있다."},{"번호":5,"판정":"틀림","설명":"ㄷ, ㄹ이 틀린 보기이고 옳은 ㄴ이 빠졌다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"건물이 건물로서의 요건을 갖췄다면 무허가건물이어도 관습법상 법정지상권이 인정된다는 것이 판례다."},{"기호":"ㄴ","판정":"옳음","설명":"성립 후 증축해도 구 건물을 기준으로 인정된다."},{"기호":"ㄷ","판정":"틀림","설명":"건물 취득 시 대지에 대한 임대차계약을 체결했다면 관습법상 법정지상권을 포기한 것으로 본다는 것이 판례다."},{"기호":"ㄹ","판정":"틀림","설명":"법정지상권자는 대지 소유자에게 지료를 지급할 의무가 있다."}],"개념":[{"종류":"표","제목":"저당권 경매의 법정지상권과 관습법상 법정지상권","머리":["구분","민법 제366조 법정지상권","관습법상 법정지상권"],"행":[["근거","민법 제366조","판례로 확립된 관습법"],["발생 원인","저당물의 경매로 토지와 건물의 소유자가 달라짐","매매 등으로 토지와 건물의 소유자가 달라짐"],["토지·건물 소유자","저당권 설정 당시 건물이 있고 동일인 소유","처분 당시 동일인 소유. 건물의 무허가·미등기는 불문"],["지료","당사자의 청구에 의하여 법원이 정함","지급 의무가 있고 협의가 안 되면 법원이 정함"],["지료 연체","2년 이상 지급하지 않으면 지상권설정자가 소멸청구(민법 제287조)","같은 규정이 적용됨(판례)"]]},{"종류":"비교","제목":"관습법상 법정지상권이 인정되는 경우와 부정되는 경우","왼쪽":{"이름":"인정","항목":["동일인 소유이던 건물만 매매 등으로 소유자가 달라진 경우","건물이 무허가·미등기인 경우","성립 후 건물을 증축·개축한 경우(구 건물 기준)"]},"오른쪽":{"이름":"부정","항목":["철거 특약이 있는 경우","건물 취득 시 대지 임대차계약을 체결해 지상권을 포기한 것으로 보는 경우","처분 전부터 토지와 건물의 소유자가 달랐던 경우"]}}],"함정":"ㄷ은 임대차계약의 체결을 지상권 포기로 보는 판례를 놓치면 옳게 읽힌다. ㄹ은 법정지상권이 성립했다고 지료까지 면제되는 것은 아니라는 점에서 틀린다."},"30회-2차-034":{"한줄":"乙이 건물의 인도와 사업자등록 신청을 마치지 못했다면 대항력이 없으므로, 건물을 매수한 丙의 인도청구에 대항할 수 없다.","근거":[{"법령":"상가건물 임대차보호법","조문":"제10조의8","원문":"임차인의 차임연체액이 3기의 차임액에 달하는 때에는 임대인은 계약을 해지할 수 있다."},{"법령":"상가건물 임대차보호법","조문":"제11조제2항","원문":"제1항에 따른 증액 청구는 임대차계약 또는 약정한 차임 등의 증액이 있은 후 1년 이내에는 하지 못한다."},{"법령":"상가건물 임대차보호법","조문":"제10조제4항","원문":"임대인이 제1항의 기간 이내에 임차인에게 갱신 거절의 통지 또는 조건 변경의 통지를 하지 아니한 경우에는 그 기간이 만료된 때에 전 임대차와 동일한 조건으로 다시 임대차한 것으로 본다. 이 경우에 임대차의 존속기간은 1년으로 본다."},{"법령":"상가건물 임대차보호법","조문":"제5조제2항","원문":"제3조제1항의 대항요건을 갖추고 관할 세무서장으로부터 임대차계약서상의 확정일자를 받은 임차인은 「민사집행법」에 따른 경매 또는 「국세징수법」에 따른 공매 시 임차건물(임대인 소유의 대지를 포함한다)의 환가대금에서 후순위권리자나 그 밖의 채권자보다 우선하여 보증금을 변제받을 권리가 있다."},{"법령":"상가건물 임대차보호법","조문":"제3조제1항","원문":"임대차는 그 등기가 없는 경우에도 임차인이 건물의 인도와 「부가가치세법」 제8조, 「소득세법」 제168조 또는 「법인세법」 제111조에 따른 사업자등록을 신청하면 그 다음 날부터 제3자에 대하여 효력이 생긴다."},{"법령":"상가건물 임대차보호법","조문":"제3조제2항","원문":"임차건물의 양수인(그 밖에 임대할 권리를 승계한 자를 포함한다)은 임대인의 지위를 승계한 것으로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"월차임 100만원이므로 200만원은 2기분이다. 해지는 연체액이 3기의 차임액에 달해야 한다(제10조의8)."},{"번호":2,"판정":"틀림","설명":"1년 제한은 증액청구에만 있다(제11조제2항). 감액에는 이런 제한이 없다."},{"번호":3,"판정":"틀림","설명":"임대차기간 만료 6개월 전부터 1개월 전까지 사이에 임대인이 갱신거절·조건변경 통지를 하지 않으면 전 임대차와 동일한 조건으로 다시 임대차한 것으로 본다(제10조제4항). 해지된 것으로 보지 않는다."},{"번호":4,"판정":"틀림","설명":"우선변제권은 후순위권리자나 그 밖의 채권자에 대한 것이다(제5조제2항). 선순위 저당권자보다 우선하지 못한다."},{"번호":5,"판정":"옳음","설명":"대항력은 건물의 인도와 사업자등록 신청이 있어야 생기고(제3조제1항) 양수인의 임대인 지위 승계(제3조제2항)도 대항력 있는 임대차를 전제로 하므로, 요건을 갖추지 못한 乙은 丙에게 대항할 수 없다."}],"개념":[{"종류":"표","제목":"상가건물 임차인의 대항력·우선변제권","머리":["구분","요건","효력 발생 시기"],"행":[["대항력(제3조제1항)","건물의 인도 + 사업자등록 신청","신청한 다음 날부터"],["우선변제권(제5조제2항)","대항요건 + 관할 세무서장의 확정일자","두 요건을 갖춘 때. 후순위권리자와 그 밖의 채권자에 우선"],["최우선변제(제14조제1항)","경매신청의 등기 전에 대항요건 구비 + 소액임차인","보증금 중 일정액을 담보물권자보다 우선"],["임차권등기(제6조제5항)","임대차 종료 후 보증금 미반환 시 등기명령 집행","등기를 마친 때 대항력·우선변제권 취득, 기존 권리는 유지"]]},{"종류":"흐름","제목":"계약갱신 관련 시기(제10조)","단계":[{"이름":"만료 6개월 전","설명":"임차인의 갱신요구 가능 시기 시작. 임대인의 갱신거절·조건변경 통지 기간도 이때부터 시작"},{"이름":"만료 1개월 전","설명":"갱신요구와 갱신거절·조건변경 통지의 마지막 시기"},{"이름":"통지 없는 경우","설명":"전 임대차와 동일한 조건으로 다시 임대차한 것으로 보고 존속기간은 1년"},{"이름":"갱신 후","설명":"임차인은 언제든지 해지를 통고할 수 있고 임대인이 받은 날부터 3개월 후 효력"},{"이름":"한도","설명":"임차인의 갱신요구권은 최초 임대차기간을 포함하여 10년 이내"}]}],"함정":"③은 통지를 하지 않았을 때의 효과가 해지가 아니라 동일 조건의 갱신이다. ①은 월 100만원 기준으로 200만원이 2기분임을 계산해야 한다. ⑤는 대항요건이 없는 임차인이 새 소유자에게 맞서지 못한다는 기본 규칙이다."},"30회-2차-036":{"한줄":"甲이 매매계약의 당사자이고 등기만 丙 명의로 한 3자간 등기명의신탁이다. 丙의 처분은 횡령죄가 되지 않고(ㄴ) 甲과 乙의 매매계약은 유효하여 甲이 乙에게 이전등기를 청구할 수 있으므로(ㄷ) ㄴ, ㄷ이 옳다.","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조제1항","원문":"명의신탁약정은 무효로 한다."},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조제2항","원문":"명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다."},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제8조 본문","원문":"다음 각 호의 어느 하나에 해당하는 경우로서 조세 포탈, 강제집행의 면탈(免脫) 또는 법령상 제한의 회피를 목적으로 하지 아니하는 경우에는 제4조부터 제7조까지 및 제12조제1항부터 제3항까지를 적용하지 아니한다."},{"판례":"대법원 전원합의체 판례(3자간 등기명의신탁의 횡령죄)","요지":"명의수탁자는 명의신탁자와 사이에 횡령죄를 구성할 위탁관계가 없으므로 부동산을 임의로 처분해도 횡령죄가 성립하지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ은 틀린 보기이고 옳은 ㄴ이 빠졌다. 명의신탁약정은 목적을 묻지 않고 무효다."},{"번호":2,"판정":"틀림","설명":"ㄱ, ㄹ 모두 틀린 보기이고 옳은 ㄴ, ㄷ이 빠졌다."},{"번호":3,"판정":"옳음","설명":"수탁자의 처분은 횡령죄가 아니고(ㄴ) 신탁자는 매도인에게 이전등기를 청구할 수 있으므로(ㄷ) 이 조합이 맞다."},{"번호":4,"판정":"틀림","설명":"ㄱ, ㄹ이 틀린 보기이고 옳은 ㄷ이 빠졌다."},{"번호":5,"판정":"틀림","설명":"ㄹ은 틀린 보기다. 3자간 유형에서 수탁자는 소유권을 취득하지 못하므로 신탁자의 부당이득반환청구권은 생기지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"명의신탁약정은 목적과 관계없이 무효다(제4조제1항). 목적을 따지는 예외는 종중·배우자·종교단체 특례뿐이다(제8조)."},{"기호":"ㄴ","판정":"옳음","설명":"3자간 등기명의신탁에서 수탁자가 부동산을 처분해도 신탁자에 대한 횡령죄가 성립하지 않는다는 것이 전원합의체 판례다."},{"기호":"ㄷ","판정":"옳음","설명":"매매계약은 유효하므로 甲은 乙에게 매매계약에 기한 소유권이전등기를 청구할 수 있다."},{"기호":"ㄹ","판정":"틀림","설명":"丙은 소유권을 취득하지 못한다(제4조제2항 본문). 甲은 대금을 乙에게 지급했으므로 丙에게 대금 상당의 부당이득반환을 청구할 수 없다."}],"개념":[{"종류":"표","제목":"부동산실명법 제8조 특례","머리":["대상","요건","효과"],"행":[["종중이 보유한 부동산을 종중 외의 자 명의로 등기","조세 포탈, 강제집행의 면탈, 법령상 제한의 회피를 목적으로 하지 않을 것","제4조~제7조, 제12조제1항~제3항 적용 제외"],["배우자 명의로 등기","위와 같음","위와 같음"],["종교단체 산하 조직이 보유한 부동산을 종교단체 명의로 등기","위와 같음","위와 같음"],["그 밖의 명의신탁","목적을 묻지 않음","약정 무효, 등기 무효, 형사처벌·과징금"]]},{"종류":"비교","제목":"3자간 등기명의신탁에서의 지위","왼쪽":{"이름":"명의신탁자(甲)","항목":["매도인과의 매매계약은 유효","매도인에게 소유권이전등기를 청구할 수 있음","매도인을 대위하여 수탁자 명의 등기의 말소를 청구할 수 있음","5년 이하의 징역 또는 2억원 이하의 벌금(제7조제1항)"]},"오른쪽":{"이름":"명의수탁자(丙)","항목":["등기가 무효여서 소유권을 취득하지 못함","대금 상당 부당이득반환 의무가 없음(대금은 매도인에게 지급됨)","부동산을 임의로 처분해도 횡령죄가 성립하지 않음","3년 이하의 징역 또는 1억원 이하의 벌금(제7조제2항)"]}}],"함정":"ㄱ은 목적이 없으면 유효하다고 본 점이 틀렸다. 목적을 따지는 특례는 종중·배우자·종교단체뿐이다. ㄹ은 계약명의신탁에서 매도인이 선의인 경우의 구제수단을 3자간 유형에 가져다 쓴 보기다."},"30회-2차-038":{"한줄":"부동산거래계약시스템으로 거래계약을 체결하면 계약이 체결된 때에 부동산거래계약 신고서를 제출한 것으로 본다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"거래신고법 제25조","원문":"국토교통부장관은 효율적인 정보의 관리 및 국민편의 증진을 위하여 대통령령으로 정하는 바에 따라 부동산거래 및 주택 임대차의 계약ㆍ신고ㆍ허가ㆍ관리 등의 업무와 관련된 정보체계를 구축ㆍ운영할 수 있다. 제5장의2 보칙"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"시행규칙 제2조제14항","원문":"법 제25조에 따라 구축된 부동산 거래계약 관련 정보시스템(이하 \"부동산거래계약시스템\"이라 한다)을 통하여 부동산 거래계약을 체결한 경우에는 부동산 거래계약이 체결된 때에 제1항, 제2항 또는 제4항의 부동산거래계약 신고서를 제출한 것으로 본다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"시행령 제19조의5제2항","원문":"제1항에 따라 전자문서로 제출하는 경우에는 「전자서명법」 제2조제6호에 따른 인증서(서명자의 실지명의를 확인할 수 있는 것으로 한정한다)를 통한 본인확인의 방법으로 서명 또는 날인할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"거래신고법 제6조의5제3항","원문":"제6조의2, 제6조의3에 따른 신고의 접수를 완료한 때에는 「주택임대차보호법」 제3조의6제1항에 따른 확정일자를 부여한 것으로 본다(임대차계약서가 제출된 경우로 한정한다)."},{"법령":"주택임대차계약증서의 확정일자 부여 및 정보제공에 관한 규칙","조문":"확정일자 규칙 제6조제2항","원문":"다음 각 호의 자는 인터넷등기소에서 전자확정일자 부여를 신청할 수 있다. 1. 해당 주택의 임대인ㆍ임차인 2. 변호사 또는 법무사[법무법인, 법무법인(유한), 법무조합, 법무사법인, 법무사법인(유한)을 포함한다. 이하 \"자격자대리인\"이라 한다] 3. 해당 주택의 주택임대차계약증서를 작성한 개업공인중개사"},{"법령":"공인중개사법","조문":"공인중개사법 제25조제3항","원문":"개업공인중개사는 중개가 완성되어 거래계약서를 작성하는 때에는 제1항에 따른 확인ㆍ설명사항을 대통령령으로 정하는 바에 따라 서면으로 작성하여 거래당사자에게 교부하고 대통령령으로 정하는 기간 동안 그 원본, 사본 또는 전자문서를 보존하여야 한다. 다만, 확인ㆍ설명사항이 「전자문서 및 전자거래 기본법」 제2조제9호에 따른 공인전자문서센터(이하 \"공인전자문서센터\"라 한다)에 보관된 경우에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"부동산거래·주택임대차의 계약·신고·허가·관리 등의 정보체계를 구축·운영할 수 있는 사람은 국토교통부장관이다(제25조). 시·도지사가 아니며 의무도 아니다."},{"번호":2,"판정":"틀림","설명":"전자문서로 신고할 때에는 인증서를 통한 본인확인의 방법으로 서명 또는 날인할 수 있다(시행령 제19조의5제2항). 전자인증으로 신분을 증명할 수 있다."},{"번호":3,"판정":"틀림","설명":"주택임대차계약증서의 전자확정일자는 해당 주택의 임대인·임차인, 계약증서를 작성한 개업공인중개사 등이 인터넷등기소에서 신청할 수 있다(확정일자 규칙 제6조제2항). 전자계약으로 체결했다는 이유로 임차인의 신청이 막히지 않는다."},{"번호":4,"판정":"옳음","설명":"부동산거래계약시스템을 통하여 거래계약을 체결한 경우 계약이 체결된 때에 부동산거래계약 신고서를 제출한 것으로 본다(시행규칙 제2조제14항)."},{"번호":5,"판정":"틀림","설명":"확인·설명사항이 공인전자문서센터에 보관된 경우에는 개업공인중개사가 서면 또는 전자문서로 보존하지 않아도 된다(공인중개사법 제25조제3항 단서)."}],"개념":[{"종류":"표","제목":"부동산거래계약시스템 이용 시 신고 의제","머리":["대상","의제 내용","근거"],"행":[["부동산 거래계약 체결","거래계약이 체결된 때에 부동산거래계약 신고서를 제출한 것으로 봄","시행규칙 제2조제14항"],["거래계약 해제등","해제등이 이루어진 때에 해제등 신고서를 제출한 것으로 봄","시행규칙 제4조제4항"],["주택 임대차 계약 체결","임대차계약당사자가 공동으로 임대차 신고서를 제출한 것으로 봄","시행규칙 제6조의2제8항"],["주택 임대차 신고 접수","임대차계약서가 제출된 경우 확정일자를 부여한 것으로 봄","거래신고법 제6조의5제3항"]]},{"종류":"표","제목":"중개대상물 확인·설명서의 작성·교부·보존","머리":["구분","내용","근거"],"행":[["작성·교부","중개가 완성되어 거래계약서를 작성하는 때 서면으로 작성하여 거래당사자에게 교부","법 제25조제3항, 영 제21조제3항"],["보존 기간","3년","영 제21조제4항"],["보존 방법","원본, 사본 또는 전자문서","법 제25조제3항"],["보존 면제","확인·설명사항이 공인전자문서센터에 보관된 경우","법 제25조제3항 단서"],["서명 및 날인","개업공인중개사, 해당 중개행위를 한 소속공인중개사가 함께","법 제25조제4항"]]}],"함정":"⑤는 전자 보관을 해도 서면 보존이 남는다고 생각하기 쉽다. 공인전자문서센터에 보관되면 보존 의무가 면제된다. ①은 주체가 시·도지사가 아니라 국토교통부장관이고, 구축·운영은 의무가 아니라 할 수 있는 임의 규정이다."}};